    public LoadMetrics? LastLoadMetrics { get; private set; }

    public MainWindow()
    {
        _tilesView = new SnapshotCollectionView<Tile>(_tiles);
        InitializeComponent();
        if (Application.Current is App app)
            app.AccessibilityPaletteChanged += App_AccessibilityPaletteChanged;
        InitializeKeyBindingEditor();
        InitializeEnhancementJobsWorkspace();
        InitializeBatchEnhancementWorkflow();
        _currentMonitorWorkArea = ResolveCurrentMonitorWorkArea;
        _currentMonitorBounds = ResolveCurrentMonitorBounds;
        _searchFilterTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(SearchFilterDebounceMilliseconds),
        };
        _searchFilterTimer.Tick += SearchFilterTimer_Tick;
        _searchStateSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(SearchStateSaveDebounceMilliseconds),
        };
        _searchStateSaveTimer.Tick += SearchStateSaveTimer_Tick;
        _galleryAutoScrollTimer = new DispatcherTimer(DispatcherPriority.Input)
        {
            Interval = TimeSpan.FromMilliseconds(16),
        };
        _galleryAutoScrollTimer.Tick += (_, _) => ApplyGalleryAutoScrollTick();
        _modalFeedbackTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(650),
        };
        _modalFeedbackTimer.Tick += (_, _) =>
        {
            _modalFeedbackTimer.Stop();
            if (ModalInteractionFeedback is not null)
                ModalInteractionFeedback.Visibility = Visibility.Collapsed;
        };
        _modalFavoritePulseTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(ModalFavoritePulseMilliseconds),
        };
        _modalFavoritePulseTimer.Tick += (_, _) => HideModalFavoritePulse();
        _statusToastDismissTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(TransientStatusToastMilliseconds),
        };
        _statusToastDismissTimer.Tick += (_, _) =>
        {
            _statusToastDismissTimer.Stop();
            if (_statusRetryAction is null && !HasUnresolvedSharedFailures && DeleteStatusToast is not null)
                DeleteStatusToast.Visibility = Visibility.Hidden;
        };
        _modalChromeTransientTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(ModalChromeTransientMilliseconds),
        };
        _modalChromeTransientTimer.Tick += (_, _) => ExpireModalChromeTransient();
        _modalTransformQualityTimer = new DispatcherTimer(DispatcherPriority.Render)
        {
            Interval = TimeSpan.FromMilliseconds(ModalTransformQualitySettleMilliseconds),
        };
        _modalTransformQualityTimer.Tick += (_, _) => EndModalTransformInteraction();
        _modalEnhancementPollTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromSeconds(1),
        };
        _modalEnhancementPollTimer.Tick += ModalEnhancementPollTimer_Tick;
        LandingFolderSetList.ItemsSource = _landingFolderSet;
        SidebarFolderSetList.ItemsSource = _folderBucketViews;
        RecentFolderSetList.ItemsSource = _recentFolderSetViews;
        PreviewTabList.ItemsSource = _previewTabs;
        SearchHistoryList.ItemsSource = _searchHistoryEntries;
        // Keep the two normally hidden filmstrips off the complete catalog.
        // Otherwise every search reset is observed by four ItemControls and a
        // 100k catalog can retain large generator/view state for an invisible UI.
        ModalFilmstripOverlayList.ItemsSource = _modalFilmstripTiles;
        RestoreState();
        LoadThumbnailStatusBorderSettings();
        BuildSampleTiles();
        _allTiles.AddRange(_tiles);
        _tiles.Clear();
        ReorderFullCatalogForSort();
        ApplyCardLayoutToAllTiles();

        ConfigureGalleryItemsSources();
        CardsList.ItemContainerGenerator.StatusChanged += SelectionItemContainerGenerator_StatusChanged;
        RowsList.ItemContainerGenerator.StatusChanged += SelectionItemContainerGenerator_StatusChanged;
        CardsList.AddHandler(ScrollViewer.ScrollChangedEvent, new ScrollChangedEventHandler(CardsList_ScrollChanged));
        RowsList.AddHandler(ScrollViewer.ScrollChangedEvent, new ScrollChangedEventHandler(RowsList_ScrollChanged));
        CardsList.AddHandler(Button.ClickEvent, new RoutedEventHandler(CardFavoriteButton_Click));
        RowsList.AddHandler(Button.ClickEvent, new RoutedEventHandler(CardFavoriteButton_Click));
        ApplyFilters(selectFirst: false);

        Loaded += (_, _) =>
        {
            ApplyAdaptiveWorkbenchLayout(ActualWidth);
            AttachGalleryVirtualizationPanel();
            if (CardsList.Items.Count > 0)
                CardsList.SelectedIndex = 0;
            ScheduleRememberCurrentGridViewportAnchor();
            UpdateWindowMaximizePresentation();
        };
        Closing += MainWindow_Closing;
        Closed += (_, _) =>
        {
            _catalogProjectionGeneration++;
            CancelPendingCatalogProjection(completePending: true);
            CancelPendingGalleryFocus();
            CardsList.CancelAutomationRealization();
            RowsList.CancelAutomationRealization();
            _galleryVirtualizingPanel?.CancelPendingRealization();
            if (Application.Current is App app)
                app.AccessibilityPaletteChanged -= App_AccessibilityPaletteChanged;
            Interlocked.Increment(ref _activeAlbumAsyncGeneration);
            Interlocked.Exchange(ref _activeAlbumAvailabilityCts, null)?.Cancel();
            CancelPreviewTabHoverDecode();
            CancelThumbnailViewportLoading();
            _favoriteWriterPumpTimer?.Stop();
            _seenWriterPumpTimer?.Stop();
            _modalChromeTransientTimer.Stop();
            _modalEnhancementPollTimer.Stop();
            _modalEnhancementGeneration++;
            _enhancementWorkspacePollTimer.Stop();
            _enhancementWorkspaceGeneration++;
            Interlocked.Exchange(ref _enhancementWorkspaceThumbnailCts, null)?.Cancel();
            CancelOwnedEnhancementCompanionLifetime();
            StopOwnedEnhancementCompanion();
        };
        CardsList.MouseDoubleClick += (_, _) => OpenModal();
        RowsList.MouseDoubleClick += (_, _) => OpenModal();
        SizeChanged += MainWindow_SizeChanged;
        StateChanged += MainWindow_StateChanged;
        RefreshLandingFolderSetUi();
        RefreshPreviewTabs();
        SetPhase(landing: true);
        _initializing = false;
        ApplyAccessibilityPreferencesToPresentation();
        if (_dateFilterMigrationPending || _cardWidthMigrationPending)
            SaveState();
    }

    private static System.ComponentModel.ICollectionView BuildGalleryView(IEnumerable<Tile> source, bool groupByDate)
    {
        var cvs = new CollectionViewSource { Source = source };
        if (groupByDate)
            cvs.GroupDescriptions.Add(new PropertyGroupDescription(nameof(Tile.Group)));
        return cvs.View;
    }

    private bool UsesDateGrouping
        => _sortBy is SortCreatedNewestValue or SortCreatedOldestValue;

    private void ConfigureGalleryItemsSources()
    {
        bool previousSync = _syncingSelection;
        _syncingSelection = true;
        try
        {
            // Keep one panel instance across sort modes. Replacing the
            // ItemsPanelTemplate discards the prepared 100k layout and every
            // recycled container exactly when the user changes sort order.
            ItemsPanelTemplate cardPanel = (ItemsPanelTemplate)FindResource(
                "VirtualizedCardItemsPanel");
            if (!ReferenceEquals(CardsList.ItemsPanel, cardPanel))
                CardsList.ItemsPanel = cardPanel;
            // The grid always owns the complete filtered catalog. Date sections
            // are drawn by the same virtualizing panel, so grouping never turns
            // into a capped secondary collection or a 100k-container layout.
            if (!ReferenceEquals(CardsList.ItemsSource, _tilesView))
                CardsList.ItemsSource = _tilesView;
            ConfigureRowsItemsSource(forceGroupedView: RowsList.Visibility == Visibility.Visible);
        }
        finally
        {
            _syncingSelection = previousSync;
        }

        Dispatcher.BeginInvoke(AttachGalleryVirtualizationPanel, DispatcherPriority.Loaded);
    }

    private void ConfigureRowsItemsSource(bool forceGroupedView)
    {
        // Group construction in WPF's stock ListBox walks the complete view.
        // Detach the hidden List surface entirely: even a collapsed ListBox
        // observes every Reset and retains generator/view bookkeeping for the
        // 100k source. Reattach and reconcile its selection when List is shown.
        bool previousSync = _syncingSelection;
        _syncingSelection = true;
        try
        {
            if (!forceGroupedView)
            {
                RowsList.ItemsSource = null;
                return;
            }
            RowsList.ItemsSource = UsesDateGrouping
                ? BuildGalleryView(_tiles, groupByDate: true)
                : _tilesView;
        }
        finally
        {
            _syncingSelection = previousSync;
        }
    }

    private void AttachGalleryVirtualizationPanel()
    {
        VirtualizingWrapPanel? panel = FindVisualDescendant<VirtualizingWrapPanel>(CardsList);
        if (ReferenceEquals(panel, _galleryVirtualizingPanel))
        {
            SyncGalleryColumnMode();
            return;
        }

        if (_galleryVirtualizingPanel is not null)
        {
            _retiredPreparedCatalogLayoutAppliedCount += _galleryVirtualizingPanel.PreparedLayoutAppliedCount;
            _retiredPreparedCatalogLayoutRejectedCount += _galleryVirtualizingPanel.PreparedLayoutRejectedCount;
            _retiredCatalogLayoutMaxMeasureMilliseconds = Math.Max(
                _retiredCatalogLayoutMaxMeasureMilliseconds,
                _galleryVirtualizingPanel.MaxMeasureMilliseconds);
            if (_galleryVirtualizingPanel.MaxMeasureDiagnostic.WallMs
                > _retiredCatalogLayoutMaxMeasureDiagnostic.WallMs)
            {
                _retiredCatalogLayoutMaxMeasureDiagnostic =
                    _galleryVirtualizingPanel.MaxMeasureDiagnostic;
            }
            _retiredCatalogPanelPhaseDiagnostics.AddRange(
                _galleryVirtualizingPanel.CapturePhaseDiagnostics());
            _catalogPanelPhaseDiagnosticOverflow |=
                _galleryVirtualizingPanel.PhaseDiagnosticOverflow;
            _galleryVirtualizingPanel.RealizedRangeChanged -= GalleryVirtualizingPanel_RealizedRangeChanged;
            _galleryVirtualizingPanel.PriorityItemMeasured -= GalleryVirtualizingPanel_PriorityItemMeasured;
        }
        _galleryVirtualizingPanel = panel;
        if (_galleryVirtualizingPanel is null)
            return;

        SyncGalleryColumnMode();
        _galleryVirtualizingPanel.SetDiagnosticOperation(_catalogInteractionDiagnosticOperation);
        _galleryVirtualizingPanel.RealizedRangeChanged += GalleryVirtualizingPanel_RealizedRangeChanged;
        _galleryVirtualizingPanel.PriorityItemMeasured += GalleryVirtualizingPanel_PriorityItemMeasured;
        ScheduleThumbnailViewportRange(
            _galleryVirtualizingPanel.FirstVisibleIndex,
            _galleryVirtualizingPanel.LastVisibleIndex,
            _galleryVirtualizingPanel.FirstRealizedIndex,
            _galleryVirtualizingPanel.LastRealizedIndex);
    }

    private void GalleryVirtualizingPanel_RealizedRangeChanged(
        object? sender,
        VirtualizingWrapPanelRangeChangedEventArgs e)
    {
        ScheduleThumbnailViewportRange(
            e.FirstVisibleIndex,
            e.LastVisibleIndex,
            e.FirstRealizedIndex,
            e.LastRealizedIndex);
        QueueSparseSelectionVisualSync(CardsList, grid: true);
        QueuePendingGalleryFocusCompletion();
        ScheduleRememberCurrentGridViewportAnchor();
    }

    private void GalleryVirtualizingPanel_PriorityItemMeasured(object? sender, EventArgs e)
        => QueuePendingGalleryFocusCompletion();

    private void CardsList_ScrollChanged(object sender, ScrollChangedEventArgs e)
    {
        if (CardsList.Visibility == Visibility.Visible
            && (Math.Abs(e.VerticalChange) > 0.01 || Math.Abs(e.ViewportHeightChange) > 0.01 || Math.Abs(e.ViewportWidthChange) > 0.01))
        {
            ScheduleRememberCurrentGridViewportAnchor();
        }
    }

    protected override void OnSourceInitialized(EventArgs e)
    {
        base.OnSourceInitialized(e);
        ConstrainWindowToCurrentWorkArea();
    }

    private void MainWindow_SizeChanged(object sender, SizeChangedEventArgs e)
    {
        ScheduleModalFitUpdate();
        if (!e.WidthChanged && !e.HeightChanged)
            return;
        GridZoomAnchor? anchor = PreferredGridGeometryAnchor();
        ApplyAdaptiveWorkbenchLayout(e.NewSize.Width, preserveGridAnchor: false);
        ScheduleGridGeometryAnchorRestore(anchor);
    }

    protected override void OnDpiChanged(DpiScale oldDpi, DpiScale newDpi)
    {
        GridZoomAnchor? anchor = PreferredGridGeometryAnchor();
        base.OnDpiChanged(oldDpi, newDpi);
        if (!_modalFullScreen)
            ConstrainWindowToCurrentWorkArea();
        PreserveGridAnchorAfterDpiChange(anchor);
    }

    private void PreserveGridAnchorAfterDpiChange(GridZoomAnchor? anchor)
        => ScheduleGridGeometryAnchorRestore(anchor);

    private void SelectionItemContainerGenerator_StatusChanged(object? sender, EventArgs e)
    {
        if (sender is not ItemContainerGenerator generator
            || generator.Status != GeneratorStatus.ContainersGenerated)
        {
            return;
        }

        if (ReferenceEquals(generator, CardsList.ItemContainerGenerator))
        {
            QueueSparseSelectionVisualSync(CardsList, grid: true);
            QueuePendingGalleryFocusCompletion();
        }
        else if (ReferenceEquals(generator, RowsList.ItemContainerGenerator))
        {
            QueueSparseSelectionVisualSync(RowsList, grid: false);
            QueuePendingGalleryFocusCompletion();
            if (RowsList.Visibility == Visibility.Visible)
                Dispatcher.BeginInvoke(ScheduleListThumbnailViewport, DispatcherPriority.Render);
        }
    }

    private void ScheduleThumbnailViewportRange(
        int firstVisibleIndex,
        int lastVisibleIndex,
        int firstRealizedIndex,
        int lastRealizedIndex)
    {
        if (_tiles.Count == 0)
        {
            ClearProtectedResidentThumbnails();
            return;
        }

        int firstVisible = Math.Clamp(firstVisibleIndex, 0, _tiles.Count - 1);
        int lastVisible = Math.Clamp(lastVisibleIndex, firstVisible, _tiles.Count - 1);
        int firstRealized = Math.Clamp(firstRealizedIndex, 0, _tiles.Count - 1);
        int lastRealized = Math.Clamp(lastRealizedIndex, firstRealized, _tiles.Count - 1);
        if (firstVisibleIndex < 0 || lastVisibleIndex < firstVisibleIndex)
        {
            firstVisible = firstRealized;
            lastVisible = lastRealized;
        }
        SetProtectedResidentThumbnailRanges(firstVisible, lastVisible, firstRealized, lastRealized);

        var candidates = new List<Tile>(Math.Max(0, lastRealized - firstRealized + 1));
        var added = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (int index = firstVisible; index <= lastVisible; index++)
        {
            Tile tile = _tiles[index];
            if (tile.Thumbnail is not null)
                TouchResidentThumbnail(tile);
            else if (tile.IsRealFile && added.Add(tile.Path))
                candidates.Add(tile);
        }
        for (int index = firstRealized; index <= lastRealized; index++)
        {
            Tile tile = _tiles[index];
            if (tile.Thumbnail is not null)
                TouchResidentThumbnail(tile);
            else if (tile.IsRealFile && added.Add(tile.Path))
                candidates.Add(tile);
        }

        if (candidates.Count == 0)
            return;

        string signature = $"grid|{_loadGeneration}|{_thumbnailViewportRevision}|{firstVisible}|{lastVisible}";
        ScheduleThumbnailCandidates(candidates, signature);
    }

    private void ScheduleThumbnailCandidates(IReadOnlyList<Tile> candidates, string signature)
    {
        if (candidates.Count == 0)
            return;

        if (_thumbnailViewportCts is not null
            && string.Equals(_thumbnailViewportSignature, signature, StringComparison.Ordinal))
        {
            _thumbnailViewportDuplicateSuppressedCount++;
            return;
        }

        CancelThumbnailViewportLoading();
        CancellationTokenSource cts = _loadCts is { } loadCts
            ? CancellationTokenSource.CreateLinkedTokenSource(loadCts.Token)
            : new CancellationTokenSource();
        _thumbnailViewportCts = cts;
        _thumbnailViewportSignature = signature;
        _thumbnailViewportScheduleCount++;
        _ = LoadThumbnailViewportAsync(candidates, _loadGeneration, cts);
    }

    private void RowsList_ScrollChanged(object sender, ScrollChangedEventArgs e)
    {
        if (RowsList.Visibility == Visibility.Visible)
        {
            ScheduleListThumbnailViewport();
            QueueSparseSelectionVisualSync(RowsList, grid: false);
        }
    }

    private void ScheduleListThumbnailViewport()
    {
        if (RowsList.Visibility != Visibility.Visible)
            return;

        ScrollViewer? viewer = FindVisualDescendant<ScrollViewer>(RowsList);
        if (viewer is null)
            return;

        double currentOffset = viewer.VerticalOffset;
        bool movingDown = currentOffset >= _lastListThumbnailVerticalOffset;
        _lastListThumbnailVerticalOffset = currentOffset;
        var candidates = new List<(Tile Tile, bool Visible, double Distance, double Top)>();
        var protectedTiles = new List<Tile>();
        foreach (ListBoxItem item in FindVisualDescendants<ListBoxItem>(RowsList))
        {
            if (item.DataContext is not Tile { IsRealFile: true } tile)
                continue;
            protectedTiles.Add(tile);
            if (tile.Thumbnail is not null)
            {
                TouchResidentThumbnail(tile);
                continue;
            }
            try
            {
                double top = item.TransformToAncestor(viewer).Transform(new Point(0, 0)).Y;
                double bottom = top + item.ActualHeight;
                bool visible = bottom >= 0 && top <= viewer.ViewportHeight;
                double distance = Math.Abs(((top + bottom) / 2) - (viewer.ViewportHeight / 2));
                candidates.Add((tile, visible, distance, top));
            }
            catch (InvalidOperationException)
            {
            }
        }
        SetProtectedResidentThumbnails(protectedTiles);

        List<Tile> visibleCandidates = candidates
            .Where(static candidate => candidate.Visible)
            .OrderBy(static candidate => candidate.Top)
            .Select(static candidate => candidate.Tile)
            .ToList();
        // Decode the leading edge in the current scroll direction before the
        // quiet-period queue. Direct jumps to either end therefore cannot be
        // starved by the intermediate layouts produced by ScrollIntoView.
        IEnumerable<Tile> leadingEdge = movingDown
            ? visibleCandidates.TakeLast(1)
            : visibleCandidates.Take(1);
        List<Tile> orderedCandidates = leadingEdge
            .Concat(candidates
                .OrderByDescending(static candidate => candidate.Visible)
                .ThenBy(static candidate => candidate.Distance)
                .Select(static candidate => candidate.Tile))
            .DistinctBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase)
            .ToList();
        string visibleSignature = string.Join(
            '\u001f',
            candidates.Where(static candidate => candidate.Visible)
                .OrderBy(static candidate => candidate.Top)
                .Select(static candidate => candidate.Tile.Path));
        string signature = $"list|{_loadGeneration}|{_thumbnailViewportRevision}|{visibleSignature}";
        ScheduleThumbnailCandidates(orderedCandidates, signature);
    }

    private async Task LoadThumbnailViewportAsync(
        IReadOnlyList<Tile> candidates,
        long generation,
        CancellationTokenSource cts)
    {
        try
        {
            Tile? selected = SelectedTile();
            List<Tile> ordered = candidates
                .OrderByDescending(tile => ReferenceEquals(tile, selected))
                .ToList();
            int immediateCount = Math.Min(ImmediateViewportThumbnailCount, ordered.Count);
            CancellationToken priorityToken = _loadCts?.Token ?? CancellationToken.None;
            await LoadThumbnailCandidatesAsync(
                ordered.Take(immediateCount).ToArray(),
                generation,
                priorityToken,
                maxBatchConcurrency: 4);
            cts.Token.ThrowIfCancellationRequested();

            if (immediateCount < ordered.Count)
            {
                // During a fast scroll/selection run, keep the selected image
                // and nearest visible cards responsive without decoding every
                // transient overscan row. Once the viewport stays put, fill
                // the remainder after a short quiet period.
                await Task.Delay(ViewportThumbnailSettleDelayMilliseconds, cts.Token);
                await LoadThumbnailCandidatesAsync(
                    ordered.Skip(immediateCount).ToArray(),
                    generation,
                    cts.Token,
                    maxBatchConcurrency: 4);
                cts.Token.ThrowIfCancellationRequested();
            }
        }
        catch (OperationCanceledException)
        {
        }
        finally
        {
            bool wasCurrent = ReferenceEquals(_thumbnailViewportCts, cts);
            if (wasCurrent)
            {
                _thumbnailViewportCts = null;
                _thumbnailViewportSignature = null;
            }
            cts.Dispose();
            if (wasCurrent && TryGetThumbnailRetryDelay(candidates, out int retryDelayMilliseconds))
                _ = RetryCurrentThumbnailViewportAsync(generation, retryDelayMilliseconds);
        }
    }

    private async Task RetryCurrentThumbnailViewportAsync(long generation, int delayMilliseconds)
    {
        await Task.Delay(Math.Max(1, delayMilliseconds));
        if (generation != _loadGeneration
            || _thumbnailViewportCts is not null
            || _galleryVirtualizingPanel is not { } panel)
        {
            return;
        }

        if (RowsList.Visibility == Visibility.Visible)
            ScheduleListThumbnailViewport();
        else
            ScheduleThumbnailViewportRange(
                panel.FirstVisibleIndex,
                panel.LastVisibleIndex,
                panel.FirstRealizedIndex,
                panel.LastRealizedIndex);
    }

    private void CancelThumbnailViewportLoading()
    {
        CancellationTokenSource? cts = _thumbnailViewportCts;
        _thumbnailViewportCts = null;
        _thumbnailViewportSignature = null;
        if (cts is not null && !cts.IsCancellationRequested)
            _thumbnailViewportCancelCount++;
        cts?.Cancel();
    }

    private void MainWindow_Closing(object? sender, CancelEventArgs e)
    {
        if (HasUnresolvedSharedFailures)
        {
            e.Cancel = true;
            SetStatusToast(
                "Favorite or Seen changes still need Retry. The window stayed open so the recovery intent is not lost.",
                RetryFailedSharedBatches);
            return;
        }

        if (!_allowCloseAfterSharedDrain && HasPendingSharedWrites())
        {
            e.Cancel = true;
            if (!_closingDrainInProgress)
                _ = DrainThenCloseAsync();
            return;
        }

        FlushViewerStateForCloseOnce();
    }

    private bool HasPendingSharedWrites()
        => _favoriteWriter?.HasPendingOrInFlight == true
            || _seenWriter?.HasPendingOrInFlight == true;

    private bool HasUnresolvedSharedFailures
        => _failedFavoriteBatch is { Count: > 0 }
            || _failedSeenBatch is { Count: > 0 };

    private async Task DrainThenCloseAsync()
    {
        _closingDrainInProgress = true;
        _sharedActionsDisabled = true;
        SetStatusToast("Saving Favorite and Seen changes before closing...");
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(2.5));
        try
        {
            Task<SharedWriteStatus> favorite = _favoriteWriter is { } favoriteWriter
                ? favoriteWriter.DrainAsync(timeout.Token)
                : Task.FromResult(SharedWriteStatus.Succeeded);
            Task<SharedWriteStatus> seen = _seenWriter is { } seenWriter
                ? seenWriter.DrainAsync(timeout.Token)
                : Task.FromResult(SharedWriteStatus.Succeeded);
            SharedWriteStatus[] statuses = await Task.WhenAll(favorite, seen);
            if (statuses.All(static status => status == SharedWriteStatus.Succeeded) && !HasPendingSharedWrites())
            {
                _allowCloseAfterSharedDrain = true;
                _sharedActionsDisabled = false;
                _closingDrainInProgress = false;
                Close();
                return;
            }

            SetStatusToast("Favorite or Seen changes could not finish saving. The window stayed open; use Retry after fixing the local store.",
                RetryFailedSharedBatches);
        }
        catch (OperationCanceledException)
        {
            SetStatusToast("Favorite or Seen changes are still saving. The window stayed open; close again after the save finishes.");
        }
        finally
        {
            if (!_allowCloseAfterSharedDrain)
            {
                _sharedActionsDisabled = false;
                _closingDrainInProgress = false;
            }
        }
    }

    private void FlushViewerStateForCloseOnce()
    {
        if (_shutdownPersistenceFlushed)
            return;

        _shutdownPersistenceFlushed = true;
        _shutdownPersistenceFlushCount++;
        _searchFilterTimer.Stop();
        _searchStateSaveTimer.Stop();
        foreach (Tile tile in _deferredFavoriteNotificationOwners.Keys)
            tile.FlushFavoriteNotifications();
        _deferredFavoriteNotificationOwners.Clear();
        CancelPendingCatalogProjection(completePending: true);
        _loadCts?.Cancel();
        _previewCts?.Cancel();
        _previewDecodeCompletion?.TrySetResult(PreviewDecodeResult.Canceled);
        _previewMetadataCts?.Cancel();
        _previewMetadataCompletion?.TrySetResult(null);
        _modalCts?.Cancel();
        _modalDecodeCompletion?.TrySetResult(false);
        _modalSingleClickGeneration++;
        _modalFeedbackTimer.Stop();
        _modalFavoritePulseTimer.Stop();
        _modalChromeTransientTimer.Stop();
        _modalTransformQualityTimer.Stop();
        CancelPreviewTabHoverDecode();

        // Closing flushes only the viewer state. Folder recents, favorites,
        // seen data, enhancement jobs, and source files are separate stores
        // and must not be rewritten merely because the window is closing.
        ForceSaveStateForClose();
    }

    private void ForceSaveStateForClose()
    {
        // Catalog publication suppresses incidental state writes while it
        // builds a replacement snapshot. Closing can interleave only at its
        // explicit dispatcher yields, where the current state is still stable;
        // bypass that temporary suppression so the one shutdown flush is real.
        bool previousSuppress = _suppressStateSave;
        _suppressStateSave = false;
        try
        {
            SaveState();
        }
        finally
        {
            _suppressStateSave = previousSuppress;
        }
    }

