    private sealed record CatalogProjectionRequest(
        long Generation,
        bool ReorderCatalog,
        bool RestrictToCurrentProjection,
        bool SelectFirst,
        int? SelectionFallbackIndex,
        GridZoomAnchor? ViewportAnchor,
        TaskCompletionSource<SearchFilterCompletion>? Completion);

