    {
        "masterpiece, best quality, 1girl, portrait, silver hair, soft rim lighting, cinematic",
        "highly detailed, elf, forest, dappled light, intricate armor, depth of field",
        "epic castle, dramatic sky, volumetric fog, wide shot, matte painting",
        "mecha, neon city, rain, reflective surfaces, cyberpunk, 8k",
        "golden hour, sunset over hills, warm tones, atmospheric, film grain",
        "samurai, cherry blossoms, ink wash style, dynamic pose, motion",
    };

    private void BuildSampleTiles()
    {
        double w = SizeSlider?.Value ?? 190;

        // (fav, unseen) per card
        (int fav, bool unseen)[] today =
        {
            (3, true), (0, true), (1, false), (0, false), (0, true), (5, false),
            (0, false), (0, false), (2, false), (0, false), (0, true), (0, false),
        };
        (int fav, bool unseen)[] yesterday =
        {
            (2, false), (0, false), (0, false), (1, false), (0, false),
            (0, true), (0, false), (4, false), (0, false), (0, false),
        };

        for (int i = 0; i < today.Length; i++)
            _tiles.Add(MakeTile(i, "Today  ·  2026-07-08", today[i].fav, today[i].unseen, 427, w));
        for (int i = 0; i < yesterday.Length; i++)
            _tiles.Add(MakeTile(i, "Yesterday  ·  2026-07-07", yesterday[i].fav, yesterday[i].unseen, 391, w, offset: 4));
    }

    private Tile MakeTile(int i, string group, int fav, bool unseen, int baseNum, double width, int offset = 0)
    {
        int idx = i + offset;
        string name = $"{(baseNum - i):00000}-{Names[idx % Names.Length]}.png";
        var tile = new Tile
        {
            ArtBase = MakeBaseBrush(idx),
            ArtGlow = MakeGlowBrush(idx),
            FileName = name,
            Fav = fav,
            Unseen = unseen,
            ShowUnseenDot = _showUnseenDots && unseen,
            Group = group,
            CardWidth = width,
            Prompt = Prompts[idx % Prompts.Length],
            Path = $@"D:\SD\outputs\txt2img\{name}",
            ImagePixelWidth = 832,
            ImagePixelHeight = 1216,
            SizeText = "832 x 1216",
            ModifiedText = "2026-07-08 14:22",
        };
        ApplyCardLayout(tile);
        return tile;
    }

    private static Color Hex(string hex) => (Color)ColorConverter.ConvertFromString(hex);

    private static Brush MakeBaseBrush(int i) => BaseBrushCache[i % BaseBrushCache.Length];

    private static Brush CreateBaseBrush(int i)
    {
        var p = Palettes[i % Palettes.Length];
        var b = new LinearGradientBrush { StartPoint = new Point(0, 0), EndPoint = new Point(1, 1) };
        b.GradientStops.Add(new GradientStop(Hex(p[2]), 0));
        b.GradientStops.Add(new GradientStop(Hex(p[1]), 0.55));
        b.GradientStops.Add(new GradientStop(Hex(p[2]), 1));
        b.Freeze();
        return b;
    }

    private static Brush MakeGlowBrush(int i) => GlowBrushCache[i % GlowBrushCache.Length];

    private static Brush CreateGlowBrush(int i)
    {
        var p = Palettes[i % Palettes.Length];
        var c = Hex(p[0]);
        double gx = 0.15 + (i * 0.17) % 0.7;
        double gy = 0.2 + (i * 0.11) % 0.6;
        var b = new RadialGradientBrush
        {
            GradientOrigin = new Point(gx, gy),
            Center = new Point(gx, gy),
            RadiusX = 0.95,
            RadiusY = 0.95,
        };
        b.GradientStops.Add(new GradientStop(Color.FromArgb(0xCC, c.R, c.G, c.B), 0));
        b.GradientStops.Add(new GradientStop(Color.FromArgb(0x00, c.R, c.G, c.B), 0.62));
        b.Freeze();
        return b;
    }

    // ─────────── Selection → right preview ───────────
    private void CardsList_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (_syncingSelection || sender is not ListBox lb)
            return;

        CancelPendingGalleryFocus();
        bool collapseSparseSelection = _selectedPaths.Count > MaxMaterializedSelectionVisualItems
            && (_shortcutModifierProvider() & (ModifierKeys.Control | ModifierKeys.Shift)) == ModifierKeys.None;
        if (collapseSparseSelection)
            _selectedPaths.Clear();

        foreach (Tile tile in e.RemovedItems.OfType<Tile>())
            _selectedPaths.Remove(tile.Path);
        foreach (Tile tile in e.AddedItems.OfType<Tile>())
            _selectedPaths.Add(tile.Path);

        Tile? primary = lb.SelectedItem as Tile;
        if (collapseSparseSelection && primary is not null)
            _selectedPaths.Add(primary.Path);
        if (primary is null || !_selectedPaths.Contains(primary.Path))
            primary = e.AddedItems.OfType<Tile>().LastOrDefault()
                ?? SelectedTiles().LastOrDefault();
        _primarySelectedPath = primary?.Path;
        _primarySelectedTile = primary;
        _primarySelectedIndex = primary is null
            ? -1
            : lb.SelectedIndex >= 0 && ReferenceEquals(lb.SelectedItem, primary)
                ? lb.SelectedIndex
                : _tiles.IndexOf(primary);
        _selectionVisualSyncGeneration++;

        IReadOnlyList<Tile>? knownMaterializedSelection = _selectedPaths.Count switch
        {
            0 => [],
            1 when primary is not null => [primary],
            _ => null,
        };
        SynchronizeSelectionControls(knownMaterializedSelection);
        ApplyPrimarySelection(primary, _primarySelectedIndex);
    }

    private void GalleryList_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (sender is not ListBox listBox
            || listBox.Visibility != Visibility.Visible
            || Modal.Visibility == Visibility.Visible
            || DeleteConfirmationDialog.Visibility == Visibility.Visible
            || BatchEnhancementDialog.Visibility == Visibility.Visible
            || AppSettingsDialog.Visibility == Visibility.Visible
            || EnhancementJobsDialog.Visibility == Visibility.Visible
            || IsGlobalShortcutInputFocused(e.OriginalSource)
            || _shortcutModifierProvider() != ModifierKeys.None)
        {
            return;
        }

        Key key = e.Key == Key.System ? e.SystemKey : e.Key;
        bool grid = ReferenceEquals(listBox, CardsList);
        bool recognized = key is Key.Home or Key.End or Key.PageUp or Key.PageDown
            || grid && key is Key.Left or Key.Right or Key.Up or Key.Down
            || !grid && key is Key.Up or Key.Down;
        if (!recognized)
            return;

        int currentIndex = ResolvePrimarySelectionIndex();
        int targetIndex = ResolveGalleryNavigationTarget(listBox, key, currentIndex);
        if (targetIndex < 0 || targetIndex >= _tiles.Count)
            return;

        if (targetIndex != currentIndex)
        {
            Tile target = _tiles[targetIndex];
            CancelPendingGalleryFocus();
            // Keep the key event itself bounded. The viewport/focus jump is
            // queued below; preview/seen presentation follows at Background
            // priority so Input gets a turn between the distant container
            // realization and the right-panel layout.
            SetSelection(
                [target],
                target,
                targetIndex,
                deferPrimaryPresentation: true);
            QueuePrimaryGalleryFocus(target, targetIndex, grid);
        }
        e.Handled = true;
    }

    private int ResolveGalleryNavigationTarget(ListBox listBox, Key key, int currentIndex)
    {
        if (_tiles.Count == 0)
            return -1;

        int safeCurrent = currentIndex >= 0
            ? Math.Clamp(currentIndex, 0, _tiles.Count - 1)
            : key is Key.End or Key.PageUp or Key.Left or Key.Up
                ? _tiles.Count - 1
                : 0;
        bool grid = ReferenceEquals(listBox, CardsList);
        int columns = grid
            ? Math.Max(1, _galleryVirtualizingPanel?.ColumnCount ?? 1)
            : 1;
        int pageSize;
        if (grid)
        {
            int visible = Math.Max(
                columns,
                (_galleryVirtualizingPanel?.LastVisibleIndex ?? -1)
                    - (_galleryVirtualizingPanel?.FirstVisibleIndex ?? 0)
                    + 1);
            pageSize = Math.Max(columns, visible);
        }
        else
        {
            int first = int.MaxValue;
            int last = -1;
            foreach (ListBoxItem container in FindVisualDescendants<ListBoxItem>(RowsList))
            {
                int index = RowsList.ItemContainerGenerator.IndexFromContainer(container);
                if (index < 0)
                    continue;
                first = Math.Min(first, index);
                last = Math.Max(last, index);
            }
            pageSize = first <= last ? Math.Max(1, last - first + 1) : 10;
        }

        int target = key switch
        {
            Key.Home => 0,
            Key.End => _tiles.Count - 1,
            Key.PageUp => safeCurrent - pageSize,
            Key.PageDown => safeCurrent + pageSize,
            Key.Left when grid => safeCurrent - 1,
            Key.Right when grid => safeCurrent + 1,
            Key.Up => safeCurrent - columns,
            Key.Down => safeCurrent + columns,
            _ => safeCurrent,
        };
        return Math.Clamp(target, 0, _tiles.Count - 1);
    }

    private int ResolvePrimarySelectionIndex()
    {
        Tile? primary = SelectedTile();
        if (primary is null)
            return -1;
        if (_primarySelectedIndex >= 0
            && _primarySelectedIndex < _tiles.Count
            && ReferenceEquals(_tiles[_primarySelectedIndex], primary))
        {
            return _primarySelectedIndex;
        }

        _primarySelectedIndex = _tiles.IndexOf(primary);
        return _primarySelectedIndex;
    }

    private bool QueuePrimaryGalleryFocus(Tile tile, int index, bool grid)
    {
        if (index < 0
            || index >= _tiles.Count
            || !ReferenceEquals(_tiles[index], tile))
        {
            return false;
        }

        _galleryFocusRequestGeneration++;
        _pendingGalleryFocusPath = tile.Path;
        _pendingGalleryFocusIndex = index;
        _pendingGalleryFocusGrid = grid;
        _pendingGalleryFocusRetryCount = 0;
        if (grid)
        {
            _galleryVirtualizingPanel?.BringItemIntoView(index);
        }
        else
        {
            RowsList.ScrollIntoView(tile);
        }

        QueuePendingGalleryFocusCompletion();
        return true;
    }

    private void QueuePendingGalleryFocusCompletion()
    {
        long generation = _galleryFocusRequestGeneration;
        if (_pendingGalleryFocusIndex < 0
            || string.IsNullOrWhiteSpace(_pendingGalleryFocusPath)
            || _queuedGalleryFocusCompletionGeneration == generation
                && _galleryFocusCompletionOperation is { Status: DispatcherOperationStatus.Pending })
        {
            return;
        }

        if (_galleryFocusCompletionOperation is { Status: DispatcherOperationStatus.Pending } staleOperation)
            staleOperation.Abort();
        _queuedGalleryFocusCompletionGeneration = generation;
        _galleryFocusCompletionOperation = Dispatcher.BeginInvoke(() =>
        {
            if (_queuedGalleryFocusCompletionGeneration == generation)
            {
                _queuedGalleryFocusCompletionGeneration = -1;
                _galleryFocusCompletionOperation = null;
            }
            if (generation == _galleryFocusRequestGeneration)
                TryCompletePendingGalleryFocus();
        }, DispatcherPriority.Background);
    }

    private void TryCompletePendingGalleryFocus()
    {
        int index = _pendingGalleryFocusIndex;
        string? path = _pendingGalleryFocusPath;
        if (index < 0 || string.IsNullOrWhiteSpace(path))
            return;

        ListBox listBox = _pendingGalleryFocusGrid ? CardsList : RowsList;
        if (listBox.Visibility != Visibility.Visible)
            return;
        if (index >= _tiles.Count)
            return;
        if (!string.Equals(_tiles[index].Path, path, StringComparison.OrdinalIgnoreCase))
            return;
        if (!string.Equals(_primarySelectedPath, path, StringComparison.OrdinalIgnoreCase))
            return;
        if (RealizedGalleryContainer(listBox, index) is not ListBoxItem container)
        {
            RetryPendingGalleryFocusCompletion(listBox, index);
            return;
        }
        if (container.DataContext is not Tile boundTile
            || !ReferenceEquals(boundTile, _tiles[index]))
            return;
        if (!container.IsMeasureValid)
        {
            RetryPendingGalleryFocusCompletion(listBox, index);
            return;
        }
        if (!container.IsVisible)
        {
            RetryPendingGalleryFocusCompletion(listBox, index);
            return;
        }
        if (!container.IsEnabled)
            return;

        SelectRealizedContainer(listBox, _tiles[index]);
        if (!container.Focus() || !container.IsKeyboardFocusWithin)
        {
            RetryPendingGalleryFocusCompletion(listBox, index);
            return;
        }

        _pendingGalleryFocusPath = null;
        _pendingGalleryFocusIndex = -1;
        _pendingGalleryFocusRetryCount = 0;
    }

    private void RetryPendingGalleryFocusCompletion(ListBox listBox, int index)
    {
        if (_pendingGalleryFocusRetryCount >= MaxPendingGalleryFocusRetryCount)
            return;
        _pendingGalleryFocusRetryCount++;
        if (ReferenceEquals(listBox, CardsList))
            _galleryVirtualizingPanel?.BringItemIntoView(index);
        else if (index >= 0 && index < _tiles.Count)
            RowsList.ScrollIntoView(_tiles[index]);
        Dispatcher.BeginInvoke(
            QueuePendingGalleryFocusCompletion,
            DispatcherPriority.Render);
    }

    private ListBoxItem? RealizedGalleryContainer(ListBox listBox, int index)
    {
        if (ReferenceEquals(listBox, CardsList)
            && _galleryVirtualizingPanel is { } panel)
        {
            return panel.RealizedContainerForIndex(index);
        }
        return listBox.ItemContainerGenerator.ContainerFromIndex(index)
            as ListBoxItem;
    }

    private void CancelPendingGalleryFocus()
    {
        _galleryFocusRequestGeneration++;
        if (_galleryFocusCompletionOperation is { Status: DispatcherOperationStatus.Pending } operation)
            operation.Abort();
        _galleryFocusCompletionOperation = null;
        _queuedGalleryFocusCompletionGeneration = -1;
        _pendingGalleryFocusPath = null;
        _pendingGalleryFocusIndex = -1;
        _pendingGalleryFocusRetryCount = 0;
    }

    private IReadOnlyList<Tile> SelectedTiles()
    {
        if (_selectedPaths.Count == 0)
            return [];
        if (_selectedPaths.Count == 1 && SelectedTile() is { } selected)
            return [selected];
        return _tiles.Where(tile => _selectedPaths.Contains(tile.Path)).ToList();
    }

    private void SetSelection(
        IEnumerable<Tile> selectedTiles,
        Tile? primary,
        int? primaryIndex = null,
        bool deferPrimaryPresentation = false,
        bool realizedOnlyVisuals = false)
    {
        CancelPendingGalleryFocus();
        _selectedPaths.Clear();
        int knownPrimaryIndex = primaryIndex.GetValueOrDefault(-1);
        bool primaryIndexIsKnown = primary is not null
            && knownPrimaryIndex >= 0
            && knownPrimaryIndex < _tiles.Count
            && ReferenceEquals(_tiles[knownPrimaryIndex], primary);
        IReadOnlyList<Tile>? materializedSelection = null;
        if (selectedTiles is IReadOnlyCollection<Tile> collection
            && collection.Count > MaxMaterializedSelectionVisualItems)
        {
            var availablePaths = new HashSet<string>(
                _tiles.Select(static tile => tile.Path),
                StringComparer.OrdinalIgnoreCase);
            foreach (Tile tile in selectedTiles)
            {
                if (availablePaths.Contains(tile.Path))
                    _selectedPaths.Add(tile.Path);
            }
        }
        else
        {
            var accepted = new List<Tile>(
                selectedTiles is IReadOnlyCollection<Tile> knownCollection
                    ? knownCollection.Count
                    : 4);
            foreach (Tile tile in selectedTiles)
            {
                bool available = primaryIndexIsKnown && ReferenceEquals(tile, primary)
                    || _tiles.Contains(tile);
                if (available && _selectedPaths.Add(tile.Path))
                    accepted.Add(tile);
            }
            materializedSelection = accepted;
        }

        Tile? effectivePrimary = primary is not null && _selectedPaths.Contains(primary.Path)
            ? primary
            : materializedSelection?.LastOrDefault()
                ?? SelectedTiles().LastOrDefault();
        _primarySelectedPath = effectivePrimary?.Path;
        _primarySelectedTile = effectivePrimary;
        _primarySelectedIndex = effectivePrimary is null
            ? -1
            : primaryIndexIsKnown
                && ReferenceEquals(primary, effectivePrimary)
                    ? knownPrimaryIndex
                    : _tiles.IndexOf(effectivePrimary);
        _selectionVisualSyncGeneration++;

        SynchronizeSelectionControls(
            materializedSelection,
            realizedOnly: realizedOnlyVisuals);
        if (deferPrimaryPresentation && effectivePrimary is not null)
            QueuePrimarySelectionPresentation(effectivePrimary, _primarySelectedIndex);
        else
            ApplyPrimarySelection(effectivePrimary, _primarySelectedIndex);
    }

    private void QueuePrimarySelectionPresentation(Tile primary, int projectedIndex)
    {
        long generation = _selectionVisualSyncGeneration;
        string path = primary.Path;
        Dispatcher.BeginInvoke(() =>
        {
            if (generation != _selectionVisualSyncGeneration
                || projectedIndex < 0
                || projectedIndex >= _tiles.Count
                || !ReferenceEquals(_tiles[projectedIndex], primary)
                || !string.Equals(_primarySelectedPath, path, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            // QueuePrimaryGalleryFocus already owns viewport realization for
            // keyboard navigation. Repeating ScrollIntoView here would merge
            // gallery and preview layout into one long dispatcher interval.
            ApplyPrimarySelection(primary, projectedIndex, ensureSelectionVisible: false);
        }, DispatcherPriority.ContextIdle);
    }

    private void SynchronizeSelectionControls(
        IReadOnlyList<Tile>? knownMaterializedSelection = null,
        bool realizedOnly = false)
    {
        if (_syncingSelection)
            return;

        try
        {
            _syncingSelection = true;
            bool hugeSparseSelection =
                _selectedPaths.Count > MaxMaterializedSelectionVisualItems;
            bool realizedOnlyVisuals = hugeSparseSelection || realizedOnly;
            IReadOnlyList<Tile>? materializedSelections = hugeSparseSelection
                ? null
                : knownMaterializedSelection
                    ?? _tiles.Where(tile => _selectedPaths.Contains(tile.Path)).ToList();
            SynchronizeCanonicalSelectionMarkers(materializedSelections);
            var cardsWatch = Stopwatch.StartNew();
            if (realizedOnlyVisuals)
                SynchronizeRealizedSelectionControl(CardsList);
            else
                SynchronizeSelectionControl(CardsList, materializedSelections!);
            cardsWatch.Stop();
            _lastCardsSelectionSyncMs = cardsWatch.ElapsedMilliseconds;
            var rowsWatch = Stopwatch.StartNew();
            if (realizedOnlyVisuals)
                SynchronizeRealizedSelectionControl(RowsList);
            else
                SynchronizeSelectionControl(RowsList, materializedSelections!);
            rowsWatch.Stop();
            _lastRowsSelectionSyncMs = rowsWatch.ElapsedMilliseconds;
        }
        finally
        {
            _syncingSelection = false;
        }
    }

    private (long ElapsedMs, bool Cleared, int ReleasedCount)
        ReleaseWpfSelectionBeforeCatalogPublication()
    {
        int selectedBefore =
            CardsList.SelectedItems.Count + RowsList.SelectedItems.Count;
        bool wasSyncingSelection = _syncingSelection;
        _syncingSelection = true;
        var watch = Stopwatch.StartNew();
        try
        {
            // WPF Selector.Reset locates any unresolved selected ItemInfo by
            // walking the new Items collection from index zero. Release only
            // WPF's bounded visual selection while its indices are still
            // current; Aibos keeps the canonical path selection and restores
            // the realized state after publication.
            if (CardsList.SelectedItems.Count > 0)
                CardsList.SelectedIndex = -1;
            if (RowsList.SelectedItems.Count > 0)
                RowsList.SelectedIndex = -1;
        }
        finally
        {
            watch.Stop();
            _syncingSelection = wasSyncingSelection;
        }

        return (
            watch.ElapsedMilliseconds,
            CardsList.SelectedItems.Count == 0
                && RowsList.SelectedItems.Count == 0,
            selectedBefore);
    }

    private bool ShouldReleaseWpfSelectionBeforeCatalogPublication(FilterResult filterResult)
    {
        IEnumerable<Tile> selectedVisualTiles =
            CardsList.SelectedItems.OfType<Tile>()
                .Concat(RowsList.SelectedItems.OfType<Tile>());
        Tile[] selectedVisualSnapshot = selectedVisualTiles.Distinct().ToArray();
        if (selectedVisualSnapshot.Length == 0)
            return false;

        // The exact favorites-only Remove path is cheap only while WPF does
        // not own the item that is about to disappear. Release that one
        // bounded visual selection before the Remove notification; canonical
        // selection chooses and restores the neighboring item afterwards.
        if (filterResult.ExactSingleRemovalIndex.HasValue
            && selectedVisualSnapshot.Any(selected =>
                !filterResult.SelectedTiles.Contains(selected)))
        {
            return true;
        }

        // Selector.LocateSelectedItems must relocate every selected ItemInfo,
        // not only the primary one. The worker computes the farthest surviving
        // selection (or the complete projection length when any selection is
        // evicted) so an Extended selection with a near primary cannot hide a
        // far-tail scan from this dispatcher-bound decision.
        return filterResult.SelectedRelocationScanLength
            >= CatalogResetSelectionScanReleaseThreshold;
    }

    private void SynchronizeCanonicalSelectionMarkers(IReadOnlyCollection<Tile>? selectedTiles)
    {
        HashSet<Tile>? next = selectedTiles is null ? null : [.. selectedTiles];
        foreach (Tile tile in _canonicalSelectionMarkers)
        {
            if (next?.Contains(tile) != true)
                tile.IsCanonicalSelected = false;
        }

        _canonicalSelectionMarkers.Clear();
        if (next is null)
            return;

        foreach (Tile tile in next)
        {
            tile.IsCanonicalSelected = true;
            _canonicalSelectionMarkers.Add(tile);
        }
    }

    private static void SynchronizeSelectionControl(ListBox listBox, IReadOnlyList<Tile> selectedTiles)
    {
        // The hidden surface is reconciled when it becomes visible. Touching a
        // grouped 20k-item ListBox here can force full index resolution even
        // though no visual state is observable.
        if (listBox.Visibility != Visibility.Visible)
            return;

        if (selectedTiles.Count <= 1)
        {
            // SelectedItems.Clear() asks a grouped 100k-item ListBox to resolve
            // every stored selection index. Canonical selection already lives
            // on Tile, so reconcile only the bounded realized containers. The
            // target container is selected when priority realization finishes.
            foreach (ListBoxItem container in FindVisualDescendants<ListBoxItem>(listBox))
            {
                bool selected = selectedTiles.Count == 1
                    && ReferenceEquals(container.DataContext, selectedTiles[0]);
                if (container.IsSelected != selected)
                    container.IsSelected = selected;
            }
            return;
        }

        listBox.SelectedItems.Clear();
        foreach (Tile tile in selectedTiles)
            listBox.SelectedItems.Add(tile);
    }

    private void SynchronizeRealizedSelectionControl(ListBox listBox)
    {
        if (listBox.Visibility != Visibility.Visible)
            return;

        // Canonical selection lives in _selectedPaths. WPF SelectedItems is
        // deliberately only a bounded visual projection for very large sets;
        // asking it to own 100k entries defeats virtualization and can hang UI.
        foreach (ListBoxItem container in FindVisualDescendants<ListBoxItem>(listBox))
        {
            bool selected = container.DataContext is Tile tile && _selectedPaths.Contains(tile.Path);
            if (container.IsSelected != selected)
                container.IsSelected = selected;
        }
    }

    private void QueueSparseSelectionVisualSync(ListBox listBox, bool grid)
    {
        if (_selectedPaths.Count <= MaxMaterializedSelectionVisualItems
            || listBox.Visibility != Visibility.Visible)
        {
            return;
        }

        long generation = _selectionVisualSyncGeneration;
        if (grid)
        {
            if (_queuedSparseGridSelectionVisualSyncGeneration == generation)
                return;
            _queuedSparseGridSelectionVisualSyncGeneration = generation;
        }
        else
        {
            if (_queuedSparseListSelectionVisualSyncGeneration == generation)
                return;
            _queuedSparseListSelectionVisualSyncGeneration = generation;
        }

        Dispatcher.BeginInvoke(() =>
        {
            if (grid && _queuedSparseGridSelectionVisualSyncGeneration == generation)
                _queuedSparseGridSelectionVisualSyncGeneration = -1;
            if (!grid && _queuedSparseListSelectionVisualSyncGeneration == generation)
                _queuedSparseListSelectionVisualSyncGeneration = -1;
            if (generation != _selectionVisualSyncGeneration
                || _selectedPaths.Count <= MaxMaterializedSelectionVisualItems
                || listBox.Visibility != Visibility.Visible)
            {
                return;
            }

            bool wasSyncingSelection = _syncingSelection;
            _syncingSelection = true;
            try
            {
                SynchronizeRealizedSelectionControl(listBox);
            }
            finally
            {
                _syncingSelection = wasSyncingSelection;
            }
        }, DispatcherPriority.Render);
    }

    private void ApplyPrimarySelection(
        Tile? primary,
        int projectedIndex = -1,
        bool ensureSelectionVisible = true)
    {
        if (primary is null)
        {
            ClearPreview();
            return;
        }

        _lastEnsureGridSelectionMs = 0;
        var cardsScrollWatch = Stopwatch.StartNew();
        if (ensureSelectionVisible && CardsList.Visibility == Visibility.Visible)
        {
            int index = projectedIndex >= 0
                && projectedIndex < _tiles.Count
                && ReferenceEquals(_tiles[projectedIndex], primary)
                    ? projectedIndex
                    : _tiles.IndexOf(primary);
            // ListBox.ScrollIntoView queues a second ItemContainerGenerator
            // navigation after a Reset. At 100k items that deferred WPF path
            // can monopolize the dispatcher seconds after filtering has already
            // completed. The gallery panel owns the exact extent, so move its
            // viewport directly and let the bounded realization pass follow.
            if (index < 0 || _galleryVirtualizingPanel?.BringItemIntoView(index) != true)
                CardsList.ScrollIntoView(primary);
            QueueGridSelectionVisualSync(primary);
        }
        cardsScrollWatch.Stop();
        _lastCardsScrollSelectionMs = cardsScrollWatch.ElapsedMilliseconds;
        var rowsScrollWatch = Stopwatch.StartNew();
        if (ensureSelectionVisible && RowsList.Visibility == Visibility.Visible)
        {
            RowsList.ScrollIntoView(primary);
            SelectRealizedContainer(RowsList, primary);
            QueueListSelectionVisualSync(primary);
        }
        rowsScrollWatch.Stop();
        _lastRowsScrollSelectionMs = rowsScrollWatch.ElapsedMilliseconds;
        var previewWatch = Stopwatch.StartNew();
        UpdatePreview(primary);
        previewWatch.Stop();
        _lastPreviewSelectionMs = previewWatch.ElapsedMilliseconds;
        if (primary.IsRealFile)
        {
            var seenWatch = Stopwatch.StartNew();
            MarkTileSeen(primary);
            seenWatch.Stop();
            _lastSeenSelectionMs = seenWatch.ElapsedMilliseconds;
            SaveState();
        }
    }

    private void SelectRealizedContainer(ListBox listBox, Tile tile)
    {
        if (listBox.ItemContainerGenerator.ContainerFromItem(tile) is not ListBoxItem container || container.IsSelected)
            return;

        bool wasSyncingSelection = _syncingSelection;
        _syncingSelection = true;
        try
        {
            container.IsSelected = true;
        }
        finally
        {
            _syncingSelection = wasSyncingSelection;
        }
    }

    private void QueueGridSelectionVisualSync(Tile tile)
    {
        long generation = _selectionVisualSyncGeneration;
        if (_queuedGridSelectionVisualSyncGeneration == generation)
            return;

        _queuedGridSelectionVisualSyncGeneration = generation;
        string path = tile.Path;
        Dispatcher.BeginInvoke(() =>
        {
            if (_queuedGridSelectionVisualSyncGeneration == generation)
                _queuedGridSelectionVisualSyncGeneration = -1;

            if (generation != _selectionVisualSyncGeneration
                || CardsList.Visibility != Visibility.Visible
                || !_selectedPaths.Contains(path)
                || !string.Equals(_primarySelectedPath, path, StringComparison.OrdinalIgnoreCase)
                || !_tiles.Contains(tile))
            {
                return;
            }

            // ScrollIntoView queues container generation. Reapply only the
            // canonical primary container after render; never enumerate the
            // catalog, move focus, or trigger another scroll from this callback.
            SelectRealizedContainer(CardsList, tile);
        }, DispatcherPriority.Render);
    }

    private void QueueListSelectionVisualSync(Tile tile)
    {
        long generation = _selectionVisualSyncGeneration;
        if (_queuedListSelectionVisualSyncGeneration == generation)
            return;

        _queuedListSelectionVisualSyncGeneration = generation;
        string path = tile.Path;
        Dispatcher.BeginInvoke(() =>
        {
            if (_queuedListSelectionVisualSyncGeneration == generation)
                _queuedListSelectionVisualSyncGeneration = -1;

            if (generation != _selectionVisualSyncGeneration
                || RowsList.Visibility != Visibility.Visible
                || !_selectedPaths.Contains(path)
                || !string.Equals(_primarySelectedPath, path, StringComparison.OrdinalIgnoreCase)
                || !_tiles.Contains(tile))
            {
                return;
            }

            SelectRealizedContainer(RowsList, tile);
        }, DispatcherPriority.Render);
    }

    private void UpdatePreview(Tile t)
    {
        RightPreviewContent.Visibility = Visibility.Visible;
        RightPreviewEmptyState.Visibility = Visibility.Collapsed;
        var watch = Stopwatch.StartNew();
        bool hasRealFile = t.IsRealFile;
        Visibility generatedMetadataVisibility = hasRealFile ? Visibility.Collapsed : Visibility.Visible;
        _previewCts?.Cancel();
        _previewDecodeCompletion?.TrySetResult(PreviewDecodeResult.Canceled);
        _previewMetadataCts?.Cancel();
        _previewMetadataCompletion?.TrySetResult(null);
        ClearPreviewMetadataCopyState();
        _previewDecodedPath = null;

        var cts = new CancellationTokenSource();
        _previewCts = cts;
        var completion = new TaskCompletionSource<PreviewDecodeResult>(TaskCreationOptions.RunContinuationsAsynchronously);
        _previewDecodeCompletion = completion;

        var immediate = hasRealFile ? t.Thumbnail : null;
        PreviewBitmap.Source = immediate;
        PreviewBitmap.Visibility = immediate is null ? Visibility.Collapsed : Visibility.Visible;
        PreviewArtBase.Visibility = immediate is null ? Visibility.Visible : Visibility.Collapsed;
        PreviewArtGlow.Visibility = immediate is null ? Visibility.Visible : Visibility.Collapsed;
        PreviewArtBase.Fill = t.ArtBase;
        PreviewArtGlow.Fill = t.ArtGlow;
        PreviewFileName.Text = t.FileName;
        PreviewTabName.Text = t.FileName;
        PreviewSizeText.Text = hasRealFile
            ? t.ImagePixelWidth > 0 && t.ImagePixelHeight > 0
                ? $"{t.ImagePixelWidth} x {t.ImagePixelHeight}"
                : "Loading..."
            : t.SizeText;
        PreviewModelLabel.Text = hasRealFile ? "TYPE" : "MODEL";
        PreviewModelText.Text = hasRealFile
            ? Path.GetExtension(t.Path).TrimStart('.').ToUpperInvariant()
            : "animagineXL_v31";
        PreviewPromptLabel.Text = hasRealFile ? "PATH" : "PROMPT";
        PreviewSamplerLabel.Visibility = generatedMetadataVisibility;
        PreviewSamplerText.Visibility = generatedMetadataVisibility;
        PreviewStepsLabel.Visibility = generatedMetadataVisibility;
        PreviewStepsText.Visibility = generatedMetadataVisibility;
        PreviewCfgLabel.Visibility = generatedMetadataVisibility;
        PreviewCfgText.Visibility = generatedMetadataVisibility;
        PreviewSeedLabel.Visibility = generatedMetadataVisibility;
        PreviewSeedText.Visibility = generatedMetadataVisibility;
        PreviewNegativeLabel.Visibility = generatedMetadataVisibility;
        PreviewNegativeCard.Visibility = generatedMetadataVisibility;
        if (hasRealFile)
            PreviewNegativeText.Text = "";
        PreviewDateText.Text = t.ModifiedText;
        PreviewPromptText.Text = hasRealFile
            ? t.Path
            : string.IsNullOrWhiteSpace(t.Prompt)
                ? t.Path
                : FormatPromptTagsForDisplay(t.Prompt);
        SyncFavoriteLevelReadouts(t.Fav);
        SyncSelectionActionSurface();
        UpdateHeaderStats();
        ModalTitle.Text = $"{t.FileName} - {PreviewSizeText.Text}";
        watch.Stop();
        _previewUpdateCount++;
        _previewMs += watch.ElapsedMilliseconds;
        _lastPreviewImmediateMs = watch.ElapsedMilliseconds;

        if (hasRealFile)
        {
            _ = LoadPreviewBitmapAsync(t.Path, cts.Token, completion);
            var metadataCts = new CancellationTokenSource();
            _previewMetadataCts = metadataCts;
            var metadataCompletion = new TaskCompletionSource<PngParametersMetadata?>(TaskCreationOptions.RunContinuationsAsynchronously);
            _previewMetadataCompletion = metadataCompletion;
            _ = LoadPreviewPngMetadataAsync(t.Path, metadataCts.Token, metadataCompletion);
        }
        else
            completion.TrySetResult(new PreviewDecodeResult(t.Path, immediate, 0, 0, 0, Applied: true));
    }

    private async Task LoadPreviewBitmapAsync(string path, CancellationToken token, TaskCompletionSource<PreviewDecodeResult> completion)
    {
        PreviewDecodeResult decoded;
        try
        {
            decoded = await Task.Run(
                () =>
                {
                    if (_previewDecodeDelayForSmokeMs > 0)
                        Thread.Sleep(_previewDecodeDelayForSmokeMs);
                    var watch = Stopwatch.StartNew();
                    var bitmap = LoadBitmap(path, 900);
                    bool hasSize = TryReadBitmapSize(path, out int width, out int height);
                    watch.Stop();
                    return new PreviewDecodeResult(path, bitmap, hasSize ? width : 0, hasSize ? height : 0, watch.ElapsedMilliseconds, Applied: false);
                },
                token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetResult(PreviewDecodeResult.Canceled);
            return;
        }
        catch
        {
            completion.TrySetResult(new PreviewDecodeResult(path, null, 0, 0, 0, Applied: false));
            return;
        }

        if (token.IsCancellationRequested)
        {
            completion.TrySetResult(PreviewDecodeResult.Canceled);
            return;
        }

        try
        {
            await Dispatcher.InvokeAsync(
                () =>
                {
                    if (token.IsCancellationRequested || !string.Equals(SelectedTile()?.Path, path, StringComparison.OrdinalIgnoreCase))
                    {
                        completion.TrySetResult(PreviewDecodeResult.Canceled);
                        return;
                    }

                    if (decoded.Bitmap is not null)
                    {
                        PreviewBitmap.Source = decoded.Bitmap;
                        PreviewBitmap.Visibility = Visibility.Visible;
                        PreviewArtBase.Visibility = Visibility.Collapsed;
                        PreviewArtGlow.Visibility = Visibility.Collapsed;
                    }
                    else
                    {
                        // The immediate source may be a thumbnail decoded before
                        // an external truncate, lock, or replacement. A failed
                        // full decode must not leave that stale bitmap presented
                        // as the current file.
                        PreviewBitmap.Source = null;
                        PreviewBitmap.Visibility = Visibility.Collapsed;
                        PreviewArtBase.Visibility = Visibility.Visible;
                        PreviewArtGlow.Visibility = Visibility.Visible;
                        PreviewSizeText.Text = "Could not decode";
                        ReportCurrentImageDecodeFailure();
                    }

                    if (decoded.Width > 0 && decoded.Height > 0)
                        PreviewSizeText.Text = $"{decoded.Width} x {decoded.Height}";

                    ModalTitle.Text = $"{PreviewFileName.Text} - {PreviewSizeText.Text}";
                    _previewDecodedPath = path;
                    _previewDeferredDecodeCount++;
                    _previewDeferredDecodeMs += decoded.DecodeMs;
                    if (LastLoadMetrics is not null)
                    {
                        LastLoadMetrics.PreviewDeferredDecodeMs = _previewDeferredDecodeMs;
                        LastLoadMetrics.PreviewDeferredDecodeCount = _previewDeferredDecodeCount;
                    }

                    completion.TrySetResult(decoded with { Applied = true });
                },
                DispatcherPriority.Background,
                token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetResult(PreviewDecodeResult.Canceled);
        }
    }

    private async Task LoadPreviewPngMetadataAsync(
        string path,
        CancellationToken token,
        TaskCompletionSource<PngParametersMetadata?> completion)
    {
        PngParametersMetadata? metadata;
        try
        {
            metadata = await Task.Run(() => ReadPngParametersMetadata(path, token), token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetResult(null);
            return;
        }
        catch
        {
            completion.TrySetResult(null);
            return;
        }

        if (token.IsCancellationRequested)
        {
            completion.TrySetResult(null);
            return;
        }

        try
        {
            await Dispatcher.InvokeAsync(
                () =>
                {
                    if (token.IsCancellationRequested || !string.Equals(SelectedTile()?.Path, path, StringComparison.OrdinalIgnoreCase))
                    {
                        completion.TrySetResult(null);
                        return;
                    }

                    if (metadata is not null)
                        ApplyPngParametersMetadata(metadata);
                    completion.TrySetResult(metadata);
                },
                DispatcherPriority.Background,
                token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetResult(null);
        }
    }

    private void ApplyPngParametersMetadata(PngParametersMetadata metadata)
    {
        Tile? selected = SelectedTile();
        if (selected is null)
            return;

        _currentPreviewMetadata = metadata;
        _currentPreviewMetadataPath = selected.Path;
        CopyPreviewMetadataButton.IsEnabled = true;
        CopyPreviewMetadataButton.Content = "Copy";
        CopyPreviewMetadataButton.ToolTip = "Copy PNG metadata";
        CopyPreviewPromptButton.IsEnabled = !string.IsNullOrWhiteSpace(metadata.Prompt);
        CopyPreviewPromptButton.ToolTip = CopyPreviewPromptButton.IsEnabled ? "Copy prompt" : "No prompt metadata loaded";
        CopyPreviewNegativeButton.IsEnabled = !string.IsNullOrWhiteSpace(metadata.NegativePrompt);
        CopyPreviewNegativeButton.ToolTip = CopyPreviewNegativeButton.IsEnabled ? "Copy negative prompt" : "No negative prompt metadata loaded";
        PreviewPromptLabel.Text = "PROMPT";
        PreviewPromptText.Text = string.IsNullOrWhiteSpace(metadata.Prompt)
            ? PreviewPromptText.Text
            : FormatPromptTagsForDisplay(metadata.Prompt);
        SetPreviewMetadataRow(PreviewSamplerLabel, PreviewSamplerText, "SAMPLER", metadata.Setting("Sampler"));
        SetPreviewMetadataRow(PreviewStepsLabel, PreviewStepsText, "STEPS", metadata.Setting("Steps"));
        SetPreviewMetadataRow(PreviewCfgLabel, PreviewCfgText, "CFG", metadata.Setting("CFG scale"));
        SetPreviewMetadataRow(PreviewSeedLabel, PreviewSeedText, "SEED", metadata.Setting("Seed"));

        bool hasNegative = !string.IsNullOrWhiteSpace(metadata.NegativePrompt);
        PreviewNegativeLabel.Visibility = hasNegative ? Visibility.Visible : Visibility.Collapsed;
        PreviewNegativeCard.Visibility = hasNegative ? Visibility.Visible : Visibility.Collapsed;
        PreviewNegativeText.Text = hasNegative ? metadata.NegativePrompt : "";
        SyncModalMetadataSidebar();
    }

    private void SyncModalMetadataSidebar()
    {
        Tile? selected = SelectedTile();
        bool current = selected is not null
            && _currentPreviewMetadata is not null
            && string.Equals(selected.Path, _currentPreviewMetadataPath, StringComparison.OrdinalIgnoreCase);
        PngParametersMetadata? metadata = current ? _currentPreviewMetadata : null;
        bool hasPrompt = !string.IsNullOrWhiteSpace(metadata?.Prompt);
        bool hasNegative = !string.IsNullOrWhiteSpace(metadata?.NegativePrompt);

        string settingsText = metadata is not null && metadata.Settings.Count > 0
            ? string.Join("  ·  ", metadata.Settings.Select(static pair => $"{pair.Key}: {pair.Value}"))
            : "No settings metadata.";
        ModalSettingsText.Text = settingsText;
        ModalMetadataStatusText.Text = metadata is null
            ? "No PNG metadata loaded"
            : metadata.Settings.Count > 0
                ? settingsText
                : "PNG parameters loaded";
        SyncModalPromptChips(hasPrompt ? metadata!.Prompt : "");
        ModalPromptText.Text = hasPrompt ? string.Join(", ", _modalPromptChipTags) : "-";
        ModalNegativeText.Text = hasNegative ? metadata!.NegativePrompt : "-";
        CopyModalMetadataButton.IsEnabled = metadata is not null;
        CopyModalMetadataButton.ToolTip = metadata is null ? "No PNG metadata loaded" : "Copy PNG metadata";
        CopyModalPromptButton.IsEnabled = hasPrompt;
        CopyModalPromptButton.ToolTip = hasPrompt ? "Copy prompt" : "No prompt metadata loaded";
        CopyModalNegativeButton.IsEnabled = hasNegative;
        CopyModalNegativeButton.ToolTip = hasNegative ? "Copy negative prompt" : "No negative prompt metadata loaded";
    }

    private static List<string> ParsePromptTags(string? prompt)
    {
        var tags = new List<string>();
        if (string.IsNullOrEmpty(prompt))
            return tags;

        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        int scanLength = Math.Min(prompt.Length, MaxModalPromptScanCharacters);
        int segmentStart = 0;
        for (int index = 0; index <= scanLength; index++)
        {
            if (index < scanLength && prompt[index] != ',')
                continue;

            int segmentLength = index - segmentStart;
            if (segmentLength <= 0 || segmentLength > MaxModalPromptTagCharacters)
            {
                segmentStart = index + 1;
                continue;
            }

            string rawTag = prompt.Substring(segmentStart, segmentLength);
            segmentStart = index + 1;
            string tag = NormalizePromptTagForDisplay(rawTag);
            if (tag.Length < 2 || tag.Contains('\n') || tag.Contains('\r'))
                continue;
            if (seen.Add(tag))
                tags.Add(tag);
            if (tags.Count >= MaxModalPromptTagCount)
                break;
        }
        return tags;
    }

    private static string NormalizePromptTagForDisplay(string rawTag)
    {
        int start = 0;
        while (start < rawTag.Length
            && (char.IsWhiteSpace(rawTag[start]) || rawTag[start] is '(' or '[' or '{'))
        {
            start++;
        }

        int end = rawTag.Length - 1;
        while (end >= start
            && (char.IsWhiteSpace(rawTag[end]) || rawTag[end] is ')' or ']' or '}'))
        {
            end--;
        }
        return end < start ? "" : rawTag[start..(end + 1)].Trim();
    }

    private static string FormatPromptTagsForDisplay(string? prompt)
        => string.Join(", ", ParsePromptTags(prompt));

    private void SyncModalPromptChips(string prompt)
    {
        if (ModalPromptChips is null)
            return;

        if (string.Equals(_modalPromptChipSource, prompt, StringComparison.Ordinal))
        {
            StartModalPromptChipRealization();
            return;
        }

        CancelModalPromptChipRealization();
        _modalPromptChipSource = prompt;
        _modalPromptChipTags = ParsePromptTags(prompt);
        _modalPromptChipNextIndex = 0;
        ModalPromptChips.Children.Clear();
        ModalPromptEmptyText.Visibility = _modalPromptChipTags.Count == 0 ? Visibility.Visible : Visibility.Collapsed;
        StartModalPromptChipRealization();
    }

    private bool ModalPromptChipSurfaceVisible()
        => ModalMetadataSidebar.Visibility == Visibility.Visible
            && ModalPromptPanel.Visibility == Visibility.Visible;

    private void StartModalPromptChipRealization()
    {
        if (!ModalPromptChipSurfaceVisible()
            || _modalPromptChipNextIndex >= _modalPromptChipTags.Count)
        {
            return;
        }

        long generation = _modalPromptChipGeneration;
        int count = _modalPromptChipNextIndex == 0
            ? ImmediateModalPromptChipCount
            : ModalPromptChipBatchCount;
        RealizeModalPromptChipBatch(generation, count);
    }

    private void RealizeModalPromptChipBatch(long generation, int count)
    {
        if (generation != _modalPromptChipGeneration || !ModalPromptChipSurfaceVisible())
            return;

        int end = Math.Min(_modalPromptChipNextIndex + Math.Max(1, count), _modalPromptChipTags.Count);
        while (_modalPromptChipNextIndex < end)
        {
            AddModalPromptChip(_modalPromptChipTags[_modalPromptChipNextIndex]);
            _modalPromptChipNextIndex++;
        }

        if (_modalPromptChipNextIndex >= _modalPromptChipTags.Count || _modalPromptChipRealizationScheduled)
            return;

        _modalPromptChipRealizationScheduled = true;
        Dispatcher.BeginInvoke(
            () =>
            {
                _modalPromptChipRealizationScheduled = false;
                RealizeModalPromptChipBatch(generation, ModalPromptChipBatchCount);
            },
            DispatcherPriority.ContextIdle);
    }

    private void AddModalPromptChip(string tag)
    {
        var chip = new Button
        {
            Content = tag,
            Tag = tag,
            Style = (Style)FindResource("GhostButton"),
            Padding = new Thickness(8, 3, 8, 3),
            Margin = new Thickness(0, 0, 6, 6),
            FontSize = 11.5,
            ToolTip = $"Search for {tag}",
        };
        System.Windows.Automation.AutomationProperties.SetName(chip, $"Search prompt tag {tag}");
        System.Windows.Automation.AutomationProperties.SetHelpText(chip, "Append this tag to search, close the modal, and focus search.");
        chip.Click += ModalPromptTag_Click;
        chip.PreviewKeyDown += ModalPromptTag_PreviewKeyDown;
        ModalPromptChips.Children.Add(chip);
    }

    private void CancelModalPromptChipRealization()
    {
        _modalPromptChipGeneration++;
        _modalPromptChipRealizationScheduled = false;
    }

    private void RealizeAllModalPromptChipsForSmoke()
    {
        while (_modalPromptChipNextIndex < _modalPromptChipTags.Count)
        {
            AddModalPromptChip(_modalPromptChipTags[_modalPromptChipNextIndex]);
            _modalPromptChipNextIndex++;
        }
    }

    private void ModalPromptTag_Click(object sender, RoutedEventArgs e)
    {
        if (sender is Button { Tag: string tag })
            ApplyModalPromptTagSearch(tag);
    }

    private void ModalPromptTag_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (e.Key is not (Key.Enter or Key.Space) || sender is not Button { Tag: string tag })
            return;

        e.Handled = true;
        ApplyModalPromptTagSearch(tag);
    }

    private bool ApplyModalPromptTagSearch(string tag)
    {
        string normalizedTag = tag.Trim();
        if (normalizedTag.Length == 0)
            return false;

        List<string> queryTags = ParsePromptTags(SearchInput.Text);
        if (!queryTags.Contains(normalizedTag, StringComparer.OrdinalIgnoreCase))
            queryTags.Add(normalizedTag);

        if (_activeAlbumId is not null)
        {
            Interlocked.Increment(ref _activeAlbumAsyncGeneration);
            Interlocked.Exchange(ref _activeAlbumAvailabilityCts, null)?.Cancel();
            ApplyActiveAlbumSource(null, 0, 0);
        }
        SetSearchQuery(string.Join(", ", queryTags));
        CloseModal();
        SearchInput.Focus();
        return true;
    }

    private void ClearPreviewMetadataCopyState()
    {
        _currentPreviewMetadata = null;
        _currentPreviewMetadataPath = null;
        _lastMetadataCopyText = "";
        if (CopyPreviewMetadataButton is null)
            return;
        CopyPreviewMetadataButton.IsEnabled = false;
        CopyPreviewMetadataButton.Content = "Copy";
        CopyPreviewMetadataButton.ToolTip = "No PNG metadata loaded";
        CopyPreviewPromptButton.IsEnabled = false;
        CopyPreviewPromptButton.Content = "Copy";
        CopyPreviewPromptButton.ToolTip = "No prompt metadata loaded";
        CopyPreviewNegativeButton.IsEnabled = false;
        CopyPreviewNegativeButton.Content = "Copy";
        CopyPreviewNegativeButton.ToolTip = "No negative prompt metadata loaded";
        if (ModalMetadataStatusText is not null)
            SyncModalMetadataSidebar();
    }

    private void CopyPreviewPrompt_Click(object sender, RoutedEventArgs e)
        => CopyCurrentPreviewMetadataValue(negative: false, useSystemClipboard: true);

    private void CopyPreviewNegative_Click(object sender, RoutedEventArgs e)
        => CopyCurrentPreviewMetadataValue(negative: true, useSystemClipboard: true);

    private bool CopyCurrentPreviewMetadataValue(bool negative, bool useSystemClipboard)
    {
        Tile? selected = SelectedTile();
        if (selected is null || _currentPreviewMetadata is null
            || !string.Equals(selected.Path, _currentPreviewMetadataPath, StringComparison.OrdinalIgnoreCase))
            return false;
        string text = negative
            ? _currentPreviewMetadata.NegativePrompt.Trim()
            : FormatPromptTagsForDisplay(_currentPreviewMetadata.Prompt);
        if (text.Length == 0)
            return false;
        _lastMetadataCopyText = text;
        if (!useSystemClipboard)
            return true;
        Button button = negative ? CopyPreviewNegativeButton : CopyPreviewPromptButton;
        try
        {
            Clipboard.SetText(text);
            button.Content = "Copied";
            return true;
        }
        catch (Exception ex) when (ex is ExternalException or InvalidOperationException)
        {
            button.ToolTip = $"Copy failed: {ex.Message}";
            return false;
        }
    }

    private void CopyPreviewMetadata_Click(object sender, RoutedEventArgs e)
        => CopyCurrentPreviewMetadata(useSystemClipboard: true);

    private bool CopyCurrentPreviewMetadata(bool useSystemClipboard)
    {
        Tile? selected = SelectedTile();
        if (selected is null
            || _currentPreviewMetadata is null
            || !string.Equals(selected.Path, _currentPreviewMetadataPath, StringComparison.OrdinalIgnoreCase))
            return false;

        string text = BuildPngMetadataCopyText(_currentPreviewMetadata);
        if (string.IsNullOrWhiteSpace(text))
            return false;

        _lastMetadataCopyText = text;
        if (!useSystemClipboard)
            return true;

        try
        {
            Clipboard.SetText(text);
            CopyPreviewMetadataButton.Content = "Copied";
            CopyPreviewMetadataButton.ToolTip = "PNG metadata copied";
            return true;
        }
        catch (Exception ex) when (ex is ExternalException or InvalidOperationException)
        {
            CopyPreviewMetadataButton.Content = "Copy";
            CopyPreviewMetadataButton.ToolTip = $"Copy failed: {ex.Message}";
            return false;
        }
    }

    private static string BuildPngMetadataCopyText(PngParametersMetadata metadata)
    {
        var lines = new List<string>();
        AddPngMetadataCopyLine(lines, "Prompt", metadata.Prompt);
        AddPngMetadataCopyLine(lines, "Negative prompt", metadata.NegativePrompt);
        foreach ((string key, string value) in metadata.Settings)
            AddPngMetadataCopyLine(lines, key, value);
        AddPngMetadataCopyLine(lines, "Raw parameters", metadata.Raw);
        return string.Join(Environment.NewLine, lines);
    }

    private static void AddPngMetadataCopyLine(ICollection<string> lines, string label, string? value)
    {
        if (!string.IsNullOrWhiteSpace(value))
            lines.Add($"{label}: {value.Trim()}");
    }

    private static void SetPreviewMetadataRow(TextBlock label, TextBlock value, string title, string? text)
    {
        bool visible = !string.IsNullOrWhiteSpace(text);
        label.Text = title;
        label.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
        value.Text = visible ? text : "";
        value.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
    }

    private static PngParametersMetadata? ReadPngParametersMetadata(string path, CancellationToken token)
    {
        if (!string.Equals(Path.GetExtension(path), ".png", StringComparison.OrdinalIgnoreCase))
            return null;

        try
        {
            using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 4096, FileOptions.SequentialScan);
            var signature = new byte[8];
            if (!TryReadExactly(stream, signature) || !signature.SequenceEqual(PngSignature))
                return null;

            var chunkHeader = new byte[8];
            while (stream.Position + 12 <= stream.Length)
            {
                token.ThrowIfCancellationRequested();
                if (!TryReadExactly(stream, chunkHeader))
                    return null;

                int length = (chunkHeader[0] << 24) | (chunkHeader[1] << 16) | (chunkHeader[2] << 8) | chunkHeader[3];
                if (length < 0 || length > MaxPngMetadataChunkBytes || stream.Position + length + 4 > stream.Length)
                    return null;

                string type = Encoding.ASCII.GetString(chunkHeader, 4, 4);
                if (string.Equals(type, "IDAT", StringComparison.Ordinal))
                    return null;

                if (string.Equals(type, "tEXt", StringComparison.Ordinal))
                {
                    var data = new byte[length];
                    if (!TryReadExactly(stream, data) || !TrySkip(stream, 4))
                        return null;

                    int separator = Array.IndexOf(data, (byte)0);
                    if (separator <= 0 || !string.Equals(Encoding.Latin1.GetString(data, 0, separator), "parameters", StringComparison.Ordinal))
                        continue;

                    string raw = Encoding.UTF8.GetString(data, separator + 1, data.Length - separator - 1);
                    return ParsePngParameters(raw);
                }

                if (!TrySkip(stream, length + 4))
                    return null;
            }
        }
        catch (IOException)
        {
        }
        catch (UnauthorizedAccessException)
        {
        }

        return null;
    }

    private static PngParametersMetadata? ParsePngParameters(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return null;

        const string negativeMarker = "Negative prompt:";
        const string settingsMarker = "\nSteps:";
        int negativeStart = raw.IndexOf(negativeMarker, StringComparison.Ordinal);
        int settingsStart = raw.IndexOf(settingsMarker, StringComparison.Ordinal);
        string prompt = negativeStart >= 0 ? raw[..negativeStart].Trim() : (settingsStart >= 0 ? raw[..settingsStart].Trim() : raw.Trim());
        int negativeValueStart = negativeStart >= 0 ? negativeStart + negativeMarker.Length : -1;
        string negative = negativeValueStart >= 0
            ? raw[negativeValueStart..(settingsStart >= negativeValueStart ? settingsStart : raw.Length)].Trim()
            : "";
        string settings = settingsStart >= 0 ? raw[(settingsStart + 1)..].Trim() : "";
        return new PngParametersMetadata(prompt, negative, ParsePngSettings(settings), raw.Trim());
    }

    private static Dictionary<string, string> ParsePngSettings(string settings)
    {
        var parsed = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (string item in SplitPngSettings(settings))
        {
            int separator = item.IndexOf(':');
            if (separator <= 0)
                continue;
            string key = item[..separator].Trim();
            string value = item[(separator + 1)..].Trim().Trim('"');
            if (!string.IsNullOrWhiteSpace(key) && !string.IsNullOrWhiteSpace(value))
                parsed[key] = value;
        }
        return parsed;
    }

    private static IEnumerable<string> SplitPngSettings(string settings)
    {
        if (string.IsNullOrWhiteSpace(settings))
            yield break;

        var current = new StringBuilder();
        bool quoted = false;
        bool escaped = false;
        foreach (char character in settings)
        {
            if (escaped)
            {
                current.Append(character);
                escaped = false;
                continue;
            }
            if (character == '\\')
            {
                current.Append(character);
                escaped = true;
                continue;
            }
            if (character == '"')
                quoted = !quoted;
            if (character == ',' && !quoted)
            {
                yield return current.ToString();
                current.Clear();
                continue;
            }
            current.Append(character);
        }
        if (current.Length > 0)
            yield return current.ToString();
    }

    private static bool TryReadExactly(Stream stream, byte[] buffer)
    {
        int offset = 0;
        while (offset < buffer.Length)
        {
            int read = stream.Read(buffer, offset, buffer.Length - offset);
            if (read == 0)
                return false;
            offset += read;
        }
        return true;
    }

    private static bool TrySkip(Stream stream, int count)
    {
        if (count < 0 || stream.Position + count > stream.Length)
            return false;
        stream.Seek(count, SeekOrigin.Current);
        return true;
    }

    private async void SearchInput_GotKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
    {
        if (_suppressSearchHistoryFocusOpen)
            return;
        await OpenSearchHistoryPopupAsync();
    }

    private void SearchInput_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        // A focused input does not raise GotKeyboardFocus again. Queue the
        // reopen after Popup's outside-click processing so click always works
        // after Escape and every open rereads the shared Browser/WPF file.
        Dispatcher.BeginInvoke(() =>
        {
            if (!_suppressSearchHistoryFocusOpen)
                _ = OpenSearchHistoryPopupAsync();
        }, DispatcherPriority.Input);
    }

    private async void SearchInput_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (e.Key == Key.Escape && SearchHistoryPopup.IsOpen)
        {
            SearchHistoryPopup.IsOpen = false;
            e.Handled = true;
            return;
        }

        if (e.Key is Key.Down or Key.Up)
        {
            await OpenSearchHistoryPopupAsync();
            int index = e.Key == Key.Down ? 0 : _searchHistoryEntries.Count - 1;
            _ = FocusSearchHistoryIndex(index);
            e.Handled = true;
            return;
        }

        if (e.Key == Key.Enter)
        {
            if (SearchHistoryPopup.IsOpen && SearchHistoryList.SelectedItem is SearchHistoryItemView selected)
                await UseSearchHistoryQueryAsync(selected.Query);
            else
                await CommitCurrentSearchHistoryAsync();
            SearchHistoryPopup.IsOpen = false;
            e.Handled = true;
        }
    }

    private void SearchInput_LostKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
    {
        Dispatcher.BeginInvoke(() =>
        {
            if (SearchInput.IsKeyboardFocusWithin)
                return;
            if (SearchHistoryPopup.Child is UIElement popupChild && popupChild.IsKeyboardFocusWithin)
                return;
            _ = CommitCurrentSearchHistoryAsync();
        }, DispatcherPriority.Input);
    }

    private async Task OpenSearchHistoryPopupAsync()
    {
        long generation = Interlocked.Increment(ref _searchHistoryUiGeneration);
        _searchHistoryReadCts?.Cancel();
        _searchHistoryReadCts?.Dispose();
        var cts = new CancellationTokenSource();
        _searchHistoryReadCts = cts;
        SearchHistoryPopup.IsOpen = true;
        SearchHistoryAnnouncementText.Text = "Loading recent searches.";

        try
        {
            SearchHistoryReadResult result = await Task.Run(
                () => SearchHistoryStore.Read(SearchHistoryStore.ResolvePath()),
                cts.Token);
            if (cts.IsCancellationRequested || generation != Interlocked.Read(ref _searchHistoryUiGeneration))
                return;
            ApplySearchHistorySurface(result.Entries, result.Supported, result.Error);
        }
        catch (OperationCanceledException)
        {
            // A newer open or mutation owns the surface generation.
        }
        catch (Exception ex)
        {
            if (generation == Interlocked.Read(ref _searchHistoryUiGeneration))
                ApplySearchHistorySurface([], supported: false, error: ex.Message);
        }
    }

    private void ApplySearchHistorySurface(
        IReadOnlyList<string> entries,
        bool supported = true,
        string? error = null)
    {
        _searchHistoryEntries.Clear();
        foreach (string query in entries)
            _searchHistoryEntries.Add(new SearchHistoryItemView(query));

        SearchHistoryList.SelectedIndex = -1;
        SearchHistoryEmptyText.Visibility = entries.Count == 0 ? Visibility.Visible : Visibility.Collapsed;
        ClearSearchHistoryButton.IsEnabled = supported && entries.Count > 0;
        SearchHistoryStatusText.Text = supported
            ? ""
            : "Search history is protected because its shared file is invalid or newer.";
        SearchHistoryStatusText.ToolTip = supported ? null : error;
        SearchHistoryStatusText.Visibility = supported ? Visibility.Collapsed : Visibility.Visible;
        SearchHistoryAnnouncementText.Text = supported
            ? $"{entries.Count} recent search{(entries.Count == 1 ? "" : "es")}."
            : "Shared search history is unavailable.";
    }

    private async Task<bool> CommitCurrentSearchHistoryAsync()
    {
        string query = SearchHistoryStore.NormalizeQuery(SearchInput.Text);
        if (query.Length == 0)
            return false;
        string rawQuery = SearchInput.Text;
        return await RunSearchHistoryMutationAsync(() => SearchHistoryStore.Commit(
            SearchHistoryStore.ResolvePath(),
            rawQuery));
    }

    private async Task<bool> RunSearchHistoryMutationAsync(Func<SearchHistoryWriteResult> mutation)
    {
        long generation = Interlocked.Increment(ref _searchHistoryUiGeneration);
        _searchHistoryReadCts?.Cancel();
        SearchHistoryAnnouncementText.Text = "Updating shared search history.";
        SearchHistoryWriteResult result;
        try
        {
            result = await Task.Run(mutation);
        }
        catch (Exception ex)
        {
            result = new SearchHistoryWriteResult(SearchHistoryWriteStatus.Failed, [], false, ex.Message);
        }
        bool succeeded = result.Status == SearchHistoryWriteStatus.Succeeded;
        if (generation == Interlocked.Read(ref _searchHistoryUiGeneration))
            _ = ApplySearchHistoryWrite(result);
        return succeeded;
    }

    private bool ApplySearchHistoryWrite(SearchHistoryWriteResult result)
    {
        if (result.Status == SearchHistoryWriteStatus.Succeeded)
        {
            ApplySearchHistorySurface(result.Entries);
            return true;
        }

        string message = result.Status == SearchHistoryWriteStatus.Protected
            ? "Search history was not changed because its shared file is invalid or newer."
            : result.Status == SearchHistoryWriteStatus.Busy
                ? "Search history is busy in another Aibos window."
                : "Search history could not be saved.";
        SetStatusToast(message);
        SearchHistoryStatusText.Text = message;
        SearchHistoryStatusText.ToolTip = result.Error;
        SearchHistoryStatusText.Visibility = Visibility.Visible;
        return false;
    }

    private async void SearchHistorySelect_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not Button { Tag: string query })
            return;
        await UseSearchHistoryQueryAsync(query);
        e.Handled = true;
    }

    private async void SearchHistoryDelete_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not Button { Tag: string query })
            return;
        await RunSearchHistoryMutationAsync(() => SearchHistoryStore.Delete(SearchHistoryStore.ResolvePath(), query));
        e.Handled = true;
    }

    private async void ClearSearchHistory_Click(object sender, RoutedEventArgs e)
    {
        await RunSearchHistoryMutationAsync(() => SearchHistoryStore.Clear(SearchHistoryStore.ResolvePath()));
        e.Handled = true;
    }

    private async Task<bool> UseSearchHistoryQueryAsync(string query)
    {
        SearchFilterCompletion projection = await SetSearchQueryInteractiveAsync(query);
        if (!projection.Applied || projection.Discarded)
            return false;
        bool committed = await CommitCurrentSearchHistoryAsync();
        CloseSearchHistoryAndFocusInput();
        return committed;
    }

    private void CloseSearchHistoryAndFocusInput()
    {
        SearchHistoryPopup.IsOpen = false;
        _suppressSearchHistoryFocusOpen = true;
        SearchInput.Focus();
        SearchInput.CaretIndex = SearchInput.Text.Length;
        Dispatcher.BeginInvoke(
            () => _suppressSearchHistoryFocusOpen = false,
            DispatcherPriority.ContextIdle);
    }

    private bool FocusSearchHistoryIndex(int index)
    {
        if (index < 0 || index >= _searchHistoryEntries.Count)
            return false;
        SearchHistoryList.SelectedIndex = index;
        SearchHistoryList.UpdateLayout();
        bool focused = SearchHistoryList.ItemContainerGenerator.ContainerFromIndex(index) is ListBoxItem item
            && item.Focus();
        SearchHistoryAnnouncementText.Text = $"Search history item {index + 1} of {_searchHistoryEntries.Count} selected.";
        return focused;
    }

    private async void SearchHistoryList_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (e.Key == Key.Escape)
        {
            CloseSearchHistoryAndFocusInput();
            e.Handled = true;
            return;
        }
        if (e.Key == Key.Enter && SearchHistoryList.SelectedItem is SearchHistoryItemView selected)
        {
            await UseSearchHistoryQueryAsync(selected.Query);
            e.Handled = true;
        }
    }

    private void SearchHistoryList_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        int index = SearchHistoryList.SelectedIndex;
        if (index >= 0)
            SearchHistoryAnnouncementText.Text = $"Search history item {index + 1} of {_searchHistoryEntries.Count} selected.";
    }

    private void SearchInput_TextChanged(object sender, TextChangedEventArgs e)
    {
        if (SearchWatermark is not null)
            SearchWatermark.Visibility = string.IsNullOrEmpty(SearchInput.Text) ? Visibility.Visible : Visibility.Collapsed;
        if (ClearSearchInputButton is not null)
            ClearSearchInputButton.Visibility = string.IsNullOrEmpty(SearchInput.Text) ? Visibility.Collapsed : Visibility.Visible;
        if (_initializing || _settingSearchQuery) return;
        ScheduleSearchFilter();
        ScheduleSearchStateSave();
    }

    private void ClearSearchInput_Click(object sender, RoutedEventArgs e)
    {
        SearchInput.Clear();
        SearchInput.Focus();
        CloseSearchHistoryAndFocusInput();
    }

    private void ScheduleSearchFilter()
    {
        _ = QueueCatalogProjection(
            debounce: true,
            reorderCatalog: false,
            selectFirst: true);
    }

    private void SearchFilterTimer_Tick(object? sender, EventArgs e)
    {
        _searchFilterTimer.Stop();
        if (_scheduledCatalogProjection is { } request)
            _ = ApplyCatalogProjectionAsync(request);
    }

    private Task<SearchFilterCompletion> QueueCatalogProjection(
        bool debounce,
        bool reorderCatalog,
        bool selectFirst,
        int? selectionFallbackIndex = null,
        GridZoomAnchor? viewportAnchor = null,
        bool restrictToCurrentProjection = false)
    {
        CancelPendingCatalogProjection(completePending: true);
        // A new query/filter owns the next gallery projection. Stop the old
        // view's progressive card realization before debounce and background
        // compute so stale container work cannot compete with current input.
        _galleryVirtualizingPanel?.CancelPendingRealization();
        long generation = ++_catalogProjectionGeneration;
        var completion = new TaskCompletionSource<SearchFilterCompletion>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        var request = new CatalogProjectionRequest(
            generation,
            reorderCatalog,
            restrictToCurrentProjection,
            selectFirst,
            selectionFallbackIndex,
            viewportAnchor ?? PreferredGridGeometryAnchor(),
            completion);
        _scheduledCatalogProjection = request;
        _pendingSearchFilterCompletion = completion;
        if (debounce)
        {
            _searchFilterTimer.Stop();
            _searchFilterTimer.Start();
        }
        else
        {
            _ = ApplyCatalogProjectionAsync(request);
        }
        return completion.Task;
    }

    private async Task ApplyCatalogProjectionAsync(CatalogProjectionRequest request)
    {
        var cts = new CancellationTokenSource();
        _catalogProjectionCts = cts;
        bool collectAllocationDiagnostics =
            !string.IsNullOrEmpty(_catalogInteractionDiagnosticOperation);
        int gen0Before = GC.CollectionCount(0);
        int gen1Before = GC.CollectionCount(1);
        int gen2Before = GC.CollectionCount(2);
        TimeSpan gcPauseBefore = GC.GetTotalPauseDuration();
        long captureAllocatedBefore = collectAllocationDiagnostics
            ? GC.GetAllocatedBytesForCurrentThread()
            : 0;
        var captureWatch = new Stopwatch();
        long captureAllocatedBytes = 0;
        long computeMs = 0;
        long computeAllocatedBytes = 0;
        long applyMs = 0;
        long applyAllocatedBytes = 0;
        long maxApplySliceMs = 0;
        CatalogProjectionApplyMetrics applyMetrics = default;
        long cleanupMs;
        long cleanupAllocatedBytes = 0;
        FilterResult? result = null;
        FilterSnapshot? snapshotForCleanup = null;
        SearchFilterCompletion outcome;
        try
        {
            captureWatch.Start();
            FilterSnapshot snapshot = CaptureFilterSnapshot(request);
            snapshotForCleanup = snapshot;
            captureWatch.Stop();
            captureAllocatedBytes = collectAllocationDiagnostics
                ? GC.GetAllocatedBytesForCurrentThread() - captureAllocatedBefore
                : 0;
            result = await Task.Run(() =>
            {
                var computeWatch = Stopwatch.StartNew();
                long computeAllocatedBefore = collectAllocationDiagnostics
                    ? GC.GetAllocatedBytesForCurrentThread()
                    : 0;
                Thread currentThread = Thread.CurrentThread;
                ThreadPriority previousPriority = currentThread.Priority;
                try
                {
                    if (previousPriority > ThreadPriority.Lowest)
                        currentThread.Priority = ThreadPriority.Lowest;
                    return ComputeFilterResult(snapshot, cts.Token);
                }
                finally
                {
                    if (currentThread.Priority != previousPriority)
                        currentThread.Priority = previousPriority;
                    computeWatch.Stop();
                    computeMs = computeWatch.ElapsedMilliseconds;
                    computeAllocatedBytes = collectAllocationDiagnostics
                        ? GC.GetAllocatedBytesForCurrentThread() - computeAllocatedBefore
                        : 0;
                }
            }, cts.Token);
            if (cts.IsCancellationRequested
                || request.Generation != _catalogProjectionGeneration
                || snapshot.CatalogRevision != _catalogContentRevision
                || snapshot.SelectionGeneration != _selectionVisualSyncGeneration
                || !string.Equals(snapshot.SortBy, _sortBy, StringComparison.Ordinal)
                || !string.Equals(snapshot.RandomSortSeed, _randomSortSeed, StringComparison.Ordinal))
            {
                _catalogProjectionDiscardedCount++;
                outcome = SearchFilterCompletion.DiscardedResult;
            }
            else
            {
                long applyAllocatedBefore = collectAllocationDiagnostics
                    ? GC.GetAllocatedBytesForCurrentThread()
                    : 0;
                var applyWatch = Stopwatch.StartNew();
                applyMetrics = await ApplyFilterResultAsync(result, snapshot, request.Generation);
                maxApplySliceMs = applyMetrics.MaxSliceMs;
                applyWatch.Stop();
                applyMs = applyWatch.ElapsedMilliseconds;
                applyAllocatedBytes = collectAllocationDiagnostics
                    ? GC.GetAllocatedBytesForCurrentThread() - applyAllocatedBefore
                    : 0;
                _lastCatalogProjectionApplySliceMilliseconds = maxApplySliceMs;
                _maxCatalogProjectionApplySliceMilliseconds = Math.Max(
                    _maxCatalogProjectionApplySliceMilliseconds,
                    maxApplySliceMs);
                if (request.Generation == _catalogProjectionGeneration)
                {
                    _lastAppliedCatalogProjectionGeneration = request.Generation;
                    outcome = SearchFilterCompletion.AppliedResult;
                }
                else
                {
                    _catalogProjectionDiscardedCount++;
                    outcome = SearchFilterCompletion.DiscardedResult;
                }
            }
        }
        catch (OperationCanceledException)
        {
            _catalogProjectionDiscardedCount++;
            outcome = SearchFilterCompletion.DiscardedResult;
        }
        catch (Exception ex)
        {
            outcome = new SearchFilterCompletion(false, false, ex.Message);
            SetStatusToast("Search could not be updated. Retry the query.");
        }
        finally
        {
            if (captureWatch.IsRunning)
                captureWatch.Stop();
            result?.AutomationProjection.ReleaseCreator();
            long cleanupAllocatedBefore = collectAllocationDiagnostics
                ? GC.GetAllocatedBytesForCurrentThread()
                : 0;
            var cleanupWatch = Stopwatch.StartNew();
            if (result is not null)
                ReturnFilterResult(result);
            if (snapshotForCleanup is not null)
                ReturnFilterSnapshot(snapshotForCleanup);
            if (ReferenceEquals(_catalogProjectionCts, cts))
                _catalogProjectionCts = null;
            cts.Dispose();
            cleanupWatch.Stop();
            cleanupMs = cleanupWatch.ElapsedMilliseconds;
            cleanupAllocatedBytes = collectAllocationDiagnostics
                ? GC.GetAllocatedBytesForCurrentThread() - cleanupAllocatedBefore
                : 0;
        }

        request.Completion?.TrySetResult(outcome with
        {
            CaptureMs = captureWatch.ElapsedMilliseconds,
            CaptureAllocatedBytes = captureAllocatedBytes,
            ComputeMs = computeMs,
            ComputeAllocatedBytes = computeAllocatedBytes,
            ApplyMs = applyMs,
            ApplyAllocatedBytes = applyAllocatedBytes,
            CleanupMs = cleanupMs,
            CleanupAllocatedBytes = cleanupAllocatedBytes,
            Gen2Collections = GC.CollectionCount(2) - gen2Before,
            Gen0Collections = GC.CollectionCount(0) - gen0Before,
            Gen1Collections = GC.CollectionCount(1) - gen1Before,
            GcPauseMs = (GC.GetTotalPauseDuration() - gcPauseBefore).TotalMilliseconds,
            MaxApplySliceMs = maxApplySliceMs,
            Generation = request.Generation,
            PublishMs = applyMetrics.PublishMs,
            StatsMs = applyMetrics.StatsMs,
            SelectionMs = applyMetrics.SelectionMs,
            ReconcileMs = applyMetrics.ReconcileMs,
            CatalogSwapMs = applyMetrics.CatalogSwapMs,
            PanelCommitMs = applyMetrics.PanelCommitMs,
            PreResetMs = applyMetrics.PreResetMs,
            PreResetSelectionReleaseMs =
                applyMetrics.PreResetSelectionReleaseMs,
            PreResetSelectionCleared =
                applyMetrics.PreResetSelectionCleared,
            PreResetSelectionReleasedCount =
                applyMetrics.PreResetSelectionReleasedCount,
            ResetMs = applyMetrics.ResetMs,
            SelectionCommitMs = applyMetrics.SelectionCommitMs,
            ResetGeneratorRemoveMs = applyMetrics.ResetGeneratorRemoveMs,
            ResetForgetDeferredMeasureMs = applyMetrics.ResetForgetDeferredMeasureMs,
            ResetRemoveInternalChildRangeMs = applyMetrics.ResetRemoveInternalChildRangeMs,
            ResetRemoveInternalChildRangeThreadCpuMs =
                applyMetrics.ResetRemoveInternalChildRangeThreadCpuMs,
            ResetPanelTotalMs = applyMetrics.ResetPanelTotalMs,
            ResetPanelThreadCpuMs = applyMetrics.ResetPanelThreadCpuMs,
            ResetPanelBudgetMs = applyMetrics.ResetPanelBudgetMs,
            ResetPanelBudgetUsedWallFallback =
                applyMetrics.ResetPanelBudgetUsedWallFallback,
            MaxResetDetachedContainersPerSlice =
                applyMetrics.MaxResetDetachedContainersPerSlice,
            InputBoundaryBeforePublication =
                applyMetrics.InputBoundaryBeforePublication,
            InputBoundaryAfterPublication =
                applyMetrics.InputBoundaryAfterPublication,
            ResetAllocatedBytes = applyMetrics.ResetAllocatedBytes,
            CatalogSnapshotResetThreadCpuMs =
                applyMetrics.CatalogSnapshotResetThreadCpuMs,
            CatalogSnapshotResetCount =
                applyMetrics.CatalogSnapshotResetCount,
            CatalogSnapshotResetNestedCount =
                applyMetrics.CatalogSnapshotResetNestedCount,
            PublishedSingleRemoval =
                applyMetrics.PublishedSingleRemoval,
            PreparedLayoutReady = result?.PreparedLayout is not null,
        });
        if (!outcome.Applied
            && request.Generation == _catalogProjectionGeneration
            && ReferenceEquals(_scheduledCatalogProjection, request))
        {
            // The request canceled stale progressive realization when it was
            // queued. If it ends without a successor or publication, resume
            // the still-current view instead of leaving an unmeasured card.
            _galleryVirtualizingPanel?.ResumePendingRealization();
        }
        if (ReferenceEquals(_pendingSearchFilterCompletion, request.Completion))
            _pendingSearchFilterCompletion = null;
        if (ReferenceEquals(_scheduledCatalogProjection, request))
            _scheduledCatalogProjection = null;
    }

    private void CancelPendingCatalogProjection(bool completePending)
    {
        _searchFilterTimer.Stop();
        _catalogProjectionCts?.Cancel();
        _catalogProjectionCts = null;
        if (completePending)
            _pendingSearchFilterCompletion?.TrySetResult(SearchFilterCompletion.DiscardedResult);
        _pendingSearchFilterCompletion = null;
        _scheduledCatalogProjection = null;
    }

