            if (AppSettingsUnseenDotsCheckBox is not null)
                AppSettingsUnseenDotsCheckBox.IsChecked = enabled;
        }
        finally
        {
            _syncingUnseenDotsControls = false;
        }
        RefreshUnseenDots();
        if (persist && !_initializing)
            SaveState();
    }

