    private void CloseAllPreviewTabs_Click(object sender, RoutedEventArgs e) => CloseAllPreviewTabs();

    private Tile? ReconcilePreviewTabsWithCurrentCatalog()
    {
        IReadOnlyList<string> requestedPaths = _previewTabsPersistenceReady
            ? _previewTabs.Select(static tab => tab.Path).ToList()
            : _restoredPreviewTabPaths;
        string? requestedActivePath = _previewTabsPersistenceReady
            ? _activePreviewTabPath
            : _restoredActivePreviewTabPath;

        bool hasPinsInCurrentRoots = _pinnedPreviewPaths.Any(path =>
            _currentFolderSet.Any(root => IsPathWithinRoot(path, root)));
        if (requestedPaths.Count == 0 && _closedPreviewTabs.Count == 0 && !hasPinsInCurrentRoots)
        {
            // The common first-open path has no tab identity to reconcile.
            // Avoid building a normalized 100k path dictionary just to prove
            // that three already-empty collections are empty.
            _previewTabs.Clear();
            _activePreviewTabPath = null;
            _restoredPreviewTabPaths.Clear();
            _restoredActivePreviewTabPath = null;
            _previewTabsPersistenceReady = true;
            RefreshPreviewTabs();
            return null;
        }

        // Preview tabs are a catalog session, not a projection of the current
        // search/filter result. A tab hidden by an exact Favorite or search
        // filter must survive reload and become visible again when filters clear.
        var currentByPath = _allTiles
            .Where(static tile => tile.IsRealFile)
            .ToDictionary(tile => NormalizeFavoritePath(tile.Path), StringComparer.OrdinalIgnoreCase);

        // Pin identity belongs to a source path. Keep pins from other folder
        // sets, but remove paths that disappeared from the roots just scanned.
        _pinnedPreviewPaths.RemoveWhere(path =>
            _currentFolderSet.Any(root => IsPathWithinRoot(path, root))
            && !currentByPath.ContainsKey(path));

        // Closed tabs hold Tile instances from the previous catalog. Rebind
        // surviving paths to the freshly materialized Tile objects so Refresh
        // does not erase valid close history merely because object identity
        // changed. Missing/renamed sources are intentionally discarded.
        var reboundClosedTabs = new List<Tile>();
        var reboundClosedPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (Tile closed in _closedPreviewTabs)
        {
            string path = NormalizeFavoritePath(closed.Path);
            if (currentByPath.TryGetValue(path, out Tile? current)
                && reboundClosedPaths.Add(path))
            {
                reboundClosedTabs.Add(current);
            }
        }
        var restoredTiles = new List<Tile>();
        foreach (string path in NormalizePreviewTabPaths(requestedPaths))
        {
            if (currentByPath.TryGetValue(path, out Tile? tile))
                restoredTiles.Add(tile);
        }

        _previewTabs.Clear();
        foreach (Tile tile in restoredTiles)
        {
            bool isPinned = NormalizePinnedPreviewPath(tile.Path) is string normalizedPath
                && _pinnedPreviewPaths.Contains(normalizedPath);
            _previewTabs.Add(new PreviewTabView(tile.Path, tile.FileName, isPinned));
        }

        string? normalizedActivePath = NormalizePinnedPreviewPath(requestedActivePath);
        Tile? active = normalizedActivePath is null
            ? null
            : restoredTiles.FirstOrDefault(tile => string.Equals(tile.Path, normalizedActivePath, StringComparison.OrdinalIgnoreCase));
        active ??= restoredTiles.FirstOrDefault();
        _activePreviewTabPath = active?.Path;
        _restoredPreviewTabPaths.Clear();
        _restoredActivePreviewTabPath = null;
        _previewTabsPersistenceReady = true;
        _closedPreviewTabs.Clear();
        _closedPreviewTabs.AddRange(reboundClosedTabs.Take(30));
        RefreshPreviewTabs();
        return active;
    }

    private void ReconcileOpenSurfacesAfterCatalogReload(
        bool modalWasVisible,
        bool modalHadFocus,
        string? focusedPreviewTabPath)
    {
        if (modalWasVisible)
        {
            if (SelectedTile() is not null)
            {
                OpenModal();
                if (modalHadFocus)
                    Dispatcher.BeginInvoke(ModalCloseBtn.Focus, DispatcherPriority.Input);
            }
            else
            {
                CloseModal();
                if (modalHadFocus)
                    Dispatcher.BeginInvoke(OpenFolderSetButton.Focus, DispatcherPriority.Input);
            }
            return;
        }

        if (string.IsNullOrWhiteSpace(focusedPreviewTabPath))
            return;

        string? nextFocusPath = _previewTabs
            .FirstOrDefault(tab => string.Equals(tab.Path, focusedPreviewTabPath, StringComparison.OrdinalIgnoreCase))?.Path
            ?? _activePreviewTabPath;
        if (!string.IsNullOrWhiteSpace(nextFocusPath))
        {
            FocusPreviewTab(nextFocusPath);
        }
        else if (_closedPreviewTabs.Count > 0)
        {
            FocusRestorePreviewTabButton();
        }
        else
        {
            Dispatcher.BeginInvoke(CardsList.Focus, DispatcherPriority.Input);
        }
    }

    private bool OpenPreviewTab(Tile tile, bool makeActive)
    {
        if (!tile.IsRealFile)
            return false;

        if (_previewTabs.All(tab => !string.Equals(tab.Path, tile.Path, StringComparison.OrdinalIgnoreCase)))
        {
            bool isPinned = NormalizePinnedPreviewPath(tile.Path) is string normalizedPath
                && _pinnedPreviewPaths.Contains(normalizedPath);
            _previewTabs.Add(new PreviewTabView(tile.Path, tile.FileName, isPinned));
        }

        _closedPreviewTabs.RemoveAll(closed => string.Equals(closed.Path, tile.Path, StringComparison.OrdinalIgnoreCase));

        if (makeActive)
            return ActivatePreviewTab(tile.Path);

        RefreshPreviewTabs();
        return true;
    }

    private bool TogglePreviewTabPin(string path)
    {
        var tab = _previewTabs.FirstOrDefault(candidate => string.Equals(candidate.Path, path, StringComparison.OrdinalIgnoreCase));
        if (tab is null)
            return false;

        string? normalizedPath = NormalizePinnedPreviewPath(tab.Path);
        if (normalizedPath is null)
            return false;
        bool isPinned = !_pinnedPreviewPaths.Remove(normalizedPath);
        if (isPinned)
            _pinnedPreviewPaths.Add(normalizedPath);
        tab.IsPinned = isPinned;
        RefreshPreviewTabs();
        SaveState();
        return true;
    }

    private bool ActivatePreviewTab(string path)
    {
        var tile = _tiles.FirstOrDefault(candidate => string.Equals(candidate.Path, path, StringComparison.OrdinalIgnoreCase));
        if (tile is null)
            return false;

        HidePreviewTabHover(path);
        _activePreviewTabPath = tile.Path;
        SelectTile(tile);
        RefreshPreviewTabs();
        SaveState();
        return true;
    }

    private bool ClosePreviewTab(string path)
    {
        var tab = _previewTabs.FirstOrDefault(candidate => string.Equals(candidate.Path, path, StringComparison.OrdinalIgnoreCase));
        if (tab is null)
            return false;

        HidePreviewTabHover(path);
        _previewTabs.Remove(tab);
        if (_allTiles.FirstOrDefault(candidate => string.Equals(candidate.Path, path, StringComparison.OrdinalIgnoreCase)) is { } closed)
        {
            _closedPreviewTabs.RemoveAll(candidate => string.Equals(candidate.Path, closed.Path, StringComparison.OrdinalIgnoreCase));
            _closedPreviewTabs.Insert(0, closed);
            if (_closedPreviewTabs.Count > 30)
                _closedPreviewTabs.RemoveRange(30, _closedPreviewTabs.Count - 30);
        }

        if (string.Equals(_activePreviewTabPath, path, StringComparison.OrdinalIgnoreCase))
        {
            _activePreviewTabPath = null;
            if (_previewTabs.LastOrDefault() is { } next)
                ActivatePreviewTab(next.Path);
            else
            {
                RefreshPreviewTabs();
                FocusRestorePreviewTabButton();
            }
        }
        else
        {
            RefreshPreviewTabs();
        }

        SaveState();
        return true;
    }

    private bool RestoreLastClosedPreviewTab()
    {
        while (_closedPreviewTabs.Count > 0)
        {
            var tile = _closedPreviewTabs[0];
            _closedPreviewTabs.RemoveAt(0);
            if (_tiles.Contains(tile))
            {
                bool restored = OpenPreviewTab(tile, makeActive: true);
                if (restored)
                    FocusPreviewTab(tile.Path);
                return restored;
            }
        }

        RefreshPreviewTabs();
        return false;
    }

    private void CloseAllPreviewTabs()
    {
        foreach (var tab in _previewTabs.ToList())
        {
            if (_allTiles.FirstOrDefault(candidate => string.Equals(candidate.Path, tab.Path, StringComparison.OrdinalIgnoreCase)) is { } tile)
            {
                _closedPreviewTabs.RemoveAll(candidate => string.Equals(candidate.Path, tile.Path, StringComparison.OrdinalIgnoreCase));
                _closedPreviewTabs.Insert(0, tile);
            }
        }

        if (_closedPreviewTabs.Count > 30)
            _closedPreviewTabs.RemoveRange(30, _closedPreviewTabs.Count - 30);

        HidePreviewTabHover();
        _previewTabs.Clear();
        _activePreviewTabPath = null;
        RefreshPreviewTabs();
        SaveState();
    }

    private static bool TryGetDraggedPreviewTab(IDataObject data, out PreviewTabView? tab)
    {
        tab = data.GetDataPresent(typeof(PreviewTabView)) ? data.GetData(typeof(PreviewTabView)) as PreviewTabView : null;
        return tab is not null;
    }

    private void SetPreviewTabDragOver(PreviewTabView? target)
    {
        foreach (PreviewTabView tab in _previewTabs)
            tab.IsDragOver = ReferenceEquals(tab, target);
    }

    private bool MovePreviewTab(PreviewTabView? tab, int destinationIndex, bool reportFailure)
    {
        int sourceIndex = tab is null ? -1 : _previewTabs.IndexOf(tab);
        if (sourceIndex < 0 || destinationIndex < 0 || destinationIndex >= _previewTabs.Count)
        {
            if (reportFailure)
                ReportPreviewTabReorderFailure(tab);
            return false;
        }

        if (sourceIndex == destinationIndex)
            return false;

        _previewTabs.Move(sourceIndex, destinationIndex);
        RefreshPreviewTabs();
        SaveState();
        FocusPreviewTab(tab!.Path);
        return true;
    }

    private void ReportPreviewTabReorderFailure(PreviewTabView? tab)
    {
        SetStatusToast("Preview tab reorder was not applied. The existing tab order was preserved.");
        if (tab is not null)
            FocusPreviewTab(tab.Path);
    }

    private bool TryReorderFocusedPreviewTab(int delta)
    {
        if (delta == 0 || !TryGetFocusedPreviewTab(out PreviewTabView? tab) || tab is null)
            return false;

        int sourceIndex = _previewTabs.IndexOf(tab);
        return sourceIndex >= 0 && MovePreviewTab(tab, sourceIndex + delta, reportFailure: false);
    }

    private static bool TryGetFocusedPreviewTab(out PreviewTabView? tab)
    {
        DependencyObject? current = Keyboard.FocusedElement as DependencyObject;
        while (current is not null)
        {
            if (current is FrameworkElement { Tag: PreviewTabView previewTab })
            {
                tab = previewTab;
                return true;
            }

            current = current is Visual or System.Windows.Media.Media3D.Visual3D
                ? VisualTreeHelper.GetParent(current)
                : LogicalTreeHelper.GetParent(current);
        }

        tab = null;
        return false;
    }

    private void FocusPreviewTab(string path)
        => Dispatcher.BeginInvoke(() =>
        {
            PreviewTabView? tab = _previewTabs.FirstOrDefault(candidate => string.Equals(candidate.Path, path, StringComparison.OrdinalIgnoreCase));
            if (tab is null)
                return;

            FindPreviewTabButton(tab)?.Focus();
        }, DispatcherPriority.Input);

    private Button? FindPreviewTabButton(PreviewTabView tab)
    {
        UpdateLayout();
        return FindVisualDescendants<Button>(PreviewTabList)
            .FirstOrDefault(candidate => candidate.Tag == tab && candidate.Content is StackPanel);
    }

    private void FocusRestorePreviewTabButton()
        => Dispatcher.BeginInvoke(() =>
        {
            if (RestorePreviewTabButton.IsVisible && RestorePreviewTabButton.IsEnabled)
                RestorePreviewTabButton.Focus();
        }, DispatcherPriority.Input);

    private void RefreshPreviewTabs()
    {
        foreach (var tab in _previewTabs)
        {
            tab.IsActive = string.Equals(tab.Path, _activePreviewTabPath, StringComparison.OrdinalIgnoreCase);
            tab.IsPinned = NormalizePinnedPreviewPath(tab.Path) is string normalizedPath
                && _pinnedPreviewPaths.Contains(normalizedPath);
        }

        if (PreviewTabsEmptyText is not null)
            PreviewTabsEmptyText.Visibility = _previewTabs.Count == 0 ? Visibility.Visible : Visibility.Collapsed;
        if (CloseAllPreviewTabsButton is not null)
            CloseAllPreviewTabsButton.IsEnabled = _previewTabs.Count > 0;
        if (RestorePreviewTabButton is not null)
            RestorePreviewTabButton.IsEnabled = _closedPreviewTabs.Count > 0;
    }

    private bool ShowPreviewTabHover(PreviewTabView tab, FrameworkElement? placementTarget, bool forceDecode = false)
    {
        var tile = _allTiles.FirstOrDefault(candidate => string.Equals(candidate.Path, tab.Path, StringComparison.OrdinalIgnoreCase));
        if (tile is null || PreviewTabHoverPopup is null)
            return false;

        if (PreviewTabHoverPopup.IsOpen
            && string.Equals(_hoverPreviewTabPath, tile.Path, StringComparison.OrdinalIgnoreCase))
        {
            if (placementTarget is not null)
                PreviewTabHoverPopup.PlacementTarget = placementTarget;
            return true;
        }

        CancelPreviewTabHoverDecode();
        _hoverPreviewTabPath = tile.Path;
        PreviewTabHoverName.Text = tile.FileName;
        PreviewTabHoverPath.Text = tile.Path;
        _hoverPreviewTabBitmapPath = null;
        PreviewTabHoverBitmap.Source = null;
        if (placementTarget is not null)
            PreviewTabHoverPopup.PlacementTarget = placementTarget;
        PreviewTabHoverPopup.IsOpen = true;

        if (!forceDecode && tile.Thumbnail is not null)
        {
            PreviewTabHoverBitmap.Source = tile.Thumbnail;
            _hoverPreviewTabBitmapPath = tile.Path;
            var immediate = new TaskCompletionSource<PreviewTabHoverDecodeCompletion>(TaskCreationOptions.RunContinuationsAsynchronously);
            immediate.TrySetResult(PreviewTabHoverDecodeCompletion.AppliedResult);
            _previewTabHoverCompletion = immediate;
            _lastPreviewTabHoverCompletion = immediate;
            return true;
        }

        var cts = new CancellationTokenSource();
        _previewTabHoverCts = cts;
        long generation = ++_previewTabHoverGeneration;
        var completion = new TaskCompletionSource<PreviewTabHoverDecodeCompletion>(TaskCreationOptions.RunContinuationsAsynchronously);
        _previewTabHoverCompletion = completion;
        _lastPreviewTabHoverCompletion = completion;
        _previewTabHoverDecodeStartCount++;
        _ = DecodePreviewTabHoverAsync(tile.Path, generation, cts, completion);
        return true;
    }

    private async Task DecodePreviewTabHoverAsync(
        string path,
        long generation,
        CancellationTokenSource cts,
        TaskCompletionSource<PreviewTabHoverDecodeCompletion> completion)
    {
        try
        {
            if (_previewTabHoverDecodeDelaysForSmoke.TryGetValue(path, out int delayMilliseconds) && delayMilliseconds > 0)
                await Task.Delay(delayMilliseconds, cts.Token);

            BitmapSource? bitmap = await Task.Run(() => LoadBitmap(path, 360), cts.Token);
            if (cts.IsCancellationRequested || generation != _previewTabHoverGeneration
                || !string.Equals(_hoverPreviewTabPath, path, StringComparison.OrdinalIgnoreCase)
                || PreviewTabHoverPopup?.IsOpen != true)
            {
                completion.TrySetResult(PreviewTabHoverDecodeCompletion.DiscardedResult);
                return;
            }

            if (bitmap is null)
            {
                _previewTabHoverDecodeFailureCount++;
                PreviewTabHoverBitmap.Source = null;
                _hoverPreviewTabBitmapPath = null;
                SetStatusToast("Preview tab image could not be decoded. You can continue browsing.");
                completion.TrySetResult(PreviewTabHoverDecodeCompletion.FailedResult);
                return;
            }

            PreviewTabHoverBitmap.Source = bitmap;
            _hoverPreviewTabBitmapPath = path;
            completion.TrySetResult(PreviewTabHoverDecodeCompletion.AppliedResult);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetResult(PreviewTabHoverDecodeCompletion.DiscardedResult);
        }
        catch
        {
            if (generation == _previewTabHoverGeneration
                && string.Equals(_hoverPreviewTabPath, path, StringComparison.OrdinalIgnoreCase)
                && PreviewTabHoverPopup?.IsOpen == true)
            {
                _previewTabHoverDecodeFailureCount++;
                PreviewTabHoverBitmap.Source = null;
                _hoverPreviewTabBitmapPath = null;
                SetStatusToast("Preview tab image could not be decoded. You can continue browsing.");
                completion.TrySetResult(PreviewTabHoverDecodeCompletion.FailedResult);
            }
            else
            {
                completion.TrySetResult(PreviewTabHoverDecodeCompletion.DiscardedResult);
            }
        }
        finally
        {
            if (ReferenceEquals(_previewTabHoverCts, cts))
                _previewTabHoverCts = null;
            if (ReferenceEquals(_previewTabHoverCompletion, completion))
                _previewTabHoverCompletion = null;
            cts.Dispose();
        }
    }

    private void CancelPreviewTabHoverDecode()
    {
        _previewTabHoverGeneration++;
        _previewTabHoverCts?.Cancel();
        _previewTabHoverCts = null;
        _previewTabHoverCompletion?.TrySetResult(PreviewTabHoverDecodeCompletion.DiscardedResult);
        _previewTabHoverCompletion = null;
    }

    private bool HidePreviewTabHover(string? path = null)
    {
        if (!string.IsNullOrWhiteSpace(path)
            && !string.Equals(_hoverPreviewTabPath, path, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        bool wasVisible = PreviewTabHoverPopup?.IsOpen == true || _hoverPreviewTabPath is not null;
        CancelPreviewTabHoverDecode();
        _hoverPreviewTabPath = null;
        _hoverPreviewTabBitmapPath = null;
        if (PreviewTabHoverPopup is not null)
            PreviewTabHoverPopup.IsOpen = false;
        if (PreviewTabHoverBitmap is not null)
            PreviewTabHoverBitmap.Source = null;
        if (PreviewTabHoverName is not null)
            PreviewTabHoverName.Text = "";
        if (PreviewTabHoverPath is not null)
            PreviewTabHoverPath.Text = "";
        return wasVisible;
    }

    public void SetSearchQuery(string query, bool persist = true)
    {
        bool previous = _suppressStateSave;
        _suppressStateSave = !persist;
        try
        {
            _settingSearchQuery = true;
            SearchInput.Text = query;
            ApplyFilters();
        }
        finally
        {
            _settingSearchQuery = false;
            _suppressStateSave = previous;
        }

        if (persist)
        {
            _searchStateSaveTimer.Stop();
            SaveState();
        }
    }

    private async Task<SearchFilterCompletion> SetSearchQueryInteractiveAsync(
        string query,
        bool persist = true)
    {
        bool previous = _suppressStateSave;
        _suppressStateSave = !persist;
        try
        {
            _settingSearchQuery = true;
            SearchInput.Text = query;
        }
        finally
        {
            _settingSearchQuery = false;
            _suppressStateSave = previous;
        }

        SearchFilterCompletion completion = await QueueCatalogProjection(
            debounce: false,
            reorderCatalog: false,
            selectFirst: true);
        if (persist)
        {
            _searchStateSaveTimer.Stop();
            SaveState();
        }
        return completion;
    }

    public Task<SearchFilterCompletion> SetSearchInputForSmokeAsync(string query)
    {
        SearchInput.Text = query;
        return _pendingSearchFilterCompletion?.Task
            ?? Task.FromResult(new SearchFilterCompletion(false, false, "search input did not schedule a filter"));
    }

    public long LastAppliedSearchFilterGenerationForSmoke => _lastAppliedCatalogProjectionGeneration;
    public long CatalogProjectionGenerationForSmoke => _catalogProjectionGeneration;
    public long LastCatalogProjectionApplySliceMsForSmoke => _lastCatalogProjectionApplySliceMilliseconds;
    public long MaxCatalogProjectionApplySliceMsForSmoke => _maxCatalogProjectionApplySliceMilliseconds;
    public int CatalogProjectionDiscardedCountForSmoke => _catalogProjectionDiscardedCount;
    public int PreparedCatalogLayoutAppliedCountForSmoke
        => _retiredPreparedCatalogLayoutAppliedCount
            + (_galleryVirtualizingPanel?.PreparedLayoutAppliedCount ?? 0);
    public int PreparedCatalogLayoutRejectedCountForSmoke
        => _retiredPreparedCatalogLayoutRejectedCount
            + (_galleryVirtualizingPanel?.PreparedLayoutRejectedCount ?? 0);
    public long CatalogLayoutMaxMeasureMsForSmoke
        => Math.Max(
            _retiredCatalogLayoutMaxMeasureMilliseconds,
            _galleryVirtualizingPanel?.MaxMeasureMilliseconds ?? 0);
    private VirtualizingMeasureDiagnostic CatalogLayoutMaxMeasureDiagnosticForSmoke
        => _galleryVirtualizingPanel is { } panel
            && panel.MaxMeasureDiagnostic.WallMs > _retiredCatalogLayoutMaxMeasureDiagnostic.WallMs
                ? panel.MaxMeasureDiagnostic
                : _retiredCatalogLayoutMaxMeasureDiagnostic;
    public string CatalogLayoutMaxMeasureOperationForSmoke
        => CatalogLayoutMaxMeasureDiagnosticForSmoke.Operation;
    public long CatalogLayoutMaxMeasureGenerationForSmoke
        => CatalogLayoutMaxMeasureDiagnosticForSmoke.LayoutGeneration;
    public double CatalogLayoutMaxMeasureWallMsForSmoke
        => CatalogLayoutMaxMeasureDiagnosticForSmoke.WallMs;
    public double CatalogLayoutMaxMeasureThreadCpuMsForSmoke
        => CatalogLayoutMaxMeasureDiagnosticForSmoke.ThreadCpuMs;
    internal bool CatalogPanelPhaseDiagnosticOverflowForSmoke
        => _catalogPanelPhaseDiagnosticOverflow
            || _galleryVirtualizingPanel?.PhaseDiagnosticOverflow == true;
    internal IReadOnlyList<VirtualizingPanelPhaseDiagnostic>
        CaptureCatalogPanelPhaseDiagnosticsForSmoke()
    {
        IReadOnlyList<VirtualizingPanelPhaseDiagnostic> current =
            _galleryVirtualizingPanel?.CapturePhaseDiagnostics() ?? [];
        if (_retiredCatalogPanelPhaseDiagnostics.Count == 0)
            return current;
        var combined = new List<VirtualizingPanelPhaseDiagnostic>(
            _retiredCatalogPanelPhaseDiagnostics.Count + current.Count);
        combined.AddRange(_retiredCatalogPanelPhaseDiagnostics);
        combined.AddRange(current);
        return combined;
    }

    public void SetCatalogInteractionDiagnosticOperationForSmoke(string operation)
    {
        _catalogInteractionDiagnosticOperation = operation ?? "";
        _galleryVirtualizingPanel?.SetDiagnosticOperation(_catalogInteractionDiagnosticOperation);
    }

    public void SuppressStatePersistence()
    {
        _suppressStateSave = true;
    }

    private void ApplyFilters(bool selectFirst = true, int? selectionFallbackIndex = null)
    {
        if (CardsList is null || RowsList is null) return;

        ++_catalogProjectionGeneration;
        CancelPendingCatalogProjection(completePending: true);
        AttachGalleryVirtualizationPanel();
        if (_galleryVirtualizingPanel is { } panel)
            panel.ShowGroupHeaders = UsesDateGrouping;
        FilterSnapshot snapshot = CaptureFilterSnapshot(
            request: null,
            selectFirst,
            selectionFallbackIndex);
        FilterResult? result = null;
        try
        {
            result = ComputeFilterResult(snapshot, CancellationToken.None);
            ApplyFilterResult(result, selectFirst, selectionFallbackIndex);
        }
        finally
        {
            if (result is not null)
                ReturnFilterResult(result);
            ReturnFilterSnapshot(snapshot);
        }
    }

    private FilterSnapshot CaptureFilterSnapshot(
        CatalogProjectionRequest? request = null,
        bool selectFirst = true,
        int? selectionFallbackIndex = null)
    {
        AttachGalleryVirtualizationPanel();
        string query = SearchInput?.Text?.Trim() ?? "";
        IReadOnlyList<Tile> catalogSource = request?.RestrictToCurrentProjection == true
            ? _tiles
            : _allTiles;
        int tileCount = catalogSource.Count;
        FilterTileSnapshot[] tiles = ArrayPool<FilterTileSnapshot>.Shared.Rent(tileCount);
        try
        {
            for (int index = 0; index < tileCount; index++)
            {
                Tile tile = catalogSource[index];
                tiles[index] = new FilterTileSnapshot(
                    tile,
                    tile.Path,
                    tile.FileName,
                    tile.IsRealFile,
                    tile.FolderBucketKey,
                    tile.Group,
                    Math.Max(1, tile.CardHeight + 4),
                    tile.Prompt,
                    tile.Fav,
                    tile.Enhanced,
                    tile.Unseen,
                    tile.ModifiedUtc,
                    tile.CreatedUtc);
            }

            Tile? previous = SelectedTile();
            VirtualizingLayoutContext? layoutContext =
                _galleryVirtualizingPanel?.CaptureLayoutContext();
            if (layoutContext is { } capturedLayoutContext)
            {
                layoutContext = capturedLayoutContext with
                {
                    ShowGroupHeaders = UsesDateGrouping,
                };
            }
            bool albumActive = _activeAlbumId is not null;
            string[] queryTokens = query.Split(
                ',',
                StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            bool favoritesOnly = FavoriteOnlyFilter?.IsChecked == true;
            bool unfavoriteOnly = UnfavoriteOnlyFilter?.IsChecked == true;
            bool enhancedOnly = EnhancedOnlyFilter?.IsChecked == true;
            bool unseenOnly = UnseenOnlyFilter?.IsChecked == true;
            FrozenSet<int> favoriteLevels = _favoriteFilterLevels.ToFrozenSet();
            FrozenSet<string> hiddenFolderBuckets =
                _hiddenFolderBuckets.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
            bool unfiltered = !albumActive
                && queryTokens.Length == 0
                && !favoritesOnly
                && !unfavoriteOnly
                && !enhancedOnly
                && !unseenOnly
                && hiddenFolderBuckets.Count == 0
                && !_dateFromLocal.HasValue
                && !_dateToLocal.HasValue;
            Tile[]? unfilteredProjection = null;
            if (unfiltered && request?.ReorderCatalog != true)
            {
                if (_unfilteredProjection is null
                    || _unfilteredProjectionRevision != _catalogContentRevision)
                {
                    _unfilteredProjection = _allTiles.ToArray();
                    _unfilteredProjectionRevision = _catalogContentRevision;
                }
                unfilteredProjection = _unfilteredProjection;
            }

            return new FilterSnapshot(
                tiles,
                tileCount,
                _catalogContentRevision,
                _selectionVisualSyncGeneration,
                _selectedPaths.ToArray(),
                _primarySelectedPath,
                previous?.Path,
                _activePreviewTabPath,
                Keyboard.FocusedElement is DependencyObject focused
                    && (IsDescendantOrSelf(focused, CardsList)
                        || IsDescendantOrSelf(focused, RowsList)),
                request?.SelectFirst ?? selectFirst,
                request?.SelectionFallbackIndex ?? selectionFallbackIndex,
                request?.ViewportAnchor,
                layoutContext,
                _catalogLayoutCache,
                unfilteredProjection,
                request?.ReorderCatalog == true,
                request?.RestrictToCurrentProjection == true,
                _sortBy,
                _randomSortSeed,
                albumActive,
                _activeAlbumMemberPaths.ToFrozenSet(StringComparer.OrdinalIgnoreCase),
                _activeAlbumMemberOrder.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase),
                queryTokens,
                favoritesOnly,
                unfavoriteOnly,
                enhancedOnly,
                unseenOnly,
                favoriteLevels,
                hiddenFolderBuckets,
                _dateFromLocal,
                _dateToLocal);
        }
        catch
        {
            ArrayPool<FilterTileSnapshot>.Shared.Return(tiles, clearArray: true);
            throw;
        }
    }

    private static void ReturnFilterSnapshot(FilterSnapshot snapshot)
        => ArrayPool<FilterTileSnapshot>.Shared.Return(snapshot.Tiles, clearArray: true);

    private static Tile[] CopyTileProjection(FilterSnapshot snapshot)
    {
        var projection = new Tile[snapshot.TileCount];
        for (int index = 0; index < projection.Length; index++)
            projection[index] = snapshot.Tiles[index].Tile;
        return projection;
    }

    private static void ReturnFilterResult(FilterResult result)
    {
        // Filter results are immutable, exactly-sized arrays. The visible
        // collection adopts them in O(1), and old snapshots remain valid for
        // any WPF enumerator that was already in flight.
    }

    private static void CheckCatalogWorkerInputHandoff(
        int index,
        int itemCount,
        CancellationToken cancellationToken)
    {
        if ((index & 63) != 0)
            return;

        cancellationToken.ThrowIfCancellationRequested();
        if (index > 0
            && itemCount > 16_384
            && cancellationToken.CanBeCanceled
            && (index & 1023) == 0)
        {
            Thread.Yield();
        }
    }

    private static FilterResult ComputeFilterResult(FilterSnapshot snapshot, CancellationToken cancellationToken)
    {
        bool unfiltered = !snapshot.AlbumActive
            && snapshot.QueryTokens.Length == 0
            && !snapshot.FavoritesOnly
            && !snapshot.UnfavoriteOnly
            && !snapshot.EnhancedOnly
            && !snapshot.UnseenOnly
            && snapshot.HiddenFolderBuckets.Count == 0
            && !snapshot.DateFromLocal.HasValue
            && !snapshot.DateToLocal.HasValue;
        if (snapshot.ReorderCatalog && snapshot.TileCount > 1)
        {
            int comparisons = 0;
            Array.Sort(
                snapshot.Tiles,
                0,
                snapshot.TileCount,
                Comparer<FilterTileSnapshot>.Create((left, right) =>
                {
                    if ((++comparisons & 1023) == 0)
                        cancellationToken.ThrowIfCancellationRequested();
                    return CompareFilterTilesForSort(
                        left,
                        right,
                        snapshot.SortBy,
                        snapshot.RandomSortSeed);
                }));
        }

        Tile[]? orderedCatalogProjection = null;
        List<Tile>? orderedCatalog = null;
        if (snapshot.ReorderCatalog)
        {
            orderedCatalogProjection = new Tile[snapshot.TileCount];
            for (int index = 0; index < snapshot.TileCount; index++)
                orderedCatalogProjection[index] = snapshot.Tiles[index].Tile;
            orderedCatalog = new List<Tile>(orderedCatalogProjection);
        }

        int filteredCount = 0;
        bool hasLayoutItem = false;
        bool uniformLayoutHeight = true;
        bool singleLayoutGroup = true;
        double firstLayoutHeight = 0;
        string firstLayoutGroup = "";
        List<int>? matchedIndices = unfiltered
            ? null
            : new List<int>(Math.Min(snapshot.TileCount, 4_096));
        for (int index = 0; index < snapshot.TileCount; index++)
        {
            CheckCatalogWorkerInputHandoff(index, snapshot.TileCount, cancellationToken);

            FilterTileSnapshot tile = snapshot.Tiles[index];
            if (!unfiltered && !MatchesFilterSnapshot(tile, snapshot))
                continue;
            matchedIndices?.Add(index);
            if (!hasLayoutItem)
            {
                hasLayoutItem = true;
                firstLayoutHeight = tile.CardHeight;
                firstLayoutGroup = tile.Group;
            }
            else
            {
                uniformLayoutHeight &= Math.Abs(tile.CardHeight - firstLayoutHeight) <= 0.01;
                singleLayoutGroup &= string.Equals(
                    tile.Group,
                    firstLayoutGroup,
                    StringComparison.Ordinal);
            }
            filteredCount++;
        }

        cancellationToken.ThrowIfCancellationRequested();
        VirtualizingLayoutContext? layoutContext = snapshot.LayoutContext;
        bool fixedContextHeight = layoutContext is { ItemHeight: > 0 } contextWithHeight
            && double.IsFinite(contextWithHeight.ItemHeight);
        bool compactLayout = layoutContext is { } context
            && (fixedContextHeight || uniformLayoutHeight)
            && (!context.ShowGroupHeaders || singleLayoutGroup);
        Tile[] filtered = unfiltered
            ? orderedCatalogProjection
                ?? snapshot.UnfilteredProjection
                ?? CopyTileProjection(snapshot)
            : new Tile[filteredCount];
        VirtualizingLayoutItem[]? filteredLayoutItems = layoutContext is not null && !compactLayout
            ? new VirtualizingLayoutItem[filteredCount]
            : null;
        if (!unfiltered)
        {
            for (int filteredIndex = 0; filteredIndex < filteredCount; filteredIndex++)
            {
                CheckCatalogWorkerInputHandoff(filteredIndex, filteredCount, cancellationToken);
                FilterTileSnapshot tile = snapshot.Tiles[matchedIndices![filteredIndex]];
                filtered[filteredIndex] = tile.Tile;
                if (filteredLayoutItems is not null)
                    filteredLayoutItems[filteredIndex] = new VirtualizingLayoutItem(tile.Group, tile.CardHeight);
            }
        }
        else if (filteredLayoutItems is not null)
        {
            for (int index = 0; index < snapshot.TileCount; index++)
            {
                CheckCatalogWorkerInputHandoff(index, snapshot.TileCount, cancellationToken);
                FilterTileSnapshot tile = snapshot.Tiles[index];
                filteredLayoutItems[index] = new VirtualizingLayoutItem(tile.Group, tile.CardHeight);
            }
        }

        cancellationToken.ThrowIfCancellationRequested();
        if (snapshot.AlbumActive)
        {
            Dictionary<Tile, VirtualizingLayoutItem>? layoutByTile = null;
            if (filteredLayoutItems is not null)
            {
                layoutByTile = new Dictionary<Tile, VirtualizingLayoutItem>(
                    filteredCount,
                    ReferenceEqualityComparer.Instance);
                for (int index = 0; index < filteredCount; index++)
                    layoutByTile[filtered[index]] = filteredLayoutItems[index];
            }
            Array.Sort(
                filtered,
                0,
                filteredCount,
                Comparer<Tile>.Create((left, right) =>
                {
                    int leftIndex = snapshot.AlbumMemberOrder.TryGetValue(left.Path, out int leftOrder)
                        ? leftOrder
                        : int.MaxValue;
                    int rightIndex = snapshot.AlbumMemberOrder.TryGetValue(right.Path, out int rightOrder)
                        ? rightOrder
                        : int.MaxValue;
                    return leftIndex.CompareTo(rightIndex);
                }));
            if (filteredLayoutItems is not null && layoutByTile is not null)
            {
                for (int index = 0; index < filteredCount; index++)
                    filteredLayoutItems[index] = layoutByTile[filtered[index]];
            }
        }

        HashSet<string>? selected = snapshot.SelectedPaths.Length == 0
            ? null
            : snapshot.SelectedPaths.ToHashSet(StringComparer.OrdinalIgnoreCase);
        List<Tile> survivingSelected = selected is null
            ? []
            : new List<Tile>(Math.Min(selected.Count, filteredCount));
        Tile? primary = null;
        Tile? previous = null;
        Tile? lastSelected = null;
        int farthestSelectedIndex = -1;
        bool activePreviewIncluded = false;
        for (int index = 0; index < filteredCount; index++)
        {
            CheckCatalogWorkerInputHandoff(index, filteredCount, cancellationToken);
            Tile tile = filtered[index];
            if (!string.IsNullOrWhiteSpace(snapshot.PrimarySelectedPath)
                && string.Equals(tile.Path, snapshot.PrimarySelectedPath, StringComparison.OrdinalIgnoreCase))
            {
                primary = tile;
            }
            if (!string.IsNullOrWhiteSpace(snapshot.PreviousSelectedPath)
                && string.Equals(tile.Path, snapshot.PreviousSelectedPath, StringComparison.OrdinalIgnoreCase))
            {
                previous = tile;
            }
            if (selected?.Contains(tile.Path) == true)
            {
                survivingSelected.Add(tile);
                lastSelected = tile;
                farthestSelectedIndex = index;
            }
            if (!activePreviewIncluded
                && !string.IsNullOrWhiteSpace(snapshot.ActivePreviewTabPath)
                && string.Equals(
                    tile.Path,
                    snapshot.ActivePreviewTabPath,
                    StringComparison.OrdinalIgnoreCase))
            {
                activePreviewIncluded = true;
            }
        }

        int selectedRelocationScanLength = selected is null
            ? 0
            : survivingSelected.Count < selected.Count
                ? filteredCount
                : farthestSelectedIndex + 1;
        Tile? preferred = primary ?? previous ?? lastSelected;
        if (preferred is null && snapshot.SelectionFallbackIndex.HasValue && filteredCount > 0)
            preferred = filtered[Math.Clamp(snapshot.SelectionFallbackIndex.Value, 0, filteredCount - 1)];
        preferred ??= snapshot.SelectFirst && filteredCount > 0 ? filtered[0] : null;
        if (preferred is not null && survivingSelected.Count == 0)
            survivingSelected.Add(preferred);
        int preferredIndex = preferred is null
            ? -1
            : Array.IndexOf(filtered, preferred, 0, filteredCount);

        PreparedVirtualizingLayout? preparedLayout = null;
        if (layoutContext is { } resolvedLayoutContext)
        {
            if (compactLayout)
            {
                double uniformItemHeight = fixedContextHeight
                    ? resolvedLayoutContext.ItemHeight
                    : hasLayoutItem
                        ? firstLayoutHeight
                        : 1;
                preparedLayout = snapshot.LayoutCache.GetOrCreateUniform(
                    filteredCount,
                    resolvedLayoutContext,
                    firstLayoutGroup,
                    uniformItemHeight,
                    cancellationToken);
            }
            else
            {
                preparedLayout = VirtualizingWrapPanel.PrepareLayout(
                    filteredLayoutItems!,
                    resolvedLayoutContext,
                    cancellationToken);
            }
        }
        int? exactSingleRemovalIndex = null;
        if (snapshot.RestrictToCurrentProjection
            && !snapshot.ReorderCatalog
            && filteredCount == snapshot.TileCount - 1)
        {
            int removedIndex = 0;
            while (removedIndex < filteredCount
                && ReferenceEquals(snapshot.Tiles[removedIndex].Tile, filtered[removedIndex]))
            {
                removedIndex++;
            }

            bool exactRemoval = true;
            for (int index = removedIndex; index < filteredCount; index++)
            {
                if (ReferenceEquals(snapshot.Tiles[index + 1].Tile, filtered[index]))
                    continue;
                exactRemoval = false;
                break;
            }
            if (exactRemoval)
                exactSingleRemovalIndex = removedIndex;
        }

        GalleryAutomationProjectionIndex automationProjection =
            GalleryAutomationProjectionIndex.Create(
                filtered,
                filteredCount,
                cancellationToken);

        return new FilterResult(
            filtered,
            filteredCount,
            orderedCatalog,
            survivingSelected.ToArray(),
            preferred,
            preferredIndex,
            selectedRelocationScanLength,
            activePreviewIncluded,
            snapshot.ViewportAnchor,
            preparedLayout,
            automationProjection,
            exactSingleRemovalIndex);
    }

    private void StageGalleryAutomationProjection(
        GalleryAutomationProjectionIndex projection)
    {
        try
        {
            CardsList.StageAutomationProjection(projection);
            RowsList.StageAutomationProjection(projection);
        }
        finally
        {
            projection.ReleaseCreator();
        }
    }

    private static int CompareFilterTilesForSort(
        FilterTileSnapshot left,
        FilterTileSnapshot right,
        string sortBy,
        string randomSortSeed)
    {
        int primary = sortBy switch
        {
            SortModifiedOldestValue => left.ModifiedUtc.CompareTo(right.ModifiedUtc),
            SortCreatedNewestValue => right.CreatedUtc.CompareTo(left.CreatedUtc),
            SortCreatedOldestValue => left.CreatedUtc.CompareTo(right.CreatedUtc),
            SortRandomValue => StableRandomSortKey(randomSortSeed, left.Path)
                .CompareTo(StableRandomSortKey(randomSortSeed, right.Path)),
            SortNameValue => StringComparer.OrdinalIgnoreCase.Compare(left.FileName, right.FileName),
            _ => right.ModifiedUtc.CompareTo(left.ModifiedUtc),
        };
        if (primary != 0)
            return primary;

        if (sortBy == SortNameValue)
        {
            int modified = right.ModifiedUtc.CompareTo(left.ModifiedUtc);
            if (modified != 0)
                return modified;
        }
        else if (sortBy != SortRandomValue)
        {
            int fileName = StringComparer.OrdinalIgnoreCase.Compare(left.FileName, right.FileName);
            if (fileName != 0)
                return fileName;
        }

        return StringComparer.OrdinalIgnoreCase.Compare(left.Path, right.Path);
    }

    private static bool MatchesFilterSnapshot(FilterTileSnapshot tile, FilterSnapshot snapshot)
    {
        if (snapshot.AlbumActive && (!tile.IsRealFile || !snapshot.AlbumMemberPaths.Contains(tile.Path)))
            return false;
        foreach (string token in snapshot.QueryTokens)
        {
            if (!ContainsText(tile.FileName, token) && !ContainsText(tile.Prompt, token))
                return false;
        }

        if (snapshot.FavoritesOnly && (tile.FavoriteLevel <= 0 || (snapshot.FavoriteLevels.Count > 0 && !snapshot.FavoriteLevels.Contains(tile.FavoriteLevel))))
            return false;
        if (snapshot.UnfavoriteOnly && tile.FavoriteLevel > 0)
            return false;
        if (snapshot.EnhancedOnly && !tile.Enhanced)
            return false;
        if (snapshot.UnseenOnly && !tile.Unseen)
            return false;
        if (tile.IsRealFile
            && !string.IsNullOrWhiteSpace(tile.FolderBucketKey)
            && snapshot.HiddenFolderBuckets.Contains(tile.FolderBucketKey))
            return false;
        if (!tile.IsRealFile || (!snapshot.DateFromLocal.HasValue && !snapshot.DateToLocal.HasValue))
            return true;

        DateTime createdDate = tile.CreatedUtc.ToLocalTime().Date;
        return (!snapshot.DateFromLocal.HasValue || createdDate >= snapshot.DateFromLocal.Value.Date)
            && (!snapshot.DateToLocal.HasValue || createdDate <= snapshot.DateToLocal.Value.Date);
    }

    private async Task<CatalogProjectionApplyMetrics> ApplyFilterResultAsync(
        FilterResult filterResult,
        FilterSnapshot snapshot,
        long generation)
    {
        await _catalogProjectionApplyGate.WaitAsync();
        try
        {
            return await ApplyFilterResultCoreAsync(filterResult, snapshot, generation);
        }
        finally
        {
            _catalogProjectionApplyGate.Release();
        }
    }

    private async Task<CatalogProjectionApplyMetrics> ApplyFilterResultCoreAsync(
        FilterResult filterResult,
        FilterSnapshot snapshot,
        long generation)
    {
        long maxSliceMs = 0;
        long publishMs = 0;
        long statsMs = 0;
        long selectionMs = 0;
        long reconcileMs = 0;
        long catalogSwapMs = 0;
        long panelCommitMs = 0;
        long preResetMs = 0;
        long preResetSelectionReleaseMs = 0;
        bool preResetSelectionCleared = true;
        int preResetSelectionReleasedCount = 0;
        long resetMs = 0;
        long selectionCommitMs = 0;
        double resetGeneratorRemoveMs = 0;
        double resetForgetDeferredMeasureMs = 0;
        double resetRemoveInternalChildRangeMs = 0;
        double resetRemoveInternalChildRangeThreadCpuMs = 0;
        double resetPanelTotalMs = 0;
        double resetPanelThreadCpuMs = -1;
        double resetPanelBudgetMs = 0;
        bool resetPanelBudgetUsedWallFallback = false;
        int maxResetDetachedContainersPerSlice = 0;
        bool inputBoundaryBeforePublication = false;
        bool inputBoundaryAfterPublication = false;
        long resetAllocatedBytes = 0;
        double catalogSnapshotResetThreadCpuMs = -1;
        int catalogSnapshotResetCount = 0;
        int catalogSnapshotResetNestedCount = 0;
        var slice = Stopwatch.StartNew();

        long FinishSlice()
        {
            slice.Stop();
            long elapsedMs = slice.ElapsedMilliseconds;
            maxSliceMs = Math.Max(maxSliceMs, elapsedMs);
            return elapsedMs;
        }

        async Task<bool> YieldForInputAsync(bool checkGeneration = true)
        {
            FinishSlice();
            await Dispatcher.Yield(DispatcherPriority.Background);
            if (checkGeneration && generation != _catalogProjectionGeneration)
                return false;
            slice.Restart();
            return true;
        }

        bool IsCurrentWithoutYield()
        {
            if (generation == _catalogProjectionGeneration)
                return true;
            FinishSlice();
            return false;
        }

        if (_galleryVirtualizingPanel is null)
            AttachGalleryVirtualizationPanel();
        VirtualizingWrapPanel? preparedPanel = _galleryVirtualizingPanel;
        CancelThumbnailViewportLoading();
        _thumbnailViewportRevision++;
        if (!await YieldForInputAsync())
            return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        inputBoundaryBeforePublication = true;

        var phase = new Stopwatch();
        int exactSingleRemovalIndex = filterResult.ExactSingleRemovalIndex ?? -1;
        bool publishSingleRemoval =
            exactSingleRemovalIndex >= 0
            && _tiles.CanReplaceOneRemoved(
                filterResult.Tiles,
                filterResult.Count,
                exactSingleRemovalIndex);
        if (!publishSingleRemoval
            && snapshot.RestoreGalleryFocus
            && Keyboard.FocusedElement is DependencyObject focusedElement)
        {
            ListBox? focusedGallery = IsDescendantOrSelf(focusedElement, CardsList)
                ? CardsList
                : IsDescendantOrSelf(focusedElement, RowsList)
                    ? RowsList
                    : null;
            if (focusedGallery is not null
                && !ReferenceEquals(focusedElement, focusedGallery)
                && focusedGallery.Focus()
                && !await YieldForInputAsync())
            {
                return new CatalogProjectionApplyMetrics(
                    maxSliceMs,
                    publishMs,
                    statsMs,
                    selectionMs,
                    reconcileMs);
            }
        }
        if (ShouldReleaseWpfSelectionBeforeCatalogPublication(filterResult))
        {
            (
                preResetSelectionReleaseMs,
                preResetSelectionCleared,
                preResetSelectionReleasedCount) =
                ReleaseWpfSelectionBeforeCatalogPublication();
            // A large relocation is rare, but keep its deselection and the
            // generator detachment as two independently bounded UI slices.
            _ = await YieldForInputAsync(checkGeneration: false);
        }
        bool resetPreparationStarted = !publishSingleRemoval
            && preparedPanel?.BeginItemsResetPreparation() == true;
        try
        {
            if (resetPreparationStarted)
            {
                bool resetPreparationComplete;
                do
                {
                    phase.Restart();
                    ItemsResetPreparationSlice resetSlice =
                        preparedPanel!.PrepareNextItemsResetSlice();
                    phase.Stop();
                    resetPreparationComplete = resetSlice.Complete;
                    maxResetDetachedContainersPerSlice = Math.Max(
                        maxResetDetachedContainersPerSlice,
                        resetSlice.DetachedContainerCount);
                    if (phase.ElapsedMilliseconds > preResetMs)
                    {
                        preResetMs = phase.ElapsedMilliseconds;
                        resetGeneratorRemoveMs = resetSlice.GeneratorRemoveMs;
                        resetForgetDeferredMeasureMs = resetSlice.ForgetDeferredMeasureMs;
                        resetRemoveInternalChildRangeMs = resetSlice.RemoveInternalChildRangeMs;
                        resetRemoveInternalChildRangeThreadCpuMs =
                            resetSlice.RemoveInternalChildRangeThreadCpuMs;
                        resetPanelTotalMs = resetSlice.PanelTotalMs;
                    }
                    if (resetSlice.PanelThreadCpuMs >= 0)
                    {
                        resetPanelThreadCpuMs = resetPanelThreadCpuMs < 0
                            ? resetSlice.PanelThreadCpuMs
                            : Math.Max(resetPanelThreadCpuMs, resetSlice.PanelThreadCpuMs);
                    }
                    bool sliceBudgetUsedWallFallback = resetSlice.PanelThreadCpuMs < 0;
                    double sliceBudgetMs = sliceBudgetUsedWallFallback
                        ? resetSlice.PanelTotalMs
                        : Math.Min(resetSlice.PanelThreadCpuMs, resetSlice.PanelTotalMs);
                    if (sliceBudgetMs > resetPanelBudgetMs)
                    {
                        resetPanelBudgetMs = sliceBudgetMs;
                        resetPanelBudgetUsedWallFallback = sliceBudgetUsedWallFallback;
                    }
                    // Preserve the original reset semantics: stale-generation
                    // rejection happens only after reset preparation finishes.
                    // Yield after the final detach as well, so its visual-tree
                    // cleanup cannot concatenate with catalog publication.
                    _ = await YieldForInputAsync(checkGeneration: false);
                    if (resetPreparationComplete)
                        break;
                }
                while (true);
            }

            if (generation != _catalogProjectionGeneration
                || snapshot.CatalogRevision != _catalogContentRevision
                || snapshot.SelectionGeneration != _selectionVisualSyncGeneration
                || !string.Equals(snapshot.SortBy, _sortBy, StringComparison.Ordinal)
                || !string.Equals(snapshot.RandomSortSeed, _randomSortSeed, StringComparison.Ordinal))
            {
                FinishSlice();
                return new CatalogProjectionApplyMetrics(
                    maxSliceMs,
                    publishMs,
                    statsMs,
                    selectionMs,
                    reconcileMs,
                    catalogSwapMs,
                    panelCommitMs,
                    preResetMs,
                    preResetSelectionReleaseMs,
                    preResetSelectionCleared,
                    preResetSelectionReleasedCount,
                    resetMs,
                    selectionCommitMs,
                    resetGeneratorRemoveMs,
                    resetForgetDeferredMeasureMs,
                    resetRemoveInternalChildRangeMs,
                    resetRemoveInternalChildRangeThreadCpuMs,
                    resetPanelTotalMs,
                    resetPanelThreadCpuMs,
                    resetPanelBudgetMs,
                    resetPanelBudgetUsedWallFallback,
                    maxResetDetachedContainersPerSlice,
                    inputBoundaryBeforePublication,
                    inputBoundaryAfterPublication);
            }

            bool wasSyncingSelection = _syncingSelection;
            _syncingSelection = true;
            try
            {
                phase.Restart();
                if (filterResult.OrderedCatalogTiles is { } orderedCatalog)
                {
                    _allTiles = orderedCatalog;
                    _catalogContentRevision++;
                }
                phase.Stop();
                catalogSwapMs = phase.ElapsedMilliseconds;

                phase.Restart();
                if (preparedPanel is not null
                    && snapshot.LayoutContext is { } targetLayoutContext)
                {
                    preparedPanel.ShowGroupHeaders = targetLayoutContext.ShowGroupHeaders;
                }
                phase.Stop();
                panelCommitMs = phase.ElapsedMilliseconds;

                bool collectResetAllocation =
                    !string.IsNullOrEmpty(_catalogInteractionDiagnosticOperation);
                long resetAllocatedBefore = collectResetAllocation
                    ? GC.GetAllocatedBytesForCurrentThread()
                    : 0;
                StageGalleryAutomationProjection(filterResult.AutomationProjection);
                if (publishSingleRemoval)
                {
                    _tiles.ReplaceOneRemovedAfterValidation(
                        filterResult.Tiles,
                        filterResult.Count,
                        exactSingleRemovalIndex);
                }
                else
                {
                    // The work above remains part of the app-owned
                    // cooperative slice. The synchronous WPF Reset is an
                    // indivisible notification and has a separate hard gate.
                    FinishSlice();
                    long resetCpuBefore = collectResetAllocation
                        ? VirtualizingWrapPanel
                            .ReadCurrentThreadCpuTimeTicksForDiagnostics()
                        : -1;
                    phase.Restart();
                    if (_catalogSnapshotResetDepth != 0)
                        catalogSnapshotResetNestedCount++;
                    _catalogSnapshotResetDepth++;
                    try
                    {
                        _tiles.ReplaceAll(filterResult.Tiles, filterResult.Count);
                        catalogSnapshotResetCount++;
                    }
                    finally
                    {
                        _catalogSnapshotResetDepth--;
                    }
                    phase.Stop();
                    resetMs = phase.ElapsedMilliseconds;
                    long resetCpuAfter = collectResetAllocation
                        ? VirtualizingWrapPanel
                            .ReadCurrentThreadCpuTimeTicksForDiagnostics()
                        : -1;
                    catalogSnapshotResetThreadCpuMs =
                        resetCpuBefore >= 0 && resetCpuAfter >= resetCpuBefore
                            ? TimeSpan.FromTicks(resetCpuAfter - resetCpuBefore)
                                .TotalMilliseconds
                            : -1;
                    slice.Restart();
                }
                resetAllocatedBytes = collectResetAllocation
                    ? GC.GetAllocatedBytesForCurrentThread() - resetAllocatedBefore
                    : 0;

                phase.Restart();
                if (resetPreparationStarted)
                {
                    preparedPanel!.CompleteItemsResetPreparation();
                    resetPreparationStarted = false;
                }
                preparedPanel?.SetPreparedLayout(filterResult.PreparedLayout);
                _selectedPaths.Clear();
                foreach (Tile selectedTile in filterResult.SelectedTiles)
                    _selectedPaths.Add(selectedTile.Path);
                phase.Stop();
                selectionCommitMs = phase.ElapsedMilliseconds;
            }
            finally
            {
                _syncingSelection = wasSyncingSelection;
            }
        }
        finally
        {
            if (resetPreparationStarted)
                preparedPanel?.CancelItemsResetPreparation();
        }

        publishMs = slice.ElapsedMilliseconds;
        // A proven one-item exclusion has already staged the matching
        // Automation projection and emitted one bounded Remove notification.
        // Retain both mandatory input turns around publication, then keep only
        // its remaining O(1) presentation phases in the same dispatcher turn.
        // Reset and broader projection paths continue to yield after every
        // phase.
        if (!await YieldForInputAsync())
            return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        inputBoundaryAfterPublication = true;

        phase.Restart();
        Tile? preferred = filterResult.PreferredSelection;
        if (preferred is not null)
        {
            if (_selectedPaths.Count == 0)
                _selectedPaths.Add(preferred.Path);
            _primarySelectedPath = preferred.Path;
            _primarySelectedTile = preferred;
            _primarySelectedIndex = filterResult.PreferredSelectionIndex;
        }
        else if (filterResult.Count == 0)
        {
            _primarySelectedPath = null;
            _primarySelectedTile = null;
            _primarySelectedIndex = -1;
        }
        if (filterResult.PreparedLayout is null)
            _galleryVirtualizingPanel?.InvalidateItemLayout();
        phase.Stop();
        statsMs = phase.ElapsedMilliseconds;
        if (!publishSingleRemoval)
        {
            if (!await YieldForInputAsync())
                return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }
        else if (!IsCurrentWithoutYield())
        {
            return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }

        phase.Restart();
        if (preferred is not null)
        {
            _selectionVisualSyncGeneration++;
            SynchronizeSelectionControls(
                filterResult.SelectedTiles,
                realizedOnly: filterResult.SelectedRelocationScanLength
                    >= CatalogResetSelectionScanReleaseThreshold);
        }

        phase.Stop();
        selectionMs = phase.ElapsedMilliseconds;
        if (!publishSingleRemoval)
        {
            if (!await YieldForInputAsync())
                return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }
        else if (!IsCurrentWithoutYield())
        {
            return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }

        phase.Restart();
        bool primarySelectionUnchanged = preferred is not null
            && string.Equals(
                snapshot.PreviousSelectedPath,
                preferred.Path,
                StringComparison.OrdinalIgnoreCase);
        if (preferred is not null && !primarySelectionUnchanged)
            ApplyPrimarySelection(preferred, filterResult.PreferredSelectionIndex);
        else if (filterResult.Count == 0)
            SelectTile(null);

        phase.Stop();
        selectionMs += phase.ElapsedMilliseconds;
        if (!publishSingleRemoval)
        {
            if (!await YieldForInputAsync())
                return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }
        else if (!IsCurrentWithoutYield())
        {
            return new CatalogProjectionApplyMetrics(maxSliceMs, publishMs, statsMs, selectionMs, reconcileMs);
        }

        phase.Restart();
        ReconcileOpenSurfacesAfterFilterChange(filterResult.ActivePreviewIncluded);
        bool restoreGalleryFocus = snapshot.RestoreGalleryFocus
            && preferred is not null
            && filterResult.PreferredSelectionIndex >= 0;
        // A focused selection is the viewport authority. Scheduling the old
        // viewport anchor and then immediately bringing the focused item into
        // view caused two competing render/layout passes after a Reset.
        if (filterResult.ViewportAnchor is not null && !restoreGalleryFocus)
            ScheduleGridGeometryAnchorRestore(filterResult.ViewportAnchor);
        if (restoreGalleryFocus)
        {
            QueuePrimaryGalleryFocus(
                preferred!,
                filterResult.PreferredSelectionIndex,
                RowsList.Visibility != Visibility.Visible);
        }
        ScheduleCatalogStatsUpdate(generation);
        phase.Stop();
        reconcileMs = phase.ElapsedMilliseconds;
        FinishSlice();
        return new CatalogProjectionApplyMetrics(
            maxSliceMs,
            publishMs,
            statsMs,
            selectionMs,
            reconcileMs,
            catalogSwapMs,
            panelCommitMs,
            preResetMs,
            preResetSelectionReleaseMs,
            preResetSelectionCleared,
            preResetSelectionReleasedCount,
            resetMs,
            selectionCommitMs,
            resetGeneratorRemoveMs,
            resetForgetDeferredMeasureMs,
            resetRemoveInternalChildRangeMs,
            resetRemoveInternalChildRangeThreadCpuMs,
            resetPanelTotalMs,
            resetPanelThreadCpuMs,
            resetPanelBudgetMs,
            resetPanelBudgetUsedWallFallback,
            maxResetDetachedContainersPerSlice,
            inputBoundaryBeforePublication,
            inputBoundaryAfterPublication,
            resetAllocatedBytes,
            catalogSnapshotResetThreadCpuMs,
            catalogSnapshotResetCount,
            catalogSnapshotResetNestedCount,
            publishSingleRemoval);
    }

    private void ScheduleCatalogStatsUpdate(long generation)
    {
        _catalogStatsPresentationGeneration = generation;
        Dispatcher.BeginInvoke(() =>
        {
            if (generation != _catalogProjectionGeneration
                || generation != _catalogStatsPresentationGeneration)
            {
                return;
            }
            if (_favoriteFilterPresentationPending)
            {
                _favoriteFilterPresentationPending = false;
                SyncFavoriteFilterControls();
            }
            UpdateFolderStats();
        }, DispatcherPriority.ContextIdle);
    }

    private void ApplyFilterResult(
        FilterResult filterResult,
        bool selectFirst,
        int? selectionFallbackIndex = null)
    {
        var previous = SelectedTile();
        Tile[] filtered = filterResult.Tiles;
        int filteredCount = filterResult.Count;

        if (_selectedPaths.Count > 0)
        {
            if (_selectedPaths.Count <= 64)
            {
                var remaining = new HashSet<string>(_selectedPaths, StringComparer.OrdinalIgnoreCase);
                var available = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int index = 0; index < filteredCount; index++)
                {
                    Tile tile = filtered[index];
                    if (remaining.Remove(tile.Path))
                        available.Add(tile.Path);
                    if (remaining.Count == 0)
                        break;
                }
                _selectedPaths.IntersectWith(available);
            }
            else
            {
                var availablePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int index = 0; index < filteredCount; index++)
                    availablePaths.Add(filtered[index].Path);
                _selectedPaths.IntersectWith(availablePaths);
            }
        }

        bool wasSyncingSelection = _syncingSelection;
        _syncingSelection = true;
        try
        {
            CancelThumbnailViewportLoading();
            _thumbnailViewportRevision++;
            if (ShouldReleaseWpfSelectionBeforeCatalogPublication(filterResult))
                ReleaseWpfSelectionBeforeCatalogPublication();
            StageGalleryAutomationProjection(filterResult.AutomationProjection);
            _tiles.ReplaceAll(filtered, filteredCount);
        }
        finally
        {
            _syncingSelection = wasSyncingSelection;
        }

        Tile? preferred = !string.IsNullOrWhiteSpace(_primarySelectedPath)
            ? _tiles.FirstOrDefault(tile => string.Equals(tile.Path, _primarySelectedPath, StringComparison.OrdinalIgnoreCase))
            : null;
        preferred ??= previous is not null && _tiles.Contains(previous) ? previous : null;
        if (preferred is null && _selectedPaths.Count > 0)
        {
            for (int index = _tiles.Count - 1; index >= 0; index--)
            {
                if (!_selectedPaths.Contains(_tiles[index].Path))
                    continue;
                preferred = _tiles[index];
                break;
            }
        }
        if (preferred is null && selectionFallbackIndex.HasValue && _tiles.Count > 0)
            preferred = _tiles[Math.Clamp(selectionFallbackIndex.Value, 0, _tiles.Count - 1)];
        preferred ??= selectFirst && _tiles.Count > 0 ? _tiles[0] : null;
        _galleryVirtualizingPanel?.InvalidateItemLayout();
        UpdateFolderStats();

        if (preferred is not null)
        {
            if (_selectedPaths.Count == 0)
                _selectedPaths.Add(preferred.Path);
            _primarySelectedPath = preferred.Path;
            _primarySelectedTile = preferred;
            _primarySelectedIndex = _tiles.IndexOf(preferred);
            _selectionVisualSyncGeneration++;
            SynchronizeSelectionControls(
                filterResult.SelectedTiles,
                realizedOnly: filterResult.SelectedRelocationScanLength
                    >= CatalogResetSelectionScanReleaseThreshold);
            ApplyPrimarySelection(preferred);
        }
        else if (filteredCount == 0)
            SelectTile(null);

        ReconcileOpenSurfacesAfterFilterChange(filterResult.ActivePreviewIncluded);
    }

    private void ReconcileOpenSurfacesAfterFilterChange(bool? activePreviewIncluded = null)
    {
        Tile? selected = SelectedTile();
        bool activePreviewIsSelected = selected is not null
            && string.Equals(
                _activePreviewTabPath,
                selected.Path,
                StringComparison.OrdinalIgnoreCase);
        if (!string.IsNullOrWhiteSpace(_activePreviewTabPath)
            && !activePreviewIsSelected
            && !(activePreviewIncluded
                ?? _tiles.Any(tile => string.Equals(
                    tile.Path,
                    _activePreviewTabPath,
                    StringComparison.OrdinalIgnoreCase))))
        {
            // Open tabs belong to the full catalog and must survive filters, but
            // an active marker may not claim that its filtered-out image is the
            // current right-preview selection.  The tab can be activated again
            // as soon as the filter admits its path.
            string filteredActivePath = _activePreviewTabPath;
            _activePreviewTabPath = null;
            PreviewTabView? filteredActiveTab = _previewTabs.FirstOrDefault(tab =>
                string.Equals(tab.Path, filteredActivePath, StringComparison.OrdinalIgnoreCase));
            if (filteredActiveTab is not null)
                filteredActiveTab.IsActive = false;
        }

        if (Modal.Visibility != Visibility.Visible)
            return;

        if (selected is null)
        {
            bool modalHadFocus = Modal.IsKeyboardFocusWithin;
            CloseModal();
            if (modalHadFocus)
                Dispatcher.BeginInvoke(SearchInput.Focus, DispatcherPriority.Input);
            return;
        }

        if (!string.Equals(_modalSourceTilePath, selected.Path, StringComparison.OrdinalIgnoreCase))
            OpenModal();
    }

    private static bool MatchesSearch(Tile tile, string query)
    {
        if (string.IsNullOrWhiteSpace(query)) return true;

        var tokens = query.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        foreach (var token in tokens)
        {
            if (ContainsText(tile.FileName, token)
                || ContainsText(tile.Prompt, token))
            {
                continue;
            }

            return false;
        }

        return true;
    }

    private static bool ContainsText(string? value, string token)
        => !string.IsNullOrEmpty(value) && value.Contains(token, StringComparison.OrdinalIgnoreCase);

    private bool MatchesFavoriteFilter(Tile tile, bool favoritesOnly, bool unfavoriteOnly)
    {
        if (favoritesOnly)
            return tile.Fav > 0 && (_favoriteFilterLevels.Count == 0 || _favoriteFilterLevels.Contains(tile.Fav));
        if (unfavoriteOnly)
            return tile.Fav <= 0;
        return true;
    }

    private bool MatchesFolderBucketFilter(Tile tile)
        => !tile.IsRealFile
            || string.IsNullOrWhiteSpace(tile.FolderBucketKey)
            || !_hiddenFolderBuckets.Contains(tile.FolderBucketKey);

    private bool MatchesDateFilter(Tile tile)
    {
        if ((!_dateFromLocal.HasValue && !_dateToLocal.HasValue)
            || !tile.IsRealFile)
        {
            return true;
        }

        DateTime createdDate = tile.CreatedUtc.ToLocalTime().Date;
        if (_dateFromLocal.HasValue && createdDate < _dateFromLocal.Value.Date)
            return false;

        if (_dateToLocal.HasValue && createdDate > _dateToLocal.Value.Date)
            return false;

        return true;
    }

    private IEnumerable<Tile> SortTiles(IEnumerable<Tile> source)
    {
        return _sortBy switch
        {
            SortModifiedOldestValue => source
                .OrderBy(static tile => tile.ModifiedUtc)
                .ThenBy(static tile => tile.FileName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
            SortCreatedNewestValue => source
                .OrderByDescending(static tile => tile.CreatedUtc)
                .ThenBy(static tile => tile.FileName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
            SortCreatedOldestValue => source
                .OrderBy(static tile => tile.CreatedUtc)
                .ThenBy(static tile => tile.FileName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
            SortRandomValue => source
                .OrderBy(tile => StableRandomSortKey(_randomSortSeed, tile.Path))
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
            SortNameValue => source
                .OrderBy(static tile => tile.FileName, StringComparer.OrdinalIgnoreCase)
                .ThenByDescending(static tile => tile.ModifiedUtc)
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
            _ => source
                .OrderByDescending(static tile => tile.ModifiedUtc)
                .ThenBy(static tile => tile.FileName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(static tile => tile.Path, StringComparer.OrdinalIgnoreCase),
        };
    }

    private void SelectFirstAvailable()
    {
        SelectTile(_tiles.Count > 0 ? _tiles[0] : null);
    }

    private void SelectRestoredOrFirst()
    {
        var restored = !string.IsNullOrWhiteSpace(_restoredSelectedPath)
            ? _tiles.FirstOrDefault(tile => string.Equals(tile.Path, _restoredSelectedPath, StringComparison.OrdinalIgnoreCase))
            : null;
        SelectTile(restored ?? (_tiles.Count > 0 ? _tiles[0] : null));
    }

    private void SelectTile(Tile? tile, int projectedIndex = -1)
    {
        SetSelection(tile is null ? [] : [tile], tile, projectedIndex);
    }

    private void ClearPreview()
    {
        _previewCts?.Cancel();
        _previewDecodeCompletion?.TrySetResult(PreviewDecodeResult.Canceled);
        _previewMetadataCts?.Cancel();
        _previewMetadataCompletion?.TrySetResult(null);
        ClearPreviewMetadataCopyState();
        _previewDecodedPath = null;
        PreviewBitmap.Source = null;
        PreviewBitmap.Visibility = Visibility.Collapsed;
        PreviewArtBase.Visibility = Visibility.Visible;
        PreviewArtGlow.Visibility = Visibility.Visible;
        PreviewFileName.Text = "No matching image";
        PreviewTabName.Text = "No selection";
        PreviewSizeText.Text = "-";
        PreviewModelText.Text = "-";
        PreviewDateText.Text = "-";
        PreviewPromptText.Text = "";
        RightPreviewContent.Visibility = Visibility.Collapsed;
        RightPreviewEmptyState.Visibility = Visibility.Visible;
        SyncFavoriteLevelReadouts(0);
        SyncSelectionActionSurface();
        ModalTitle.Text = "No selection";
        UpdateHeaderStats();
    }

    private void UpdateFolderStats()
    {
        if (FolderCountText is null) return;

        int total = _allTiles.Count;
        int visible = _tiles.Count;
        string loaded = $"{total:N0} images indexed";
        FolderCountText.Text = visible == total ? loaded : $"{visible:N0} shown / {loaded}";
        UpdateHeaderStats();
    }

    private void UpdateHeaderStats()
    {
        if (HeaderStats is null) return;

        int selected = _selectedPaths.Count;
        int visible = _tiles.Count;
        int total = _allTiles.Count;
        string imageText = visible == total ? $"{total:N0} images" : $"{visible:N0} / {total:N0} images";
        string folderText = _currentFolderSet.Count == 0 ? "sample" : $"{_currentFolderSet.Count:N0} folder(s)";
        HeaderStats.Text = _activeAlbumId is null
            ? $"{selected:N0} selected - {imageText} - {folderText}"
            : $"{selected:N0} selected - {visible:N0}/{_activeAlbumMemberCount:N0} in {_activeAlbumName} - {_activeAlbumOutsideCount:N0} outside unavailable - {_activeAlbumMissingCount:N0} missing";
    }

    private void UpdateGridMetrics(LoadMetrics metrics)
    {
        VirtualizingWrapPanel? panel = FindVisualDescendant<VirtualizingWrapPanel>(CardsList);
        int realizedCount = panel?.RealizedItemCount ?? 0;
        int windowStart = Math.Max(0, panel?.FirstRealizedIndex ?? 0);
        int windowEnd = Math.Max(windowStart, (panel?.LastRealizedIndex ?? -1) + 1);
        metrics.GridTotalItems = _tiles.Count;
        metrics.GridRealizedItems = realizedCount;
        metrics.GridDeferredItems = Math.Max(0, _tiles.Count - realizedCount);
        metrics.GridInitialRealizationLimit = MaxVirtualizedContainerSmokeCount;
        metrics.GridRealizationBatchSize = 0;
        metrics.GridMaxRealizationCount = MaxVirtualizedContainerSmokeCount;
        metrics.GridWindowStartIndex = windowStart;
        metrics.GridWindowEndIndex = windowEnd;
    }

    // ─────────── Size slider ───────────
    private void SizeSlider_ValueChanged(object sender, RoutedPropertyChangedEventArgs<double> e)
    {
        if (_suppressSizeSliderChange)
            return;

        if (RowsList?.Visibility == Visibility.Visible)
        {
            _suppressSizeSliderChange = true;
            try { SizeSlider.Value = e.OldValue; }
            finally { _suppressSizeSliderChange = false; }
            return;
        }

        GridZoomAnchor? anchor = CaptureGridZoomAnchor();
        SyncGalleryColumnMode();
        ApplyCardLayoutToAllTiles();
        RestoreGridZoomAnchorAfterLayout(anchor);
        if (!_initializing)
            SaveState();
    }

    private void ZoomOut_Click(object sender, RoutedEventArgs e) => AdjustCardWidth(-1);
    private void ZoomIn_Click(object sender, RoutedEventArgs e) => AdjustCardWidth(1);
    private void ZoomReset_Click(object sender, RoutedEventArgs e) => ResetCardWidth();

    private bool AdjustCardWidth(int steps)
    {
        double before = SizeSlider.Value;
        SetCardWidth(before + (CardWidthStep * steps));
        return Math.Abs(SizeSlider.Value - before) > 0.01;
    }

    private bool ResetCardWidth()
    {
        double before = SizeSlider.Value;
        SetCardWidth(DefaultCardWidth);
        return Math.Abs(SizeSlider.Value - before) > 0.01;
    }

    private void SetCardWidth(double value)
    {
        if (RowsList?.Visibility == Visibility.Visible)
            return;
        SizeSlider.Value = NormalizeCardWidth(value);
    }

    private double NormalizeCardWidth(double value)
        => double.IsFinite(value)
            ? Math.Clamp(value, Math.Max(MinCardWidth, SizeSlider.Minimum), Math.Min(MaxCardWidth, SizeSlider.Maximum))
            : DefaultCardWidth;

    private void SyncGalleryColumnMode()
    {
        if (CardsList is null || SizeSlider is null)
            return;
        VirtualizingWrapPanel? panel = _galleryVirtualizingPanel ?? FindVisualDescendant<VirtualizingWrapPanel>(CardsList);
        if (panel is null)
            return;
        // CardsList always publishes this exact filtered collection. Let the
        // panel read variable heights/groups directly instead of paying the
        // WPF ItemCollection indexer cost once per item on every extent rebuild.
        panel.SetLayoutSource(_tiles);
        (double uniformWidth, double uniformHeight) = ResolveUniformCardLayout();
        // The panel otherwise asks ItemCollection for every tile while rebuilding
        // its 20k/100k extent. Width is always uniform, and non-original aspect
        // modes also have a uniform height, so publish those shared metrics once.
        panel.ItemWidth = uniformWidth + 4;
        panel.ItemHeight = double.IsFinite(uniformHeight) ? uniformHeight + 4 : double.NaN;
        panel.ForceSingleColumn = SizeSlider.Value >= Math.Min(MaxCardWidth, SizeSlider.Maximum) - 0.01;
    }

    private (double Width, double Height) ResolveUniformCardLayout()
    {
        double baseWidth = SizeSlider?.Value ?? DefaultCardWidth;
        double minWidth = SizeSlider?.Minimum ?? 130;
        double maxWidth = SizeSlider?.Maximum ?? 280;
        double widthFactor = _displayStyle switch
        {
            DisplayStyleCompact => 0.82,
            DisplayStylePoster => 1.12,
            _ => 1.0,
        };
        double width = Math.Clamp(baseWidth * widthFactor, minWidth, maxWidth);
        // Icon-size cards are square for every aspect mode. Publishing that
        // uniform height keeps the virtualizing panel from walking the full
        // ItemCollection merely to rediscover the same value at minimum zoom.
        double aspectHeightFactor = _aspectMode switch
        {
            AspectSquareValue => 1.0,
            AspectOriginalValue => double.NaN,
            _ => 1.5,
        };
        double height = width < 80
            ? width
            : double.IsFinite(aspectHeightFactor)
                ? Math.Max(40, width * aspectHeightFactor)
                : double.NaN;
        return (width, height);
    }

    private GridZoomAnchor? CaptureGridZoomAnchor()
    {
        if (CardsList?.Visibility != Visibility.Visible)
            return null;
        ScrollViewer? viewer = FindVisualDescendant<ScrollViewer>(CardsList);
        if (viewer is null || viewer.ViewportHeight <= 0)
            return null;

        GridZoomAnchor? selected = null;
        GridZoomAnchor? best = null;
        GridZoomAnchor? previous = null;
        double center = viewer.ViewportHeight / 2;
        string? selectedPath = SelectedTile() is { IsRealFile: true } selectedTile
            ? selectedTile.Path
            : _primarySelectedPath;
        VirtualizingWrapPanel? panel = _galleryVirtualizingPanel
            ?? FindVisualDescendant<VirtualizingWrapPanel>(CardsList);
        if (panel is {
                FirstVisibleIndex: >= 0,
                LastVisibleIndex: >= 0,
            })
        {
            int firstVisible = Math.Clamp(panel.FirstVisibleIndex, 0, _tiles.Count - 1);
            int lastVisible = Math.Clamp(panel.LastVisibleIndex, firstVisible, _tiles.Count - 1);

            GridZoomAnchor? CandidateForPath(string? path)
            {
                if (string.IsNullOrWhiteSpace(path))
                    return null;
                int index = -1;
                for (int candidateIndex = firstVisible;
                     candidateIndex <= lastVisible;
                     candidateIndex++)
                {
                    if (!string.Equals(
                            _tiles[candidateIndex].Path,
                            path,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                    index = candidateIndex;
                    break;
                }
                if (index < firstVisible || index > lastVisible || !_tiles[index].IsRealFile)
                    return null;
                double top = panel.GetItemViewportTop(index);
                return double.IsFinite(top)
                    ? new GridZoomAnchor(path, top, Math.Abs(top - center))
                    : null;
            }

            GridZoomAnchor? selectedLayoutAnchor = CandidateForPath(selectedPath);
            if (selectedLayoutAnchor is not null)
                return selectedLayoutAnchor;
            GridZoomAnchor? previousLayoutAnchor = CandidateForPath(_lastGridZoomAnchorPath);
            if (previousLayoutAnchor is not null)
                return previousLayoutAnchor;

            int middle = firstVisible + ((lastVisible - firstVisible) / 2);
            for (int distance = 0; distance <= lastVisible - firstVisible; distance++)
            {
                int left = middle - distance;
                int right = middle + distance;
                int index = left >= firstVisible && _tiles[left].IsRealFile
                    ? left
                    : right <= lastVisible && _tiles[right].IsRealFile
                        ? right
                        : -1;
                if (index < 0)
                    continue;
                double top = panel.GetItemViewportTop(index);
                if (double.IsFinite(top))
                {
                    return new GridZoomAnchor(
                        _tiles[index].Path,
                        top,
                        Math.Abs(top - center));
                }
            }
        }
        foreach (ListBoxItem item in FindVisualDescendants<ListBoxItem>(CardsList))
        {
            if (item.DataContext is not Tile tile || !tile.IsRealFile || item.ActualHeight <= 0)
                continue;
            try
            {
                Point top = item.TransformToAncestor(viewer).Transform(new Point(0, 0));
                if (top.Y >= viewer.ViewportHeight || top.Y + item.ActualHeight <= 0)
                    continue;
                double distance = Math.Abs((top.Y + item.ActualHeight / 2) - center);
                var candidate = new GridZoomAnchor(tile.Path, top.Y, distance);
                if (!string.IsNullOrWhiteSpace(selectedPath) && string.Equals(tile.Path, selectedPath, StringComparison.OrdinalIgnoreCase))
                    selected = candidate;
                if (best is null || distance < best.Value.CenterDistance)
                    best = candidate;
                if (!string.IsNullOrWhiteSpace(_lastGridZoomAnchorPath) && string.Equals(tile.Path, _lastGridZoomAnchorPath, StringComparison.OrdinalIgnoreCase))
                    previous = candidate;
            }
            catch (InvalidOperationException)
            {
                // The visual can be recycled while a scroll/layout pass is in flight.
            }
        }
        return selected ?? previous ?? best;
    }

    private void ScheduleRememberCurrentGridViewportAnchor()
    {
        long generation = ++_gridAnchorRememberGeneration;
        Dispatcher.BeginInvoke(() =>
        {
            if (generation != _gridAnchorRememberGeneration || _restoringGridZoomAnchor || CardsList.Visibility != Visibility.Visible)
                return;
            GridZoomAnchor? anchor = CaptureGridZoomAnchor();
            if (anchor is not null)
                _lastStableGridViewportAnchor = anchor;
        }, DispatcherPriority.ContextIdle);
    }

    private void ScheduleGridGeometryAnchorRestore(GridZoomAnchor? anchor = null)
    {
        if (_initializing || CardsList?.Visibility != Visibility.Visible)
            return;
        GridZoomAnchor? resolved = anchor ?? _lastStableGridViewportAnchor ?? CaptureGridZoomAnchor();
        if (resolved is null)
            return;
        _gridAnchorRememberGeneration++;
        RestoreGridZoomAnchorAfterLayout(resolved);
    }

    private GridZoomAnchor? PreferredGridGeometryAnchor()
    {
        string? selectedPath = SelectedTile() is { IsRealFile: true } selectedTile
            ? selectedTile.Path
            : _primarySelectedPath;
        if (!string.IsNullOrWhiteSpace(selectedPath)
            && _lastRequestedGridGeometryAnchor is { } requested
            && string.Equals(requested.Path, selectedPath, StringComparison.OrdinalIgnoreCase))
        {
            return requested;
        }

        return _lastStableGridViewportAnchor ?? CaptureGridZoomAnchor();
    }

    private void RestoreGridZoomAnchorAfterLayout(GridZoomAnchor? anchor)
    {
        if (anchor is null)
            return;
        _lastRequestedGridGeometryAnchor = anchor;
        _lastGridZoomAnchorPath = anchor.Value.Path;
        _lastGridZoomAnchorDrift = double.PositiveInfinity;
        _restoringGridZoomAnchor = true;
        Dispatcher.BeginInvoke(() =>
        {
            VirtualizingWrapPanel? panel = FindVisualDescendant<VirtualizingWrapPanel>(CardsList);
            Tile? anchorTile = _tiles.FirstOrDefault(tile => string.Equals(tile.Path, anchor.Value.Path, StringComparison.OrdinalIgnoreCase));
            int anchorIndex = anchorTile is null ? -1 : _tiles.IndexOf(anchorTile);
            if (panel is not null && anchorIndex >= 0 && panel.RestoreItemViewportTop(anchorIndex, anchor.Value.ViewportY))
            {
                Dispatcher.BeginInvoke(() =>
                {
                    double actual = panel.GetItemViewportTop(anchorIndex);
                    if (double.IsFinite(actual))
                        _lastGridZoomAnchorDrift = Math.Abs(actual - anchor.Value.ViewportY);
                    _restoringGridZoomAnchor = false;
                    _lastStableGridViewportAnchor = CaptureGridZoomAnchor() ?? anchor;
                    ScheduleRememberCurrentGridViewportAnchor();
                }, DispatcherPriority.Render);
                return;
            }

            ScrollViewer? viewer = FindVisualDescendant<ScrollViewer>(CardsList);
            FrameworkElement? item = FindVisualDescendants<FrameworkElement>(CardsList)
                .FirstOrDefault(element => element.DataContext is Tile tile && string.Equals(tile.Path, anchor.Value.Path, StringComparison.OrdinalIgnoreCase));
            if (viewer is null || item is null)
            {
                _restoringGridZoomAnchor = false;
                return;
            }
            try
            {
                double before = item.TransformToAncestor(viewer).Transform(new Point(0, 0)).Y;
                double requested = Math.Clamp(viewer.VerticalOffset + (before - anchor.Value.ViewportY), 0, Math.Max(0, viewer.ExtentHeight - viewer.ViewportHeight));
                viewer.ScrollToVerticalOffset(requested);
                Dispatcher.BeginInvoke(() =>
                {
                    FrameworkElement? settled = FindVisualDescendants<FrameworkElement>(CardsList)
                        .FirstOrDefault(element => element.DataContext is Tile tile && string.Equals(tile.Path, anchor.Value.Path, StringComparison.OrdinalIgnoreCase));
                    if (settled is null)
                    {
                        _restoringGridZoomAnchor = false;
                        return;
                    }
                    double actual = settled.TransformToAncestor(viewer).Transform(new Point(0, 0)).Y;
                    _lastGridZoomAnchorDrift = Math.Abs(actual - anchor.Value.ViewportY);
                    _restoringGridZoomAnchor = false;
                    _lastStableGridViewportAnchor = CaptureGridZoomAnchor() ?? anchor;
                    ScheduleRememberCurrentGridViewportAnchor();
                }, DispatcherPriority.Render);
            }
            catch (InvalidOperationException)
            {
                _restoringGridZoomAnchor = false;
            }
        }, DispatcherPriority.Render);
    }

    private static T? FindVisualDescendant<T>(DependencyObject root) where T : DependencyObject
        => FindVisualDescendants<T>(root).FirstOrDefault();

    private static IEnumerable<T> FindVisualDescendants<T>(DependencyObject root) where T : DependencyObject
    {
        for (int index = 0; index < VisualTreeHelper.GetChildrenCount(root); index++)
        {
            DependencyObject child = VisualTreeHelper.GetChild(root, index);
            if (child is T typed)
                yield return typed;
            foreach (T nested in FindVisualDescendants<T>(child))
                yield return nested;
        }
    }

    private void ApplyCardLayoutToAllTiles()
    {
        SyncGalleryColumnMode();
        foreach (var tile in _allTiles)
            ApplyCardLayout(tile);
        _galleryVirtualizingPanel?.InvalidateItemLayout();
    }

    private void ApplyCardLayout(Tile tile)
        => ApplyCardLayout(tile, CaptureCardLayoutContext());

    private CatalogCardLayoutContext CaptureCardLayoutContext()
        => new(
            SizeSlider?.Value ?? DefaultCardWidth,
            SizeSlider?.Minimum ?? 130,
            SizeSlider?.Maximum ?? 280,
            _displayStyle,
            _aspectMode);

    private static void ApplyCardLayout(Tile tile, CatalogCardLayoutContext context)
    {
        (double widthFactor, double listThumbnailBase) = context.DisplayStyle switch
        {
            DisplayStyleCompact => (0.82, 42),
            DisplayStylePoster => (1.12, 64),
            _ => (1.0, 52),
        };

        double width = Math.Clamp(context.BaseWidth * widthFactor, context.MinimumWidth, context.MaximumWidth);
        double aspectHeightFactor = AspectHeightFactor(tile, context.AspectMode);
        // At icon-size zoom levels, extreme source ratios make cards look like
        // vertical slivers. Keep the media cell square while preserving the
        // complete source inside it through Stretch.Uniform.
        double height = width < 80 ? width : Math.Max(40, width * aspectHeightFactor);
        double listThumbnailHeight = Math.Clamp(listThumbnailBase * aspectHeightFactor, 32, 120);
        tile.ApplyCardLayout(
            width,
            height,
            context.AspectMode == AspectOriginalValue ? Stretch.Uniform : Stretch.UniformToFill,
            showDetails: width >= 96,
            showStatusBadge: width >= 72,
            listThumbnailBase,
            listThumbnailHeight,
            Math.Max(listThumbnailBase, listThumbnailHeight));
    }

    private static double AspectHeightFactor(Tile tile, string aspectMode)
    {
        return aspectMode switch
        {
            AspectSquareValue => 1.0,
            AspectOriginalValue when tile.ImagePixelWidth > 0 && tile.ImagePixelHeight > 0
                => Math.Clamp(tile.ImagePixelHeight / (double)tile.ImagePixelWidth, 0.35, 3.0),
            _ => 1.5,
        };
    }

    private readonly record struct CatalogCardLayoutContext(
        double BaseWidth,
        double MinimumWidth,
        double MaximumWidth,
        string DisplayStyle,
        string AspectMode);

    private sealed record CatalogSharedStateSnapshot(
        IReadOnlyDictionary<string, int> Favorites,
        IReadOnlySet<string> SeenPaths,
        IReadOnlyDictionary<string, ManagedEnhancedOutput> EnhancedOutputs);

    private readonly record struct CatalogTilePreparationResult(
        List<Tile> Tiles,
        bool Parallelized,
        int Workers);

    private static string NormalizeDisplayStyle(string? style)
    {
        return style?.Trim().ToLowerInvariant() switch
        {
            DisplayStyleCompact => DisplayStyleCompact,
            DisplayStylePoster => DisplayStylePoster,
            _ => DisplayStyleStandard,
        };
    }

    private bool SetDisplayStyle(string style)
    {
        string normalized = NormalizeDisplayStyle(style);
        bool changed = !string.Equals(_displayStyle, normalized, StringComparison.Ordinal);
        _displayStyle = normalized;
        SyncDisplayStyleButtons();
        ApplyCardLayoutToAllTiles();
        if (!_initializing)
            SaveState();
        return changed;
    }

    private void SyncDisplayStyleButtons()
    {
        if (StyleStandard is null || StyleCompact is null || StylePoster is null)
            return;

        StyleStandard.IsChecked = _displayStyle == DisplayStyleStandard;
        StyleCompact.IsChecked = _displayStyle == DisplayStyleCompact;
        StylePoster.IsChecked = _displayStyle == DisplayStylePoster;
    }

    private static string NormalizeAspectMode(string? aspectMode)
    {
        return aspectMode?.Trim().ToLowerInvariant() switch
        {
            AspectSquareValue or "1:1" => AspectSquareValue,
            AspectPortraitValue or "2:3" => AspectPortraitValue,
            AspectOriginalValue => AspectOriginalValue,
            _ => AspectOriginalValue,
        };
    }

    private bool SetAspectMode(string aspectMode)
    {
        string normalized = NormalizeAspectMode(aspectMode);
        bool changed = !string.Equals(_aspectMode, normalized, StringComparison.Ordinal);
        _aspectMode = normalized;
        SyncAspectButtons();
        ApplyCardLayoutToAllTiles();
        if (changed && !_initializing)
            SaveState();
        return changed;
    }

    private void SyncAspectButtons()
    {
        if (AspectOriginalButton is null || AspectSquareButton is null || AspectPortraitButton is null)
            return;

        AspectOriginalButton.IsChecked = _aspectMode == AspectOriginalValue;
        AspectSquareButton.IsChecked = _aspectMode == AspectSquareValue;
        AspectPortraitButton.IsChecked = _aspectMode == AspectPortraitValue;
    }

    private static string NormalizeSortBy(string? sortBy)
    {
        return sortBy?.Trim().ToLowerInvariant() switch
        {
            SortModifiedOldestValue or "oldest" => SortModifiedOldestValue,
            SortCreatedNewestValue => SortCreatedNewestValue,
            SortCreatedOldestValue => SortCreatedOldestValue,
            SortNameValue => SortNameValue,
            SortRandomValue => SortRandomValue,
            SortModifiedNewestValue or "newest" => SortModifiedNewestValue,
            _ => SortModifiedNewestValue,
        };
    }

    private bool SetSortBy(string sortBy)
    {
        string normalized = NormalizeSortBy(sortBy);
        bool changed = !string.Equals(_sortBy, normalized, StringComparison.Ordinal);
        _sortBy = normalized;
        SyncSortButtons();

        if (changed && !_initializing)
        {
            ConfigureGalleryItemsSources();
            // Keep the complete catalog in product sort order. Subsequent
            // searches and filters can then preserve this order in O(n)
            // instead of re-sorting 100k entries after every query.
            ReorderFullCatalogForSort();
            ApplyFilters();
            SaveState();
        }

        return changed;
    }

    private async Task<bool> SetSortByInteractiveAsync(string sortBy)
    {
        string normalized = NormalizeSortBy(sortBy);
        bool changed = !string.Equals(_sortBy, normalized, StringComparison.Ordinal);
        _sortBy = normalized;
        SyncSortButtons();
        if (!changed || _initializing)
            return changed;

        return await ApplyCurrentSortInteractiveAsync();
    }

    private async Task<bool> ApplyCurrentSortInteractiveAsync()
    {
        ConfigureGalleryItemsSources();
        SearchFilterCompletion completion = await QueueCatalogProjection(
            debounce: false,
            reorderCatalog: true,
            selectFirst: true);
        if (!completion.Applied || completion.Discarded)
            return false;
        SaveState();
        return true;
    }

    private static List<Tile> SortTiles(IEnumerable<Tile> tiles, string sortBy, string randomSortSeed)
    {
        var ordered = tiles.ToList();
        ordered.Sort((left, right) => CompareTilesForSort(left, right, sortBy, randomSortSeed));
        return ordered;
    }

    private void ReorderFullCatalogForSort()
    {
        if (_allTiles.Count < 2)
            return;
        // List.Sort works in place. LINQ OrderBy materializes several 100k
        // key/index buffers for every mode change and leaves tens of MB for a
        // later full GC during rapid interaction.
        _allTiles.Sort((left, right) => CompareTilesForSort(left, right, _sortBy, _randomSortSeed));
        _catalogContentRevision++;
    }

    private static int CompareTilesForSort(Tile left, Tile right, string sortBy, string randomSortSeed)
    {
        int primary = sortBy switch
        {
            SortModifiedOldestValue => left.ModifiedUtc.CompareTo(right.ModifiedUtc),
            SortCreatedNewestValue => right.CreatedUtc.CompareTo(left.CreatedUtc),
            SortCreatedOldestValue => left.CreatedUtc.CompareTo(right.CreatedUtc),
            SortRandomValue => StableRandomSortKey(randomSortSeed, left.Path)
                .CompareTo(StableRandomSortKey(randomSortSeed, right.Path)),
            SortNameValue => StringComparer.OrdinalIgnoreCase.Compare(left.FileName, right.FileName),
            _ => right.ModifiedUtc.CompareTo(left.ModifiedUtc),
        };
        if (primary != 0)
            return primary;

        if (sortBy == SortNameValue)
        {
            int modified = right.ModifiedUtc.CompareTo(left.ModifiedUtc);
            if (modified != 0)
                return modified;
        }
        else if (sortBy != SortRandomValue)
        {
            int fileName = StringComparer.OrdinalIgnoreCase.Compare(left.FileName, right.FileName);
            if (fileName != 0)
                return fileName;
        }

        return StringComparer.OrdinalIgnoreCase.Compare(left.Path, right.Path);
    }

    private void SyncSortButtons()
    {
        if (SortModifiedNewest is null || SortModifiedOldest is null || SortCreatedNewest is null || SortCreatedOldest is null || SortName is null || SortRandom is null)
            return;

        SortModifiedNewest.IsChecked = _sortBy == SortModifiedNewestValue;
        SortModifiedOldest.IsChecked = _sortBy == SortModifiedOldestValue;
        SortCreatedNewest.IsChecked = _sortBy == SortCreatedNewestValue;
        SortCreatedOldest.IsChecked = _sortBy == SortCreatedOldestValue;
        SortName.IsChecked = _sortBy == SortNameValue;
        SortRandom.IsChecked = _sortBy == SortRandomValue;
    }

    private static ulong StableRandomSortKey(string seed, string path)
    {
        const ulong offset = 14695981039346656037;
        const ulong prime = 1099511628211;
        ulong hash = offset;
        foreach (char value in seed)
        {
            hash ^= value;
            hash *= prime;
        }
        hash ^= 0;
        hash *= prime;
        foreach (char value in path)
        {
            hash ^= value;
            hash *= prime;
        }
        return hash;
    }

    private bool ReshuffleRandomSort()
    {
        _randomSortSeed = Guid.NewGuid().ToString("N");
        if (_sortBy != SortRandomValue)
            _sortBy = SortRandomValue;
        SyncSortButtons();
        if (!_initializing)
        {
            ReorderFullCatalogForSort();
            ApplyFilters();
            SaveState();
        }
        return true;
    }

    private async Task<bool> ReshuffleRandomSortInteractiveAsync()
    {
        _randomSortSeed = Guid.NewGuid().ToString("N");
        _sortBy = SortRandomValue;
        SyncSortButtons();
        if (_initializing)
            return true;
        return await ApplyCurrentSortInteractiveAsync();
    }

    private static string NormalizeDatePreset(string? preset)
    {
        return preset?.Trim().ToLowerInvariant() switch
        {
            DatePresetManualValue or "range" => DatePresetManualValue,
            "clear" or "" or null => DatePresetNoneValue,
            _ => DatePresetNoneValue,
        };
    }

    private static bool TryGetLegacyDateRange(string? preset, out DateTime? from, out DateTime? to)
    {
        DateTime today = DateTime.Today;
        switch (preset?.Trim().ToLowerInvariant())
        {
            case "today":
                from = today;
                to = today;
                return true;
            case "7d":
            case "last7":
            case "last-7":
                from = today.AddDays(-6);
                to = today;
                return true;
            case "30d":
            case "last30":
            case "last-30":
                from = today.AddDays(-29);
                to = today;
                return true;
            case "this-year":
            case "year":
                from = new DateTime(today.Year, 1, 1);
                to = today;
                return true;
            default:
                from = null;
                to = null;
                return false;
        }
    }

    private static string? FormatStateDate(DateTime? date)
        => date?.ToString("yyyy-MM-dd");

    private static DateTime? ParseStateDate(string? value)
    {
        if (DateTime.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTime parsed))
            return parsed.Date;

        return null;
    }

    private bool SetManualDateRange(DateTime? from, DateTime? to, bool asynchronous = true)
    {
        DateTime? normalizedFrom = from?.Date;
        DateTime? normalizedTo = to?.Date;
        string normalizedPreset = normalizedFrom.HasValue || normalizedTo.HasValue
            ? DatePresetManualValue
            : DatePresetNoneValue;

        bool changed = !string.Equals(_datePreset, normalizedPreset, StringComparison.Ordinal)
            || !SameDate(_dateFromLocal, normalizedFrom)
            || !SameDate(_dateToLocal, normalizedTo);

        _datePreset = normalizedPreset;
        _dateFromLocal = normalizedFrom;
        _dateToLocal = normalizedTo;
        SyncDateControls();
        UpdateDateFilterSummary();

        if (changed && !_initializing)
        {
            if (asynchronous)
            {
                _ = QueueCatalogProjection(
                    debounce: false,
                    reorderCatalog: false,
                    selectFirst: true);
            }
            else
            {
                ApplyFilters();
            }
            SaveState();
        }

        return changed;
    }

    private static bool SameDate(DateTime? left, DateTime? right)
        => left?.Date == right?.Date;

    private void RestoreDateFilter(ViewerState state)
    {
        DateTime? persistedFrom = ParseStateDate(state.DateFrom);
        DateTime? persistedTo = ParseStateDate(state.DateTo);
        if (TryGetLegacyDateRange(state.DatePreset, out DateTime? legacyFrom, out DateTime? legacyTo))
        {
            // Preserve an old saved range exactly. Only range-less legacy tokens are resolved once,
            // then immediately saved as a fixed manual range so they never move with the calendar again.
            bool hasSavedRangeValue = persistedFrom.HasValue || persistedTo.HasValue;
            _dateFromLocal = hasSavedRangeValue ? persistedFrom : legacyFrom;
            _dateToLocal = hasSavedRangeValue ? persistedTo : legacyTo;
            _datePreset = DatePresetManualValue;
            _dateFilterMigrationPending = true;
        }
        else
        {
            _dateFromLocal = persistedFrom;
            _dateToLocal = persistedTo;
            _datePreset = _dateFromLocal.HasValue || _dateToLocal.HasValue
                ? DatePresetManualValue
                : DatePresetNoneValue;
        }

        SyncDateControls();
        UpdateDateFilterSummary();
    }

    private void SyncDateControls()
    {
        if (DateFromInput is null || DateToInput is null)
        {
            return;
        }

        _syncingDateControls = true;
        try
        {
            DateFromInput.SelectedDate = _dateFromLocal;
            DateToInput.SelectedDate = _dateToLocal;
        }
        finally
        {
            _syncingDateControls = false;
        }
    }

    private void UpdateDateFilterSummary()
    {
        if (DateFilterSummary is null)
            return;

        if (!_dateFromLocal.HasValue && !_dateToLocal.HasValue)
        {
            DateFilterSummary.Text = "No date filter";
            return;
        }

        DateFilterSummary.Text = $"Manual: {FormatStateDate(_dateFromLocal) ?? "..."} – {FormatStateDate(_dateToLocal) ?? "..."}";
    }

