    private void ToggleRight_Click(object sender, RoutedEventArgs e)
    {
        GridZoomAnchor? anchor = CaptureGridZoomAnchor();
        bool show = RightPanel.Visibility != Visibility.Visible;
        ApplyRightPanelState(show);
        ScheduleGridGeometryAnchorRestore(anchor);
        SaveState();
    }

    private void ApplyRightPanelState(bool open)
    {
        if (!open && !_adaptiveWorkbench && RightCol.ActualWidth >= MinRightPanelWidth)
            _rightPanelWidth = NormalizeRightPanelWidth(RightCol.ActualWidth);

        if (open)
            _rightPanelWidth = NormalizeRightPanelWidth(_rightPanelWidth);

        RightPanel.Visibility = open ? Visibility.Visible : Visibility.Collapsed;
        RightPanelSplitter.Visibility = open ? Visibility.Visible : Visibility.Collapsed;
        ApplyRightPanelPlacement(open);
        ToggleRight.Style = (Style)FindResource(open ? "IconButtonActive" : "IconButton");
        ToggleRight.ToolTip = open ? "Hide right panel" : "Show right panel";
    }

    private void ApplyRightPanelPlacement(bool open)
    {
        if (_adaptiveWorkbench)
        {
            Grid.SetRow(RightPanelSplitter, 1);
            Grid.SetColumn(RightPanelSplitter, 1);
            Grid.SetColumnSpan(RightPanelSplitter, 3);
            RightPanelSplitter.Width = double.NaN;
            RightPanelSplitter.Height = 6;
            RightPanelSplitter.HorizontalAlignment = HorizontalAlignment.Stretch;
            RightPanelSplitter.VerticalAlignment = VerticalAlignment.Stretch;
            RightPanelSplitter.ResizeDirection = GridResizeDirection.Rows;
            RightPanelSplitter.ResizeBehavior = GridResizeBehavior.PreviousAndNext;

            Grid.SetRow(RightPanel, 2);
            Grid.SetColumn(RightPanel, 1);
            Grid.SetColumnSpan(RightPanel, 3);
            RightPanel.BorderThickness = new Thickness(0, 1, 0, 0);
            WorkbenchPreviewSplitterRow.Height = open ? new GridLength(6) : new GridLength(0);
            WorkbenchPreviewRow.Height = open ? new GridLength(CurrentAdaptivePreviewHeight()) : new GridLength(0);
            RightSplitterCol.Width = new GridLength(0);
            RightCol.MinWidth = 0;
            RightCol.MaxWidth = MaxRightPanelWidth;
            RightCol.Width = new GridLength(0);
            PreviewImageCanvas.Height = CurrentAdaptivePreviewImageHeight();
            PreviewBitmap.Stretch = Stretch.Uniform;
            return;
        }

        Grid.SetRow(RightPanelSplitter, 0);
        Grid.SetColumn(RightPanelSplitter, 2);
        Grid.SetColumnSpan(RightPanelSplitter, 1);
        RightPanelSplitter.Width = 6;
        RightPanelSplitter.Height = double.NaN;
        RightPanelSplitter.HorizontalAlignment = HorizontalAlignment.Stretch;
        RightPanelSplitter.VerticalAlignment = VerticalAlignment.Stretch;
        RightPanelSplitter.ResizeDirection = GridResizeDirection.Columns;
        RightPanelSplitter.ResizeBehavior = GridResizeBehavior.PreviousAndNext;

        Grid.SetRow(RightPanel, 0);
        Grid.SetColumn(RightPanel, 3);
        Grid.SetColumnSpan(RightPanel, 1);
        RightPanel.BorderThickness = new Thickness(1, 0, 0, 0);
        WorkbenchPreviewSplitterRow.Height = new GridLength(0);
        WorkbenchPreviewRow.Height = new GridLength(0);
        RightSplitterCol.Width = open ? new GridLength(6) : new GridLength(0);
        RightCol.MinWidth = open ? MinRightPanelWidth : 0;
        RightCol.MaxWidth = MaxRightPanelWidth;
        RightCol.Width = open ? new GridLength(_rightPanelWidth) : new GridLength(0);
        PreviewImageCanvas.Height = 320;
        PreviewBitmap.Stretch = Stretch.UniformToFill;
    }

    private void ApplyAdaptiveWorkbenchLayout(double width, bool preserveGridAnchor = true)
    {
        ApplyModalToolbarLayout(width);
        bool adaptive = double.IsFinite(width) && width < AdaptiveWorkbenchThreshold;
        if (adaptive == _adaptiveWorkbench)
        {
            if (adaptive && RightPanel.Visibility == Visibility.Visible)
            {
                WorkbenchPreviewRow.Height = new GridLength(CurrentAdaptivePreviewHeight());
                PreviewImageCanvas.Height = CurrentAdaptivePreviewImageHeight();
            }
            return;
        }

        GridZoomAnchor? anchor = preserveGridAnchor ? CaptureGridZoomAnchor() : null;
        if (adaptive)
        {
            _sidebarVisibleBeforeAdaptive = Sidebar.Visibility == Visibility.Visible;
            _adaptiveWorkbench = true;
            Sidebar.Visibility = Visibility.Collapsed;
            NarrowSidebarRail.Visibility = Visibility.Visible;
            SidebarCol.Width = new GridLength(CompactSidebarRailWidth);
            SearchBoxContainer.MinWidth = 140;
            SearchBoxContainer.MaxWidth = 360;
            ViewerShortcutsButton.Visibility = Visibility.Collapsed;
            OpenAppSettingsButton.Visibility = Visibility.Collapsed;
        }
        else
        {
            _adaptiveWorkbench = false;
            NarrowSidebarRail.Visibility = Visibility.Collapsed;
            Sidebar.Visibility = _sidebarVisibleBeforeAdaptive ? Visibility.Visible : Visibility.Collapsed;
            SidebarCol.Width = _sidebarVisibleBeforeAdaptive ? new GridLength(WideSidebarWidth) : new GridLength(0);
            SearchBoxContainer.MinWidth = 240;
            SearchBoxContainer.MaxWidth = 480;
            ViewerShortcutsButton.Visibility = Visibility.Visible;
            OpenAppSettingsButton.Visibility = Visibility.Visible;
        }

        bool rightOpen = RightPanel.Visibility == Visibility.Visible;
        ApplyRightPanelPlacement(rightOpen);
        ToggleSidebar.Style = (Style)FindResource(Sidebar.Visibility == Visibility.Visible ? "IconButtonActive" : "IconButton");
        ToggleSidebar.ToolTip = Sidebar.Visibility == Visibility.Visible ? "Hide sidebar" : "Show sidebar";
        if (preserveGridAnchor)
            ScheduleGridGeometryAnchorRestore(anchor);
    }

    private void ApplyModalToolbarLayout(double width)
    {
        bool compact = double.IsFinite(width) && width < ModalCompactToolbarThreshold;
        Visibility optionalVisibility = compact ? Visibility.Collapsed : Visibility.Visible;
        ModalSourceLabel.Visibility = optionalVisibility;
        ModalFileSizeText.Visibility = optionalVisibility;
        ModalShortcutsButton.Visibility = optionalVisibility;
        ModalDeleteButton.Visibility = optionalVisibility;
        ModalOpenExternalButton.Visibility = optionalVisibility;
        ModalRevealButton.Visibility = optionalVisibility;
        ModalTitle.MaxWidth = compact ? 210 : 420;
        ModalEnhancementStatusText.MaxWidth = compact ? 88 : 240;
    }

    private double CurrentAdaptivePreviewHeight()
    {
        double availableHeight = ActualHeight;
        if (!double.IsFinite(availableHeight) || availableHeight <= 0)
            availableHeight = Height;
        if (!double.IsFinite(availableHeight) || availableHeight <= 0)
            availableHeight = MinHeight;
        return Math.Clamp(
            Math.Round(availableHeight * AdaptivePreviewHeightRatio),
            AdaptivePreviewMinHeight,
            AdaptivePreviewMaxHeight);
    }

    private double CurrentAdaptivePreviewImageHeight()
        => Math.Clamp(
            CurrentAdaptivePreviewHeight() - 124,
            72,
            112);

    private static double NormalizeRightPanelWidth(double width)
        => double.IsFinite(width) ? Math.Clamp(width, MinRightPanelWidth, MaxRightPanelWidth) : DefaultRightPanelWidth;

    private bool SetRightPanelWidth(double width)
    {
        double normalized = NormalizeRightPanelWidth(width);
        bool changed = Math.Abs(normalized - _rightPanelWidth) >= 0.5;
        _rightPanelWidth = normalized;
        if (!_adaptiveWorkbench && RightPanel.Visibility == Visibility.Visible)
            RightCol.Width = new GridLength(_rightPanelWidth);
        return changed;
    }

    private void RightPanelSplitter_DragCompleted(object sender, DragCompletedEventArgs e)
    {
        if (RightPanel.Visibility != Visibility.Visible)
            return;

        if (_adaptiveWorkbench)
        {
            ScheduleGridGeometryAnchorRestore(_rightPanelResizeAnchor);
            _rightPanelResizeAnchor = null;
            return;
        }

        SetRightPanelWidth(RightCol.ActualWidth);
        ScheduleGridGeometryAnchorRestore(_rightPanelResizeAnchor);
        _rightPanelResizeAnchor = null;
        SaveState();
    }

    private void RightPanelSplitter_DragStarted(object sender, DragStartedEventArgs e)
        => _rightPanelResizeAnchor = CaptureGridZoomAnchor();

    private void RightPanelSplitter_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (e.Key is not (Key.Left or Key.Right or Key.Up or Key.Down))
            return;

        GridZoomAnchor? anchor = CaptureGridZoomAnchor();
        Dispatcher.BeginInvoke(() =>
        {
            if (RightPanel.Visibility != Visibility.Visible)
                return;
            if (_adaptiveWorkbench)
                return;
            SetRightPanelWidth(RightCol.ActualWidth);
            ScheduleGridGeometryAnchorRestore(anchor);
            SaveState();
        }, DispatcherPriority.Render);
    }

    // ─────────── Display mode (Grid / List) ───────────
    private void ModeGrid_Checked(object sender, RoutedEventArgs e)
    {
        if (CardsList is null || RowsList is null) return;
        bool restoreGalleryFocus = Keyboard.FocusedElement is DependencyObject focused
            && IsDescendantOrSelf(focused, RowsList);
        Tile? selected = SelectedTile();
        CardsList.Visibility = Visibility.Visible;
        RowsList.Visibility = Visibility.Collapsed;
        ConfigureRowsItemsSource(forceGroupedView: false);
        if (selected is not null)
        {
            SynchronizeSelectionControls();
            CardsList.ScrollIntoView(selected);
            QueueGridSelectionVisualSync(selected);
            if (restoreGalleryFocus)
                QueuePrimaryGalleryFocus(selected, ResolvePrimarySelectionIndex(), grid: true);
        }
        else
            SynchronizeSelectionControls();
        SizeSlider.IsEnabled = true;
    }

    private void ModeList_Checked(object sender, RoutedEventArgs e)
    {
        if (CardsList is null || RowsList is null) return;
        bool restoreGalleryFocus = Keyboard.FocusedElement is DependencyObject focused
            && IsDescendantOrSelf(focused, CardsList);
        Tile? selected = SelectedTile();
        CardsList.Visibility = Visibility.Collapsed;
        RowsList.Visibility = Visibility.Visible;
        ConfigureRowsItemsSource(forceGroupedView: true);
        SynchronizeSelectionControls();
        if (selected is not null)
        {
            RowsList.ScrollIntoView(selected);
            SelectRealizedContainer(RowsList, selected);
            QueueListSelectionVisualSync(selected);
            if (restoreGalleryFocus)
                QueuePrimaryGalleryFocus(selected, ResolvePrimarySelectionIndex(), grid: false);
        }
        Dispatcher.BeginInvoke(ScheduleListThumbnailViewport, DispatcherPriority.Render);
        SizeSlider.IsEnabled = false;
    }

