    private void GalleryAutoScroll_PreviewMouseDown(object sender, MouseButtonEventArgs e)
    {
        if (sender is not ListBox surface)
            return;

        if (e.ChangedButton == MouseButton.Left && FindCardFavoriteButton(e.OriginalSource) is Button favoriteButton)
        {
            _pendingCardFavoriteButton = favoriteButton;
            _fileDragSession = null;
            e.Handled = true;
            return;
        }

        if (_galleryAutoScrollSurface is not null)
        {
            StopGalleryAutoScroll();
            e.Handled = true;
            return;
        }

        if (e.ChangedButton != MouseButton.Middle || !CanStartGalleryAutoScroll(surface))
            return;

        ScrollViewer? viewer = FindVisualDescendant<ScrollViewer>(surface);
        if (viewer is null)
            return;

        _fileDragSession = null;
        _galleryAutoScrollSurface = surface;
        _galleryAutoScrollViewer = viewer;
        _galleryAutoScrollAnchor = e.GetPosition(surface);
        _galleryAutoScrollPointer = _galleryAutoScrollAnchor;
        Mouse.Capture(surface, CaptureMode.SubTree);
        _galleryAutoScrollTimer.Start();
        surface.Cursor = Cursors.ScrollNS;
        e.Handled = true;
    }

    private bool CanStartGalleryAutoScroll(ListBox surface)
        => Modal.Visibility != Visibility.Visible
            && AppSettingsDialog.Visibility != Visibility.Visible
            && DeleteConfirmationDialog.Visibility != Visibility.Visible
            && Landing.Visibility != Visibility.Visible
            && (ReferenceEquals(surface, CardsList) || ReferenceEquals(surface, RowsList));

    private void GalleryAutoScroll_PreviewMouseUp(object sender, MouseButtonEventArgs e)
    {
        if (e.ChangedButton == MouseButton.Left && _pendingCardFavoriteButton is Button pending)
        {
            Button? released = FindCardFavoriteButton(e.OriginalSource);
            _pendingCardFavoriteButton = null;
            if (ReferenceEquals(released, pending))
                QueueCardFavoriteButtonActivation(pending);
            e.Handled = true;
            return;
        }
        // Browser-style auto-scroll remains active after the initiating middle
        // click; a subsequent click or Escape cancels it.
        if (_galleryAutoScrollSurface is not null && e.ChangedButton == MouseButton.Middle)
            e.Handled = true;
    }

    private void GalleryAutoScroll_LostMouseCapture(object sender, MouseEventArgs e)
    {
        if (_galleryAutoScrollSurface is not null && !ReferenceEquals(Mouse.Captured, _galleryAutoScrollSurface))
            StopGalleryAutoScroll(releaseCapture: false);
    }

    private bool UpdateGalleryAutoScrollPointer(FrameworkElement surface, MouseEventArgs e)
    {
        if (!ReferenceEquals(surface, _galleryAutoScrollSurface))
            return false;
        _galleryAutoScrollPointer = e.GetPosition(surface);
        e.Handled = true;
        return true;
    }

    private bool ApplyGalleryAutoScrollTick()
    {
        if (_galleryAutoScrollViewer is not ScrollViewer viewer || _galleryAutoScrollSurface is null)
            return false;

        double displacement = _galleryAutoScrollPointer.Y - _galleryAutoScrollAnchor.Y;
        const double deadZone = 12;
        if (Math.Abs(displacement) <= deadZone)
            return false;
        double speed = Math.Sign(displacement) * Math.Min(48, (Math.Abs(displacement) - deadZone) * 0.12);
        double before = viewer.VerticalOffset;
        double target = Math.Clamp(before + speed, 0, Math.Max(0, viewer.ExtentHeight - viewer.ViewportHeight));
        if (Math.Abs(target - before) <= 0.01)
            return false;
        viewer.ScrollToVerticalOffset(target);
        return true;
    }

    private void StopGalleryAutoScroll(bool releaseCapture = true)
    {
        ListBox? surface = _galleryAutoScrollSurface;
        _galleryAutoScrollTimer.Stop();
        _galleryAutoScrollSurface = null;
        _galleryAutoScrollViewer = null;
        if (surface is not null)
            surface.ClearValue(CursorProperty);
        if (releaseCapture && surface is not null && ReferenceEquals(Mouse.Captured, surface))
            Mouse.Capture(null);
    }

    private static Button? FindCardFavoriteButton(object? source)
    {
        for (DependencyObject? current = source as DependencyObject; current is not null; current = current is Visual or System.Windows.Media.Media3D.Visual3D
            ? VisualTreeHelper.GetParent(current)
            : LogicalTreeHelper.GetParent(current))
        {
            if (current is Button { CommandParameter: string action, Tag: Tile }
                && action is "increase" or "decrease")
                return (Button)current;
        }
        return null;
    }

    private void CardFavoriteButton_Click(object sender, RoutedEventArgs e)
    {
        if (FindCardFavoriteButton(e.OriginalSource) is not Button button)
            return;
        QueueCardFavoriteButtonActivation(button);
        e.Handled = true;
    }

    private void QueueCardFavoriteButtonActivation(Button button)
    {
        if (button.Tag is not Tile { IsRealFile: true } tile
            || button.CommandParameter is not string action
            || action is not ("increase" or "decrease"))
        {
            return;
        }

        int delta = action == "decrease" ? -1 : 1;
        // A favorites-only mutation can remove this card from the virtualized
        // ItemsSource. Do that after the current pointer/click route unwinds so
        // WPF never recycles the event's source container mid-route.
        Dispatcher.BeginInvoke(
            () => SetFavoriteLevel(tile, Math.Clamp(tile.Fav + delta, 0, 5)),
            DispatcherPriority.Input);
    }

    private bool ActivateCardFavoriteButton(Button button)
    {
        if (button.Tag is not Tile { IsRealFile: true } tile || button.CommandParameter is not string action)
            return false;
        int delta = action == "decrease" ? -1 : 1;
        return SetFavoriteLevel(tile, Math.Clamp(tile.Fav + delta, 0, 5));
    }

    private void FileDragSurface_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        if (sender is not FrameworkElement surface || e.ChangedButton != MouseButton.Left)
            return;

        Tile? origin = ResolveFileDragOrigin(surface, e.OriginalSource as DependencyObject);
        if (origin is null || !origin.IsRealFile)
        {
            _fileDragSession = null;
            return;
        }

        _fileDragSession = new FileDragSession(surface, origin, e.GetPosition(surface), _selectedPaths.Contains(origin.Path));
    }

    private void FileDragSurface_PreviewMouseMove(object sender, MouseEventArgs e)
    {
        if (sender is FrameworkElement autoScrollSurface && UpdateGalleryAutoScrollPointer(autoScrollSurface, e))
            return;
        if (sender is not FrameworkElement surface
            || _fileDragSession is not FileDragSession session
            || !ReferenceEquals(session.Surface, surface)
            || e.LeftButton != MouseButtonState.Pressed)
        {
            return;
        }

        Point current = e.GetPosition(surface);
        if (!ExceedsFileDragThreshold(session.Start, current))
            return;

        _fileDragSession = null;
        if (!TryBuildFileDropPayload(session.Origin, session.OriginWasSelected, out string[] paths, out string reason))
        {
            SetStatusToast($"Explorer drag was not started: {reason}.");
            return;
        }

        try
        {
            if (ReferenceEquals(surface, PreviewImageDragSurface))
                _suppressPreviewClickAfterFileDrag = true;
            var data = new DataObject(DataFormats.FileDrop, paths);
            DragDrop.DoDragDrop(surface, data, DragDropEffects.Copy);
        }
        catch (Exception ex)
        {
            SetStatusToast($"Explorer drag could not start: {ex.Message}");
        }
        finally
        {
            Dispatcher.BeginInvoke(() => _suppressPreviewClickAfterFileDrag = false, DispatcherPriority.Input);
        }
    }

    private void FileDragSurface_PreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
    {
        if (sender is FrameworkElement surface
            && _fileDragSession is FileDragSession session
            && ReferenceEquals(session.Surface, surface))
        {
            _fileDragSession = null;
        }
    }

    private Tile? ResolveFileDragOrigin(FrameworkElement surface, DependencyObject? originalSource)
    {
        if (ReferenceEquals(surface, PreviewImageDragSurface))
            return SelectedTile();

        for (DependencyObject? current = originalSource; current is not null; current = current is Visual or System.Windows.Media.Media3D.Visual3D
            ? VisualTreeHelper.GetParent(current)
            : LogicalTreeHelper.GetParent(current))
        {
            if (current is FrameworkElement { DataContext: Tile tile })
                return tile;
            if (ReferenceEquals(current, surface))
                break;
        }

        return null;
    }

    private static bool ExceedsFileDragThreshold(Point start, Point current)
        => Math.Abs(current.X - start.X) > SystemParameters.MinimumHorizontalDragDistance
            || Math.Abs(current.Y - start.Y) > SystemParameters.MinimumVerticalDragDistance;

    private bool TryBuildFileDropPayload(Tile origin, bool originWasSelected, out string[] paths, out string reason)
    {
        IReadOnlyList<Tile> candidates = originWasSelected
            ? _tiles.Where(tile => tile.IsRealFile && _selectedPaths.Contains(tile.Path)).ToList()
            : [origin];
        if (candidates.Count == 0)
        {
            paths = [];
            reason = "no real selected image";
            return false;
        }

        var canonicalPaths = new List<string>(candidates.Count);
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (Tile tile in candidates)
        {
            if (!TryValidateFileDropTile(tile, out string canonical, out reason))
            {
                paths = [];
                return false;
            }
            if (seen.Add(canonical))
                canonicalPaths.Add(canonical);
        }

        if (canonicalPaths.Count == 0)
        {
            paths = [];
            reason = "no valid source image";
            return false;
        }

        paths = canonicalPaths.ToArray();
        reason = "";
        return true;
    }

    private bool TryValidateFileDropTile(Tile tile, out string canonical, out string reason)
    {
        canonical = "";
        if (!tile.IsRealFile || string.IsNullOrWhiteSpace(tile.Path))
            return Fail("not a source image", out reason);
        if (!_allTiles.Contains(tile))
            return Fail("not in the current catalog", out reason);
        if (!Path.IsPathFullyQualified(tile.Path))
            return Fail("path is not absolute", out reason);
        if (!SupportedImageExtensions.Contains(Path.GetExtension(tile.Path)))
            return Fail("unsupported file type", out reason);
        if (!File.Exists(tile.Path))
            return Fail("source no longer exists", out reason);

        string lexical;
        try
        {
            lexical = Path.GetFullPath(tile.Path);
            canonical = _resolveFinalPath(lexical);
            if (!File.Exists(canonical))
                return Fail("canonical source no longer exists", out reason);
        }
        catch (Exception ex)
        {
            Trace.TraceWarning($"Explorer source canonicalization failed: {ex.GetType().Name}");
            return Fail("canonical path could not be resolved", out reason);
        }

        List<string> activeRoots = _currentFolderSet.Count > 0 ? _currentFolderSet : _currentFolder is null ? [] : [_currentFolder];
        if (activeRoots.Count == 0)
            return Fail("no active source root", out reason);
        foreach (string root in activeRoots)
        {
            try
            {
                string lexicalRoot = Path.GetFullPath(root);
                string canonicalRoot = _resolveFinalPath(lexicalRoot);
                if (IsPathInside(lexical, lexicalRoot) && IsPathInside(canonical, canonicalRoot))
                {
                    reason = "";
                    return true;
                }
            }
            catch
            {
                // A broken root cannot authorize an Explorer FileDrop payload.
            }
        }

        return Fail("source is outside the active root", out reason);
    }

    private void OpenModal()
    {
        _ = RefreshEnhancedStateIfChanged();
        if (SelectedTile() is not Tile t) return;
        UpdateModalPositionText(t);
        StopGalleryAutoScroll();
        bool opening = Modal.Visibility != Visibility.Visible;
        bool sourceChanged = !string.Equals(_modalSourceTilePath, t.Path, StringComparison.OrdinalIgnoreCase);
        if (opening)
            _modalFocusBeforeOverlay = Keyboard.FocusedElement;
        if (!string.Equals(_modalTransformPath, t.Path, StringComparison.OrdinalIgnoreCase))
            ResetModalTransform(t.Path);
        if (sourceChanged)
        {
            _modalSourceTilePath = t.Path;
            // Each navigation target is resolved independently. A currently valid,
            // owned succeeded output is the preferred asset for a newly selected image.
            InitializeModalEnhancementVersions(t);
        }
        var watch = Stopwatch.StartNew();
        _modalCts?.Cancel();
        _modalDecodeCompletion?.TrySetCanceled();
        var cts = new CancellationTokenSource();
        _modalCts = cts;
        var decodeCompletion = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
        _modalDecodeCompletion = decodeCompletion;

        bool requestedEnhanced = _modalShowingEnhanced || (sourceChanged && t.Enhanced);
        bool canShowEnhanced = TryGetModalEnhancedOutput(t, out _);
        if (!TryResolveDisplayedAsset(t, requestedEnhanced, out DisplayedAssetResolution displayedAsset, out string resolutionFailure))
        {
            _modalShowingEnhanced = false;
            SetStatusToast($"Preview unavailable: {resolutionFailure}.");
            displayedAsset = new DisplayedAssetResolution(t.Path, 0, false, null);
        }
        _modalShowingEnhanced = displayedAsset.Enhanced;
        if (requestedEnhanced && displayedAsset.FallbackReason is not null)
            SetStatusToast(displayedAsset.FallbackReason);
        string displayPath = displayedAsset.Path;
        _modalDisplayPath = displayPath;
        ModalFileSizeText.Text = FormatFileSizeMb(displayedAsset.SizeBytes);
        UpdateModalEnhancedControls(canShowEnhanced);

        var immediate = _modalShowingEnhanced ? null : PreviewBitmap.Source as BitmapSource ?? t.Thumbnail;
        ModalBitmap.Source = immediate;
        ModalBitmap.Visibility = immediate is null ? Visibility.Collapsed : Visibility.Visible;
        ModalArtBase.Visibility = immediate is null ? Visibility.Visible : Visibility.Collapsed;
        ModalArtGlow.Visibility = immediate is null ? Visibility.Visible : Visibility.Collapsed;
        ModalArtBase.Fill = t.ArtBase;
        ModalArtGlow.Fill = t.ArtGlow;
        if (opening)
            SetModalMetadataSidebarVisible(false);
        Modal.Visibility = Visibility.Visible;
        if (opening)
            Dispatcher.BeginInvoke(Modal.Focus, DispatcherPriority.Input);
        Modal.UpdateLayout();
        UpdateModalFit();
        ScheduleModalFitUpdate();
        if (opening)
        {
            _modalHasPointerPosition = false;
            _modalPressedEdgeTarget = ModalEdgeTarget.None;
            SetModalChromeVisible(true, showFeedback: false);
        }
        SyncModalFilmstripSelection(t);
        SyncModalMetadataSidebar();
        watch.Stop();

        if (LastLoadMetrics is not null)
        {
            LastLoadMetrics.ModalOpenMs = watch.ElapsedMilliseconds;
            LastLoadMetrics.ModalImmediateSource = immediate is not null;
            LastLoadMetrics.ModalDeferredDecode = t.IsRealFile;
        }

        if (t.IsRealFile && File.Exists(displayPath))
            _ = LoadModalBitmapAsync(displayPath, t.Path, cts.Token, decodeCompletion);
        else
            decodeCompletion.TrySetResult(immediate is not null);

        if (opening || sourceChanged)
            BeginModalEnhancementRefresh(t.Path);
    }

    private void UpdateModalPositionText(Tile tile)
    {
        int total = _tiles.Count;
        int index = total > 0 ? _tiles.IndexOf(tile) : -1;
        int position = index >= 0 ? index + 1 : 0;
        int digits = Math.Max(3, total.ToString(CultureInfo.InvariantCulture).Length);
        string positionText = position.ToString($"D{digits}", CultureInfo.InvariantCulture);
        string totalText = total.ToString($"D{digits}", CultureInfo.InvariantCulture);
        ModalPositionText.Text = $"{positionText} / {totalText}";
        AutomationProperties.SetName(
            ModalPositionText,
            total > 0 && position > 0
                ? $"Image {position} of {total}"
                : "No image position");
    }

    private bool TryGetModalEnhancedOutput(Tile tile, out string? outputPath)
    {
        outputPath = null;
        if (tile.IsRealFile
            && TryGetPreferredModalEnhancementVersion(
                tile,
                out ManagedEnhancementVersion selectedVersion))
        {
            outputPath = selectedVersion.Output.OutputPath;
            return true;
        }
        if (!tile.IsRealFile
            || !tile.Enhanced
            || string.IsNullOrWhiteSpace(tile.EnhancedOutputPath)
            || !TryGetManagedEnhancedOutputForPath(tile.Path, out ManagedEnhancedOutput stored)
            || !TryCreateManagedEnhancedOutput(tile, stored.OutputPath, stored.SourceSize, stored.SourceMtimeMs, out ManagedEnhancedOutput current)
            || !string.Equals(current.OutputPath, tile.EnhancedOutputPath, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        outputPath = current.OutputPath;
        return true;
    }

    private bool TryResolveDisplayedAsset(
        Tile tile,
        bool requestEnhanced,
        out DisplayedAssetResolution resolution,
        out string failureReason)
    {
        resolution = null!;
        if (!TryValidateFileDropTile(tile, out string canonicalSource, out failureReason))
            return false;

        var sourceInfo = new FileInfo(canonicalSource);
        if (requestEnhanced)
        {
            if (TryGetModalEnhancedOutput(tile, out string? outputPath) && outputPath is not null)
            {
                var outputInfo = new FileInfo(outputPath);
                resolution = new DisplayedAssetResolution(outputPath, outputInfo.Length, true, null);
                failureReason = "";
                return true;
            }

            resolution = new DisplayedAssetResolution(
                canonicalSource,
                sourceInfo.Length,
                false,
                "Displayed Enhanced output is unavailable; using Original instead.");
            failureReason = "";
            return true;
        }

        resolution = new DisplayedAssetResolution(canonicalSource, sourceInfo.Length, false, null);
        failureReason = "";
        return true;
    }

    private static string FormatFileSizeMb(long? sizeBytes)
        => sizeBytes is null or < 0
            ? "--"
            : $"{sizeBytes.Value / (1024d * 1024d):0.00}MB";

    private void UpdateModalEnhancedControls(bool canShowEnhanced)
    {
        string currentDisplay = CurrentModalEnhancementVersionLabel();
        if (ModalEnhancedToggleButton is not null)
        {
            ModalEnhancedToggleButton.IsEnabled = canShowEnhanced;
            ModalEnhancedToggleButton.ToolTip = canShowEnhanced
                ? _modalShowingEnhanced
                    ? "Show original (E). Ctrl+↑ / Ctrl+↓ cycles all versions."
                    : "Show newest AI output (E). Ctrl+↑ / Ctrl+↓ cycles all versions."
                : "No enhanced output available";
        }

        if (ModalEnhancedToggleLabel is not null)
            ModalEnhancedToggleLabel.Text = currentDisplay;
        if (ModalEnhancedToggleButton is not null)
        {
            AutomationProperties.SetName(
                ModalEnhancedToggleButton,
                $"Current display: {currentDisplay}. Toggle with E or cycle versions with Ctrl+Up and Ctrl+Down");
        }
        if (ModalSourceLabel is not null)
            ModalSourceLabel.Text = _modalShowingEnhanced ? $"{currentDisplay} output" : "Original";
    }

    private async Task LoadModalBitmapAsync(string displayPath, string selectedPath, CancellationToken token, TaskCompletionSource<bool> completion)
    {
        BitmapSource? bitmap;
        try
        {
            bitmap = await Task.Run(() =>
            {
                if (_modalDecodeDelayForSmokeMs > 0)
                    Thread.Sleep(_modalDecodeDelayForSmokeMs);
                return LoadBitmap(displayPath, 1400);
            }, token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetCanceled(token);
            return;
        }
        catch
        {
            completion.TrySetResult(false);
            return;
        }

        if (token.IsCancellationRequested)
        {
            completion.TrySetCanceled(token);
            return;
        }

        try
        {
            await Dispatcher.InvokeAsync(
                () =>
                {
                    if (token.IsCancellationRequested || Modal.Visibility != Visibility.Visible)
                    {
                        completion.TrySetResult(false);
                        return;
                    }
                    if (SelectedTile()?.Path != selectedPath)
                    {
                        completion.TrySetResult(false);
                        return;
                    }
                    if (!string.Equals(_modalDisplayPath, displayPath, StringComparison.OrdinalIgnoreCase))
                    {
                        completion.TrySetResult(false);
                        return;
                    }

                    if (bitmap is null)
                    {
                        // OpenModal intentionally shows an immediate preview or
                        // thumbnail while the full decode runs. If the source
                        // changed underneath that decode, clear the immediate
                        // bitmap so a stale image is never mistaken for success.
                        ModalBitmap.Source = null;
                        ModalBitmap.Visibility = Visibility.Collapsed;
                        ModalArtBase.Visibility = Visibility.Visible;
                        ModalArtGlow.Visibility = Visibility.Visible;
                        ReportCurrentImageDecodeFailure();
                        completion.TrySetResult(false);
                        return;
                    }

                    ModalBitmap.Source = bitmap;
                    ModalBitmap.Visibility = Visibility.Visible;
                    ModalArtBase.Visibility = Visibility.Collapsed;
                    ModalArtGlow.Visibility = Visibility.Collapsed;
                    completion.TrySetResult(true);
                },
                DispatcherPriority.Background,
                token);
        }
        catch (OperationCanceledException)
        {
            completion.TrySetCanceled(token);
        }
    }

