    private void ModalOneToOne_Click(object sender, RoutedEventArgs e)
    {
        if (_modalFitScale > 0)
            SetModalZoom(1 / _modalFitScale);
    }

    private bool ToggleModalFlip()
    {
        if (Modal.Visibility != Visibility.Visible)
            return false;

        _modalFlipped = !_modalFlipped;
        UpdateModalTransform();
        return true;
    }

    private bool AdjustModalZoom(double multiplier, Point? anchor = null)
    {
        if (Modal.Visibility != Visibility.Visible || multiplier <= 0)
            return false;

        return SetModalZoom(_modalZoom * multiplier, anchor);
    }

    private static double ModalWheelZoomMultiplier(int delta)
        => delta == 0 ? 1 : Math.Pow(ModalZoomWheelStep, delta / 120d);

    private bool SetModalZoom(double zoom, Point? anchor = null, bool animate = true)
    {
        double next = Math.Clamp(zoom, ModalZoomMin, ModalZoomMax);
        if (Math.Abs(next - _modalZoom) < 0.0001)
            return false;

        double previous = _modalZoom;
        if (anchor.HasValue && ModalImage.ActualWidth > 0 && ModalImage.ActualHeight > 0)
        {
            Point point = anchor.Value;
            double offsetX = point.X - (ModalImage.ActualWidth / 2);
            double offsetY = point.Y - (ModalImage.ActualHeight / 2);
            double previousScaleX = _modalFlipped ? -previous : previous;
            double nextScaleX = _modalFlipped ? -next : next;
            _modalPanX += offsetX * (previousScaleX - nextScaleX);
            _modalPanY += offsetY * (previous - next);
        }

        _modalZoom = next;
        ClampModalPan();
        BeginModalTransformInteraction();
        UpdateModalTransform(animate);
        return true;
    }

    private bool ResetModalTransform(string? path = null, bool showFeedback = false)
    {
        bool changed = Math.Abs(_modalZoom - 1) >= 0.0001
            || _modalFlipped
            || !string.Equals(_modalTransformPath, path, StringComparison.OrdinalIgnoreCase);
        CancelPendingModalPanRender();
        EndModalPan();
        _modalZoom = 1;
        _modalFlipped = false;
        _modalPanX = 0;
        _modalPanY = 0;
        _modalTransformPath = path;
        UpdateModalTransform(animate: showFeedback);
        return changed;
    }

    private bool SetModalPan(double x, double y)
    {
        if (Modal.Visibility != Visibility.Visible || _modalZoom <= 1)
            return false;

        (double maxX, double maxY) = ModalPanLimits();
        double nextX = Math.Clamp(x, -maxX, maxX);
        double nextY = Math.Clamp(y, -maxY, maxY);
        if (Math.Abs(nextX - _modalPanX) < 0.0001 && Math.Abs(nextY - _modalPanY) < 0.0001)
            return false;

        _modalPanX = nextX;
        _modalPanY = nextY;
        _modalPanInputUpdateCount++;
        if (_modalPointerState == ModalPointerState.Panning && !ReducedMotionEnabled)
        {
            ScheduleModalPanRender();
        }
        else
        {
            BeginModalTransformInteraction();
            ApplyModalPanVisual();
        }
        return true;
    }

    private void ScheduleModalPanRender()
    {
        if (_modalPanRenderQueued || Modal.Visibility != Visibility.Visible)
            return;

        _modalPanRenderQueued = true;
        long generation = _modalPanRenderGeneration;
        Dispatcher.BeginInvoke(() =>
        {
            if (!_modalPanRenderQueued || generation != _modalPanRenderGeneration)
                return;

            _modalPanRenderQueued = false;
            if (Modal.Visibility == Visibility.Visible)
                ApplyModalPanVisual();
        }, DispatcherPriority.Render);
    }

    private void ApplyModalPanVisual()
    {
        _modalPanVisualUpdateCount++;
        UpdateModalTransform();
    }

    private void FlushPendingModalPanRender()
    {
        bool apply = _modalPanRenderQueued && Modal.Visibility == Visibility.Visible;
        _modalPanRenderGeneration++;
        _modalPanRenderQueued = false;
        if (apply)
            ApplyModalPanVisual();
    }

    private void CancelPendingModalPanRender()
    {
        _modalPanRenderGeneration++;
        _modalPanRenderQueued = false;
    }

    private (double MaxX, double MaxY) ModalPanLimits()
    {
        double imageWidth = ModalImage?.ActualWidth > 0 ? ModalImage.ActualWidth : 440;
        double imageHeight = ModalImage?.ActualHeight > 0 ? ModalImage.ActualHeight : 640;
        double viewportWidth = ModalImageArea?.ActualWidth > 0 ? ModalImageArea.ActualWidth : imageWidth;
        double viewportHeight = ModalImageArea?.ActualHeight > 0 ? ModalImageArea.ActualHeight : imageHeight;
        return (
            Math.Max(0, ((imageWidth * _modalZoom) - viewportWidth) / 2),
            Math.Max(0, ((imageHeight * _modalZoom) - viewportHeight) / 2));
    }

    private void ClampModalPan()
    {
        if (_modalZoom <= 1)
        {
            _modalPanX = 0;
            _modalPanY = 0;
            return;
        }

        (double maxX, double maxY) = ModalPanLimits();
        _modalPanX = Math.Clamp(_modalPanX, -maxX, maxX);
        _modalPanY = Math.Clamp(_modalPanY, -maxY, maxY);
    }

    private void UpdateModalTransform(bool animate = false)
    {
        if (ModalVisualTransform is not null)
        {
            SetAnimatedTransformValue(
                ModalVisualTransform,
                ScaleTransform.ScaleXProperty,
                _modalFlipped ? -_modalZoom : _modalZoom,
                animate);
            SetAnimatedTransformValue(
                ModalVisualTransform,
                ScaleTransform.ScaleYProperty,
                _modalZoom,
                animate);
        }

        if (ModalPanTransform is not null)
        {
            SetAnimatedTransformValue(ModalPanTransform, TranslateTransform.XProperty, _modalPanX, animate);
            SetAnimatedTransformValue(ModalPanTransform, TranslateTransform.YProperty, _modalPanY, animate);
        }

        if (ModalZoomLabel is not null)
            ModalZoomLabel.Text = $"{Math.Round(_modalFitScale * _modalZoom * 100):0}%";
        if (ModalImageArea is not null)
            UpdateModalEdgeNavigationPresentation();
    }

    private void SetAnimatedTransformValue(
        Animatable target,
        DependencyProperty property,
        double value,
        bool animate)
    {
        double current = target.GetValue(property) is double existing ? existing : value;
        target.BeginAnimation(property, null);
        target.SetValue(property, value);
        if (!animate
            || ReducedMotionEnabled
            || !double.IsFinite(current)
            || Math.Abs(current - value) < 0.0001)
            return;

        var motion = new DoubleAnimation(current, value, TimeSpan.FromMilliseconds(ModalTransformAnimationMilliseconds))
        {
            EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut },
            FillBehavior = FillBehavior.Stop,
        };
        target.BeginAnimation(property, motion, HandoffBehavior.SnapshotAndReplace);
    }

    private void BeginModalTransformInteraction()
    {
        if (ReducedMotionEnabled)
        {
            _modalTransformQualityTimer.Stop();
            if (ModalBitmap is not null)
                RenderOptions.SetBitmapScalingMode(ModalBitmap, BitmapScalingMode.HighQuality);
            return;
        }

        if (ModalBitmap is not null)
            RenderOptions.SetBitmapScalingMode(ModalBitmap, BitmapScalingMode.Linear);
        _modalTransformQualityTimer.Stop();
        _modalTransformQualityTimer.Start();
    }

    private void EndModalTransformInteraction()
    {
        _modalTransformQualityTimer.Stop();
        if (ModalBitmap is not null)
            RenderOptions.SetBitmapScalingMode(ModalBitmap, BitmapScalingMode.HighQuality);
    }

    private void ScheduleModalFitUpdate()
    {
        if (_modalFitUpdateQueued || Modal.Visibility != Visibility.Visible)
            return;
        _modalFitUpdateQueued = true;
        Dispatcher.BeginInvoke(() =>
        {
            _modalFitUpdateQueued = false;
            UpdateModalFit();
        }, DispatcherPriority.Loaded);
    }

    private void UpdateModalFit()
    {
        if (Modal.Visibility != Visibility.Visible || SelectedTile() is not Tile tile)
            return;
        double sourceWidth = tile.ImagePixelWidth > 0 ? tile.ImagePixelWidth : ModalBitmap.Source?.Width ?? 440;
        double sourceHeight = tile.ImagePixelHeight > 0 ? tile.ImagePixelHeight : ModalBitmap.Source?.Height ?? 640;
        double oldEffectiveScale = _modalFitScale * _modalZoom;
        bool preserveUserZoom = Math.Abs(_modalZoom - 1) > 0.0001;
        double areaWidth = ModalImageArea.ActualWidth > 0 ? ModalImageArea.ActualWidth : Modal.ActualWidth;
        double areaHeight = ModalImageArea.ActualHeight > 0 ? ModalImageArea.ActualHeight : Modal.ActualHeight;
        double availableWidth = Math.Max(1, areaWidth);
        double availableHeight = Math.Max(1, areaHeight);
        _modalFitScale = Math.Min(availableWidth / sourceWidth, availableHeight / sourceHeight);
        ModalImage.Width = Math.Max(1, sourceWidth * _modalFitScale);
        ModalImage.Height = Math.Max(1, sourceHeight * _modalFitScale);
        ModalMetadataSidebar.MaxHeight = Math.Max(1, areaHeight - 24);
        if (preserveUserZoom)
            _modalZoom = Math.Clamp(oldEffectiveScale / _modalFitScale, ModalZoomMin, ModalZoomMax);
        ClampModalPan();
        UpdateModalTransform();
    }

    private void ModalImage_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        if (Modal.Visibility != Visibility.Visible)
            return;
        if (e.OriginalSource is DependencyObject target && IsModalChromeInteractionTarget(target))
            return;

        Point start = e.GetPosition(ModalImageArea);
        if (!IsPointInsideTransformedModalImage(start))
            return;

        CancelPendingModalSingleClick();
        if (e.ClickCount == 2 && ToggleModalMetadataSidebarFromImageDoubleClick())
        {
            EndModalPointerGesture();
            e.Handled = true;
            return;
        }

        BeginModalPointerInteraction();
        _modalPointerStartPoint = start;
        _modalPointerMoved = false;
        if (_modalZoom > 1)
        {
            _modalPanStartPoint = start;
            _modalPanStartOffset = new Vector(_modalPanX, _modalPanY);
        }
        Mouse.Capture(ModalImageArea, CaptureMode.SubTree);
        e.Handled = true;
    }

    private bool ToggleModalMetadataSidebarFromImageDoubleClick()
    {
        if (Modal.Visibility != Visibility.Visible)
            return false;

        SetModalMetadataSidebarVisible(ModalMetadataSidebar.Visibility != Visibility.Visible);
        return true;
    }

    private void ModalImage_MouseMove(object sender, MouseEventArgs e)
    {
        if (!_modalPointerStartPoint.HasValue || !ReferenceEquals(Mouse.Captured, ModalImageArea))
            return;

        Point current = e.GetPosition(ModalImageArea);
        Vector delta = current - _modalPointerStartPoint.Value;
        if (Math.Abs(delta.X) >= SystemParameters.MinimumHorizontalDragDistance
            || Math.Abs(delta.Y) >= SystemParameters.MinimumVerticalDragDistance)
        {
            _modalPointerMoved = true;
            if (_modalZoom > 1 && _modalPanStartPoint.HasValue)
                BeginModalPanning();
        }

        if (_modalPointerState == ModalPointerState.Panning
            && _modalZoom > 1
            && _modalPanStartPoint.HasValue)
        {
            Vector panDelta = current - _modalPanStartPoint.Value;
            SetModalPan(_modalPanStartOffset.X + panDelta.X, _modalPanStartOffset.Y + panDelta.Y);
        }
        e.Handled = true;
    }

    private void ModalImage_MouseLeftButtonUp(object sender, MouseButtonEventArgs e)
    {
        if (!_modalPointerStartPoint.HasValue || !ReferenceEquals(Mouse.Captured, ModalImageArea))
            return;

        Point end = e.GetPosition(ModalImageArea);
        Point? start = _modalPointerStartPoint;
        bool moved = _modalPointerMoved;
        EndModalPointerGesture();
        if (start.HasValue)
        {
            Vector delta = end - start.Value;
            if (!TryNavigateModalSwipe(delta) && !moved)
                ToggleModalChromeFromImage();
        }
        e.Handled = true;
    }

    private void ModalImage_LostMouseCapture(object sender, MouseEventArgs e) => EndModalPointerGesture();

    private void EndModalPan()
    {
        _modalPanStartPoint = null;
        if (ReferenceEquals(Mouse.Captured, ModalImageArea))
            ModalImageArea.ReleaseMouseCapture();
    }

    private void EndModalPointerGesture()
    {
        bool wasPanning = _modalPointerState == ModalPointerState.Panning;
        if (wasPanning)
            FlushPendingModalPanRender();
        _modalPointerStartPoint = null;
        _modalPointerMoved = false;
        EndModalPan();
        if (wasPanning)
        {
            _modalPointerState = ModalPointerState.Hidden;
            BeginModalTransformInteraction();
            UpdateModalChromePresentation();
        }
        else
        {
            EndModalPointerInteraction();
        }
    }

    private bool TryNavigateModalSwipe(Vector delta)
    {
        if (Modal.Visibility != Visibility.Visible || _modalZoom > 1)
            return false;

        double absoluteX = Math.Abs(delta.X);
        double absoluteY = Math.Abs(delta.Y);
        if (delta.Y > 0 && absoluteY > absoluteX)
        {
            double closeThreshold = Math.Clamp(ModalImage.ActualHeight * 0.16, 72, 180);
            if (absoluteY < closeThreshold)
                return false;
            CloseModal(restoreFocus: true);
            return true;
        }

        if (absoluteX <= absoluteY)
            return false;

        double threshold = Math.Clamp(ModalImage.ActualWidth * 0.16, 72, 180);
        if (absoluteX < threshold)
            return false;

        return NavigateModal(delta.X < 0 ? 1 : -1);
    }

    private void HideModalChromeFromImage()
    {
        if (Modal.Visibility != Visibility.Visible)
            return;

        CancelPendingModalSingleClick();
        SetModalChromeVisible(false, showFeedback: false);
    }

    private void ToggleModalChromeFromImage()
    {
        if (Modal.Visibility != Visibility.Visible)
            return;

        CancelPendingModalSingleClick();
        SetModalChromeVisible(!_modalManualChromeVisible, showFeedback: false);
    }

    private void CancelPendingModalSingleClick() => _modalSingleClickGeneration++;

    private void SetModalChromeVisible(bool visible, bool showFeedback)
    {
        _modalChromeTransientTimer.Stop();
        _modalManualChromeVisible = visible;
        _modalTransientChromeVisible = false;
        _modalFilmstripHoverVisible = false;
        _modalPointerState = visible ? ModalPointerState.Visible : ModalPointerState.Hidden;
        _modalPressedEdgeTarget = ModalEdgeTarget.None;
        _modalChromePointerPressActive = false;
        if (!visible)
        {
            _modalFeedbackTimer.Stop();
            ModalInteractionFeedback.Visibility = Visibility.Collapsed;
        }
        UpdateModalChromePresentation();
        if (showFeedback)
            ShowModalInteractionFeedback(visible ? "Controls shown" : "Controls hidden");
    }

    private bool ModalChromeEffectivelyVisible => _modalManualChromeVisible || _modalTransientChromeVisible;

    private void RevealModalChromeTransient()
    {
        if (Modal.Visibility != Visibility.Visible
            || _modalManualChromeVisible
            || _modalPointerState == ModalPointerState.Panning)
            return;

        if (!_modalTransientChromeVisible)
        {
            _modalTransientChromeVisible = true;
        }
        _modalPointerState = ModalPointerState.ArmedToHide;
        UpdateModalChromePresentation();
        _modalChromeTransientTimer.Stop();
        _modalChromeTransientTimer.Start();
    }

    private void ExpireModalChromeTransient()
    {
        _modalChromeTransientTimer.Stop();
        if (_modalPointerState is ModalPointerState.Interacting or ModalPointerState.Panning)
            return;
        if (!_modalTransientChromeVisible)
            return;
        _modalTransientChromeVisible = false;
        _modalFilmstripHoverVisible = false;
        _modalPointerState = _modalManualChromeVisible
            ? ModalPointerState.Visible
            : ModalPointerState.Hidden;
        UpdateModalChromePresentation();
    }

    private void BeginModalPointerInteraction()
    {
        if (Modal.Visibility != Visibility.Visible || _modalPointerState == ModalPointerState.Panning)
            return;

        _modalChromeTransientTimer.Stop();
        _modalPointerState = ModalPointerState.Interacting;
        UpdateModalEdgeNavigationPresentation();
    }

    private void EndModalPointerInteraction()
    {
        if (_modalPointerState != ModalPointerState.Interacting)
            return;

        if (_modalManualChromeVisible)
        {
            _modalPointerState = ModalPointerState.Visible;
            _modalChromeTransientTimer.Stop();
        }
        else if (_modalTransientChromeVisible)
        {
            _modalPointerState = ModalPointerState.ArmedToHide;
            _modalChromeTransientTimer.Stop();
            _modalChromeTransientTimer.Start();
        }
        else
        {
            _modalPointerState = ModalPointerState.Hidden;
        }
        UpdateModalChromePresentation();
    }

    private void BeginModalPanning()
    {
        if (Modal.Visibility != Visibility.Visible || _modalPointerState == ModalPointerState.Panning)
            return;

        _modalChromeTransientTimer.Stop();
        _modalManualChromeVisible = false;
        _modalTransientChromeVisible = false;
        _modalFilmstripHoverVisible = false;
        _modalPressedEdgeTarget = ModalEdgeTarget.None;
        _modalPointerState = ModalPointerState.Panning;
        _modalTransformQualityTimer.Stop();
        if (ModalBitmap is not null)
        {
            RenderOptions.SetBitmapScalingMode(
                ModalBitmap,
                ReducedMotionEnabled ? BitmapScalingMode.HighQuality : BitmapScalingMode.Linear);
        }
        UpdateModalChromePresentation();
    }

    private void Modal_PreviewMouseDown(object sender, MouseButtonEventArgs e)
    {
        if (Modal.Visibility != Visibility.Visible
            || e.ChangedButton != MouseButton.Left
            || e.OriginalSource is not DependencyObject source
            || !IsModalChromeInteractionTarget(source))
        {
            return;
        }

        _modalChromePointerPressActive = true;
        _modalPressedEdgeTarget = IsDescendantOrSelf(source, ModalPreviousButton)
            ? ModalEdgeTarget.Previous
            : IsDescendantOrSelf(source, ModalNextButton)
                ? ModalEdgeTarget.Next
                : ModalEdgeTarget.None;
        BeginModalPointerInteraction();
    }

    private void Modal_PreviewMouseUp(object sender, MouseButtonEventArgs e)
    {
        if (e.ChangedButton != MouseButton.Left || !_modalChromePointerPressActive)
            return;

        _modalChromePointerPressActive = false;
        Dispatcher.BeginInvoke(() =>
        {
            _modalPressedEdgeTarget = ModalEdgeTarget.None;
            if (Modal.Visibility != Visibility.Visible || _modalPointerState == ModalPointerState.Panning)
                return;

            if (Mouse.DirectlyOver is DependencyObject target
                && (IsModalChromeInteractionTarget(target) || IsModalChromeCaptureActive()))
            {
                BeginModalPointerInteraction();
            }
            else
            {
                EndModalPointerInteraction();
            }
            UpdateModalEdgeNavigationPresentation();
        }, DispatcherPriority.Input);
    }

    private void Modal_PreviewMouseMove(object sender, MouseEventArgs e)
    {
        if (Modal.Visibility != Visibility.Visible)
            return;

        Point position = e.GetPosition(ModalImageArea);
        _modalHasPointerPosition = double.IsFinite(position.X) && double.IsFinite(position.Y);
        if (_modalHasPointerPosition)
            _modalLastPointerPosition = position;

        if (_modalPointerState == ModalPointerState.Panning)
        {
            SetModalFilmstripHoverVisible(false);
            UpdateModalEdgeNavigationPresentation();
            return;
        }

        if (_modalPointerStartPoint.HasValue)
        {
            BeginModalPointerInteraction();
            SetModalFilmstripHoverVisible(false);
            return;
        }

        bool overChrome = e.OriginalSource is DependencyObject target
            && IsModalChromeInteractionTarget(target);
        if (!overChrome)
            overChrome = IsModalChromeCaptureActive();

        if (!_modalManualChromeVisible && !_modalTransientChromeVisible)
            RevealModalChromeTransient();
        else if (!_modalManualChromeVisible && _modalTransientChromeVisible && !overChrome)
            RevealModalChromeTransient();

        if (overChrome)
            BeginModalPointerInteraction();
        else if (_modalPointerState == ModalPointerState.Interacting)
            EndModalPointerInteraction();
        else if (_modalManualChromeVisible)
            _modalPointerState = ModalPointerState.Visible;

        Point modalPosition = e.GetPosition(Modal);
        SetModalFilmstripHoverVisible(
            modalPosition.Y >= Math.Max(0, Modal.ActualHeight - ModalFilmstripHoverZone)
            && modalPosition.Y <= Modal.ActualHeight);
        UpdateModalEdgeNavigationPresentation();
    }

    private void Modal_MouseLeave(object sender, MouseEventArgs e)
    {
        _modalHasPointerPosition = false;
        SetModalFilmstripHoverVisible(false);
        if (!_modalChromePointerPressActive
            && !_modalPointerStartPoint.HasValue
            && !IsModalChromeCaptureActive())
        {
            EndModalPointerInteraction();
        }
        UpdateModalEdgeNavigationPresentation();
    }

    private void SetModalFilmstripHoverVisible(bool visible)
    {
        if (_modalPointerState == ModalPointerState.Panning)
            visible = false;
        if (_modalFilmstripHoverVisible == visible)
            return;
        _modalFilmstripHoverVisible = visible;
        UpdateModalChromePresentation();
    }

    private void ToggleModalFilmstrip_Click(object sender, RoutedEventArgs e) => ToggleModalFilmstrip();

    private bool ToggleModalFilmstrip()
        => SetModalFilmstripOpen(!_modalFilmstripOpen);

    private bool SetModalFilmstripOpen(bool open, bool persist = true)
    {
        if (Modal.Visibility != Visibility.Visible)
            return false;

        bool changed = _modalFilmstripOpen != open;
        _modalFilmstripOpen = open;
        _modalFilmstripHoverVisible = false;
        UpdateModalChromePresentation();
        if (open && SelectedTile() is Tile selected)
            SyncModalFilmstripSelection(selected);
        if (changed && persist)
            SaveState();
        return changed;
    }

    private void ModalFilmstrip_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (_syncingModalFilmstripSelection || sender is not ListBox list || list.SelectedItem is not Tile tile)
            return;
        if (ReferenceEquals(tile, SelectedTile()))
            return;

        _syncingModalFilmstripSelection = true;
        try
        {
            ModalFilmstripOverlayList.SelectedItem = tile;
        }
        finally
        {
            _syncingModalFilmstripSelection = false;
        }
        SelectTile(tile);
        SaveState();
        OpenModal();
    }

    private void SyncModalFilmstripSelection(Tile tile)
    {
        _syncingModalFilmstripSelection = true;
        try
        {
            RefreshModalFilmstripWindow(tile);
            ModalFilmstripOverlayList.SelectedItem = tile;
            if (ModalFilmstripOverlay.Visibility == Visibility.Visible)
                ModalFilmstripOverlayList.ScrollIntoView(tile);
        }
        finally
        {
            _syncingModalFilmstripSelection = false;
        }
    }

    private void RefreshModalFilmstripWindow(Tile selected)
    {
        int selectedIndex = _tiles.IndexOf(selected);
        if (selectedIndex < 0)
        {
            _modalFilmstripTiles.ReplaceAll(Array.Empty<Tile>());
            return;
        }

        int count = Math.Min(MaxModalFilmstripWindowItems, _tiles.Count);
        int start = Math.Clamp(
            selectedIndex - (count / 2),
            0,
            Math.Max(0, _tiles.Count - count));

        bool unchanged = _modalFilmstripTiles.Count == count;
        for (int index = 0; unchanged && index < count; index++)
            unchanged = ReferenceEquals(_modalFilmstripTiles[index], _tiles[start + index]);
        if (unchanged)
            return;

        var window = new Tile[count];
        for (int index = 0; index < count; index++)
            window[index] = _tiles[start + index];
        _modalFilmstripTiles.ReplaceAll(window, count);
    }

    private void UpdateModalFilmstripPresentation()
    {
        bool overlayVisible = _modalFilmstripOpen
            && (_modalManualChromeVisible || _modalFilmstripHoverVisible)
            && _modalPointerState != ModalPointerState.Panning;
        SetModalChromeElementVisibility(ModalFilmstripOverlay, overlayVisible, animateReveal: true);
        ModalFilmstripToggleButton.ToolTip = $"{(_modalFilmstripOpen ? "Hide" : "Show")} image filmstrip ({BindingText(ViewerKeyAction.ToggleModalFilmstrip)})";
        AutomationProperties.SetName(ModalFilmstripToggleButton, $"{(_modalFilmstripOpen ? "Hide" : "Show")} image filmstrip");
    }

    private bool IsModalChromeCaptureActive()
        => Mouse.Captured is DependencyObject captured
            && IsModalChromeInteractionTarget(captured);

    private bool IsModalChromeInteractionTarget(DependencyObject? target)
    {
        if (target is null)
            return false;

        return IsDescendantOrSelf(target, ModalWindowCaptionControls)
            || IsDescendantOrSelf(target, ModalTopBarSurface)
            || IsDescendantOrSelf(target, ModalTopBar)
            || IsDescendantOrSelf(target, ModalMetadataSidebar)
            || IsDescendantOrSelf(target, ModalFooter)
            || IsDescendantOrSelf(target, ModalFilmstripOverlay)
            || IsDescendantOrSelf(target, ModalPreviousButton)
            || IsDescendantOrSelf(target, ModalNextButton);
    }

    private bool TryGetTransformedModalImageRectangle(out Rect imageRectangle)
    {
        imageRectangle = Rect.Empty;
        if (ModalImageArea.ActualWidth <= 0
            || ModalImageArea.ActualHeight <= 0
            || ModalImage.ActualWidth <= 0
            || ModalImage.ActualHeight <= 0
            || ModalVisual.RenderSize.Width <= 0
            || ModalVisual.RenderSize.Height <= 0)
        {
            return false;
        }

        try
        {
            imageRectangle = ModalVisual
                .TransformToAncestor(ModalImageArea)
                .TransformBounds(new Rect(new Point(0, 0), ModalVisual.RenderSize));
            imageRectangle.Intersect(new Rect(0, 0, ModalImageArea.ActualWidth, ModalImageArea.ActualHeight));
            return !imageRectangle.IsEmpty
                && imageRectangle.Width > 0
                && imageRectangle.Height > 0;
        }
        catch (InvalidOperationException)
        {
            imageRectangle = Rect.Empty;
            return false;
        }
        catch (ArgumentException)
        {
            imageRectangle = Rect.Empty;
            return false;
        }
    }

    private bool IsPointInsideTransformedModalImage(Point point)
        => TryGetTransformedModalImageRectangle(out Rect imageRectangle)
            && imageRectangle.Contains(point);

    private ModalEdgeTarget ResolveModalEdgeTarget(Point point)
    {
        if (_modalPointerState == ModalPointerState.Panning
            || _modalEdgeNavigationPercent <= 0
            || ModalImageArea.ActualWidth <= 0
            || !TryGetTransformedModalImageRectangle(out Rect imageRectangle)
            || !imageRectangle.Contains(point))
        {
            return ModalEdgeTarget.None;
        }

        double edgeWidth = ModalImageArea.ActualWidth * (_modalEdgeNavigationPercent / 100d);
        if (point.X <= edgeWidth)
            return ModalEdgeTarget.Previous;
        if (point.X >= ModalImageArea.ActualWidth - edgeWidth)
            return ModalEdgeTarget.Next;
        return ModalEdgeTarget.None;
    }

    private bool TryFindModalBlackCanvasPoint(out Point point)
    {
        point = default;
        if (!TryGetTransformedModalImageRectangle(out Rect imageRectangle))
            return false;

        double width = ModalImageArea.ActualWidth;
        double height = ModalImageArea.ActualHeight;
        Point[] candidates =
        [
            new Point(1, height / 2),
            new Point(Math.Max(1, width - 1), height / 2),
            new Point(width / 2, 1),
            new Point(width / 2, Math.Max(1, height - 1)),
        ];
        foreach (Point candidate in candidates)
        {
            if (candidate.X >= 0
                && candidate.X <= width
                && candidate.Y >= 0
                && candidate.Y <= height
                && !imageRectangle.Contains(candidate))
            {
                point = candidate;
                return true;
            }
        }
        return false;
    }

    private void UpdateModalEdgeNavigationPresentation()
    {
        bool chromeVisible = ModalChromeEffectivelyVisible
            && _modalPointerState != ModalPointerState.Panning;
        bool hasImageRectangle = TryGetTransformedModalImageRectangle(out Rect imageRectangle);
        ModalEdgeTarget target = _modalPressedEdgeTarget != ModalEdgeTarget.None
            ? _modalPressedEdgeTarget
            : _modalHasPointerPosition
                ? ResolveModalEdgeTarget(_modalLastPointerPosition)
                : ModalEdgeTarget.None;

        SetModalEdgeButtonPresentation(
            ModalPreviousButton,
            chromeVisible,
            target == ModalEdgeTarget.Previous,
            hasImageRectangle ? imageRectangle : null);
        SetModalEdgeButtonPresentation(
            ModalNextButton,
            chromeVisible,
            target == ModalEdgeTarget.Next,
            hasImageRectangle ? imageRectangle : null);
    }

    private void SetModalEdgeButtonPresentation(
        Button button,
        bool chromeVisible,
        bool active,
        Rect? imageRectangle)
    {
        const double activeOpacity = 0.55;
        bool wasActive = button.Visibility == Visibility.Visible && button.IsHitTestVisible;
        if (!chromeVisible)
        {
            button.BeginAnimation(OpacityProperty, null);
            button.Opacity = 0;
            button.IsHitTestVisible = false;
            KeyboardNavigation.SetIsTabStop(button, false);
            button.Visibility = Visibility.Collapsed;
            return;
        }

        button.Visibility = Visibility.Visible;
        if (imageRectangle is Rect image)
        {
            button.VerticalAlignment = VerticalAlignment.Top;
            button.Height = Math.Max(1, image.Height);
            button.Margin = new Thickness(0, Math.Max(0, image.Top), 0, 0);
        }
        else
        {
            button.VerticalAlignment = VerticalAlignment.Stretch;
            button.Height = double.NaN;
            button.Margin = new Thickness(0);
            active = false;
        }

        button.IsHitTestVisible = active;
        KeyboardNavigation.SetIsTabStop(button, active);
        if (!active)
        {
            if (wasActive || button.Opacity > 0)
            {
                button.BeginAnimation(OpacityProperty, null);
                button.Opacity = 0;
            }
            return;
        }

        if (!wasActive)
        {
            button.BeginAnimation(OpacityProperty, null);
            button.Opacity = activeOpacity;
            if (!ReducedMotionEnabled)
            {
                button.BeginAnimation(
                    OpacityProperty,
                    new DoubleAnimation(0, activeOpacity, TimeSpan.FromMilliseconds(ModalChromeRevealAnimationMilliseconds))
                    {
                        EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut },
                        FillBehavior = FillBehavior.Stop,
                    },
                    HandoffBehavior.SnapshotAndReplace);
            }
        }
        else if (!button.HasAnimatedProperties)
        {
            button.Opacity = activeOpacity;
        }
    }

    private void UpdateModalChromePresentation()
    {
        bool visible = ModalChromeEffectivelyVisible;
        bool animateReveal = visible && !_modalManualChromeVisible && _modalTransientChromeVisible;
        SetModalChromeElementVisibility(ModalTopBarSurface, visible, animateReveal);
        SetModalChromeElementVisibility(ModalTopBar, visible, animateReveal);
        SetModalChromeElementVisibility(ModalFooter, visible, animateReveal);
        SetModalChromeElementVisibility(ModalZoomIndicator, visible, animateReveal);
        UpdateModalEdgeNavigationPresentation();
        UpdateModalFilmstripPresentation();

        bool cursorHidden = !ModalChromeEffectivelyVisible && ModalFilmstripOverlay.Visibility != Visibility.Visible;
        Modal.Cursor = cursorHidden ? Cursors.None : Cursors.Arrow;
        Modal.ForceCursor = cursorHidden;
    }

    private void SetModalChromeElementVisibility(
        UIElement element,
        bool visible,
        bool animateReveal)
    {
        if (!visible)
        {
            element.BeginAnimation(OpacityProperty, null);
            element.Opacity = 1;
            element.Visibility = Visibility.Collapsed;
            return;
        }

        bool wasVisible = element.Visibility == Visibility.Visible;
        element.Visibility = Visibility.Visible;
        if (!animateReveal || wasVisible || ReducedMotionEnabled)
        {
            if (!wasVisible)
            {
                element.BeginAnimation(OpacityProperty, null);
                element.Opacity = 1;
            }
            return;
        }

        element.Opacity = 1;
        element.BeginAnimation(
            OpacityProperty,
            new DoubleAnimation(0.2, 1, TimeSpan.FromMilliseconds(ModalChromeRevealAnimationMilliseconds))
            {
                EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut },
                FillBehavior = FillBehavior.Stop,
            },
            HandoffBehavior.SnapshotAndReplace);
    }

    private void ShowModalInteractionFeedback(string message)
    {
        if (Modal.Visibility != Visibility.Visible || string.IsNullOrWhiteSpace(message))
            return;

        ModalInteractionFeedbackText.Text = message;
        ModalInteractionFeedback.Visibility = Visibility.Visible;
        _modalFeedbackTimer.Stop();
        _modalFeedbackTimer.Start();
    }

    private void ShowModalFavoriteIncreaseEffect(Tile tile, int previousLevel, int currentLevel)
    {
        if (Modal.Visibility != Visibility.Visible
            || currentLevel <= previousLevel
            || ModalChromeEffectivelyVisible
            || !string.Equals(_modalSourceTilePath, tile.Path, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        ModalFavoritePulse.BeginAnimation(OpacityProperty, null);
        ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleXProperty, null);
        ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleYProperty, null);
        ModalFavoritePulse.Opacity = 1;
        ModalFavoritePulseScale.ScaleX = 1;
        ModalFavoritePulseScale.ScaleY = 1;
        ModalFavoritePulseLevelText.Text = currentLevel.ToString(CultureInfo.InvariantCulture);
        AutomationProperties.SetName(ModalFavoritePulse, $"Favorite level increased to {currentLevel}");
        ModalFavoritePulse.Visibility = Visibility.Visible;

        if (!ReducedMotionEnabled)
        {
            var scale = new DoubleAnimationUsingKeyFrames
            {
                FillBehavior = FillBehavior.Stop,
            };
            scale.KeyFrames.Add(new LinearDoubleKeyFrame(0.72, KeyTime.FromTimeSpan(TimeSpan.Zero)));
            scale.KeyFrames.Add(new EasingDoubleKeyFrame(
                1.12,
                KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(150)),
                new QuadraticEase { EasingMode = EasingMode.EaseOut }));
            scale.KeyFrames.Add(new EasingDoubleKeyFrame(
                1,
                KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(280)),
                new QuadraticEase { EasingMode = EasingMode.EaseInOut }));
            ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleXProperty, scale);
            ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleYProperty, scale);

            ModalFavoritePulse.BeginAnimation(
                OpacityProperty,
                new DoubleAnimation(1, 0, TimeSpan.FromMilliseconds(270))
                {
                    BeginTime = TimeSpan.FromMilliseconds(350),
                    FillBehavior = FillBehavior.Stop,
                });
        }

        _modalFavoritePulseTimer.Stop();
        _modalFavoritePulseTimer.Start();
    }

    private void HideModalFavoritePulse()
    {
        _modalFavoritePulseTimer.Stop();
        if (ModalFavoritePulse is null)
            return;

        ModalFavoritePulse.BeginAnimation(OpacityProperty, null);
        ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleXProperty, null);
        ModalFavoritePulseScale.BeginAnimation(ScaleTransform.ScaleYProperty, null);
        ModalFavoritePulse.Opacity = 1;
        ModalFavoritePulseScale.ScaleX = 1;
        ModalFavoritePulseScale.ScaleY = 1;
        ModalFavoritePulse.Visibility = Visibility.Collapsed;
    }

    private void ModalPrevious_Click(object sender, RoutedEventArgs e)
    {
        NavigateModal(-1);
    }

    private void ModalNext_Click(object sender, RoutedEventArgs e)
    {
        NavigateModal(1);
    }

    private bool NavigateModal(int delta)
    {
        if (delta == 0 || _tiles.Count == 0)
            return false;

        var selected = SelectedTile();
        int currentIndex = selected is null ? -1 : _tiles.IndexOf(selected);
        int nextIndex;
        if (currentIndex < 0)
        {
            nextIndex = delta > 0 ? 0 : _tiles.Count - 1;
        }
        else
        {
            nextIndex = ((currentIndex + delta) % _tiles.Count + _tiles.Count) % _tiles.Count;
        }
        if (nextIndex == currentIndex)
            return false;

        SelectTile(_tiles[nextIndex]);
        SaveState();

        if (Modal.Visibility == Visibility.Visible)
        {
            bool chromeWasVisible = ModalChromeEffectivelyVisible;
            OpenModal();
            if (chromeWasVisible)
                ShowModalInteractionFeedback(delta > 0 ? "Next image" : "Previous image");
        }

        return true;
    }

    /// <summary>Used only by the --shot --modal smoke path to capture the modal state.</summary>
    public void ShowModalForShot()
    {
        if (CardsList.SelectedItem is null && CardsList.Items.Count > 0)
            CardsList.SelectedIndex = 0;
        OpenModal();
    }

    private Tile? SelectedTile()
    {
        // _selectedPaths is the canonical selection. A hidden Grid/List surface
        // may deliberately retain a bounded visual SelectedItem until that
        // surface becomes visible again; never let that stale projection revive
        // a cleared selection for Favorite or Recycle actions.
        if (_selectedPaths.Count == 0)
            return null;

        if (_primarySelectedTile is { } cachedPrimary
            && !string.IsNullOrWhiteSpace(_primarySelectedPath)
            && string.Equals(
                cachedPrimary.Path,
                _primarySelectedPath,
                StringComparison.OrdinalIgnoreCase)
            && _selectedPaths.Contains(cachedPrimary.Path))
        {
            if (_primarySelectedIndex < 0
                || _primarySelectedIndex >= _tiles.Count
                || !ReferenceEquals(_tiles[_primarySelectedIndex], cachedPrimary))
            {
                _primarySelectedIndex = _tiles.IndexOf(cachedPrimary);
            }
            return cachedPrimary;
        }

        if (!string.IsNullOrWhiteSpace(_primarySelectedPath))
        {
            var primary = _tiles.FirstOrDefault(tile => string.Equals(tile.Path, _primarySelectedPath, StringComparison.OrdinalIgnoreCase));
            if (primary is not null && _selectedPaths.Contains(primary.Path))
            {
                _primarySelectedTile = primary;
                _primarySelectedIndex = _tiles.IndexOf(primary);
                return primary;
            }
        }

        Tile? projected = CardsList.SelectedItem as Tile ?? RowsList.SelectedItem as Tile;
        if (projected is not null && _selectedPaths.Contains(projected.Path))
        {
            Tile? current = _tiles.FirstOrDefault(tile =>
                string.Equals(tile.Path, projected.Path, StringComparison.OrdinalIgnoreCase));
            if (current is not null)
            {
                _primarySelectedTile = current;
                _primarySelectedPath = current.Path;
                _primarySelectedIndex = _tiles.IndexOf(current);
            }
            return current;
        }

        Tile? fallback = _tiles.FirstOrDefault(tile => _selectedPaths.Contains(tile.Path));
        if (fallback is not null)
        {
            _primarySelectedTile = fallback;
            _primarySelectedPath = fallback.Path;
            _primarySelectedIndex = _tiles.IndexOf(fallback);
        }
        else
            _primarySelectedIndex = -1;
        return fallback;
    }

    private void OpenSelectedExternally_Click(object sender, RoutedEventArgs e)
        => TryOpenSelectedExternally();

    private bool TryOpenSelectedExternally()
    {
        Tile? tile = SelectedTile();
        string reason = "select a source image";
        bool requestEnhanced = tile is not null
            && Modal.Visibility == Visibility.Visible
            && _modalShowingEnhanced
            && string.Equals(_modalSourceTilePath, tile.Path, StringComparison.OrdinalIgnoreCase);
        if (tile is null || !TryResolveDisplayedAsset(tile, requestEnhanced, out DisplayedAssetResolution displayedAsset, out reason))
        {
            SetStatusToast($"Open externally unavailable: {reason}.");
            return false;
        }

        if (displayedAsset.FallbackReason is not null && Modal.Visibility == Visibility.Visible)
        {
            _modalShowingEnhanced = false;
            OpenModal();
        }

        try
        {
            var startInfo = new ProcessStartInfo(displayedAsset.Path) { UseShellExecute = true };
            if (!_externalFileLauncher(startInfo))
            {
                ReportExternalOpenFailure();
                return false;
            }

            SetStatusToast(displayedAsset.FallbackReason is not null
                ? $"{displayedAsset.FallbackReason} Opened Original externally."
                : displayedAsset.Enhanced
                    ? "Opened the displayed Enhanced image externally."
                    : "Opened the displayed Original image externally.");
            return true;
        }
        catch (Exception ex) when (ex is Win32Exception
            or IOException
            or UnauthorizedAccessException
            or InvalidOperationException
            or ArgumentException
            or NotSupportedException
            or System.Security.SecurityException)
        {
            Trace.TraceWarning($"External image open failed: {ex.GetType().Name}");
            ReportExternalOpenFailure();
            return false;
        }
    }

    private void ReportExternalOpenFailure()
        => SetStatusToast(
            "Open externally could not start the selected image. Check the default app and try again.",
            () => { TryOpenSelectedExternally(); });

    private void ShowSelectedInFolder_Click(object sender, RoutedEventArgs e)
        => ShowSelectedInFolder();

    private bool ShowSelectedInFolder()
    {
        string reason = "select a source image";
        if (SelectedTile() is not Tile tile || !TryValidateFileDropTile(tile, out string canonical, out reason))
        {
            SetStatusToast($"Show in folder unavailable: {reason}.");
            return false;
        }
        try
        {
            var startInfo = new ProcessStartInfo("explorer.exe") { UseShellExecute = true };
            startInfo.ArgumentList.Add($"/select,{canonical}");
            if (!_explorerLauncher(startInfo))
            {
                SetStatusToast("Show in folder could not start Explorer. Try again.");
                return false;
            }
            SetStatusToast("Opened Explorer with the selected source.");
            return true;
        }
        catch (Exception ex)
        {
            Trace.TraceWarning($"Show in folder failed: {ex.GetType().Name}");
            SetStatusToast("Show in folder could not start Explorer. Try again.");
            return false;
        }
    }

