    private string BindingText(ViewerKeyAction action)
        => _keyBindings.TryGetValue(action, out KeyChord chord)
            ? chord.DisplayText
            : KeyBindingSettings.Definition(action).DefaultChord.DisplayText;

    private static string ThumbnailStatusBorderSettingsPath
    {
        get
        {
            string? overridePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH");
            return string.IsNullOrWhiteSpace(overridePath)
                ? ProjectCachePath("settings.json")
                : Path.GetFullPath(overridePath);
        }
    }

    private void LoadThumbnailStatusBorderSettings()
    {
        ThumbnailStatusBorderLoadResult loaded;
        try
        {
            loaded = ThumbnailStatusBorderSettingsStore.Read(ThumbnailStatusBorderSettingsPath);
        }
        catch (Exception ex)
        {
            loaded = new ThumbnailStatusBorderLoadResult(
                ThumbnailStatusBorderSettings.Default,
                true,
                $"Shared settings path is unavailable: {ex.Message}");
        }

        _thumbnailStatusBorderSettings = loaded.Settings;
        _draftThumbnailStatusBorderSettings = loaded.Settings;
        _thumbnailStatusBorderSettingsProtected = loaded.IsProtected;
        _thumbnailStatusBorderSettingsError = loaded.Error;
        _sharedKeyBindingsProtected = loaded.IsProtected;
        _sharedKeyBindingsError = loaded.Error;
        if (!loaded.IsProtected)
        {
            if (KeyBindingSettings.TryApplyBrowserSharedBindings(
                    _keyBindings,
                    loaded.BrowserKeyBindings,
                    out Dictionary<ViewerKeyAction, KeyChord> sharedBindings,
                    out string? sharedBindingError))
            {
                _keyBindings = sharedBindings;
                _draftKeyBindings = new Dictionary<ViewerKeyAction, KeyChord>(_keyBindings);
                _sharedKeyBindingsProtected = false;
                _sharedKeyBindingsError = null;
            }
            else
            {
                _sharedKeyBindingsProtected = true;
                _sharedKeyBindingsError = sharedBindingError;
            }
        }
        _confirmBeforeDelete =
            ThumbnailStatusBorderSettingsStore.ResolveEffectiveConfirmBeforeDelete(
                _confirmBeforeDelete,
                loaded);
        SyncConfirmBeforeDeleteCheckBox();
        ApplyThumbnailStatusBorderResources(loaded.Settings);
        ApplyKeyBindingTooltips();
        RefreshKeyBindingEditor();
    }

    private static void ApplyThumbnailStatusBorderResources(ThumbnailStatusBorderSettings settings)
    {
        if (Application.Current is null)
            return;
        if (Application.Current is App { HighContrastPaletteApplied: true })
        {
            Application.Current.Resources["FavoriteThumbnailStatusBorderBrush"] = settings.Favorite.Enabled
                ? CreateFrozenSolidColorBrush(SystemColors.HotTrackColor)
                : Brushes.Transparent;
            Application.Current.Resources["EnhancedThumbnailStatusBorderBrush"] = settings.Enhanced.Enabled
                ? CreateFrozenSolidColorBrush(SystemColors.HotTrackColor)
                : Brushes.Transparent;
            return;
        }
        Application.Current.Resources["FavoriteThumbnailStatusBorderBrush"] = CreateThumbnailStatusBorderBrush(
            settings.Favorite);
        Application.Current.Resources["EnhancedThumbnailStatusBorderBrush"] = CreateThumbnailStatusBorderBrush(
            settings.Enhanced);
    }

    private static Brush CreateThumbnailStatusBorderBrush(ThumbnailStatusBorderPreference preference)
    {
        if (!preference.Enabled)
            return Brushes.Transparent;

        // Legacy "rainbow" remains readable, but the WPF/browser parity
        // presentation is now the same quiet solid cyan.
        string requestedColor = string.Equals(
            preference.Color,
            ThumbnailStatusBorderSettings.RainbowColor,
            StringComparison.OrdinalIgnoreCase)
                ? EnhancedStatusBorderDefaultColor
                : preference.Color;
        if (!ThumbnailStatusBorderSettingsStore.TryNormalizeColor(requestedColor, out string color))
            return Brushes.Transparent;

        byte red = byte.Parse(color.AsSpan(1, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
        byte green = byte.Parse(color.AsSpan(3, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
        byte blue = byte.Parse(color.AsSpan(5, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
        var brush = new SolidColorBrush(Color.FromRgb(red, green, blue));
        brush.Freeze();
        return brush;
    }

    private void App_AccessibilityPaletteChanged(object? sender, EventArgs e)
    {
        if (_initializing)
            return;
        if (Dispatcher.CheckAccess())
            ApplyAccessibilityPreferencesToPresentation();
        else
            Dispatcher.BeginInvoke(() => ApplyAccessibilityPreferencesToPresentation());
    }

    private void ApplyAccessibilityPreferencesToPresentation()
    {
        ApplyThumbnailStatusBorderResources(_thumbnailStatusBorderSettings);
        SearchHistoryPopup.PopupAnimation = ReducedMotionEnabled
            ? PopupAnimation.None
            : PopupAnimation.Fade;

        if (ReducedMotionEnabled)
        {
            _modalTransformQualityTimer.Stop();
            ModalVisualTransform?.BeginAnimation(ScaleTransform.ScaleXProperty, null);
            ModalVisualTransform?.BeginAnimation(ScaleTransform.ScaleYProperty, null);
            ModalPanTransform?.BeginAnimation(TranslateTransform.XProperty, null);
            ModalPanTransform?.BeginAnimation(TranslateTransform.YProperty, null);
            foreach (UIElement element in ModalAnimatedElements())
                element.BeginAnimation(OpacityProperty, null);
            UpdateModalTransform(animate: false);
            UpdateModalChromePresentation();
            if (ModalBitmap is not null)
                RenderOptions.SetBitmapScalingMode(ModalBitmap, BitmapScalingMode.HighQuality);
        }

        SyncAccessibilityPreferenceControls();
    }

    private IEnumerable<UIElement> ModalAnimatedElements()
    {
        yield return ModalTopBarSurface;
        yield return ModalTopBar;
        yield return ModalFooter;
        yield return ModalZoomIndicator;
        yield return ModalPreviousButton;
        yield return ModalNextButton;
    }

    private static Brush CreateFrozenSolidColorBrush(Color color)
    {
        var brush = new SolidColorBrush(color);
        brush.Freeze();
        return brush;
    }

    private void BeginThumbnailStatusBorderEdit()
    {
        _draftThumbnailStatusBorderSettings = _thumbnailStatusBorderSettings;
        _dirtyThumbnailStatusBorderPreferences = ThumbnailStatusBorderDirtyPreferences.None;
        PopulateThumbnailStatusBorderControls(_draftThumbnailStatusBorderSettings);
        RefreshThumbnailStatusBorderIdleText();
    }

    private void RefreshThumbnailStatusBorderIdleText()
    {
        SaveThumbnailBordersButton.Content = UiLanguageResources.Text(
            _thumbnailStatusBorderSettingsProtected ? "UiRetrySave" : "UiSaveBorders");
        ThumbnailBordersStatusText.Text = _thumbnailStatusBorderSettingsProtected
            ? UiLanguageResources.Format(
                "UiSharedSettingsProtectedFormat",
                _thumbnailStatusBorderSettingsError ?? "")
            : UiLanguageResources.Text("UiThumbnailBordersEditable");
    }

    private void PopulateThumbnailStatusBorderControls(ThumbnailStatusBorderSettings settings)
    {
        _syncingThumbnailStatusBorderControls = true;
        try
        {
            FavoriteThumbnailBorderCheckBox.IsChecked = settings.Favorite.Enabled;
            FavoriteThumbnailBorderColorTextBox.Text = settings.Favorite.Color;
            EnhancedThumbnailBorderCheckBox.IsChecked = settings.Enhanced.Enabled;
            bool legacyRainbow = string.Equals(
                settings.Enhanced.Color,
                ThumbnailStatusBorderSettings.RainbowColor,
                StringComparison.OrdinalIgnoreCase);
            EnhancedThumbnailBorderColorTextBox.Text = legacyRainbow
                ? EnhancedStatusBorderDefaultColor
                : settings.Enhanced.Color;
        }
        finally
        {
            _syncingThumbnailStatusBorderControls = false;
        }
        RefreshThumbnailStatusBorderColorPreviews();
    }

    private bool RefreshThumbnailStatusBorderColorPreviews()
    {
        if (FavoriteThumbnailBorderColorPreview is null || EnhancedThumbnailBorderColorPreview is null)
            return false;
        bool favoriteValid = ThumbnailStatusBorderSettingsStore.TryNormalizeColor(
            FavoriteThumbnailBorderColorTextBox?.Text,
            out string favoriteColor);
        bool enhancedValid = ThumbnailStatusBorderSettingsStore.TryNormalizeColor(
            EnhancedThumbnailBorderColorTextBox?.Text,
            out _);
        string enhancedColor = EnhancedThumbnailBorderColorTextBox?.Text ?? "";
        FavoriteThumbnailBorderColorPreview.Background = favoriteValid
            ? CreateThumbnailStatusBorderBrush(
                new ThumbnailStatusBorderPreference(true, favoriteColor))
            : Brushes.Transparent;
        EnhancedThumbnailBorderColorPreview.Background = enhancedValid
            ? CreateThumbnailStatusBorderBrush(
                new ThumbnailStatusBorderPreference(true, enhancedColor))
            : Brushes.Transparent;
        return favoriteValid && enhancedValid;
    }

    private void ThumbnailBorderColor_TextChanged(object sender, TextChangedEventArgs e)
    {
        if (_initializing || _syncingThumbnailStatusBorderControls)
            return;
        _dirtyThumbnailStatusBorderPreferences |= ReferenceEquals(sender, FavoriteThumbnailBorderColorTextBox)
            ? ThumbnailStatusBorderDirtyPreferences.Favorite
            : ThumbnailStatusBorderDirtyPreferences.Enhanced;
        bool valid = RefreshThumbnailStatusBorderColorPreviews();
        ThumbnailBordersStatusText.Text = valid
            ? UiLanguageResources.Text("UiBordersReadyToSave")
            : UiLanguageResources.Text("UiBorderHexHelp");
    }

    private void ThumbnailBorderEnabled_Changed(object sender, RoutedEventArgs e)
    {
        if (_initializing || _syncingThumbnailStatusBorderControls)
            return;
        _dirtyThumbnailStatusBorderPreferences |= ReferenceEquals(sender, FavoriteThumbnailBorderCheckBox)
            ? ThumbnailStatusBorderDirtyPreferences.Favorite
            : ThumbnailStatusBorderDirtyPreferences.Enhanced;
        ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiBordersReadyToSave");
    }

    private void ResetThumbnailBorders_Click(object sender, RoutedEventArgs e)
    {
        _draftThumbnailStatusBorderSettings = ThumbnailStatusBorderSettings.Default;
        _dirtyThumbnailStatusBorderPreferences = ThumbnailStatusBorderDirtyPreferences.All;
        PopulateThumbnailStatusBorderControls(_draftThumbnailStatusBorderSettings);
        SaveThumbnailBordersButton.Content = UiLanguageResources.Text("UiSaveBorders");
        EnhancedThumbnailBorderColorTextBox.Text = EnhancedStatusBorderDefaultColor;
        ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiBorderDefaultsReady");
    }

    private void SaveThumbnailBorders_Click(object sender, RoutedEventArgs e)
    {
        _lastThumbnailStatusBorderSaveSucceeded = false;
        if (_dirtyThumbnailStatusBorderPreferences == ThumbnailStatusBorderDirtyPreferences.None)
        {
            if (_thumbnailStatusBorderSettingsProtected)
            {
                SaveThumbnailBordersButton.Content = UiLanguageResources.Text("UiRetrySave");
                ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiProtectedChangeBeforeRetry");
            }
            else
            {
                _lastThumbnailStatusBorderSaveSucceeded = true;
                ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiNoBorderChanges");
            }
            return;
        }
        if (!TryReadThumbnailStatusBorderDraft(out ThumbnailStatusBorderSettings draft))
        {
            SaveThumbnailBordersButton.Content = UiLanguageResources.Text("UiRetrySave");
            ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiBordersNeedHex");
            return;
        }

        _draftThumbnailStatusBorderSettings = draft;
        if (!TryPersistThumbnailStatusBorderSettings(
                draft,
                _dirtyThumbnailStatusBorderPreferences,
                out ThumbnailStatusBorderSettings persisted,
                out string? error))
        {
            _thumbnailStatusBorderSettingsProtected = true;
            _thumbnailStatusBorderSettingsError = error;
            SaveThumbnailBordersButton.Content = UiLanguageResources.Text("UiRetrySave");
            ThumbnailBordersStatusText.Text = UiLanguageResources.Format("UiCouldNotSaveSharedFormat", error ?? "");
            return;
        }

        _thumbnailStatusBorderSettings = persisted;
        _draftThumbnailStatusBorderSettings = persisted;
        _thumbnailStatusBorderSettingsProtected = false;
        _thumbnailStatusBorderSettingsError = null;
        ApplyThumbnailStatusBorderResources(persisted);
        PopulateThumbnailStatusBorderControls(persisted);
        _dirtyThumbnailStatusBorderPreferences = ThumbnailStatusBorderDirtyPreferences.None;
        _lastThumbnailStatusBorderSaveSucceeded = true;
        SaveThumbnailBordersButton.Content = UiLanguageResources.Text("UiSaveBorders");
        ThumbnailBordersStatusText.Text = UiLanguageResources.Text("UiBordersSaved");
    }

    private bool TryReadThumbnailStatusBorderDraft(out ThumbnailStatusBorderSettings settings)
    {
        settings = ThumbnailStatusBorderSettings.Default;
        if (!ThumbnailStatusBorderSettingsStore.TryNormalizeColor(
                FavoriteThumbnailBorderColorTextBox.Text,
                out string favoriteColor))
        {
            return false;
        }
        if (!ThumbnailStatusBorderSettingsStore.TryNormalizeColor(
                EnhancedThumbnailBorderColorTextBox.Text,
                out string enhancedColor))
        {
            return false;
        }
        settings = new ThumbnailStatusBorderSettings(
            new ThumbnailStatusBorderPreference(FavoriteThumbnailBorderCheckBox.IsChecked == true, favoriteColor),
            new ThumbnailStatusBorderPreference(EnhancedThumbnailBorderCheckBox.IsChecked == true, enhancedColor));
        return true;
    }

    private static bool TryPersistThumbnailStatusBorderSettings(
        ThumbnailStatusBorderSettings settings,
        ThumbnailStatusBorderDirtyPreferences dirtyPreferences,
        out ThumbnailStatusBorderSettings persistedSettings,
        out string? error)
    {
        persistedSettings = settings;
        error = null;
        string path;
        try
        {
            path = ThumbnailStatusBorderSettingsPath;
        }
        catch (Exception ex)
        {
            error = $"Shared settings path is unavailable: {ex.Message}";
            return false;
        }

        string? operationError = null;
        ThumbnailStatusBorderSettings mergedSettings = settings;
        bool operationStarted = false;
        bool saved = TryWithPersistenceLock(path, () =>
        {
            operationStarted = true;
            if (!ThumbnailStatusBorderSettingsStore.TryReadExistingJson(
                    path,
                    out string? existingJson,
                    out operationError))
            {
                return false;
            }

            if (!ThumbnailStatusBorderSettingsStore.TryMerge(
                    existingJson,
                    settings,
                    dirtyPreferences,
                    out string mergedJson,
                    out operationError))
                return false;
            ThumbnailStatusBorderLoadResult parsed = ThumbnailStatusBorderSettingsStore.Parse(mergedJson);
            if (parsed.IsProtected)
            {
                operationError = parsed.Error ?? "The merged thumbnail border settings were invalid.";
                return false;
            }
            if (!TryWriteAtomicSharedJson(path, mergedJson, out operationError))
                return false;
            mergedSettings = parsed.Settings;
            return true;
        });

        if (saved)
        {
            persistedSettings = mergedSettings;
            return true;
        }
        error = operationError ?? (operationStarted
            ? "The shared settings write failed."
            : "The shared settings file is busy. Try again.");
        return false;
    }

    private void OpenAppSettings_Click(object sender, RoutedEventArgs e)
        => OpenAppSettings(focusShortcuts: false);

    private void OpenShortcuts_Click(object sender, RoutedEventArgs e)
        => OpenAppSettings(focusShortcuts: true);

    private void OpenAppSettings(bool focusShortcuts)
    {
        StopGalleryAutoScroll();
        if (Application.Current is App app)
            app.RefreshAccessibilityPreferencesFromSystem();
        SyncAccessibilityPreferenceControls();
        _settingsFocusBeforeDialog = Keyboard.FocusedElement;
        BeginKeyBindingEdit();
        BeginThumbnailStatusBorderEdit();
        ConfirmBeforeDeleteCheckBox.IsChecked = _confirmBeforeDelete;
        SetShowUnseenDots(_showUnseenDots, persist: false);
        SetFavoriteChangeNotifications(_showFavoriteChangeNotifications, persist: false);
        RefreshSharedDataSettings();
        DiagnosticsText.Text = BuildDiagnosticsText();
        DiagnosticsStatusText.Text = "Read-only diagnostics. Copy excludes paths, image metadata, prompts, and personal state.";
        AppSettingsDialog.Visibility = Visibility.Visible;
        SelectAppSettingsSection(focusShortcuts ? "keyboard" : "general", bringIntoView: false);
        Dispatcher.BeginInvoke(() =>
        {
            SelectAppSettingsSection(focusShortcuts ? "keyboard" : "general", bringIntoView: true);
            if (focusShortcuts)
            {
                Button? firstBinding = KeyBindingSettings.Definitions
                    .Select(definition => _keyBindingButtons.TryGetValue(definition.Action, out Button? button) ? button : null)
                    .FirstOrDefault(static button => button is not null);
                if (firstBinding?.Focus() != true)
                    KeyBindingsPanel.Focus();
                return;
            }
            ConfirmBeforeDeleteCheckBox.Focus();
        }, DispatcherPriority.Input);
    }

    private void AppSettingsNavigation_Click(object sender, RoutedEventArgs e)
    {
        if (sender is FrameworkElement { Tag: string section })
            SelectAppSettingsSection(section, bringIntoView: true);
    }

    private void SelectAppSettingsSection(string section, bool bringIntoView)
    {
        if (string.Equals(section, "storage", StringComparison.Ordinal))
            RefreshSharedDataSettings();

        (FrameworkElement Target, RadioButton Navigation) selection = section switch
        {
            "display" => (DisplaySettingsHeading, SettingsDisplayNav),
            "thumbnails" => (ThumbnailSettingsHeading, SettingsThumbnailsNav),
            "keyboard" => (KeyBindingsHeading, SettingsKeyboardNav),
            "storage" => (SharedDataSettingsHeading, SettingsStorageNav),
            "about" => (AboutSettingsHeading, SettingsAboutNav),
            _ => (GeneralSettingsHeading, SettingsGeneralNav),
        };

        selection.Navigation.IsChecked = true;
        if (!bringIntoView)
            return;
        if (ReferenceEquals(selection.Target, GeneralSettingsHeading))
            AppSettingsScrollViewer.ScrollToTop();
        else
        {
            AppSettingsDialog.UpdateLayout();
            Point targetInViewport = selection.Target.TranslatePoint(
                new Point(0, 0),
                AppSettingsScrollViewer);
            AppSettingsScrollViewer.ScrollToVerticalOffset(
                Math.Max(
                    0,
                    AppSettingsScrollViewer.VerticalOffset
                        + targetInViewport.Y
                        - AppSettingsScrollViewer.Padding.Top));
        }
    }

    private static SharedDataLocationView BuildSharedDataLocationView(
        SharedDataRootActivationResult? activation,
        Func<string, bool> directoryExists)
    {
        if (activation is null)
            return SharedDataLocationView.Unavailable("Shared data has not been resolved for this process.");

        if (activation.Status == SharedDataRootActivationStatus.OverridesOnly)
        {
            return new SharedDataLocationView(
                "overrides",
                "Individual store overrides",
                "Advanced per-store paths are active, so this process has no single data folder.",
                "No single data folder",
                null,
                false,
                "Nothing was opened or changed.");
        }

        string? normalizedRoot = null;
        if (!string.IsNullOrWhiteSpace(activation.SharedDataRoot))
        {
            try
            {
                string candidate = Path.GetFullPath(activation.SharedDataRoot);
                if (Path.IsPathFullyQualified(candidate))
                    normalizedRoot = candidate;
            }
            catch
            {
                normalizedRoot = null;
            }
        }

        if (normalizedRoot is null)
            return SharedDataLocationView.Unavailable("The fixed data location is unavailable. No files were changed.");

        bool exists;
        try
        {
            exists = directoryExists(normalizedRoot);
        }
        catch
        {
            exists = false;
        }

        if (activation.Status == SharedDataRootActivationStatus.LegacyUninitialized)
        {
            return new SharedDataLocationView(
                "legacy-uninitialized",
                "Local data not initialized",
                "No shared-root locator is active. Aibos will create its local data folder only after an explicit state change.",
                normalizedRoot,
                normalizedRoot,
                exists,
                exists
                    ? "The local data folder already exists and can be opened."
                    : "The folder does not exist yet. Opening Settings did not create it.");
        }

        bool sharedByLocator =
            activation.Status == SharedDataRootActivationStatus.Activated
            && activation.ResolutionStatus == SharedDataRootResolutionStatus.Resolved;
        string title = sharedByLocator ? "Shared with Browser" : "Local Aibos data";
        string description = sharedByLocator
            ? "Aibos and the Browser app use this location for Favorites, Seen, shared settings, Albums, Search History, Recent folders, and Enhancement data."
            : "No shared-root locator is active. Aibos is using its existing local durable-data folder.";
        return new SharedDataLocationView(
            sharedByLocator ? "shared" : "legacy",
            title,
            description,
            normalizedRoot,
            normalizedRoot,
            exists,
            exists
                ? "The existing folder can be opened without changing shared data."
                : "The configured folder is currently unavailable. No folder was created.");
    }

    private void RefreshSharedDataSettings()
    {
        _sharedDataLocation = BuildSharedDataLocationView(
            _sharedDataRootActivationProvider(),
            _sharedDataRootDirectoryExists);
        SharedDataModeText.Text = _sharedDataLocation.Title;
        SharedDataDescriptionText.Text = _sharedDataLocation.Description;
        SharedDataRootTextBox.Text = _sharedDataLocation.DisplayPath;
        SharedDataRootTextBox.ToolTip = _sharedDataLocation.DisplayPath;
        OpenSharedDataFolderButton.IsEnabled = _sharedDataLocation.CanOpen;
        SharedDataStatusText.Text = _sharedDataLocation.Status;
    }

    private void OpenSharedDataFolder_Click(object sender, RoutedEventArgs e)
        => TryOpenSharedDataFolder();

    private bool TryOpenSharedDataFolder()
    {
        RefreshSharedDataSettings();
        if (!_sharedDataLocation.CanOpen
            || string.IsNullOrWhiteSpace(_sharedDataLocation.RootPath))
        {
            SharedDataStatusText.Text = _sharedDataLocation.Status;
            return false;
        }

        try
        {
            var startInfo = new ProcessStartInfo("explorer.exe")
            {
                UseShellExecute = true,
            };
            startInfo.ArgumentList.Add(_sharedDataLocation.RootPath);
            if (!_explorerLauncher(startInfo))
            {
                SharedDataStatusText.Text = "The data folder could not be opened. Check folder access and try again.";
                return false;
            }

            SharedDataStatusText.Text = "Opened the data folder. No shared data was changed.";
            return true;
        }
        catch (Exception ex) when (ex is Win32Exception
            or IOException
            or UnauthorizedAccessException
            or InvalidOperationException
            or ArgumentException
            or NotSupportedException
            or System.Security.SecurityException)
        {
            Trace.TraceWarning($"Shared data folder open failed: {ex.GetType().Name}");
            SharedDataStatusText.Text = "The data folder could not be opened. Check folder access and try again.";
            return false;
        }
    }

    private void AppSettingsBackdrop_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        if (TryCloseAppSettingsFromBackdrop(e.OriginalSource))
        {
            e.Handled = true;
        }
    }

    private bool TryCloseAppSettingsFromBackdrop(object? hitTarget)
    {
        if (AppSettingsDialog.Visibility != Visibility.Visible || !ReferenceEquals(hitTarget, AppSettingsDialog))
            return false;
        CloseAppSettings_Click(AppSettingsDialog, new RoutedEventArgs());
        return true;
    }

    private void AppSettingsDialog_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
    {
        if (e.OriginalSource is not DependencyObject source || !IsDescendantOrSelf(source, AppSettingsScrollViewer))
            e.Handled = true;
    }

    private void CloseAppSettings_Click(object sender, RoutedEventArgs e)
    {
        CancelKeyBindingEdit();
        _draftThumbnailStatusBorderSettings = _thumbnailStatusBorderSettings;
        _dirtyThumbnailStatusBorderPreferences = ThumbnailStatusBorderDirtyPreferences.None;
        AppSettingsDialog.Visibility = Visibility.Collapsed;
        RestoreOverlayFocus(_settingsFocusBeforeDialog);
    }

    private void ConfirmBeforeDelete_Changed(object sender, RoutedEventArgs e)
    {
        if (_initializing || _syncingConfirmBeforeDelete)
            return;

        bool requested = ConfirmBeforeDeleteCheckBox.IsChecked == true;
        if (requested == _confirmBeforeDelete)
            return;
        if (!TrySetConfirmBeforeDelete(requested, out string? error))
        {
            SetStatusToast($"Shared delete confirmation was not changed. {error}");
            return;
        }
    }

    private bool TrySetConfirmBeforeDelete(bool value, out string? error)
    {
        error = null;
        if (value != _confirmBeforeDelete
            && !TryPersistSharedConfirmBeforeDelete(value, out error))
        {
            SyncConfirmBeforeDeleteCheckBox();
            return false;
        }

        _confirmBeforeDelete = value;
        SyncConfirmBeforeDeleteCheckBox();
        SaveState();
        return true;
    }

    private void SyncConfirmBeforeDeleteCheckBox()
    {
        _syncingConfirmBeforeDelete = true;
        try
        {
            ConfirmBeforeDeleteCheckBox.IsChecked = _confirmBeforeDelete;
        }
        finally
        {
            _syncingConfirmBeforeDelete = false;
        }
    }

    private static bool TryPersistSharedConfirmBeforeDelete(bool value, out string? error)
    {
        error = null;
        string path;
        try
        {
            path = ThumbnailStatusBorderSettingsPath;
        }
        catch (Exception ex)
        {
            error = $"Shared settings path is unavailable: {ex.Message}";
            return false;
        }

        string? operationError = null;
        bool operationStarted = false;
        bool saved = TryWithPersistenceLock(path, () =>
        {
            operationStarted = true;
            if (!ThumbnailStatusBorderSettingsStore.TryReadExistingJson(
                    path,
                    out string? existingJson,
                    out operationError))
            {
                return false;
            }

            ThumbnailStatusBorderLoadResult existing =
                ThumbnailStatusBorderSettingsStore.Parse(existingJson ?? "{}");
            if (existing.IsProtected)
            {
                operationError = existing.Error ?? "The shared settings file is protected.";
                return false;
            }
            if (existing.ConfirmBeforeDelete == value)
                return true;

            if (!ThumbnailStatusBorderSettingsStore.TryMergeConfirmBeforeDelete(
                    existingJson,
                    value,
                    out string mergedJson,
                    out operationError))
            {
                return false;
            }

            ThumbnailStatusBorderLoadResult merged =
                ThumbnailStatusBorderSettingsStore.Parse(mergedJson);
            if (merged.IsProtected || merged.ConfirmBeforeDelete != value)
            {
                operationError = merged.Error
                    ?? "The merged shared delete confirmation setting was invalid.";
                return false;
            }

            if (!TryWriteAtomicSharedJson(path, mergedJson, out operationError))
                return false;
            return true;
        });

        if (saved)
            return true;
        error = operationError ?? (operationStarted
            ? "The shared settings write failed."
            : "The shared settings file is busy. Try again.");
        return false;
    }

    private string BuildDiagnosticsText()
    {
        Assembly assembly = Assembly.GetEntryAssembly() ?? typeof(MainWindow).Assembly;
        string version = assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
            ?? assembly.GetName().Version?.ToString() ?? "local build";
        string sourceRevision = Environment.GetEnvironmentVariable("PVU_SOURCE_REVISION")?.Trim() ?? "";
        string sourceDirty = Environment.GetEnvironmentVariable("PVU_SOURCE_DIRTY")?.Trim() ?? "";
        string source = string.IsNullOrWhiteSpace(sourceRevision)
            ? "local build"
            : $"{sourceRevision[..Math.Min(12, sourceRevision.Length)]}{(string.Equals(sourceDirty, "1", StringComparison.OrdinalIgnoreCase) || string.Equals(sourceDirty, "true", StringComparison.OrdinalIgnoreCase) ? " (dirty)" : "")}";
        string buildTime = "unavailable";
        try
        {
            string? exe = Environment.ProcessPath;
            if (!string.IsNullOrWhiteSpace(exe) && File.Exists(exe))
            {
                DateTime utc = File.GetLastWriteTimeUtc(exe);
                buildTime = $"{utc:yyyy-MM-dd HH:mm:ss} UTC / {utc.ToLocalTime():yyyy-MM-dd HH:mm:ss} local";
            }
        }
        catch { }
        return string.Join(Environment.NewLine, [
            $"PhotoViewer.Wpf {version}",
            $"Source: {source}",
            $"Build: {buildTime}",
            $"Process: {RuntimeInformation.ProcessArchitecture} · {RuntimeInformation.FrameworkDescription}",
            $"Catalog: {_allTiles.Count} · Visible: {_tiles.Count}",
            $"Safety: confirm delete {(_confirmBeforeDelete ? "on" : "off")} · unseen dots {(_showUnseenDots ? "on" : "off")}",
        ]);
    }

    private void CopyDiagnostics_Click(object sender, RoutedEventArgs e)
        => TryCopyDiagnostics();

    private bool TryCopyDiagnostics()
    {
        string text = BuildDiagnosticsText();
        _lastDiagnosticsCopyText = text;
        try
        {
            _diagnosticsClipboardWriter(text);
            DiagnosticsStatusText.Text = "Diagnostics copied. It contains no paths, metadata, prompts, or saved image state.";
            return true;
        }
        catch (Exception ex)
        {
            Trace.TraceWarning($"Diagnostics clipboard copy failed: {ex.GetType().Name}");
            DiagnosticsStatusText.Text = "Diagnostics could not be copied. Try again after another app releases the clipboard.";
            return false;
        }
    }

    private bool RequestDeleteSelected()
    {
        if (SelectedTile() is not Tile tile)
        {
            SetDeleteStatus("Select an image to move to Recycle Bin.");
            return false;
        }

        if (!TryValidateDelete(tile, out string reason))
        {
            SetDeleteStatus($"Move to Recycle Bin blocked: {reason}");
            return false;
        }

        int favoriteLevel = FavoriteLevelForDelete(tile);
        bool favoriteProtected = favoriteLevel > 0;
        if (_confirmBeforeDelete || favoriteProtected)
        {
            _pendingDeleteTile = tile;
            _pendingBulkDeleteSnapshot = null;
            string favoriteWarning = favoriteProtected
                ? $"\nFavorite level {favoriteLevel}. Favorite images always require confirmation."
                : "";
            ShowDeleteConfirmation(
                $"{tile.FileName}\nThe source will be moved to the Windows Recycle Bin.{favoriteWarning}",
                "Move selected image to Recycle Bin",
                favoriteProtected);
            return true;
        }

        return ExecuteDelete(tile, favoriteConfirmed: false);
    }

    private bool RequestBulkDeleteSelected()
    {
        List<Tile> selected = SelectedTiles().Where(static tile => tile.IsRealFile).ToList();
        if (selected.Count <= 1)
            return RequestDeleteSelected();

        var snapshot = new DeleteSnapshot(selected, _tiles.ToList());
        int favoriteCount = selected.Count(tile => FavoriteLevelForDelete(tile) > 0);
        bool favoriteProtected = favoriteCount > 0;
        if (_confirmBeforeDelete || favoriteProtected)
        {
            _pendingDeleteTile = null;
            _pendingBulkDeleteSnapshot = snapshot;
            string favoriteWarning = favoriteProtected
                ? $"\n{favoriteCount:N0} favorite image(s) are included. Favorite images always require confirmation."
                : "";
            ShowDeleteConfirmation(
                $"{selected.Count:N0} selected images\nEach source will be moved independently to the Windows Recycle Bin. Failed images will remain available.{favoriteWarning}",
                $"Move {selected.Count:N0} selected images to Recycle Bin",
                favoriteProtected);
            return true;
        }

        return ExecuteBulkDelete(snapshot, favoriteConfirmed: false);
    }

    private void ShowDeleteConfirmation(string message, string confirmAutomationName, bool favoriteProtected)
    {
        _deleteFocusBeforeDialog = Keyboard.FocusedElement;
        _favoriteDeleteConfirmationRequired = favoriteProtected;
        DeleteConfirmationText.Text = message;
        System.Windows.Automation.AutomationProperties.SetName(DeleteConfirmButton, confirmAutomationName);
        DoNotAskAgainCheckBox.IsChecked = false;
        DoNotAskAgainCheckBox.Visibility = favoriteProtected ? Visibility.Collapsed : Visibility.Visible;
        DoNotAskAgainCheckBox.IsEnabled = !favoriteProtected;
        DeleteConfirmationDialog.Visibility = Visibility.Visible;
        Dispatcher.BeginInvoke(DeleteCancelButton.Focus, DispatcherPriority.Input);
    }

    private void DeleteCancel_Click(object sender, RoutedEventArgs e)
    {
        _pendingDeleteTile = null;
        _pendingBulkDeleteSnapshot = null;
        _favoriteDeleteConfirmationRequired = false;
        DeleteConfirmationDialog.Visibility = Visibility.Collapsed;
        SetDeleteStatus("Move to Recycle Bin cancelled.");
        RestoreOverlayFocus(_deleteFocusBeforeDialog);
    }

    private void DeleteConfirm_Click(object sender, RoutedEventArgs e)
    {
        Tile? tile = _pendingDeleteTile;
        DeleteSnapshot? bulkSnapshot = _pendingBulkDeleteSnapshot;
        bool favoriteProtected = _favoriteDeleteConfirmationRequired;
        if (!favoriteProtected && DoNotAskAgainCheckBox.IsChecked == true)
        {
            if (!TrySetConfirmBeforeDelete(false, out string? error))
            {
                DoNotAskAgainCheckBox.IsChecked = false;
                SetStatusToast($"Delete confirmation stays enabled. {error}");
            }
        }

        _pendingDeleteTile = null;
        _pendingBulkDeleteSnapshot = null;
        _favoriteDeleteConfirmationRequired = false;
        DeleteConfirmationDialog.Visibility = Visibility.Collapsed;
        if (bulkSnapshot is not null)
            ExecuteBulkDelete(bulkSnapshot, favoriteConfirmed: favoriteProtected);
        else if (tile is not null)
            ExecuteDelete(tile, favoriteConfirmed: favoriteProtected);
        RestoreOverlayFocus(_deleteFocusBeforeDialog);
    }

    private bool ExecuteDelete(Tile tile, bool favoriteConfirmed)
    {
        // Keep the favorite guard at the destructive boundary as well as in
        // the request UI. A future caller must not be able to bypass the
        // mandatory confirmation by invoking execution directly.
        int favoriteLevel = FavoriteLevelForDelete(tile);
        if (favoriteLevel > 0 && !favoriteConfirmed)
        {
            SetDeleteStatus($"Move to Recycle Bin blocked: {tile.FileName} is Favorite level {favoriteLevel} and requires confirmation.");
            return false;
        }

        // Revalidate immediately before the only destructive boundary.
        if (!TryValidateDelete(tile, out string reason))
        {
            SetDeleteStatus($"Move to Recycle Bin blocked: {reason}");
            return false;
        }

        List<Tile> priorFilteredOrder = _tiles.ToList();
        int oldIndex = priorFilteredOrder.IndexOf(tile);
        RecycleBinDeleteResult result = _recycleBinDelete(tile.Path);
        if (!result.Succeeded)
        {
            SetDeleteStatus($"Move to Recycle Bin failed: {result.Reason}. Retry is available.", isFailure: true, retryTile: tile);
            return false;
        }
        bool albumCleanupSucceeded = CleanupAlbumMembershipAfterRecycle([tile.Path]);

        bool modalManualChromeWasVisible = _modalManualChromeVisible;
        bool refreshModal = ReconcileSuccessfulSourceRecycle([tile]);
        ApplyFilters(selectFirst: false);

        Tile? neighbor = priorFilteredOrder
            .Skip(Math.Max(0, oldIndex + 1))
            .FirstOrDefault(_tiles.Contains)
            ?? priorFilteredOrder
                .Take(Math.Max(0, oldIndex))
                .Reverse()
                .FirstOrDefault(_tiles.Contains);
        if (neighbor is not null)
        {
            SelectTile(neighbor);
            if (refreshModal)
            {
                OpenModal();
                SetModalChromeVisible(modalManualChromeWasVisible, showFeedback: false);
            }
        }
        else
        {
            SelectTile(null);
            CloseModal();
        }

        if (albumCleanupSucceeded)
        {
            SetDeleteStatus($"Moved {tile.FileName} to Recycle Bin. Album membership was reconciled.");
        }
        else
        {
            SetStatusToast(
                $"Moved {tile.FileName} to Recycle Bin, but Album cleanup is pending. The missing membership was preserved; Retry only removes that membership and never recycles the source again.",
                RetryPendingAlbumMembershipCleanup);
        }
        SaveState();
        return true;
    }

    private bool ExecuteBulkDelete(DeleteSnapshot snapshot, bool favoriteConfirmed)
    {
        int favoriteCount = snapshot.Targets.Count(tile => FavoriteLevelForDelete(tile) > 0);
        if (favoriteCount > 0 && !favoriteConfirmed)
        {
            SetDeleteStatus($"Move to Recycle Bin blocked: {favoriteCount:N0} favorite image(s) require confirmation.");
            return false;
        }

        var succeeded = new List<Tile>();
        var failed = new List<(Tile Tile, string Reason)>();
        foreach (Tile tile in snapshot.Targets)
        {
            if (!TryValidateDelete(tile, out string reason))
            {
                failed.Add((tile, reason));
                continue;
            }

            RecycleBinDeleteResult result = _recycleBinDelete(tile.Path);
            if (result.Succeeded)
                succeeded.Add(tile);
            else
                failed.Add((tile, string.IsNullOrWhiteSpace(result.Reason) ? "Recycle Bin rejected the source" : result.Reason));
        }

        if (succeeded.Count == 0)
        {
            string reason = failed.FirstOrDefault().Reason ?? "No source could be moved";
            SetStatusToast($"No selected images were moved to Recycle Bin. {failed.Count:N0} failed; they remain selected. {reason}");
            return false;
        }
        bool albumCleanupSucceeded = CleanupAlbumMembershipAfterRecycle(succeeded.Select(static tile => tile.Path).ToList());

        bool modalManualChromeWasVisible = _modalManualChromeVisible;
        bool refreshModal = ReconcileSuccessfulSourceRecycle(succeeded);
        ApplyFilters(selectFirst: false);

        var remainingSelected = snapshot.Targets
            .Where(tile => !succeeded.Contains(tile) && _tiles.Contains(tile))
            .ToList();
        Tile? neighbor = FindBulkDeleteNeighbor(snapshot.FilteredOrder, snapshot.Targets);
        if (neighbor is not null)
        {
            if (!remainingSelected.Contains(neighbor))
                remainingSelected.Add(neighbor);
            SetSelection(remainingSelected, neighbor);
            if (refreshModal)
            {
                OpenModal();
                SetModalChromeVisible(modalManualChromeWasVisible, showFeedback: false);
            }
        }
        else if (remainingSelected.Count > 0)
        {
            SetSelection(remainingSelected, remainingSelected[^1]);
            if (refreshModal)
            {
                OpenModal();
                SetModalChromeVisible(modalManualChromeWasVisible, showFeedback: false);
            }
        }
        else
        {
            SelectTile(null);
            CloseModal();
        }

        SaveState();
        if (failed.Count == 0 && albumCleanupSucceeded)
        {
            SetStatusToast($"Moved {succeeded.Count:N0} selected images to Recycle Bin. Album membership was reconciled.");
        }
        else
        {
            string firstReason = failed.Count > 0 ? $" {failed[0].Reason}" : "";
            string cleanupReason = albumCleanupSucceeded ? "" : " Album cleanup failed; missing membership was preserved for recovery.";
            SetStatusToast(
                $"Moved {succeeded.Count:N0} image(s); {failed.Count:N0} failed and remain selected.{firstReason}{cleanupReason}",
                albumCleanupSucceeded ? null : RetryPendingAlbumMembershipCleanup);
        }
        return true;
    }

    private int FavoriteLevelForDelete(Tile tile)
        => Math.Max(Math.Clamp(tile.Fav, 0, 5), FavoriteLevelForPath(tile.Path));

    private bool CleanupAlbumMembershipAfterRecycle(
        IReadOnlyList<string> recycledPaths,
        int timeoutMilliseconds = 2_000)
    {
        string[] sharedPaths = recycledPaths
            .Where(path => Path.GetExtension(path).ToLowerInvariant() is ".png" or ".jpg" or ".jpeg" or ".webp" or ".avif" or ".gif")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (sharedPaths.Length == 0)
            return true;
        try
        {
            AlbumMutationResult result = AlbumStore.CleanupPaths(
                AlbumStore.ResolvePath(),
                sharedPaths,
                expectedRevision: null,
                timeoutMilliseconds: timeoutMilliseconds);
            if (!result.Ok)
            {
                _pendingAlbumCleanupPaths = _pendingAlbumCleanupPaths
                    .Concat(sharedPaths)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                return false;
            }
            _pendingAlbumCleanupPaths = _pendingAlbumCleanupPaths
                .Except(sharedPaths, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            QueueActiveAlbumSourceRefresh();
            return true;
        }
        catch
        {
            _pendingAlbumCleanupPaths = _pendingAlbumCleanupPaths
                .Concat(sharedPaths)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
            return false;
        }
    }

    private void RetryPendingAlbumMembershipCleanup()
    {
        string[] pending = _pendingAlbumCleanupPaths.ToArray();
        if (pending.Length == 0)
        {
            SetStatusToast("Album cleanup retry is no longer needed.");
            return;
        }

        if (CleanupAlbumMembershipAfterRecycle(pending))
        {
            SetStatusToast($"Removed {pending.Length:N0} missing source membership(s) from Album. No source Recycle action was repeated.");
            return;
        }

        SetStatusToast(
            "Album cleanup is still pending. The source is already in Recycle Bin; Retry only attempts the idempotent membership cleanup.",
            RetryPendingAlbumMembershipCleanup);
    }

    /// <summary>
    /// Reconciles WPF-owned UI references after the Recycle Bin backend has
    /// confirmed success. Favorite, Seen, and enhancement data are deliberately
    /// retained: those stores are multi-owner history with separate deletion
    /// authority, not children of the source-file lifecycle.
    /// </summary>
    private bool ReconcileSuccessfulSourceRecycle(IEnumerable<Tile> deletedTiles)
    {
        var deletedPaths = new HashSet<string>(deletedTiles.Select(static tile => tile.Path), StringComparer.OrdinalIgnoreCase);
        var deletedKeys = new HashSet<string>(deletedPaths.Select(NormalizeFavoritePath), StringComparer.OrdinalIgnoreCase);
        long recycleGeneration = ++_sourceRecycleGeneration;
        foreach (string key in deletedKeys)
            _sourceRecycleGenerationByPath[key] = recycleGeneration;
        bool refreshModal = Modal.Visibility == Visibility.Visible;
        bool deletedModalSource = refreshModal
            && !string.IsNullOrWhiteSpace(_modalSourceTilePath)
            && deletedPaths.Contains(_modalSourceTilePath);

        if (deletedModalSource)
            CloseModal();
        if (_hoverPreviewTabPath is not null && deletedPaths.Contains(_hoverPreviewTabPath))
            HidePreviewTabHover();

        if (_allTiles.RemoveAll(tile => deletedPaths.Contains(tile.Path)) > 0)
            _catalogContentRevision++;
        _selectedPaths.RemoveWhere(deletedPaths.Contains);
        if (_primarySelectedPath is not null && deletedPaths.Contains(_primarySelectedPath))
        {
            _primarySelectedPath = null;
            _primarySelectedTile = null;
            _primarySelectedIndex = -1;
        }
        if (_restoredSelectedPath is not null && deletedPaths.Contains(_restoredSelectedPath))
            _restoredSelectedPath = null;

        foreach (string key in deletedKeys)
            _pinnedPreviewPaths.Remove(key);
        foreach (PreviewTabView tab in _previewTabs.Where(tab => deletedPaths.Contains(tab.Path)).ToList())
            _previewTabs.Remove(tab);
        _closedPreviewTabs.RemoveAll(tile => deletedPaths.Contains(tile.Path));
        _restoredPreviewTabPaths.RemoveAll(path => deletedPaths.Contains(path));
        bool activePreviewTabDeleted = _activePreviewTabPath is not null && deletedPaths.Contains(_activePreviewTabPath);
        if (activePreviewTabDeleted)
            _activePreviewTabPath = null;
        if (activePreviewTabDeleted && _previewTabs.LastOrDefault() is { } nextActiveTab)
            _activePreviewTabPath = nextActiveTab.Path;
        if (_restoredActivePreviewTabPath is not null && deletedPaths.Contains(_restoredActivePreviewTabPath))
            _restoredActivePreviewTabPath = null;
        if (_previewDecodedPath is not null && deletedPaths.Contains(_previewDecodedPath))
            _previewDecodedPath = null;
        if (_currentPreviewMetadataPath is not null && deletedPaths.Contains(_currentPreviewMetadataPath))
        {
            _currentPreviewMetadataPath = null;
            _currentPreviewMetadata = null;
        }

        RefreshPreviewTabs();
        return refreshModal;
    }

    private bool WasSourceRecycledAfter(string path, long generation)
        => _sourceRecycleGenerationByPath.TryGetValue(NormalizeFavoritePath(path), out long recycledAt)
            && recycledAt > generation;

    private Tile? FindBulkDeleteNeighbor(IReadOnlyList<Tile> priorFilteredOrder, IReadOnlyList<Tile> targets)
    {
        int lastDeletedIndex = Enumerable.Range(0, priorFilteredOrder.Count)
            .Where(index => targets.Contains(priorFilteredOrder[index]))
            .DefaultIfEmpty(-1)
            .Max();
        if (lastDeletedIndex >= 0)
        {
            Tile? next = priorFilteredOrder.Skip(lastDeletedIndex + 1).FirstOrDefault(_tiles.Contains);
            if (next is not null)
                return next;
            return priorFilteredOrder.Take(lastDeletedIndex).Reverse().FirstOrDefault(_tiles.Contains);
        }

        return _tiles.FirstOrDefault();
    }

    private sealed record DeleteSnapshot(IReadOnlyList<Tile> Targets, IReadOnlyList<Tile> FilteredOrder);

    private bool TryValidateDelete(Tile tile, out string reason)
    {
        reason = "";
        if (!tile.IsRealFile || string.IsNullOrWhiteSpace(tile.Path))
            return Fail("not a source image", out reason);
        if (!_allTiles.Contains(tile))
            return Fail("not in the current catalog", out reason);
        if (!_tiles.Contains(tile))
            return Fail("not in the current filtered order", out reason);
        if (!Path.IsPathFullyQualified(tile.Path))
            return Fail("path is not absolute", out reason);
        if (!SupportedImageExtensions.Contains(Path.GetExtension(tile.Path)))
            return Fail("unsupported file type", out reason);
        if (!File.Exists(tile.Path))
            return Fail("source no longer exists", out reason);

        string lexical;
        string canonical;
        try
        {
            lexical = Path.GetFullPath(tile.Path);
            canonical = _resolveFinalPath(lexical);
        }
        catch (Exception ex)
        {
            return Fail($"canonical path failed ({ex.Message})", out reason);
        }

        if (IsProtectedDeletePath(lexical, canonical, out reason))
            return false;

        var activeRoots = _currentFolderSet.Count > 0 ? _currentFolderSet : _currentFolder is null ? [] : [_currentFolder];
        if (activeRoots.Count == 0)
            return Fail("no active source root", out reason);
        foreach (string root in activeRoots)
        {
            try
            {
                string lexicalRoot = Path.GetFullPath(root);
                string canonicalRoot = _resolveFinalPath(lexicalRoot);
                if (IsPathInside(lexical, lexicalRoot) && IsPathInside(canonical, canonicalRoot))
                    return true;
            }
            catch
            {
                // A broken root cannot authorize a delete.
            }
        }

        return Fail("source is outside the active root", out reason);
    }

    private bool IsProtectedDeletePath(string lexical, string canonical, out string reason)
    {
        IReadOnlyList<string> protectedRoots;
        try
        {
            protectedRoots = _protectedDeleteRoots();
        }
        catch
        {
            reason = "protected project/app root could not be verified";
            return true;
        }

        foreach (string root in protectedRoots.Where(static root => !string.IsNullOrWhiteSpace(root)))
        {
            try
            {
                string lexicalRoot = Path.GetFullPath(root);
                string canonicalRoot = _resolveFinalPath(lexicalRoot);
                if (IsPathInside(lexical, lexicalRoot)
                    || IsPathInside(canonical, canonicalRoot)
                    || IsPathInside(lexical, canonicalRoot)
                    || IsPathInside(canonical, lexicalRoot))
                {
                    reason = "source is inside a protected project/app root";
                    return true;
                }
            }
            catch
            {
                // A root that cannot be resolved cannot safely authorize a
                // destructive operation. Fail closed without disclosing it.
                reason = "protected project/app root could not be verified";
                return true;
            }
        }

        reason = "";
        return false;
    }

    private static IReadOnlyList<string> ResolveProtectedDeleteRoots()
    {
        var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        static void Add(HashSet<string> destination, string? candidate)
        {
            if (!string.IsNullOrWhiteSpace(candidate))
                destination.Add(Path.GetFullPath(candidate));
        }

        Add(roots, AppContext.BaseDirectory);
        Add(roots, FindProjectRoot(Environment.CurrentDirectory));
        Add(roots, FindProjectRoot(AppContext.BaseDirectory));
        Add(roots, FindProjectRoot(Path.GetDirectoryName(Environment.ProcessPath ?? "") ?? ""));
        return roots.ToList();
    }

    private static bool Fail(string value, out string reason)
    {
        reason = value;
        return false;
    }

    private static bool IsPathInside(string candidate, string root)
    {
        string normalizedRoot = Path.TrimEndingDirectorySeparator(Path.GetFullPath(root));
        string prefix = Path.EndsInDirectorySeparator(normalizedRoot)
            ? normalizedRoot
            : normalizedRoot + Path.DirectorySeparatorChar;
        return string.Equals(candidate, normalizedRoot, StringComparison.OrdinalIgnoreCase)
            || candidate.StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
    }

    private static string ResolveFinalPathCore(string path)
    {
        string fullPath = Path.GetFullPath(path);
        string root = Path.GetPathRoot(fullPath) ?? throw new IOException("path root is unavailable");
        string current = root;
        string tail = fullPath[root.Length..];
        foreach (string part in tail.Split([Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar], StringSplitOptions.RemoveEmptyEntries))
        {
            string candidate = Path.Combine(current, part);
            if (!File.Exists(candidate) && !Directory.Exists(candidate))
                return Path.GetFullPath(candidate);

            FileSystemInfo info = Directory.Exists(candidate) ? new DirectoryInfo(candidate) : new FileInfo(candidate);
            if (info.LinkTarget is null)
            {
                current = candidate;
                continue;
            }

            FileSystemInfo? resolved = info.ResolveLinkTarget(returnFinalTarget: true);
            if (resolved is null)
                throw new IOException($"cannot resolve link target: {candidate}");
            current = Path.GetFullPath(resolved.FullName);
        }

        return Path.GetFullPath(current);
    }

    private static RecycleBinDeleteResult SendFileToWindowsRecycleBin(string path)
    {
        try
        {
            Microsoft.VisualBasic.FileIO.FileSystem.DeleteFile(
                path,
                Microsoft.VisualBasic.FileIO.UIOption.OnlyErrorDialogs,
                Microsoft.VisualBasic.FileIO.RecycleOption.SendToRecycleBin,
                Microsoft.VisualBasic.FileIO.UICancelOption.ThrowException);
            return RecycleBinDeleteResult.Success;
        }
        catch (Exception ex)
        {
            return RecycleBinDeleteResult.Failed(ex.Message);
        }
    }

    private void SetStatusToast(string status, Action? retryAction = null)
    {
        _statusToastDismissTimer?.Stop();
        if (HasUnresolvedSharedFailures)
        {
            // The toast is a singleton, but Favorite and Seen recovery intents
            // are independent. Never let an unrelated success/warning replace
            // the only reachable route to either retained failed batch.
            retryAction = RetryFailedSharedBatches;
            if (!status.Contains("Retry", StringComparison.OrdinalIgnoreCase))
                status = $"{status} Favorite or Seen changes still need Retry.";
        }
        _deleteStatus = status;
        _statusRetryAction = retryAction;
        if (ScanMessage is not null)
            ScanMessage.Text = status;
        if (DeleteStatusText is not null)
        {
            DeleteStatusText.Text = status;
            DeleteStatusRetryButton.Visibility = retryAction is null ? Visibility.Collapsed : Visibility.Visible;
            DeleteStatusToast.Visibility = Visibility.Visible;
        }
    }

    private void SetTransientStatusToast(string status)
    {
        SetStatusToast(status);
        if (_statusRetryAction is not null || HasUnresolvedSharedFailures)
            return;
        _statusToastDismissTimer?.Stop();
        _statusToastDismissTimer?.Start();
    }

    private void ReportCurrentImageDecodeFailure()
    {
        const string currentFailure = "Image could not be decoded. It may be locked, changing, or unavailable. Refresh after fixing the file.";
        bool previousIsRecoverableStatus = _deleteStatus.Contains("selected root(s) were unavailable", StringComparison.OrdinalIgnoreCase)
            || _deleteStatus.Contains("folders could not be scanned", StringComparison.OrdinalIgnoreCase)
            || _deleteStatus.Contains("junction or symbolic-link", StringComparison.OrdinalIgnoreCase)
            || _deleteStatus.Contains("image file(s) could not be decoded", StringComparison.OrdinalIgnoreCase)
            || _deleteStatus.Contains("could not be saved", StringComparison.OrdinalIgnoreCase)
            || _deleteStatus.Contains("is busy in another Aibos window", StringComparison.OrdinalIgnoreCase);
        if (!previousIsRecoverableStatus)
        {
            SetStatusToast(currentFailure);
            return;
        }

        // Scan warnings and persistence refusals explain how to recover data
        // or retry a protected write. A later preview failure must not erase
        // those instructions or its retry action.
        SetStatusToast(
            _deleteStatus.Contains("could not be decoded", StringComparison.OrdinalIgnoreCase)
                ? _deleteStatus
                : $"{_deleteStatus} {currentFailure}",
            _statusRetryAction);
    }

    private void SetDeleteStatus(string status, bool isFailure = false, Tile? retryTile = null)
        => SetStatusToast(status, isFailure && retryTile is not null
            ? () => RetryDelete(retryTile)
            : null);

    private void DismissDeleteStatus_Click(object sender, RoutedEventArgs e)
    {
        _statusToastDismissTimer?.Stop();
        DeleteStatusToast.Visibility = Visibility.Hidden;
    }

    private void RetryDelete_Click(object sender, RoutedEventArgs e)
    {
        Action? retryAction = _statusRetryAction;
        _statusRetryAction = null;
        DeleteStatusRetryButton.Visibility = Visibility.Collapsed;
        if (retryAction is null)
        {
            SetDeleteStatus("Retry is no longer available.");
            return;
        }

        retryAction();
    }

    private void RetryDelete(Tile tile)
    {
        if (!_tiles.Contains(tile))
        {
            SetDeleteStatus("Retry is no longer available.");
            return;
        }

        SelectTile(tile);
        RequestDeleteSelected();
    }

    private void RestoreOverlayFocus(IInputElement? target, bool preferPrimaryGallery = false)
        => Dispatcher.BeginInvoke(() =>
        {
            if (preferPrimaryGallery && TryFocusPrimaryGalleryItem())
                return;
            if (target is UIElement element
                && (!preferPrimaryGallery || IsCurrentPrimaryGalleryFocusTarget(element))
                && element.IsVisible
                && element.IsEnabled
                && element.Focus())
                return;
            if (Landing.Visibility == Visibility.Visible && OpenFolderSetButton.IsVisible && OpenFolderSetButton.IsEnabled && OpenFolderSetButton.Focus())
                return;
            if (!preferPrimaryGallery && TryFocusPrimaryGalleryItem())
                return;
            ListBox activeList = RowsList.Visibility == Visibility.Visible ? RowsList : CardsList;
            if (activeList.IsVisible && activeList.IsEnabled && activeList.Focus())
                return;
            LogoHomeButton.Focus();
        }, DispatcherPriority.Input);

    private bool IsCurrentPrimaryGalleryFocusTarget(DependencyObject target)
    {
        Tile? primary = SelectedTile();
        if (primary is null)
            return false;

        for (DependencyObject? current = target;
             current is not null;
             current = current is Visual or System.Windows.Media.Media3D.Visual3D
                 ? VisualTreeHelper.GetParent(current)
                 : LogicalTreeHelper.GetParent(current))
        {
            if (current is ListBoxItem { DataContext: Tile tile })
            {
                return string.Equals(tile.Path, primary.Path, StringComparison.OrdinalIgnoreCase);
            }
        }

        return false;
    }

    private bool TryFocusPrimaryGalleryItem()
    {
        Tile? tile = SelectedTile();
        ListBox activeList = RowsList.Visibility == Visibility.Visible ? RowsList : CardsList;
        if (tile is null || !activeList.IsVisible || !activeList.IsEnabled)
            return false;

        int index = ResolvePrimarySelectionIndex();
        if (index < 0)
            return false;
        if (RealizedGalleryContainer(activeList, index) is ListBoxItem container
            && container.IsMeasureValid
            && container.IsVisible
            && container.IsEnabled
            && container.Focus())
        {
            return true;
        }

        // A 100k catalog may need two bounded realization frames: one to
        // generate the priority container and one to measure it. Never force
        // those frames synchronously with UpdateLayout on the input path.
        return QueuePrimaryGalleryFocus(
            tile,
            index,
            ReferenceEquals(activeList, CardsList));
    }

    private static string StatePath => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PhotoViewer.Wpf",
        "state.json");

    private static string ResolvedStatePath
    {
        get
        {
            var overridePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
            return string.IsNullOrWhiteSpace(overridePath) ? StatePath : Path.GetFullPath(overridePath);
        }
    }

    private void RestoreState()
    {
        var state = ReadState();
        SetUiLanguage(state?.UiLanguage, persist: false);
        SetFavoriteChangeNotifications(
            state?.ShowFavoriteChangeNotifications ?? true,
            persist: false);
        SetAccessibilityPreferences(
            state?.ReducedMotionOverride,
            state?.ReducedTransparencyOverride,
            persist: false);
        SharedRecentReadResult sharedRecent = ReadSharedRecentFolders();
        var lastFolderSet = ResolveStartupFolderSet(
            state?.LastFolderSet ?? [],
            state?.LastFolder,
            sharedRecent);
        _lastFolderSet = lastFolderSet.ToList();

        if (lastFolderSet.Count > 0)
        {
            _currentFolderSet = lastFolderSet;
            _currentFolder = _currentFolderSet.FirstOrDefault();
            SetLandingFolderSet(lastFolderSet);
            FolderPathText.Text = FormatFolderSetSummary(lastFolderSet);
            int existing = lastFolderSet.Count(Directory.Exists);
            FolderCountText.Text = existing > 0 ? "Last folder set saved" : "Last folder set unavailable";
        }

        if (state is null)
        {
            SyncFavoriteFilterControls();
            SyncFoldersSectionControls();
            RestoreModalPhotorealSettings(null, null, null, null);
            _keyBindings = KeyBindingSettings.CreateDefaults();
            _draftKeyBindings = new Dictionary<ViewerKeyAction, KeyChord>(_keyBindings);
            ApplyKeyBindingTooltips();
            RefreshKeyBindingEditor();
            return;
        }

        _stateExtensionData = state.ExtensionData is null ? null : new Dictionary<string, JsonElement>(state.ExtensionData);
        _keyBindings = KeyBindingSettings.NormalizePersisted(state.KeyBindings, out _keyBindingUnknownEntries);
        _draftKeyBindings = new Dictionary<ViewerKeyAction, KeyChord>(_keyBindings);

        double normalizedCardWidth = NormalizeCardWidth(state.CardWidth);
        _cardWidthMigrationPending = Math.Abs(normalizedCardWidth - state.CardWidth) >= 0.01;
        SizeSlider.Value = normalizedCardWidth;

        _rightPanelWidth = NormalizeRightPanelWidth(state.RightPanelWidth);
        ApplyRightPanelState(state.RightPanelOpen ?? true);

        _displayStyle = NormalizeDisplayStyle(state.DisplayStyle);
        SyncDisplayStyleButtons();
        _aspectMode = NormalizeAspectMode(state.AspectMode);
        SyncAspectButtons();
        _sortBy = NormalizeSortBy(state.SortBy);
        _randomSortSeed = string.IsNullOrWhiteSpace(state.RandomSortSeed) ? "default" : state.RandomSortSeed;
        SyncSortButtons();
        RestoreDateFilter(state);
        _favoriteFilterLevels.Clear();
        if (state.FavoriteFilterLevels is { Count: > 0 })
            _favoriteFilterLevels.UnionWith(state.FavoriteFilterLevels.Where(level => level is >= MinFavoriteFilterLevel and <= MaxFavoriteFilterLevel));
        else if (state.FavoriteFilterLevel is >= MinFavoriteFilterLevel and <= MaxFavoriteFilterLevel)
            _favoriteFilterLevels.Add(state.FavoriteFilterLevel.Value); // additive migration from the scalar schema
        _showUnseenDots = state.ShowUnseenDots;
        _confirmBeforeDelete = state.ConfirmBeforeDelete;
        _foldersSectionExpanded = state.FoldersSectionExpanded ?? true;
        _modalFilmstripOpen = state.ModalFilmstripOpen ?? true;
        SetModalEdgeNavigationPercent(
            state.ModalEdgeNavigationPercent ?? ModalEdgeNavigationDefaultPercent,
            persist: false);
        RestoreModalPhotorealSettings(
            state.PhotorealStrength,
            state.PhotorealStructureStrength,
            state.PhotorealSteps,
            state.PhotorealMaxDimension);
        SyncFoldersSectionControls();
        if (ConfirmBeforeDeleteCheckBox is not null) ConfirmBeforeDeleteCheckBox.IsChecked = _confirmBeforeDelete;
        SetShowUnseenDots(_showUnseenDots, persist: false);
        SetFavoriteFilterState(state.ShowFavoritesOnly, !state.ShowFavoritesOnly && state.ShowUnfavoriteOnly, apply: false, persist: false);
        _hiddenFolderBuckets.Clear();
        foreach (string folder in NormalizeFolderSet(state.HiddenFolderBuckets ?? []))
            _hiddenFolderBuckets.Add(folder);
        _selectedFolderBucketKeys.Clear();
        foreach (string folder in NormalizeFolderSet(state.SelectedFolderBucketKeys ?? []))
            _selectedFolderBucketKeys.Add(folder);
        _primarySelectedFolderBucketKey = NormalizeFolderSet([state.PrimarySelectedFolderBucketKey ?? ""]).FirstOrDefault();
        _pinnedPreviewPaths.Clear();
        foreach (string? path in (state.PinnedPreviewPaths ?? []).Select(NormalizePinnedPreviewPath))
        {
            if (path is not null)
                _pinnedPreviewPaths.Add(path);
        }

        _restoredPreviewTabPaths.Clear();
        _restoredPreviewTabPaths.AddRange(NormalizePreviewTabPaths(state.PreviewTabPaths ?? [], MaxPersistedPreviewTabs));
        _restoredActivePreviewTabPath = NormalizePinnedPreviewPath(state.ActivePreviewTabPath);
        if (_restoredActivePreviewTabPath is null
            || !_restoredPreviewTabPaths.Contains(_restoredActivePreviewTabPath, StringComparer.OrdinalIgnoreCase))
        {
            _restoredActivePreviewTabPath = _restoredPreviewTabPaths.FirstOrDefault();
        }
        _previewTabsPersistenceReady = _restoredPreviewTabPaths.Count == 0;

        if (!string.IsNullOrWhiteSpace(state.SearchQuery))
            SearchInput.Text = state.SearchQuery;

        _restoredSelectedPath = state.SelectedPath;
        ApplyKeyBindingTooltips();
        RefreshKeyBindingEditor();
    }

    private ViewerState? ReadState()
    {
        if (!TryReadViewerStateFile(ResolvedStatePath, out var state))
        {
            _stateWriteBlocked = true;
            ReportPersistenceRefusal("Viewer settings", ResolvedStatePath, protectedFile: true);
            return null;
        }

        return state;
    }

    private static bool TryReadViewerStateFile(string path, out ViewerState? state)
    {
        state = null;
        if (!File.Exists(path))
            return true;

        try
        {
            string json = File.ReadAllText(path);
            using var document = JsonDocument.Parse(json);
            if (document.RootElement.ValueKind != JsonValueKind.Object)
                return false;
            state = JsonSerializer.Deserialize<ViewerState>(json);
            return state is not null && state.Version <= 2;
        }
        catch
        {
            state = null;
            return false;
        }
    }

    private static Dictionary<string, JsonElement>? CloneExtensionData(Dictionary<string, JsonElement>? source)
    {
        if (source is null || source.Count == 0)
            return null;

        var clone = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
        foreach (var entry in source)
            clone[entry.Key] = entry.Value.Clone();
        return clone;
    }

    private void SaveState()
    {
        if (_initializing || _suppressStateSave) return;
        if (_stateWriteBlocked)
        {
            ReportPersistenceRefusal("Viewer settings", ResolvedStatePath, protectedFile: true);
            return;
        }

        try
        {
            string path = ResolvedStatePath;
            var selectedPath = SelectedTile() is { IsRealFile: true } selected ? selected.Path : null;
            _restoredSelectedPath = selectedPath;
            List<string> previewTabPaths = _previewTabsPersistenceReady
                ? NormalizePreviewTabPaths(_previewTabs.Select(static tab => tab.Path), MaxPersistedPreviewTabs)
                : _restoredPreviewTabPaths.ToList();
            string? activePreviewTabPath = _previewTabsPersistenceReady
                ? NormalizePinnedPreviewPath(_activePreviewTabPath)
                : _restoredActivePreviewTabPath;
            if (activePreviewTabPath is null
                || !previewTabPaths.Contains(activePreviewTabPath, StringComparer.OrdinalIgnoreCase))
            {
                activePreviewTabPath = previewTabPaths.FirstOrDefault();
            }
            var state = new ViewerState
            {
                Version = 2,
                LastFolder = _currentFolder,
                LastFolderSet = _currentFolderSet.Count > 0 ? _currentFolderSet : null,
                SearchQuery = SearchInput.Text,
                CardWidth = SizeSlider.Value,
                RightPanelOpen = RightPanel.Visibility == Visibility.Visible,
                RightPanelWidth = _rightPanelWidth,
                DisplayStyle = _displayStyle,
                AspectMode = _aspectMode,
                SortBy = _sortBy,
                RandomSortSeed = _randomSortSeed,
                DatePreset = _dateFromLocal.HasValue || _dateToLocal.HasValue ? DatePresetManualValue : DatePresetNoneValue,
                DateFrom = FormatStateDate(_dateFromLocal),
                DateTo = FormatStateDate(_dateToLocal),
                ShowFavoritesOnly = FavoriteOnlyFilter?.IsChecked == true,
                ShowUnfavoriteOnly = UnfavoriteOnlyFilter?.IsChecked == true,
                FavoriteFilterLevels = _favoriteFilterLevels.Count > 0 ? _favoriteFilterLevels.OrderBy(static level => level).ToList() : null,
                ShowUnseenDots = _showUnseenDots,
                ShowFavoriteChangeNotifications = _showFavoriteChangeNotifications,
                ConfirmBeforeDelete = _confirmBeforeDelete,
                FoldersSectionExpanded = _foldersSectionExpanded,
                ModalFilmstripOpen = _modalFilmstripOpen,
                ModalEdgeNavigationPercent = _modalEdgeNavigationPercent,
                PhotorealStrength = _modalPhotorealStrength,
                PhotorealStructureStrength = _modalPhotorealStructureStrength,
                PhotorealSteps = _modalPhotorealSteps,
                PhotorealMaxDimension = _modalPhotorealMaxDimension,
                UiLanguage = _uiLanguage,
                ReducedMotionOverride = _reducedMotionOverride,
                ReducedTransparencyOverride = _reducedTransparencyOverride,
                HiddenFolderBuckets = _hiddenFolderBuckets.Count > 0 ? _hiddenFolderBuckets.OrderBy(static item => item, StringComparer.OrdinalIgnoreCase).ToList() : null,
                SelectedFolderBucketKeys = _selectedFolderBucketKeys.Count > 0 ? _selectedFolderBucketKeys.OrderBy(static item => item, StringComparer.OrdinalIgnoreCase).ToList() : null,
                PrimarySelectedFolderBucketKey = _primarySelectedFolderBucketKey,
                PinnedPreviewPaths = _pinnedPreviewPaths.Count > 0 ? _pinnedPreviewPaths.OrderBy(static item => item, StringComparer.OrdinalIgnoreCase).ToList() : null,
                PreviewTabPaths = previewTabPaths.Count > 0 ? previewTabPaths : null,
                ActivePreviewTabPath = activePreviewTabPath,
                SelectedPath = selectedPath,
                KeyBindings = KeyBindingSettings.ToPersisted(_keyBindings, _keyBindingUnknownEntries),
                ExtensionData = CloneExtensionData(_stateExtensionData),
            };
            bool malformed = false;
            bool saved = TryWithPersistenceLock(path, () =>
            {
                if (!TryReadViewerStateFile(path, out var latest))
                {
                    malformed = true;
                    return false;
                }
                state.ExtensionData = CloneExtensionData(latest is null ? _stateExtensionData : latest.ExtensionData);
                _ = KeyBindingSettings.NormalizePersisted(latest?.KeyBindings, out Dictionary<string, JsonElement>? latestUnknownKeyBindings);
                state.KeyBindings = KeyBindingSettings.ToPersisted(
                    _keyBindings,
                    latest is null ? _keyBindingUnknownEntries : latestUnknownKeyBindings);
                string json = JsonSerializer.Serialize(state, new JsonSerializerOptions { WriteIndented = true });
                return TryWriteAtomicText(path, json);
            });
            if (!saved)
            {
                if (malformed)
                    _stateWriteBlocked = true;
                ReportPersistenceRefusal("Viewer settings", path, malformed, malformed ? null : SaveState);
                return;
            }
            _stateExtensionData = CloneExtensionData(state.ExtensionData);
            _ = KeyBindingSettings.NormalizePersisted(state.KeyBindings, out _keyBindingUnknownEntries);
        }
        catch
        {
            ReportPersistenceRefusal("Viewer settings", ResolvedStatePath, retryAction: SaveState);
        }
    }

    private static string ResolvedSharedRecentPath
    {
        get
        {
            string? overridePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH");
            return string.IsNullOrWhiteSpace(overridePath) ? ProjectCachePath("recent-folders.json") : Path.GetFullPath(overridePath);
        }
    }

    private static SharedRecentReadResult ReadSharedRecentFolders()
    {
        return ReadSharedRecentFolders(ResolvedSharedRecentPath);
    }

    private static SharedRecentReadResult ReadSharedRecentFolders(string path)
    {
        SharedJsonDocumentReadResult read = SharedJsonDocumentReader.Read(path);
        if (!read.Ok)
        {
            return new SharedRecentReadResult(
                false,
                NormalizeSharedRecentFolders(null),
                read.Error,
                true);
        }
        if (!read.Exists)
        {
            return new SharedRecentReadResult(
                true,
                NormalizeSharedRecentFolders(null),
                null,
                false);
        }

        try
        {
            using var document = JsonDocument.Parse(read.Json!);
            if (document.RootElement.ValueKind != JsonValueKind.Object)
                return new SharedRecentReadResult(false, NormalizeSharedRecentFolders(null), "shared recent root is not an object", true);
            return new SharedRecentReadResult(true, NormalizeSharedRecentFolders(document.RootElement), null, true);
        }
        catch (Exception ex)
        {
            return new SharedRecentReadResult(false, NormalizeSharedRecentFolders(null), ex.Message, true);
        }
    }

    private static List<string> ResolveStartupFolderSet(
        IEnumerable<string> localLastFolderSet,
        string? localLastFolder,
        SharedRecentReadResult sharedRecent)
    {
        var local = NormalizeFolderSet(localLastFolderSet);
        if (local.Count == 0 && !string.IsNullOrWhiteSpace(localLastFolder))
            local = NormalizeFolderSet([localLastFolder]);
        return sharedRecent.Ok && sharedRecent.Exists
            ? sharedRecent.Recent.LastFolderSet.ToList()
            : local;
    }

    internal static IReadOnlyList<string> ResolveStartupFolderSetForSmoke(
        string sharedRecentPath,
        IEnumerable<string> localLastFolderSet,
        string? localLastFolder)
        => ResolveStartupFolderSet(
            localLastFolderSet,
            localLastFolder,
            ReadSharedRecentFolders(sharedRecentPath));

    internal static SharedRecentReadResult ReadSharedRecentFoldersForSmoke(string path)
        => ReadSharedRecentFolders(path);

    private static SharedRecentFoldersState NormalizeSharedRecentFolders(JsonElement? root)
    {
        List<string> lastFolderSet = [];
        List<List<string>> recentFolderSets = [];
        string updatedAtUtc = DateTime.UtcNow.ToString("O");

        if (root.HasValue && root.Value.ValueKind == JsonValueKind.Object)
        {
            var element = root.Value;
            if (element.TryGetProperty("version", out var versionElement)
                && (versionElement.ValueKind != JsonValueKind.Number
                    || !versionElement.TryGetInt32(out int version)
                    || version != 1))
                throw new JsonException("version must be 1");
            if (element.TryGetProperty("lastFolderSet", out var lastFolderSetElement))
            {
                if (lastFolderSetElement.ValueKind is not (JsonValueKind.Array or JsonValueKind.String))
                    throw new JsonException("lastFolderSet must be an array or string");
                if (lastFolderSetElement.ValueKind == JsonValueKind.Array
                    && lastFolderSetElement.EnumerateArray().Any(static item => item.ValueKind != JsonValueKind.String))
                    throw new JsonException("lastFolderSet array entries must be strings");
                lastFolderSet = NormalizeFolderSet(lastFolderSetElement);
            }
            if (element.TryGetProperty("recentFolderSets", out var recentFolderSetsElement))
            {
                if (recentFolderSetsElement.ValueKind != JsonValueKind.Array)
                    throw new JsonException("recentFolderSets must be an array");
                foreach (var folderSetElement in recentFolderSetsElement.EnumerateArray())
                {
                    if (folderSetElement.ValueKind is not (JsonValueKind.Array or JsonValueKind.String))
                        throw new JsonException("recentFolderSets entries must be arrays or strings");
                    if (folderSetElement.ValueKind == JsonValueKind.Array
                        && folderSetElement.EnumerateArray().Any(static item => item.ValueKind != JsonValueKind.String))
                        throw new JsonException("recentFolderSets nested entries must be strings");
                }
                recentFolderSets = NormalizeRecentFolderSets(recentFolderSetsElement);
            }
            if (element.TryGetProperty("updatedAtUtc", out var updatedAtElement) &&
                updatedAtElement.ValueKind != JsonValueKind.String)
                throw new JsonException("updatedAtUtc must be a string");
            if (element.TryGetProperty("updatedAtUtc", out updatedAtElement) && !string.IsNullOrWhiteSpace(updatedAtElement.GetString()))
                updatedAtUtc = updatedAtElement.GetString()!;

            var extensionData = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
            foreach (var property in element.EnumerateObject())
            {
                if (property.Name is "version" or "lastFolderSet" or "recentFolderSets" or "updatedAtUtc")
                    continue;
                extensionData[property.Name] = property.Value.Clone();
            }
            return new SharedRecentFoldersState
            {
                LastFolderSet = lastFolderSet,
                RecentFolderSets = recentFolderSets,
                UpdatedAtUtc = updatedAtUtc,
                ExtensionData = extensionData.Count > 0 ? extensionData : null,
            };
        }

        return new SharedRecentFoldersState
        {
            LastFolderSet = lastFolderSet,
            RecentFolderSets = recentFolderSets,
            UpdatedAtUtc = updatedAtUtc,
        };
    }

    private static List<string> NormalizeFolderSet(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.Array)
            return NormalizeFolderSet(element.EnumerateArray()
                .Where(static item => item.ValueKind == JsonValueKind.String)
                .Select(static item => item.GetString() ?? ""));

        if (element.ValueKind == JsonValueKind.String)
            return NormalizeFolderSet(SplitFolderSet(element.GetString()));

        return [];
    }

    private static List<string> NormalizeFolderSet(IEnumerable<string> paths)
    {
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var normalized = new List<string>();
        foreach (string raw in paths)
        {
            string? path = NormalizeRecentFolderPath(raw);
            if (path is null || !seen.Add(path))
                continue;
            normalized.Add(path);
        }

        return normalized;
    }

    private static IEnumerable<string> SplitFolderSet(string? value)
        => string.IsNullOrWhiteSpace(value)
            ? []
            : value.Split(["\r\n", "\n"], StringSplitOptions.None).Select(static item => item.Trim());

    private static List<List<string>> NormalizeRecentFolderSets(JsonElement element)
    {
        if (element.ValueKind != JsonValueKind.Array)
            return [];

        return NormalizeRecentFolderSets(element.EnumerateArray().Select(NormalizeFolderSet));
    }

    private static List<List<string>> NormalizeRecentFolderSets(IEnumerable<IReadOnlyList<string>> folderSets)
    {
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var normalized = new List<List<string>>();
        foreach (var folderSet in folderSets)
        {
            var folders = NormalizeFolderSet(folderSet);
            if (folders.Count == 0)
                continue;

            string key = FormatRecentFolderSet(folders);
            if (!seen.Add(key))
                continue;

            normalized.Add(folders);
            if (normalized.Count >= MaxRecentFolderSets)
                break;
        }

        return normalized;
    }

    private static string FormatRecentFolderSet(IEnumerable<string> paths)
        => string.Join("\n", NormalizeFolderSet(paths));

    private static string? NormalizeRecentFolderPath(string? path)
    {
        if (string.IsNullOrWhiteSpace(path))
            return null;

        try
        {
            return Path.GetFullPath(path.Trim());
        }
        catch
        {
            return null;
        }
    }

    private bool SaveSharedRecentFolderSet(IEnumerable<string> folders)
    {
        var folderSet = NormalizeFolderSet(folders);
        if (folderSet.Count == 0)
            return true;

        try
        {
            string path = ResolvedSharedRecentPath;
            bool malformed = false;
            bool saved = TryWithPersistenceLock(path, () =>
            {
                var current = ReadSharedRecentFolders();
                if (!current.Ok)
                {
                    malformed = true;
                    return false;
                }
                var recentFolderSets = NormalizeRecentFolderSets(
                    new[] { folderSet }.Concat(current.Recent.RecentFolderSets));
                var next = new SharedRecentFoldersState
                {
                    LastFolderSet = folderSet,
                    RecentFolderSets = recentFolderSets,
                    UpdatedAtUtc = DateTime.UtcNow.ToString("O"),
                    ExtensionData = CloneExtensionData(current.Recent.ExtensionData),
                };
                var json = JsonSerializer.Serialize(next, SharedRecentJsonOptions);
                if (!SharedJsonDocumentReader.TryEncodeCanonical(
                        json,
                        out byte[] bytes,
                        out _))
                {
                    malformed = true;
                    return false;
                }
                return TryWriteAtomicBytes(path, bytes);
            });
            if (!saved)
                ReportPersistenceRefusal("Recent folder history", path, malformed, malformed ? null : () => SaveSharedRecentFolderSet(folderSet));
            return saved;
        }
        catch
        {
            ReportPersistenceRefusal("Recent folder history", ResolvedSharedRecentPath, retryAction: () => SaveSharedRecentFolderSet(folderSet));
            return false;
        }
    }

    private bool CommitSharedRecentFolderSet(IEnumerable<string> folders)
    {
        var folderSet = NormalizeFolderSet(folders);
        if (folderSet.Count == 0)
            return true;

        string key = FormatRecentFolderSet(folderSet);
        if (string.Equals(key, _lastSuccessfulSharedRecentFolderSetKey, StringComparison.OrdinalIgnoreCase))
            return true;

        _sharedRecentCommitAttemptCount++;
        if (!SaveSharedRecentFolderSet(folderSet))
            return false;

        _lastSuccessfulSharedRecentFolderSetKey = key;
        _sharedRecentCommitSuccessCount++;
        return true;
    }

    private bool CloseTopmostOverlay()
    {
        if (DeleteConfirmationDialog.Visibility == Visibility.Visible)
        {
            DeleteCancel_Click(this, new RoutedEventArgs());
            return true;
        }

        if (BatchEnhancementDialog.Visibility == Visibility.Visible)
        {
            CloseBatchEnhancementDialog(restoreFocus: true);
            return true;
        }

        if (AppSettingsDialog.Visibility == Visibility.Visible)
        {
            CloseAppSettings_Click(this, new RoutedEventArgs());
            return true;
        }

        if (EnhancementJobsDialog.Visibility == Visibility.Visible)
        {
            CloseEnhancementJobsWorkspace(restoreFocus: true);
            return true;
        }

        if (Modal.Visibility != Visibility.Visible)
            return false;

        CloseModal(restoreFocus: true);
        return true;
    }

    protected override void OnPreviewKeyDown(KeyEventArgs e)
    {
        var key = e.Key == Key.System ? e.SystemKey : e.Key;
        ModifierKeys modifiers = _shortcutModifierProvider();
        if (_galleryAutoScrollSurface is not null && key == Key.Escape)
        {
            StopGalleryAutoScroll();
            e.Handled = true;
            return;
        }
        if (DeleteConfirmationDialog.Visibility == Visibility.Visible
            || BatchEnhancementDialog.Visibility == Visibility.Visible
            || AppSettingsDialog.Visibility == Visibility.Visible
            || EnhancementJobsDialog.Visibility == Visibility.Visible)
        {
            if (AppSettingsDialog.Visibility == Visibility.Visible
                && _recordingKeyAction is not null
                && CaptureRecordedKey(key, modifiers))
            {
                e.Handled = true;
                return;
            }
            if (key == Key.Escape)
            {
                CloseTopmostOverlay();
                e.Handled = true;
                return;
            }

            // Let dialog controls retain normal Tab/Shift+Tab/Space/Enter behavior;
            // only gallery-global shortcuts are suppressed while an overlay is active.
            base.OnPreviewKeyDown(e);
            return;
        }

        if (!IsViewerShortcutSurfaceActive())
        {
            base.OnPreviewKeyDown(e);
            return;
        }

        bool modalVisible = Modal.Visibility == Visibility.Visible;
        IInputElement? shortcutFocusedElement = _shortcutFocusOverrideForSmoke ?? Keyboard.FocusedElement;
        bool modalNativeInputFocused = modalVisible
            && (IsModalNativeInputFocused(e.OriginalSource) || IsModalNativeInputFocused(shortcutFocusedElement));
        bool modalActionButtonFocused = modalVisible
            && (IsModalActionButtonFocused(e.OriginalSource) || IsModalActionButtonFocused(shortcutFocusedElement));
        if (modalVisible
            && !modalNativeInputFocused
            && modifiers == ModifierKeys.Control
            && key is Key.Up or Key.Down
            && CycleModalEnhancementVersion(key == Key.Down ? 1 : -1))
        {
            e.Handled = true;
            return;
        }
        if (modalVisible && key == Key.F11 && modifiers == ModifierKeys.None)
        {
            SetModalFullScreen(!_modalFullScreen);
            e.Handled = true;
            return;
        }
        if (modalVisible && _modalFullScreen && key == Key.Escape && modifiers == ModifierKeys.None)
        {
            SetModalFullScreen(false);
            e.Handled = true;
            return;
        }
        // Modal close remains reachable even when a child Button owns focus.
        // Settings and Recycle confirmation use the fixed Escape rescue above.
        if (Modal.Visibility == Visibility.Visible
            && MatchesBinding(ViewerKeyAction.CloseModal, key, modifiers))
        {
            CloseModal(restoreFocus: true);
            e.Handled = true;
            return;
        }

        // Preview-tab reorder is meaningful only while a tab button owns focus.
        // Handle just these configured chords before the generic Button guard;
        // ordinary buttons and editable inputs still suppress viewer shortcuts.
        if ((MatchesBinding(ViewerKeyAction.MovePreviewTabLeft, key, modifiers)
                && TryReorderFocusedPreviewTab(-1))
            || (MatchesBinding(ViewerKeyAction.MovePreviewTabRight, key, modifiers)
                && TryReorderFocusedPreviewTab(1)))
        {
            e.Handled = true;
            return;
        }

        if (modalActionButtonFocused && key is Key.Enter or Key.Space)
        {
            base.OnPreviewKeyDown(e);
            return;
        }

        if ((IsGlobalShortcutInputFocused(e.OriginalSource)
                || IsGlobalShortcutInputFocused(shortcutFocusedElement))
            && !modalActionButtonFocused)
        {
            base.OnPreviewKeyDown(e);
            return;
        }

        if (key is Key.Enter or Key.Return && modifiers == ModifierKeys.None)
        {
            if (Modal.Visibility == Visibility.Visible)
            {
                e.Handled = TryOpenSelectedExternally();
                return;
            }
            if (IsGalleryEnterSurfaceFocused())
            {
                OpenModal();
                e.Handled = Modal.Visibility == Visibility.Visible;
                return;
            }
        }

        if (TryHandleConfiguredViewerShortcut(key, modifiers))
        {
            e.Handled = true;
            return;
        }

        base.OnPreviewKeyDown(e);
    }

    private bool TryHandleConfiguredViewerShortcut(Key key, ModifierKeys modifiers)
    {
        if (!IsViewerShortcutSurfaceActive())
            return false;

        bool modalVisible = Modal.Visibility == Visibility.Visible;
        if (modalVisible)
        {
            if (MatchesBinding(ViewerKeyAction.CloseModal, key, modifiers))
            {
                CloseModal(restoreFocus: true);
                return true;
            }
            if (MatchesBinding(ViewerKeyAction.PreviousImage, key, modifiers))
            {
                NavigateModal(-1);
                return true;
            }
            if (MatchesBinding(ViewerKeyAction.NextImage, key, modifiers))
            {
                NavigateModal(1);
                return true;
            }
            if (MatchesBinding(ViewerKeyAction.FlipHorizontal, key, modifiers))
                return ToggleModalFlip();
            if (MatchesBinding(ViewerKeyAction.ToggleEnhancedPreview, key, modifiers))
                return ToggleModalEnhanced();
            if (MatchesBinding(ViewerKeyAction.EnhanceCurrentImage, key, modifiers)
                && ModalEnhanceButton.IsEnabled)
            {
                StartModalEnhancement_Click(this, new RoutedEventArgs());
                return true;
            }
            if (MatchesBinding(ViewerKeyAction.ModalZoomIn, key, modifiers))
                return AdjustModalZoom(ModalZoomKeyboardStep);
            if (MatchesBinding(ViewerKeyAction.ModalZoomOut, key, modifiers))
                return AdjustModalZoom(1 / ModalZoomKeyboardStep);
            if (MatchesBinding(ViewerKeyAction.ModalZoomReset, key, modifiers))
                return ResetModalTransform(_modalTransformPath, showFeedback: true);
            if (MatchesBinding(ViewerKeyAction.ToggleModalFilmstrip, key, modifiers))
                return ToggleModalFilmstrip();
        }
        else
        {
            if (MatchesBinding(ViewerKeyAction.SelectAllResults, key, modifiers))
                return SelectAllCurrentResults();
            if (MatchesBinding(ViewerKeyAction.ClearSelection, key, modifiers))
                return ClearCurrentSelection();
            if (MatchesBinding(ViewerKeyAction.GalleryZoomIn, key, modifiers))
                return AdjustCardWidth(1);
            if (MatchesBinding(ViewerKeyAction.GalleryZoomOut, key, modifiers))
                return AdjustCardWidth(-1);
            if (MatchesBinding(ViewerKeyAction.GalleryZoomReset, key, modifiers))
                return ResetCardWidth();
        }

        if (MatchesBinding(ViewerKeyAction.FavoriteIncrease, key, modifiers))
            return AdjustSelectedFavorite(1);
        if (MatchesBinding(ViewerKeyAction.FavoriteDecrease, key, modifiers))
            return AdjustSelectedFavorite(-1);
        if (MatchesBinding(ViewerKeyAction.FavoriteLevel1, key, modifiers))
            return SetFavoriteLevelForSelection(1);
        if (MatchesBinding(ViewerKeyAction.FavoriteLevel2, key, modifiers))
            return SetFavoriteLevelForSelection(2);
        if (MatchesBinding(ViewerKeyAction.FavoriteLevel3, key, modifiers))
            return SetFavoriteLevelForSelection(3);
        if (MatchesBinding(ViewerKeyAction.FavoriteLevel4, key, modifiers))
            return SetFavoriteLevelForSelection(4);
        if (MatchesBinding(ViewerKeyAction.FavoriteLevel5, key, modifiers))
            return SetFavoriteLevelForSelection(5);
        if (MatchesBinding(ViewerKeyAction.RecycleCurrentImage, key, modifiers))
            return RequestDeleteSelected();
        if (MatchesBinding(ViewerKeyAction.AddToAlbum, key, modifiers))
            return ShowAlbumLibrary();
        if (MatchesBinding(ViewerKeyAction.ReopenLastClosedPreviewTab, key, modifiers))
            return RestoreLastClosedPreviewTab();
        if (MatchesBinding(ViewerKeyAction.MovePreviewTabLeft, key, modifiers))
            return TryReorderFocusedPreviewTab(-1);
        if (MatchesBinding(ViewerKeyAction.MovePreviewTabRight, key, modifiers))
            return TryReorderFocusedPreviewTab(1);
        return false;
    }

    private bool MatchesBinding(ViewerKeyAction action, Key key, ModifierKeys modifiers)
        => _keyBindings.TryGetValue(action, out KeyChord chord)
            && chord.Matches(key, modifiers);

    private bool SelectAllCurrentResults()
    {
        Tile? previousPrimary = SelectedTile();
        Tile? primary = null;
        int selectableCount = 0;
        _selectedPaths.Clear();
        foreach (Tile tile in _tiles)
        {
            if (!tile.IsRealFile)
                continue;
            selectableCount++;
            _selectedPaths.Add(tile.Path);
            primary ??= tile;
            if (ReferenceEquals(tile, previousPrimary))
                primary = tile;
        }

        if (selectableCount == 0 || primary is null)
            return false;

        _primarySelectedPath = primary.Path;
        _primarySelectedTile = primary;
        _primarySelectedIndex = _tiles.IndexOf(primary);
        _selectionVisualSyncGeneration++;
        SynchronizeSelectionControls();
        ApplyPrimarySelection(primary);
        SetStatusToast($"Selected all {selectableCount:N0} current results.");
        return true;
    }

    private bool ClearCurrentSelection()
    {
        if (_selectedPaths.Count == 0)
            return false;
        _selectedPaths.Clear();
        _primarySelectedPath = null;
        _primarySelectedTile = null;
        _primarySelectedIndex = -1;
        _selectionVisualSyncGeneration++;
        SynchronizeSelectionControls();
        ApplyPrimarySelection(null);
        SetStatusToast("Image selection cleared.");
        return true;
    }

    private static bool IsGlobalShortcutInputFocused(object? source)
    {
        // Mouse routed events normally report a template child (TextBoxView,
        // ScrollViewer, Path, TextBlock, etc.) as OriginalSource rather than
        // the owning input/button. Walk both visual and logical ancestry so a
        // Ctrl/Win+wheel gesture over any part of those controls keeps its
        // native behavior instead of leaking into gallery zoom.
        for (DependencyObject? current = source as DependencyObject;
             current is not null;
             current = current is Visual or System.Windows.Media.Media3D.Visual3D
                 ? VisualTreeHelper.GetParent(current)
                 : LogicalTreeHelper.GetParent(current))
        {
            if (current is TextBoxBase or ComboBox or DatePicker or ButtonBase)
                return true;
        }

        return false;
    }

    private static bool IsModalNativeInputFocused(object? source)
    {
        for (DependencyObject? current = source as DependencyObject;
             current is not null;
             current = current is Visual or System.Windows.Media.Media3D.Visual3D
                 ? VisualTreeHelper.GetParent(current)
                 : LogicalTreeHelper.GetParent(current))
        {
            if (current is TextBoxBase or ComboBox or DatePicker)
                return true;
        }
        return false;
    }

    private bool IsModalActionButtonFocused(object? source)
    {
        for (DependencyObject? current = source as DependencyObject;
             current is not null;
             current = current is Visual or System.Windows.Media.Media3D.Visual3D
                 ? VisualTreeHelper.GetParent(current)
                 : LogicalTreeHelper.GetParent(current))
        {
            if (current is not ButtonBase button)
                continue;
            return IsDescendantOrSelf(button, ModalTopBar)
                || IsDescendantOrSelf(button, ModalFooter)
                || ReferenceEquals(button, ModalPreviousButton)
                || ReferenceEquals(button, ModalNextButton);
        }
        return false;
    }

    private bool IsGalleryWheelSource(object? source)
        => source is DependencyObject dependency
            && (IsDescendantOrSelf(dependency, CardsList) || IsDescendantOrSelf(dependency, RowsList));

    private bool IsViewerShortcutSurfaceActive()
        => Landing.Visibility != Visibility.Visible;

    private bool IsGalleryEnterSurfaceFocused()
    {
        if (Keyboard.FocusedElement is not DependencyObject focused)
            return false;
        ListBox activeList = RowsList.Visibility == Visibility.Visible ? RowsList : CardsList;
        return IsDescendantOrSelf(focused, activeList);
    }

    private bool IsModalImageWheelSource(DependencyObject? source)
        => source is not null
            && IsDescendantOrSelf(source, ModalImageArea)
            && !IsDescendantOrSelf(source, ModalMetadataSidebar)
            && !IsDescendantOrSelf(source, ModalPreviousButton)
            && !IsDescendantOrSelf(source, ModalNextButton)
            && !IsDescendantOrSelf(source, ModalFilmstripOverlay)
            && !IsDescendantOrSelf(source, ModalFooter);

    private static bool IsDescendantOrSelf(DependencyObject source, DependencyObject ancestor)
    {
        for (DependencyObject? current = source; current is not null; current = current is Visual or System.Windows.Media.Media3D.Visual3D
            ? VisualTreeHelper.GetParent(current)
            : LogicalTreeHelper.GetParent(current))
        {
            if (ReferenceEquals(current, ancestor))
                return true;
        }
        return false;
    }

    protected override void OnPreviewMouseWheel(MouseWheelEventArgs e)
    {
        if (DeleteConfirmationDialog.Visibility == Visibility.Visible
            || AppSettingsDialog.Visibility == Visibility.Visible
            || !IsViewerShortcutSurfaceActive())
        {
            base.OnPreviewMouseWheel(e);
            return;
        }

        if (Modal.Visibility == Visibility.Visible)
        {
            if (IsModalImageWheelSource(e.OriginalSource as DependencyObject))
            {
                Point viewportAnchor = _modalWheelViewportAnchorForSmoke
                    ?? e.GetPosition(ModalImageArea);
                if (IsPointInsideTransformedModalImage(viewportAnchor))
                {
                    Point imageAnchor = ModalImageArea.TranslatePoint(viewportAnchor, ModalImage);
                    AdjustModalZoom(ModalWheelZoomMultiplier(e.Delta), imageAnchor);
                    e.Handled = true;
                }
                else
                {
                    base.OnPreviewMouseWheel(e);
                }
            }
            else
            {
                base.OnPreviewMouseWheel(e);
            }
            return;
        }

        if (IsGlobalShortcutInputFocused(e.OriginalSource)
            || IsGlobalShortcutInputFocused(Keyboard.FocusedElement))
        {
            base.OnPreviewMouseWheel(e);
            return;
        }

        if (IsZoomModifierActive() && IsGalleryWheelSource(e.OriginalSource))
        {
            // Browser parity keeps List rows at a fixed size. Only consume the
            // wheel when Grid zoom actually changes; otherwise native List
            // scrolling must keep working instead of silently swallowing input.
            if (AdjustCardWidth(e.Delta > 0 ? 1 : -1))
            {
                e.Handled = true;
                return;
            }
        }

        base.OnPreviewMouseWheel(e);
    }

    // ─────────── Window chrome buttons ───────────
    private void Minimize_Click(object sender, RoutedEventArgs e) => WindowState = WindowState.Minimized;

    private bool SetModalFullScreen(bool enabled, bool showFeedback = true)
    {
        if (enabled && Modal.Visibility != Visibility.Visible)
            return false;
        if (_modalFullScreen == enabled)
            return true;

        if (enabled)
        {
            _modalFullScreenRestoreBounds = WindowState == WindowState.Normal
                ? new Rect(Left, Top, Width, Height)
                : RestoreBounds;
            _modalFullScreenRestoreFakeMaximized = _fakeMaximized;
            _modalFullScreenRestoreWindowState = WindowState;
            _modalFullScreenRestoreResizeMode = ResizeMode;
            _modalFullScreenRestoreMinWidth = MinWidth;
            _modalFullScreenRestoreMinHeight = MinHeight;

            Rect monitor = ResolveSafeCurrentMonitorBounds();
            _modalFullScreen = true;
            _fakeMaximized = false;
            WindowState = WindowState.Normal;
            ResizeMode = ResizeMode.NoResize;
            MinWidth = 1;
            MinHeight = 1;
            Left = monitor.Left;
            Top = monitor.Top;
            Width = monitor.Width;
            Height = monitor.Height;
            // Maximized + borderless is the Windows fullscreen contract that
            // covers the selected display, including its taskbar area.
            WindowState = WindowState.Maximized;
        }
        else
        {
            _modalFullScreen = false;
            WindowState = WindowState.Normal;
            ResizeMode = _modalFullScreenRestoreResizeMode;
            MinWidth = _modalFullScreenRestoreMinWidth;
            MinHeight = _modalFullScreenRestoreMinHeight;
            if (_modalFullScreenRestoreFakeMaximized)
            {
                Rect workArea = ResolveSafeCurrentMonitorWorkArea();
                ApplyEffectiveWindowMinimums(workArea);
                Left = workArea.Left;
                Top = workArea.Top;
                Width = workArea.Width;
                Height = workArea.Height;
                _fakeMaximized = true;
            }
            else
            {
                Rect restored = _modalFullScreenRestoreBounds;
                Left = restored.Left;
                Top = restored.Top;
                Width = restored.Width;
                Height = restored.Height;
                _fakeMaximized = false;
                if (_modalFullScreenRestoreWindowState != WindowState.Minimized)
                    WindowState = _modalFullScreenRestoreWindowState;
            }
        }

        UpdateModalFullScreenPresentation();
        UpdateWindowMaximizePresentation();
        Dispatcher.BeginInvoke(() =>
        {
            UpdateLayout();
            UpdateModalFit();
            ScheduleModalFitUpdate();
        }, DispatcherPriority.Loaded);
        if (showFeedback)
            ShowModalInteractionFeedback(enabled ? "Full screen" : "Windowed");
        return true;
    }

    private void UpdateModalFullScreenPresentation()
    {
        ModalWindowCaptionControls.Visibility = _modalFullScreen
            ? Visibility.Collapsed
            : Visibility.Visible;
        ModalTopBar.Margin = _modalFullScreen
            ? new Thickness(12, 7, 12, 7)
            : new Thickness(12, 7, 150, 7);
        string label = _modalFullScreen ? "Exit full screen" : "Enter full screen";
        ModalFullScreenButton.ToolTip = $"{label} (F11)";
        AutomationProperties.SetName(ModalFullScreenButton, label);
        ModalContextFullScreen.Header = $"{label} (F11)";
        ModalFullScreenIcon.Data = Geometry.Parse(_modalFullScreen
            ? "M3,9 H9 V3 M15,3 V9 H21 M21,15 H15 V21 M9,21 V15 H3"
            : "M3,9 V3 H9 M15,3 H21 V9 M21,15 V21 H15 M9,21 H3 V15");
    }

    private void Maximize_Click(object sender, RoutedEventArgs e)
    {
        // Fake-maximize to the working area so the taskbar is never covered and
        // borderless content is not clipped by the maximized non-client frame.
        Rect workArea = ResolveSafeCurrentMonitorWorkArea();
        ApplyEffectiveWindowMinimums(workArea);
        if (_fakeMaximized)
        {
            Rect restored = NormalizeRestoreBounds(
                _restoreBounds,
                workArea,
                DesignWindowMinWidth,
                DesignWindowMinHeight);
            Width = restored.Width;
            Height = restored.Height;
            Left = restored.Left;
            Top = restored.Top;
            _fakeMaximized = false;
        }
        else
        {
            _restoreBounds = new Rect(Left, Top, Width, Height);
            Left = workArea.Left;
            Top = workArea.Top;
            Width = workArea.Width;
            Height = workArea.Height;
            _fakeMaximized = true;
        }
        UpdateWindowMaximizePresentation();
    }

    private void MainWindow_StateChanged(object? sender, EventArgs e)
    {
        if (_normalizingNativeMaximize)
            return;

        if (!_modalFullScreen && WindowState == WindowState.Maximized)
        {
            Rect workArea = ResolveSafeCurrentMonitorWorkArea();
            Rect nativeRestoreBounds = RestoreBounds;
            bool restoreRequested = _fakeMaximized;
            _normalizingNativeMaximize = true;
            try
            {
                WindowState = WindowState.Normal;
                ApplyEffectiveWindowMinimums(workArea);
                if (restoreRequested)
                {
                    Rect restored = NormalizeRestoreBounds(
                        _restoreBounds,
                        workArea,
                        DesignWindowMinWidth,
                        DesignWindowMinHeight);
                    Left = restored.Left;
                    Top = restored.Top;
                    Width = restored.Width;
                    Height = restored.Height;
                    _fakeMaximized = false;
                }
                else
                {
                    _restoreBounds = NormalizeRestoreBounds(
                        nativeRestoreBounds,
                        workArea,
                        DesignWindowMinWidth,
                        DesignWindowMinHeight);
                    Left = workArea.Left;
                    Top = workArea.Top;
                    Width = workArea.Width;
                    Height = workArea.Height;
                    _fakeMaximized = true;
                }
            }
            finally
            {
                _normalizingNativeMaximize = false;
            }
        }

        UpdateWindowMaximizePresentation();
    }

    private void UpdateWindowMaximizePresentation()
    {
        bool restore = _fakeMaximized || (!_modalFullScreen && WindowState == WindowState.Maximized);
        Geometry geometry = Geometry.Parse(restore ? RestoreWindowIconGeometry : MaximizeWindowIconGeometry);
        MaximizeIcon.Data = geometry;
        LandingMaximizeIcon.Data = geometry;
        ModalMaximizeIcon.Data = geometry;

        string label = restore ? "Restore window" : "Maximize window";
        MaxButton.ToolTip = label;
        LandingMaximizeButton.ToolTip = label;
        ModalMaximizeButton.ToolTip = label;
        AutomationProperties.SetName(MaxButton, label);
        AutomationProperties.SetName(LandingMaximizeButton, label);
        AutomationProperties.SetName(ModalMaximizeButton, label);
    }

    private bool WindowMaximizePresentationMatches(bool restore)
    {
        string expectedGeometry = Geometry.Parse(
            restore ? RestoreWindowIconGeometry : MaximizeWindowIconGeometry)
            .ToString(CultureInfo.InvariantCulture);
        string expectedLabel = restore ? "Restore window" : "Maximize window";
        return new[] { MaximizeIcon, LandingMaximizeIcon, ModalMaximizeIcon }
                .All(path => string.Equals(
                    path.Data?.ToString(CultureInfo.InvariantCulture),
                    expectedGeometry,
                    StringComparison.Ordinal))
            && new[] { MaxButton, LandingMaximizeButton, ModalMaximizeButton }
                .All(button =>
                    string.Equals(button.ToolTip?.ToString(), expectedLabel, StringComparison.Ordinal)
                    && string.Equals(AutomationProperties.GetName(button), expectedLabel, StringComparison.Ordinal));
    }

    private void ApplyEffectiveWindowMinimums(Rect workArea)
    {
        MinWidth = Math.Min(DesignWindowMinWidth, Math.Max(1, workArea.Width));
        MinHeight = Math.Min(DesignWindowMinHeight, Math.Max(1, workArea.Height));
    }

    private void ConstrainWindowToCurrentWorkArea()
    {
        Rect workArea = ResolveSafeCurrentMonitorWorkArea();
        ApplyEffectiveWindowMinimums(workArea);
        if (_fakeMaximized)
        {
            Left = workArea.Left;
            Top = workArea.Top;
            Width = workArea.Width;
            Height = workArea.Height;
            return;
        }

        Rect normalized = NormalizeRestoreBounds(
            new Rect(Left, Top, Width, Height),
            workArea,
            DesignWindowMinWidth,
            DesignWindowMinHeight);
        Left = normalized.Left;
        Top = normalized.Top;
        Width = normalized.Width;
        Height = normalized.Height;
    }

    private static Rect NormalizeRestoreBounds(Rect saved, Rect workArea, double minWidth, double minHeight)
    {
        double safeMinWidth = Math.Min(workArea.Width, Math.Max(1, minWidth));
        double safeMinHeight = Math.Min(workArea.Height, Math.Max(1, minHeight));
        double width = double.IsFinite(saved.Width) && saved.Width > 0
            ? Math.Clamp(saved.Width, safeMinWidth, workArea.Width)
            : safeMinWidth;
        double height = double.IsFinite(saved.Height) && saved.Height > 0
            ? Math.Clamp(saved.Height, safeMinHeight, workArea.Height)
            : safeMinHeight;
        double left = double.IsFinite(saved.Left)
            ? Math.Clamp(saved.Left, workArea.Left, workArea.Right - width)
            : workArea.Left + ((workArea.Width - width) / 2);
        double top = double.IsFinite(saved.Top)
            ? Math.Clamp(saved.Top, workArea.Top, workArea.Bottom - height)
            : workArea.Top + ((workArea.Height - height) / 2);
        return new Rect(left, top, width, height);
    }

    private Rect ResolveSafeCurrentMonitorWorkArea()
    {
        try
        {
            Rect area = _currentMonitorWorkArea();
            if (!area.IsEmpty
                && double.IsFinite(area.Left) && double.IsFinite(area.Top)
                && double.IsFinite(area.Width) && double.IsFinite(area.Height)
                && area.Width > 0 && area.Height > 0)
                return area;
        }
        catch
        {
            // Fall through to WPF's primary work area if monitor discovery is
            // unavailable. Maximize remains non-destructive and reversible.
        }
        return SystemParameters.WorkArea;
    }

    private Rect ResolveSafeCurrentMonitorBounds()
    {
        try
        {
            Rect bounds = _currentMonitorBounds();
            if (!bounds.IsEmpty
                && double.IsFinite(bounds.Left) && double.IsFinite(bounds.Top)
                && double.IsFinite(bounds.Width) && double.IsFinite(bounds.Height)
                && bounds.Width > 0 && bounds.Height > 0)
            {
                return bounds;
            }
        }
        catch
        {
            // Keep fullscreen reversible even if monitor discovery fails.
        }

        Rect workArea = ResolveSafeCurrentMonitorWorkArea();
        return workArea.IsEmpty
            ? new Rect(0, 0, SystemParameters.PrimaryScreenWidth, SystemParameters.PrimaryScreenHeight)
            : workArea;
    }

    private Rect ResolveCurrentMonitorWorkArea()
    {
        nint windowHandle = new System.Windows.Interop.WindowInteropHelper(this).Handle;
        if (windowHandle == 0)
            return SystemParameters.WorkArea;
        nint monitor = MonitorFromWindow(windowHandle, MonitorDefaultToNearest);
        if (monitor == 0)
            return SystemParameters.WorkArea;

        var info = new NativeMonitorInfo { Size = (uint)Marshal.SizeOf<NativeMonitorInfo>() };
        if (!GetMonitorInfo(monitor, ref info))
            return SystemParameters.WorkArea;

        Matrix fromDevice = PresentationSource.FromVisual(this)?.CompositionTarget?.TransformFromDevice
            ?? Matrix.Identity;
        Point topLeft = fromDevice.Transform(new Point(info.WorkArea.Left, info.WorkArea.Top));
        Point bottomRight = fromDevice.Transform(new Point(info.WorkArea.Right, info.WorkArea.Bottom));
        return new Rect(topLeft, bottomRight);
    }

    private Rect ResolveCurrentMonitorBounds()
    {
        nint windowHandle = new System.Windows.Interop.WindowInteropHelper(this).Handle;
        if (windowHandle == 0)
            return new Rect(0, 0, SystemParameters.PrimaryScreenWidth, SystemParameters.PrimaryScreenHeight);
        nint monitor = MonitorFromWindow(windowHandle, MonitorDefaultToNearest);
        if (monitor == 0)
            return new Rect(0, 0, SystemParameters.PrimaryScreenWidth, SystemParameters.PrimaryScreenHeight);

        var info = new NativeMonitorInfo { Size = (uint)Marshal.SizeOf<NativeMonitorInfo>() };
        if (!GetMonitorInfo(monitor, ref info))
            return new Rect(0, 0, SystemParameters.PrimaryScreenWidth, SystemParameters.PrimaryScreenHeight);

        Matrix fromDevice = PresentationSource.FromVisual(this)?.CompositionTarget?.TransformFromDevice
            ?? Matrix.Identity;
        Point topLeft = fromDevice.Transform(new Point(info.MonitorArea.Left, info.MonitorArea.Top));
        Point bottomRight = fromDevice.Transform(new Point(info.MonitorArea.Right, info.MonitorArea.Bottom));
        return new Rect(topLeft, bottomRight);
    }

    private const uint MonitorDefaultToNearest = 2;

    [DllImport("user32.dll")]
    private static extern nint MonitorFromWindow(nint windowHandle, uint flags);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetMonitorInfo(nint monitor, ref NativeMonitorInfo info);

    [StructLayout(LayoutKind.Sequential)]
    private struct NativeMonitorInfo
    {
        public uint Size;
        public NativeRect MonitorArea;
        public NativeRect WorkArea;
        public uint Flags;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct NativeRect
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

