    public async Task WaitForActiveAlbumAvailabilityStartedForSmokeAsync(int startedAfter, int timeoutMilliseconds = 5_000)
    {
        var timeout = Stopwatch.StartNew();
        while (Volatile.Read(ref _activeAlbumAvailabilityStartedCount) <= startedAfter)
        {
            if (timeout.ElapsedMilliseconds >= timeoutMilliseconds)
                throw new TimeoutException("Active Album availability scan did not start.");
            await Task.Delay(10);
        }
    }

    public async Task WaitForActiveAlbumAvailabilityIdleForSmokeAsync(int timeoutMilliseconds = 5_000)
    {
        var timeout = Stopwatch.StartNew();
        while (Volatile.Read(ref _activeAlbumAvailabilityPendingCount) > 0
            || Volatile.Read(ref _activeAlbumAvailabilityActiveCount) > 0)
        {
            if (timeout.ElapsedMilliseconds >= timeoutMilliseconds)
                throw new TimeoutException("Active Album availability scans did not stop.");
            await Task.Delay(10);
        }
    }
