        try
        {
            var args = new MouseWheelEventArgs(Mouse.PrimaryDevice, Environment.TickCount, delta)
            {
                RoutedEvent = Mouse.PreviewMouseWheelEvent,
                Source = source,
            };
            OnPreviewMouseWheel(args);
            return args.Handled;
        }
        finally
        {
            _shortcutModifierProvider = previous;
        }
    }

