    public void SeedLargeSelectionCatalogForSmoke(int count, string primaryPath)
    {
        if (count <= 0)
            throw new ArgumentOutOfRangeException(nameof(count));

        Tile template = _allTiles.FirstOrDefault(tile => string.Equals(tile.Path, primaryPath, StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException("The large-selection primary fixture is not in the current catalog.");
        string root = Path.GetDirectoryName(template.Path) ?? Path.GetTempPath();
        var tiles = new List<Tile>(count) { template };
        for (int index = 1; index < count; index++)
        {
            tiles.Add(new Tile
            {
                Path = Path.Combine(root, $".selection-smoke-{index:D6}.png"),
                FileName = $"selection-smoke-{index:D6}.png",
                IsRealFile = true,
                Group = template.Group,
                FolderBucketKey = template.FolderBucketKey,
                FolderBucketLabel = template.FolderBucketLabel,
                ModifiedUtc = template.ModifiedUtc,
                CreatedUtc = template.CreatedUtc,
                ModifiedText = template.ModifiedText,
                SizeText = template.SizeText,
                Thumbnail = template.Thumbnail,
                ArtBase = template.ArtBase,
                ArtGlow = template.ArtGlow,
                Fav = 0,
                Unseen = false,
            });
        }

        PublishLogicalCatalogForSmoke(tiles);
    }

    public void SeedLargeInteractionCatalogForSmoke(int count)
    {
        if (count <= 0)
            throw new ArgumentOutOfRangeException(nameof(count));

        Tile template = _allTiles.FirstOrDefault() ?? new Tile();
        string root = Path.GetDirectoryName(template.Path) ?? Path.GetTempPath();
        DateTime epoch = new(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        var tiles = new List<Tile>(count);
        for (int index = 0; index < count; index++)
        {
            bool nameMatch = index % 100 == 0;
            string suffix = nameMatch ? "-needle" : "";
            tiles.Add(new Tile
            {
                Path = Path.Combine(root, $".interaction-smoke-{index:D6}{suffix}.png"),
                FileName = $"interaction-smoke-{index:D6}{suffix}.png",
                Prompt = index % 250 == 0 ? "aurora interaction target" : "",
                IsRealFile = false,
                Group = "Logical 100k",
                FolderBucketKey = $"logical-{index % 4}",
                FolderBucketLabel = $"Logical {index % 4}",
                ModifiedUtc = epoch.AddSeconds(count - index),
                CreatedUtc = epoch.AddSeconds(index),
                ModifiedText = "logical",
                SizeText = "0.00 MB",
                Thumbnail = null,
                ArtBase = template.ArtBase,
                ArtGlow = template.ArtGlow,
                Fav = index % 10 == 0 ? 5 : 0,
                Enhanced = index % 20 == 0,
                Unseen = index % 3 != 0,
            });
        }

        PublishLogicalCatalogForSmoke(tiles);
    }

    private void PublishLogicalCatalogForSmoke(List<Tile> tiles)
    {
        bool wasSyncingSelection = _syncingSelection;
        _syncingSelection = true;
        try
        {
            _allTiles.Clear();
            _allTiles.AddRange(tiles);
            ReorderFullCatalogForSort();
            GalleryAutomationProjectionIndex automationProjection =
                GalleryAutomationProjectionIndex.Create(
                    _allTiles,
                    _allTiles.Count,
                    CancellationToken.None);
            StageGalleryAutomationProjection(automationProjection);
            _tiles.ReplaceAll(_allTiles);
            _selectedPaths.Clear();
            _primarySelectedPath = null;
            _primarySelectedTile = null;
            _primarySelectedIndex = -1;
        }
        finally
        {
            _syncingSelection = wasSyncingSelection;
        }

        ApplyCardLayoutToAllTiles();
        _galleryVirtualizingPanel?.InvalidateItemLayout();
        _selectionVisualSyncGeneration++;
        SynchronizeSelectionControls();
        ApplyPrimarySelection(null);
        UpdateFolderStats();
    }
