    public async Task<bool> WaitForModalChromeTransientExpirationForSmokeAsync(int timeoutMilliseconds = 5000)
    {
        var watch = Stopwatch.StartNew();
        while (watch.ElapsedMilliseconds < timeoutMilliseconds)
        {
            if (!_modalManualChromeVisible && !_modalTransientChromeVisible && !ModalChromeEffectivelyVisible)
                return true;
            await Task.Delay(25);
        }
        return !_modalManualChromeVisible && !_modalTransientChromeVisible && !ModalChromeEffectivelyVisible;
    }
