internal sealed class SnapshotCollectionView<T> : CollectionView, IReadOnlyList<T>
{
    private readonly ResettableObservableCollection<T> _source;

    public SnapshotCollectionView(ResettableObservableCollection<T> source)
        : base(Array.Empty<T>())
    {
        _source = source;
        _source.CollectionChanged += Source_CollectionChanged;
    }

    public override int Count => _source.Count;
    public override bool IsEmpty => _source.Count == 0;
    public T this[int index] => _source[index];

    public override object GetItemAt(int index) => _source[index]!;
    public override int IndexOf(object item) => item is T value ? _source.IndexOf(value) : -1;
    public override bool Contains(object item) => item is T value && _source.Contains(value);

    protected override IEnumerator GetEnumerator() => _source.GetEnumerator();

    protected override void RefreshOverride()
    {
        OnPropertyChanged(new PropertyChangedEventArgs(nameof(Count)));
        OnPropertyChanged(new PropertyChangedEventArgs(nameof(IsEmpty)));
        OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset));
    }

    private void Source_CollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
        => OnCollectionChanged(e);

    IEnumerator<T> IEnumerable<T>.GetEnumerator() => _source.GetEnumerator();
}

internal sealed class ResettableObservableCollection<T> :
    IList<T>,
    IReadOnlyList<T>,
    IList,
    INotifyCollectionChanged,
    INotifyPropertyChanged
{
    private T[] _items = [];
    private readonly object _syncRoot = new();

    public event NotifyCollectionChangedEventHandler? CollectionChanged;
    public event PropertyChangedEventHandler? PropertyChanged;

    public int Count => _items.Length;
    public int ResetNotificationCount { get; private set; }
    public int RemoveNotificationCount { get; private set; }
    public bool IsReadOnly => false;
    bool IList.IsFixedSize => false;
    bool IList.IsReadOnly => false;
    bool ICollection.IsSynchronized => false;
    object ICollection.SyncRoot => _syncRoot;

    public T this[int index]
    {
        get => _items[index];
        set
        {
            T[] next = (T[])_items.Clone();
            T previous = next[index];
            next[index] = value;
            _items = next;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
            CollectionChanged?.Invoke(
                this,
                new NotifyCollectionChangedEventArgs(
                    NotifyCollectionChangedAction.Replace,
                    value,
                    previous,
                    index));
        }
    }

    object? IList.this[int index]
    {
        get => this[index];
        set => this[index] = Cast(value);
    }

    public void ReplaceAll(IReadOnlyList<T> items)
    {
        ArgumentNullException.ThrowIfNull(items);
        T[] next = new T[items.Count];
        for (int index = 0; index < items.Count; index++)
            next[index] = items[index];
        ReplaceOwned(next);
    }

    public void ReplaceAll(T[] items, int count)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (count < 0 || count > items.Length)
            throw new ArgumentOutOfRangeException(nameof(count));
        ReplaceOwned(count == items.Length ? items : items.AsSpan(0, count).ToArray());
    }

    public bool CanReplaceOneRemoved(T[] items, int count, int removedIndex)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (count != items.Length
            || _items.Length != count + 1
            || (uint)removedIndex >= (uint)_items.Length)
        {
            return false;
        }

        EqualityComparer<T> comparer = EqualityComparer<T>.Default;
        for (int index = 0; index < removedIndex; index++)
        {
            if (!comparer.Equals(_items[index], items[index]))
                return false;
        }
        for (int index = removedIndex; index < count; index++)
        {
            if (!comparer.Equals(_items[index + 1], items[index]))
                return false;
        }
        return true;
    }

    public void ReplaceOneRemovedAfterValidation(T[] items, int count, int removedIndex)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (count != items.Length
            || _items.Length != count + 1
            || (uint)removedIndex >= (uint)_items.Length)
        {
            throw new InvalidOperationException("The validated one-item removal shape changed before publication.");
        }

        T removed = _items[removedIndex];
        _items = items;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Count)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        RemoveNotificationCount++;
        CollectionChanged?.Invoke(
            this,
            new NotifyCollectionChangedEventArgs(
                NotifyCollectionChangedAction.Remove,
                removed,
                removedIndex));
    }

    private void ReplaceOwned(T[] items)
    {
        _items = items;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Count)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        ResetNotificationCount++;
        CollectionChanged?.Invoke(this, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset));
    }

    public void Add(T item)
    {
        int index = _items.Length;
        T[] next = new T[index + 1];
        Array.Copy(_items, next, index);
        next[index] = item;
        _items = next;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Count)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        CollectionChanged?.Invoke(
            this,
            new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, item, index));
    }

    int IList.Add(object? value)
    {
        Add(Cast(value));
        return _items.Length - 1;
    }

    public void Clear()
    {
        if (_items.Length == 0)
            return;
        ReplaceOwned([]);
    }

    public bool Contains(T item) => Array.IndexOf(_items, item) >= 0;
    bool IList.Contains(object? value) => value is T item && Contains(item);

    public void CopyTo(T[] array, int arrayIndex)
        => Array.Copy(_items, 0, array, arrayIndex, _items.Length);

    void ICollection.CopyTo(Array array, int index)
        => Array.Copy(_items, 0, array, index, _items.Length);

    public IEnumerator<T> GetEnumerator()
        => ((IEnumerable<T>)_items).GetEnumerator();

    IEnumerator IEnumerable.GetEnumerator() => _items.GetEnumerator();

    public int IndexOf(T item) => Array.IndexOf(_items, item);
    int IList.IndexOf(object? value) => value is T item ? IndexOf(item) : -1;

    public void Insert(int index, T item)
    {
        if ((uint)index > (uint)_items.Length)
            throw new ArgumentOutOfRangeException(nameof(index));
        T[] next = new T[_items.Length + 1];
        Array.Copy(_items, 0, next, 0, index);
        next[index] = item;
        Array.Copy(_items, index, next, index + 1, _items.Length - index);
        _items = next;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Count)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        CollectionChanged?.Invoke(
            this,
            new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, item, index));
    }

    void IList.Insert(int index, object? value) => Insert(index, Cast(value));

    public bool Remove(T item)
    {
        int index = IndexOf(item);
        if (index < 0)
            return false;
        RemoveAt(index);
        return true;
    }

    void IList.Remove(object? value)
    {
        if (value is T item)
            Remove(item);
    }

    public void RemoveAt(int index)
    {
        T removed = _items[index];
        T[] next = new T[_items.Length - 1];
        Array.Copy(_items, 0, next, 0, index);
        Array.Copy(_items, index + 1, next, index, _items.Length - index - 1);
        _items = next;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Count)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        RemoveNotificationCount++;
        CollectionChanged?.Invoke(
            this,
            new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Remove, removed, index));
    }

    private static T Cast(object? value)
    {
        if (value is T item)
            return item;
        if (value is null && default(T) is null)
            return default!;
        throw new ArgumentException($"Value must be assignable to {typeof(T).FullName}.", nameof(value));
    }
}

// ─────────── Tile view model ───────────
public sealed class Tile : INotifyPropertyChanged
{
    private static readonly PropertyChangedEventArgs AllLayoutPropertiesChanged = new(string.Empty);

    public Brush? ArtBase { get; set; }
    public Brush? ArtGlow { get; set; }
    public string FileName { get; set; } = "";
    public string Group { get; set; } = "";
    public string Path { get; set; } = "";
    public bool IsRealFile { get; set; }
    public string FolderBucketKey { get; set; } = "";
    public string FolderBucketLabel { get; set; } = "";
    public string? EnhancedOutputPath { get; set; }
    public DateTime ModifiedUtc { get; set; }
    public DateTime CreatedUtc { get; set; }
    public long SourceLength { get; set; }
    public long SourceLastWriteUtcTicks { get; set; }
    public long SourceCreationUtcTicks { get; set; }
    public string SizeText { get; set; } = "";
    public string ModifiedText { get; set; } = "";
    public string AutomationHelpText
        => $"{SizeText}. Favorite level {_fav}. {(_enhanced ? "AI-enhanced" : "Original")}. {(_unseen ? "Unseen" : "Seen")}.";

    private string _prompt = "";
    private int _imagePixelWidth;
    private int _imagePixelHeight;
    private bool _enhanced;
    private bool _showCardDetails = true;
    private bool _showCardStatusBadge = true;
    private bool _isCanonicalSelected;

    public bool IsCanonicalSelected
    {
        get => _isCanonicalSelected;
        internal set
        {
            if (_isCanonicalSelected == value) return;
            _isCanonicalSelected = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(IsCanonicalSelected)));
        }
    }

    public bool Enhanced
    {
        get => _enhanced;
        set
        {
            if (_enhanced == value) return;
            _enhanced = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Enhanced)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowEnhancedBadge)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(AutomationHelpText)));
        }
    }

    public bool ShowCardDetails
    {
        get => _showCardDetails;
        set
        {
            if (_showCardDetails == value) return;
            _showCardDetails = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowCardDetails)));
        }
    }

    public bool ShowCardStatusBadge
    {
        get => _showCardStatusBadge;
        set
        {
            if (_showCardStatusBadge == value) return;
            _showCardStatusBadge = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowCardStatusBadge)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowFavoriteBadge)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowEnhancedBadge)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(ShowUnseenDotOnCard)));
        }
    }

    public bool ShowFavoriteBadge => _showCardStatusBadge && _fav > 0;
    public string FavoriteGlyph => _fav > 0 ? "\uEB52" : "\uEB51";
    public bool ShowEnhancedBadge => _showCardStatusBadge && _enhanced;
    public bool ShowUnseenDotOnCard => _showCardStatusBadge && _showUnseenDot;
    public double CardFavoriteButtonSize => Math.Clamp(_cardWidth - 4, 18, 34);
    public bool UseCompactCardTemplate => _cardWidth < 80;
    public double CompactFavoriteControlHeight => Math.Clamp(_cardHeight * 0.45, 10, 18);

    public string Prompt
    {
        get => _prompt;
        set
        {
            value ??= "";
            if (string.Equals(_prompt, value, StringComparison.Ordinal)) return;
            _prompt = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Prompt)));
        }
    }

